L["DPS/Tank made calm for questing: your action bars and your own frame fade a while after a fight (back under the mouse, in a fight or when you're hurt), the damage meter starts folded (one click on the panel's tab brings it out), the minimap is a little smaller and the XP bar shows its percent. Nothing fades in dungeons, raids, battlegrounds or arenas (General > Fade, Fade only in the open world). Choose it above to use it. If the profile you're on has moved action bars, it offers to bring them along."] = "DPS/Tank, nyugodtra hangolva küldetezéshez: az akciósávjaid és a saját kereted harc után egy idővel elhalványulnak (visszajönnek az egér alatt, harcban vagy ha sérült vagy), a sebzésmérő összecsukva indul (egy kattintás a panel fülén előhozza), a minitérkép kicsit kisebb, az XP-sáv pedig százalékot mutat. Kazamatában, raidben, csatatéren és arénában semmi sem halványul el (Általános > Elhalványítás, Elhalványítás csak a nyílt világban). Válaszd ki fent a használatához. Ha a jelenlegi profilodban áthelyezett akciósávok vannak, felajánlja, hogy átveszi őket."
