L["Hover a zone on the world map to see its level range after its name, colored by how hard it is for you: green is easy, yellow is right for you, red is too high."] = "Vidd az egeret egy zóna fölé a világtérképen, és a neve után látod a szinttartományát, aszerint színezve, mennyire nehéz neked: a zöld könnyű, a sárga épp neked való, a piros túl magas."
L["How big \"Flying to\" and where you flew from are."] = "Mekkora az \"Úti cél\" és az indulási hely."
L["How big the health text is on this frame, while Large health number is off."] = "Mekkora az életerő-szöveg ezen a kereten, amíg a Nagy életerőszám ki van kapcsolva."
L["How big the name of where you're going is."] = "Mekkora a célhely neve."
L["How big the place's name is in the welcome on landing."] = "Mekkora a hely neve az érkezési üdvözlésben."
L["How big the rez icon is."] = "Mekkora a feltámasztás ikonja."
L["How big the time left is."] = "Mekkora a hátralévő idő."
L["How big the totem timers are, in percent."] = "Mekkorák a totem-időzítők, százalékban."
L["How every Cooldown Manager bar moves. A bar's own card in the layout editor can give it its own."] = "Hogyan mozog minden Cooldown-kezelő sáv. Egy sáv saját kártyája az elrendezésszerkesztőben adhat neki egyedit."
L["How fast this bar's animation moves. 1x is its usual pace."] = "Milyen gyorsan mozog a sáv animációja. Az 1x a szokásos tempója."
L["How long each totem has left, on its icon."] = "Mennyi ideje maradt minden totemnek, az ikonján."
L["How many buff icons sit side by side before the next row starts. 0 fits them to the frame's width."] = "Hány buff-ikon fér egymás mellé, mielőtt új sor kezdődik. A 0 a keret szélességéhez igazítja őket."
L["How many colors your custom gradient runs through, left to right."] = "Hány színen fut át az egyedi színátmeneted, balról jobbra."
L["How many debuff icons sit side by side before the next row starts. 0 fits them to the frame's width."] = "Hány debuff-ikon fér egymás mellé, mielőtt új sor kezdődik. A 0 a keret szélességéhez igazítja őket."
L["How many icons sit side by side before the next row starts. 0 spreads them evenly over the rows. Inside the frame a row never runs past its edge."] = "Hány ikon fér egymás mellé, mielőtt új sor kezdődik. A 0 egyenletesen osztja el őket a sorok között. A kereten belül egy sor sosem lóg túl a szélén."
L["How many seconds each line stays after your last loot of it. In a log, more of the same within this time adds to its line instead of a new one."] = "Hány másodpercig marad minden sor az utolsó ilyen zsákmány után. Naplóban az ezen belül érkező ugyanilyen zsákmány a sorához adódik, nem új sort kap."
L["How strongly the animation shows over the bar's own fill."] = "Milyen erősen látszik az animáció a sáv saját kitöltése fölött."
L["How tall each combo point pip is. 0 picks a height to suit the frame."] = "Milyen magas minden kombópont-jelölő. A 0 a kerethez illő magasságot választ."
L["How tall each party cast bar is, inside its border. Not inside the frame, where it takes the power bar's place."] = "Milyen magas minden csoporttag varázslássávja a keretén belül. Nem a kereten belül, ahol az erőforrássáv helyét veszi át."
L["How the bar moves. Flow rolls the bar's colors along it; Tide swells softly through it and surges with every heal and hit. By power type picks one that suits mana, rage or energy. Needs Motion effects (General > Appearance)."] = "Hogyan mozog a sáv. A Folyás végiggörgeti a sáv színeit; az Ár lágyan hullámzik benne, és minden gyógyításnál és találatnál megemelkedik. Az Erőforrás szerint a manához, dühhöz vagy energiához illőt választ. Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["How the bar moves. Flow rolls the bar's colors along it; Tide swells softly through it and surges with every heal and hit. Needs Motion effects (General > Appearance)."] = "Hogyan mozog a sáv. A Folyás végiggörgeti a sáv színeit; az Ár lágyan hullámzik benne, és minden gyógyításnál és találatnál megemelkedik. Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["How this bar moves. All bars follows Cooldown Manager > Bar animation. Needs Motion effects (General > Appearance)."] = "Hogyan mozog ez a sáv. A Minden sáv a Cooldown-kezelő > Sáv-animáció beállítást követi. Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["How wide the flight timer and its route line are."] = "Milyen széles a repülésidőzítő és az útvonalvonala."
L["How wide your cast bar is. Not while under the frame or between the frames: there it fills the space it has."] = "Milyen széles a varázslássávod. Nem, ha a keret alatt vagy a keretek között van: ott kitölti a rendelkezésre álló helyet."
L["Incomplete"] = "Befejezetlen"
L["Innkeeper"] = "Fogadós"
L["Item counts on tooltips"] = "Tárgyszámok a súgóbuborékokon"
L["Its name in the AddOns list should read \"%s %s\": every plugin\'s does."] = "A neve az AddOns listában így kell szóljon: \"%s %s\": minden bővítményé így szól."
L["%s wonders where you went."] = "%s azon tűnődik, hová lettél."
L["%s · Level %d"] = "%s · %d. szint"
L["%s, set %d"] = "%s, %d. szett"
L["%s, skill %d / %d"] = "%s, jártasság %d / %d"
L["%s, talent set %d"] = "%s, %d. tehetségszett"
L["%s: %s can't be read (%s), so it's left out."] = "%s: a(z) %s nem olvasható (%s), ezért kimaradt."
L["%s: %s comes with %s already, so it's left out."] = "%s: a(z) %s már tartalmazza ezt: %s, ezért kimaradt."
L["%s: %s needs a function."] = "%s: a(z) %s függvényt igényel."
L["%s: /dui %s is already taken."] = "%s: a /dui %s már foglalt."
L["%s: DaylightUI has no event called %s."] = "%s: a DaylightUI-nak nincs %s nevű eseménye."
L["%s: fade %s left out something that isn't a frame."] = "%s: a(z) %s elhalványítás kihagyott valamit, ami nem keret."
L["%s: its options need a module called %s."] = "%s: a beállításaihoz %s nevű modul kell."
L["%s: options row %d left out (%s)."] = "%s: a(z) %d. beállítássor kimaradt (%s)."
L["%s: the %s page makes its own groups and takes none from plugins."] = "%s: a(z) %s oldal saját csoportokat készít, bővítményektől nem fogad."
L["+ %d already known"] = "+ %d már ismert"
L["+ %d ignored"] = "+ %d figyelmen kívül"
L["+ %d weapon skills"] = "+ %d fegyverjártasság"
L["+ Add piece"] = "+ Darab hozzáadása"
L["+ a choice of %d items"] = "+ választás %d tárgy közül"
L["+%s since you logged in. Nice."] = "+%s a belépés óta. Szép."
L["- %d already known"] = "- %d már ismert"
L["- %d ignored"] = "- %d figyelmen kívül"
L["- %d weapon skills"] = "- %d fegyverjártasság"
L["... and %d more"] = "... és még %d"
L["/dui - open options"] = "/dui - beállítások megnyitása"
L["/dui afk - preview the AFK screen (any key closes it)"] = "/dui afk - az AFK-képernyő előnézete (bármely gomb bezárja)"
L["/dui all - every command"] = "/dui all - minden parancs"
L["/dui bank - your bank and your other characters' bags, anywhere"] = "/dui bank - a bankod és a többi karaktered táskái, bárhol"
L["/dui bars - what the action bars are doing (pages, slots, keys)"] = "/dui bars - mit csinálnak az akciósávok (lapok, helyek, gombok)"
L["/dui brew - preview the brew"] = "/dui brew - a főzet előnézete"
L["/dui buffs - buff and debuff bars (/dui buffs help for more)"] = "/dui buffs - buff- és debuff-sávok (több: /dui buffs help)"
L["/dui buffs - open the Buffs & Debuffs options"] = "/dui buffs - a Buffok és debuffok beállításainak megnyitása"
L["/dui buffs auras - dump your buffs and debuffs as the client reports them"] = "/dui buffs auras - a buffjaid és debuffjaid kiírása úgy, ahogy a kliens jelenti őket"
L["/dui buffs categories - open the Categories page"] = "/dui buffs categories - a Kategóriák oldal megnyitása"
L["/dui buffs debug - what each bar is doing"] = "/dui buffs debug - mit csinál az egyes sávok"
L["/dui buffs scan - list buffs on your group that aren't recognized"] = "/dui buffs scan - a csoportodon lévő, fel nem ismert buffok listája"
L["/dui buffs test [0-1 | N% | off] - preview a sample of every known buff"] = "/dui buffs test [0-1 | N% | off] - minden ismert buff mintájának előnézete"
L["/dui buffs toggle <category> - show or hide one category"] = "/dui buffs toggle <kategória> - egy kategória megjelenítése vagy elrejtése"
L["/dui campfire - preview the campfire glow"] = "/dui campfire - a tábortűz fényének előnézete"
L["/dui chat daylight|classic - the chat box style"] = "/dui chat daylight|classic - a chatdoboz stílusa"
L["/dui copy - chat text to select and copy"] = "/dui copy - chatszöveg kijelöléshez és másoláshoz"
L["/dui debug [frame] - report how a frame's border was drawn"] = "/dui debug [keret] - jelentés arról, hogyan rajzolódott egy keret szegélye"
L["/dui export - the profile in use as text to share"] = "/dui export - a használt profil megosztható szövegként"
L["/dui fishing - preview the fishing water"] = "/dui fishing - a horgászvíz előnézete"
L["/dui forge - preview the forge"] = "/dui forge - a kovácsműhely előnézete"
L["/dui glow - preview the object glow"] = "/dui glow - a tárgyfény előnézete"
L["/dui import - add a shared DaylightUI profile"] = "/dui import - megosztott DaylightUI-profil hozzáadása"
L["/dui install - the setup guide: set this character up, or take the tour again"] = "/dui install - a beállítási útmutató: állítsd be ezt a karaktert, vagy nézd végig újra a bemutatót"
L["/dui leader - open or close the leader tools; /dui leader test (or test party) tries them with sample members"] = "/dui leader - a vezetői eszközök megnyitása vagy bezárása; a /dui leader test (vagy test party) mintatagokkal próbálja ki őket"
L["/dui levelup - preview the level-up animation"] = "/dui levelup - a szintlépési animáció előnézete"
L["/dui lock - finish moving"] = "/dui lock - mozgatás befejezése"
L["/dui loot - preview the loot feed"] = "/dui loot - a zsákmánysáv előnézete"
L["/dui notes - what's new"] = "/dui notes - újdonságok"
L["/dui npc - try the NPC window with a sample talk"] = "/dui npc - az NPC-ablak kipróbálása egy mintabeszélgetéssel"
L["/dui opens the settings."] = "A /dui megnyitja a beállításokat."
L["/dui platecheck - run while a nameplate is missing, and send us what it prints"] = "/dui platecheck - futtasd, amikor hiányzik egy névtábla, és küldd el, amit kiír"
L["/dui platedebug - your target's nameplate's click area"] = "/dui platedebug - a célpontod névtáblájának kattintható területe"
L["/dui platefps - hide or show our nameplates and print addon time (testing)"] = "/dui platefps - a névtábláink elrejtése vagy megjelenítése, és az addon idejének kiírása (teszteléshez)"
L["/dui plateprobe - run after /dui platecheck while nameplates are missing, and say if they come back"] = "/dui plateprobe - futtasd a /dui platecheck után, amíg hiányoznak a névtáblák, és mondd meg, visszajönnek-e"
L["/dui rep - preview the reputation banner"] = "/dui rep - a hírnévszalag előnézete"
L["/dui reset - put every frame back"] = "/dui reset - minden keret visszahelyezése"
L["/dui sewing - preview the sewing"] = "/dui sewing - a varrás előnézete"
L["/dui sweep party, or /dui sweep raid"] = "/dui sweep party vagy /dui sweep raid"
L["/dui sweep party|raid - step through sample looks for the party or raid frames, to check them"] = "/dui sweep party|raid - a csoport- vagy raidkeretek mintakinézeteinek végiglépése ellenőrzéshez"
L["/dui taint - the game's values DaylightUI has marked (for tracking down blocked actions)"] = "/dui taint - a játék értékei, amiket a DaylightUI megjelölt (blokkolt műveletek felderítéséhez)"
L["/dui test - preview every frame with sample units (/dui test raid: with a raid of forty)"] = "/dui test - minden keret előnézete mintaegységekkel (/dui test raid: negyvenfős raiddel)"
L["/dui unlock - move frames"] = "/dui unlock - keretek mozgatása"
L["/dui unlock lets you move frames; right-click a handle to put one back."] = "A /dui unlock paranccsal mozgathatod a kereteket; jobb klikk egy fogantyún visszateszi a helyére."
L["/dui whispers - every whisper conversation"] = "/dui whispers - minden suttogásbeszélgetés"
L["/dui workshop - preview the workshop"] = "/dui workshop - a műhely előnézete"
L["/dui zone - preview the zone title"] = "/dui zone - a zónacím előnézete"
L["0 leaves just the bars, with no outline round them."] = "A 0 csak a sávokat hagyja meg, körvonal nélkül."
L["1 day"] = "1 nap"
L["1 item"] = "1 tárgy"
L["1 item is missing"] = "1 tárgy hiányzik"
L["1 new talent point"] = "1 új tehetségpont"
L["1 setting matches."] = "1 beállítás illik a keresésre."
L["1 slot left"] = "1 hely maradt"
L["1 spam line hidden"] = "1 spam sor elrejtve"
L["1 unrecognized buff on the group:"] = "1 ismeretlen buff a csoporton:"
L["24-hour clock"] = "24 órás óra"
L["2D portrait"] = "2D portré"
L["30 days"] = "30 nap"
L["3D portrait"] = "3D portré"
L["62% rather than 62, when the health text shows a percent."] = "62 helyett 62%, ha az életerő-szöveg százalékot mutat."
L["7 days"] = "7 nap"
L[">> You <<"] = ">> Te <<"
L["A bar ( | )"] = "Függőleges vonal ( | )"
L["A bar of its own for the faction you're watching. While it's on, the experience bar no longer turns to reputation when you gain some."] = "Külön sáv a figyelt frakciódnak. Amíg be van kapcsolva, a tapasztalatsáv nem vált hírnévre, amikor hírnevet kapsz."
L["A big number in the middle of your screen counts down any pull your group starts, in place of the game's bar. Move it in unlock mode. In a dungeon or raid the game may keep its own bar for a countdown someone else starts."] = "Egy nagy szám a képernyő közepén visszaszámol minden pullt, amit a csoportod indít, a játék sávja helyett. Feloldott módban mozgathatod. Kazamatában vagy raidben a játék megtarthatja a saját sávját, ha valaki más indítja a visszaszámlálást."
L["A bird on the world map at each flight master you can use: blue for Alliance, red for Horde, gold for both."] = "Egy madár a világtérképen minden használható repülésmesternél: kék a Szövetségnek, piros a Hordának, arany mindkettőnek."
L["A border and shadow around the boxes."] = "Keret és árnyék a dobozok körül."
L["A border and shadow around the meter's own window."] = "Keret és árnyék a mérő saját ablaka körül."
L["A border and shadow around the panel behind the bar. When off, the panel is a plain fill."] = "Keret és árnyék a sáv mögötti panel körül. Kikapcsolva a panel sima kitöltés."
L["A border and shadow around the second meter's window."] = "Keret és árnyék a második mérő ablaka körül."
L["A bright line along the cooldown shade's moving edge."] = "Fényes vonal a cooldown-árnyék mozgó szélén."
L["A buff's exact name"] = "Egy buff pontos neve"
L["A clean chat panel with class colors, timestamps and copyable links."] = "Tiszta chatpanel kasztszínekkel, időbélyegekkel és másolható linkekkel."
L["A color over the icon while the mouse is over it."] = "Szín az ikon fölött, amíg rajta van az egér."
L["A color over the icon while you press it."] = "Szín az ikon fölött, amíg lenyomod."
L["A copy of the one in use, layout and all."] = "A használatban lévő másolata, elrendezéssel együtt."
L["A countdown icon for each totem you have down."] = "Visszaszámláló ikon minden lerakott totemedhez."
L["A crown on top of the portrait ring (or over the name tab) for the party or raid leader."] = "Korona a portrégyűrű tetején (vagy a névfül fölött) a csoport- vagy raidvezetőnek."
L["A dash ( - )"] = "Kötőjel ( - )"
L["A done objective stays, dimmed with a tick. When off, it disappears once it's done."] = "A teljesített feladat ott marad, halványítva, pipával. Kikapcsolva eltűnik, amint kész."
L["A dot ( · )"] = "Pont ( · )"
L["A dragon wrapped around the end of an elite's or boss's bar, in gold, or silver for a rare."] = "Egy sárkány tekeredik az elit vagy boss sávjának végére, aranyban, ritka lénynél ezüstben."
L["A frame dropped in unlock mode, a spell placed in the Cooldown Manager editor, a click-cast bound. The game has no sound of its own for these."] = "Feloldott módban lerakott keret, a Cooldown-kezelő szerkesztőjében elhelyezett varázslat, egy beállított kattintásos varázslás. A játéknak ezekhez nincs saját hangja."
L["A framed panel behind the bar."] = "Keretes panel a sáv mögött."
L["A friendly player's <guild> under their name, smaller."] = "Egy barátságos játékos <céhe> a neve alatt, kisebben."
L["A green sliver on the health bar for heals on their way, as the unit frames show them."] = "Zöld csík az életerősávon az érkező gyógyításoknak, ahogy az egységkeretek is mutatják."
L["A group you deleted comes back, with its items."] = "Egy törölt csoport visszajön, a tárgyaival együtt."
L["A halo and a ring of embers light the round icon at the top of a window as it opens. Needs Motion effects (General > Appearance)."] = "Fényudvar és parázsgyűrű világítja meg az ablak tetején lévő kerek ikont, amikor megnyílik. Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["A kill or item for a quest shows for a moment at the top of the screen, small, with a progress bar. Turn it off to see the game's yellow line instead. Move it in unlock mode."] = "Egy küldetéshez szükséges ölés vagy tárgy egy pillanatra megjelenik a képernyő tetején, kicsiben, haladássávval. Kapcsold ki, ha inkább a játék sárga sorát látnád. Feloldott módban mozgathatod."
L["A line on enemy health bars where your finishing moves start to work. The bar's end up to it lights up in your accent color once the enemy is that low. Your class: warriors (Execute), paladins (Hammer of Wrath), and priests once they know Shadow Word: Death."] = "Egy vonal az ellenséges életerősávokon ott, ahol a befejező mozdulataid elkezdenek működni. A sáv vége eddig a kiemelőszínedben világít, amint az ellenség ennyire lement. Kasztod: harcosok (Execute), paladinok (Hammer of Wrath), és papok, ha már ismerik a Shadow Word: Death-t."
L["A mana, rage or energy bar under the health. When off, the frame is all health."] = "Mana-, düh- vagy energiasáv az életerő alatt. Kikapcsolva a keret csupa életerő."
L["A marker over the quest you picked and breadcrumbs on the ground leading to it. With the QuestieDB addon, an arrow to the nearest objective too."] = "Jelölő a kiválasztott küldetés fölött és nyomvonal a földön, ami odavezet. A QuestieDB addonnal egy nyíl is a legközelebbi feladathoz."
L["A member's border turns red while something is attacking them."] = "Egy tag kerete pirosra vált, amíg valami támadja."
L["A member's ring (or name tab without a portrait) turns red while something is attacking them."] = "Egy tag gyűrűje (vagy portré nélkül a névfüle) pirosra vált, amíg valami támadja."
L["A name for the new group:"] = "Az új csoport neve:"
L["A name for the new profile (a copy of %s):"] = "Az új profil neve (%s másolata):"
L["A new profession"] = "Új szakma"
L["A new profile, made from %s with your picks."] = "Új profil, %s alapján, a te választásaiddal."
L["A new whisper shows its first words above the tiles for a few seconds. Click it to answer."] = "Egy új suttogás első szavai néhány másodpercre megjelennek a csempék fölött. Kattints rá a válaszhoz."
L["A new zone's name rises in at the top of the screen with a thin line under it, then the subzone and PvP status; a subzone shows just its name, small. It replaces the game's zone text. Follows Motion effects (General > Appearance)."] = "Egy új zóna neve beúszik a képernyő tetejére, alatta vékony vonallal, aztán az alzóna és a PvP-állapot; egy alzónánál csak a neve látszik, kicsiben. A játék zónaszövegét váltja ki. A Mozgáseffekteket követi (Általános > Megjelenés)."
L["A note about this player"] = "Megjegyzés erről a játékosról"
L["A note for %s:"] = "Megjegyzés ehhez: %s"
L["A pale sliver on the health bar for an absorb shield, as the unit frames show them."] = "Halvány csík az életerősávon az elnyelő pajzsnak, ahogy az egységkeretek is mutatják."
L["A panel behind the whole bar, so its buttons sit on one strip."] = "Panel az egész sáv mögött, így a gombjai egy csíkon ülnek."
L["A panel behind the whole bar."] = "Panel az egész sáv mögött."
L["A player's <guild> under their name, smaller."] = "Egy játékos <céhe> a neve alatt, kisebben."
L["A player's casts in their class color, or their class's gradient with a two-color fill. Creatures' casts keep the fill style. Not with the Daylight gradient."] = "Egy játékos varázslásai a kasztszínében, vagy kétszínű kitöltésnél a kasztja színátmenetében. A lények varázslásai megtartják a kitöltés stílusát. A Daylight színátmenettel nem."
L["A player's name in their class color; other units in their reaction's color."] = "A játékos neve a kasztszínében; más egységek a viszonyuk színében."
L["A pressed button's icon sinks in a little and springs back as you let go."] = "A lenyomott gomb ikonja kicsit besüllyed, és felenged, amikor elengeded."
L["A profile per character or talent set, and a share string for your whole setup."] = "Profil karakterenként vagy tehetségszettenként, és megosztó szöveg az egész beállításodhoz."
L["A pulsing border while the spell's proc alert is up."] = "Lüktető keret, amíg a varázslat proc-jelzése fent van."
L["A quest ready to hand in shows its title alone. A timed quest never folds."] = "A leadható küldetésnek csak a címe látszik. Az időzített küldetés sosem csukódik össze."
L["A quest you've failed, like a timed one that ran out."] = "Egy elbukott küldetés, például egy lejárt időzített."
L["A ring over the outer end. Class icons show for players; NPCs show their face. Needs a frame at least 20 tall."] = "Gyűrű a külső végén. Játékosoknál kasztikon, NPC-knél az arcuk. Legalább 20 magas keret kell hozzá."
L["A round badge with their portrait, or a slim bar with the portrait beside it and the name above."] = "Kerek jelvény a portréjukkal, vagy vékony sáv mellette portréval, fölötte a névvel."
L["A second damage meter in its own window, for two lists at once: healing beside damage, say. Hover it for the same buttons."] = "Második sebzésmérő külön ablakban, hogy egyszerre két lista legyen: például gyógyítás a sebzés mellett. Vidd fölé az egeret ugyanazokért a gombokért."
L["A set already has that name."] = "Már van ilyen nevű szett."
L["A shield: the bar empties as it soaks damage, with the amount left on it. Or by its time, like any buff."] = "Pajzs: a sáv kiürül, ahogy elnyeli a sebzést, rajta a maradék mennyiséggel. Vagy az ideje szerint, mint bármely buff."
L["A skill going up shows its new rank, out of its cap: Tailoring 152 / 225. More skill-ups move the same line on."] = "Egy növekvő jártasság az új szintjét mutatja a plafonjához képest: Tailoring 152 / 225. A további növekedések ugyanezt a sort léptetik."
L["A slash ( / )"] = "Perjel ( / )"
L["A slim bar under the tooltip of a player or creature."] = "Vékony sáv egy játékos vagy lény súgóbuboréka alatt."
L["A slot at or under this much durability gets an amber dot and says Repair soon."] = "Az ennyi vagy ennél kevesebb tartósságú hely borostyán pontot kap, és ezt írja: Hamarosan javítsd."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner of bank items, until the item is bound to you."] = "Kis BoE (felvételkor kötődik) vagy BoU (használatkor kötődik) jel a banki tárgyak bal felső sarkában, amíg a tárgy hozzád nem kötődik."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound to you."] = "Kis BoE (felvételkor kötődik) vagy BoU (használatkor kötődik) jel a bal felső sarokban, amíg a tárgy hozzád nem kötődik."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound."] = "Kis BoE (felvételkor kötődik) vagy BoU (használatkor kötődik) jel a bal felső sarokban, amíg a tárgy nem kötődik."
L["A small Copy button at the top-right of the chat. It opens the tab's text so you can select it and press Ctrl+C. /dui copy does the same."] = "Kis Másolás gomb a chat jobb felső sarkában. Megnyitja a fül szövegét, hogy kijelöld és Ctrl+C-vel másold. A /dui copy ugyanezt teszi."
L["A small badge at the foot of the portrait (or the frame's corner without one), colored by how hard the unit is for you."] = "Kis jelvény a portré alján (portré nélkül a keret sarkában), aszerint színezve, mennyire nehéz neked az egység."
L["A small badge at the foot of the portrait, colored by how hard the unit is for you. Needs the portrait or the name tab."] = "Kis jelvény a portré alján, aszerint színezve, mennyire nehéz neked az egység. Kell hozzá a portré vagy a névfül."
L["A small bar beside each party member who has a pet out. Your own pet keeps its own frame."] = "Kis sáv minden csoporttag mellett, akinek kint van a háziállata. A saját háziállatod megtartja a saját keretét."
L["A small crown on the raid leader's tile."] = "Kis korona a raidvezető csempéjén."
L["A small crown tab beside your party or raid frames while you lead the group or assist in a raid. It opens ready check, role check, a pull timer, target and world markers, and Everyone is assist. When off, these are only in the game's slash commands."] = "Kis koronás fül a csoport- vagy raidkereteid mellett, amíg vezeted a csoportot vagy segédvezető vagy raidben. Innen nyílik a készenléti ellenőrzés, a szerepellenőrzés, a pull-időzítő, a célpont- és világjelölők és a Mindenki segédvezető. Kikapcsolva ezek csak a játék perjeles parancsaiban érhetők el."
L["A small dot in front of each quest you're tracking."] = "Kis pont minden követett küldetés előtt."
L["A small dot in the top right corner on bank items that are part of one of your equipment sets."] = "Kis pont a jobb felső sarokban a banki tárgyakon, amelyek valamelyik felszerelés-szettedhez tartoznak."
L["A small dot in the top right corner on items that are part of one of your equipment sets."] = "Kis pont a jobb felső sarokban a tárgyakon, amelyek valamelyik felszerelés-szettedhez tartoznak."
L["A small number in your accent color after a tab's name: how many new messages landed in it since you last looked."] = "Kis szám a kiemelőszínedben a fül neve után: hány új üzenet érkezett oda, mióta utoljára megnézted."
L["A small icon in a corner for a debuff you can remove, edged in its type's color."] = "Kis ikon egy sarokban az általad levehető debuffhoz, a típusa színével szegélyezve."
L["A small mana, rage or energy number on the power bar."] = "Kis mana-, düh- vagy energiaszám az erőforrássávon."
L["A small pet bar beside each party member whose pet is out."] = "Kis háziállat-sáv minden csoporttag mellett, akinek kint van a háziállata."
L["A small skull on the portrait once your damage over time is enough to finish the target."] = "Kis koponya a portrén, amint az időbeli sebzésed elég a célpont végzéséhez."
L["A small skull past the bar's end once your damage over time is enough to finish that enemy."] = "Kis koponya a sáv vége után, amint az időbeli sebzésed elég az ellenség végzéséhez."
L["A small speech bubble at the top-right of the chat that counts your unread whispers and opens all your conversations. /dui whispers does the same."] = "Kis szövegbuborék a chat jobb felső sarkában, ami számolja az olvasatlan suttogásaidat, és megnyitja az összes beszélgetésedet. A /dui whispers ugyanezt teszi."
L["A small square left of the frame: red while your pet is unhappy, yellow while content, green while happy. Hover for its damage, loyalty and diet."] = "Kis négyzet a kerettől balra: piros, amíg a háziállatod boldogtalan, sárga, ha elégedett, zöld, ha boldog. Vidd fölé az egeret a sebzéséért, hűségéért és étrendjéért."
L["A small tag after an elite, dungeon, raid or PvP quest's title, here and in the quest log on the map."] = "Kis címke egy elit, kazamata-, raid- vagy PvP-küldetés címe után, itt és a térkép küldetésnaplójában."
L["A small time at the bottom of the map. Hover it for both local and server time."] = "Kis óra a térkép alján. Vidd fölé az egeret a helyi és a szerveridőért."
L["A small zone name over each group of quests, the zone you're in first."] = "Kis zónanév minden küldetéscsoport fölött, elöl azzal a zónával, ahol vagy."
L["A soft chime when talents are applied, a talent set is switched, a spell is learned at a trainer or a letter is sent."] = "Halk csengés, amikor tehetségeket alkalmazol, tehetségszettet váltasz, oktatónál varázslatot tanulsz vagy levelet küldesz."
L["A soft glow in the threat color around the health bar."] = "Lágy fény a fenyegetés színében az életerősáv körül."
L["A soft light behind the arrow, in its color."] = "Lágy fény a nyíl mögött, a színében."
L["A soft light in the line's color runs across it as it comes in or adds up."] = "Lágy fény a sor színében fut végig rajta, amikor beérkezik vagy összeadódik."
L["A soft light round the frame in the debuff's type color."] = "Lágy fény a keret körül a debuff típusának színében."
L["A soft light round the tile in the debuff's type color."] = "Lágy fény a csempe körül a debuff típusának színében."
L["A soft shadow round each button."] = "Lágy árnyék minden gomb körül."
L["A soft sound when your name or one of your words shows up."] = "Halk hang, amikor a neved vagy valamelyik szavad megjelenik."
L["A soft, minimal interface."] = "Puha, minimalista felület."
L["A soft, warm chime when a tracked quest is ready to hand in."] = "Halk, meleg csengés, amikor egy követett küldetés leadható."
L["A space"] = "Szóköz"
L["A spell that just lit up, like Overpower or Execute."] = "Egy épp felvillant varázslat, például az Overpower vagy az Execute."
L["A spell with charges: the bar is cut into one piece per charge."] = "Töltetes varázslat: a sáv töltetenként egy darabra van osztva."
L["A spell's icon pops and lights up once when it comes off a real cooldown (never for the global cooldown). Needs Motion effects (General > Appearance)."] = "Egy varázslat ikonja egyszer felpattan és felvillan, amikor egy valódi cooldown lejár (a globális cooldownnál soha). Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["A spell's icon turns gray while it's on cooldown. The global cooldown doesn't count."] = "Egy varázslat ikonja szürke, amíg cooldownon van. A globális cooldown nem számít."
L["A square minimap in the panel. Scroll to zoom."] = "Szögletes minitérkép a panelen. Görgetéssel nagyít."
L["A symbol on the world map at each boat dock and zeppelin tower. Hover it to see where it goes."] = "Egy jel a világtérképen minden hajókikötőnél és zeppelintoronynál. Vidd fölé az egeret, hogy lásd, hová megy."
L["A symbol on the world map at each dungeon and raid entrance. Hover it for the name."] = "Egy jel a világtérképen minden kazamata- és raidbejáratnál. Vidd fölé az egeret a nevéért."
L["A thin bar under the name."] = "Vékony sáv a név alatt."
L["A thin line across the bars where your threat would pull it: 110% of the tank's in melee, 130% at range. Not shown on a boss, whose numbers the game keeps hidden."] = "Vékony vonal a sávokon ott, ahol a fenyegetésed átvenné az aggrót: közelharcban a tank 110%-a, távolról 130%. Bossnál nem látszik, mert a játék elrejti a számait."
L["A thin line in your accent color along the top of the chat."] = "Vékony vonal a kiemelőszínedben a chat tetején."
L["A thin mana strip along the bottom of the power bar while a form hides your mana."] = "Vékony manacsík az erőforrássáv alján, amíg egy forma elrejti a manádat."
L["A thin mana, rage or energy bar at the foot of each tile."] = "Vékony mana-, düh- vagy energiasáv minden csempe alján."
L["A thin outline on chat text."] = "Vékony körvonal a chatszövegen."
L["A thin power bar under each pet's health."] = "Vékony erőforrássáv minden háziállat életereje alatt."
L["A thin strip under the minimap: gold, gear, bag space, friends online. Hover one for details, click it to open its window."] = "Vékony csík a minitérkép alatt: arany, felszerelés, táskahely, online barátok. Vidd fölé az egeret a részletekért, kattints rá az ablaka megnyitásához."
L["A thinner outline leaves more of each pip for the color. Set to 0 for none."] = "A vékonyabb körvonal több helyet hagy a jelölők színének. A 0 kikapcsolja."
L["A tooltip for something in the world (a creature, a player, a mailbox) fades away slowly after the mouse leaves it, as the game does. When off, it's gone at once."] = "A világban lévő dolgok (lény, játékos, postaláda) súgóbuboréka lassan elhalványul, miután az egér elhagyta, ahogy a játékban. Kikapcsolva azonnal eltűnik."
L["A trail of small diamonds from your feet to the marker, drifting toward it. Like the marker, it fades away once you're in the quest's area on the map."] = "Kis rombuszokból álló nyomvonal a lábadtól a jelölőig, felé sodródva. A jelölőhöz hasonlóan elhalványul, amint a küldetés területén vagy a térképen."
L["A two-minute tour of everything DaylightUI does, picking as you go. Nothing is saved until you finish."] = "Kétperces bemutató mindarról, amit a DaylightUI tud, közben választhatsz. Semmi sem mentődik, amíg be nem fejezed."
L["A warm line of light spreads across the top of the screen, your new level rolls in and what you gained fades in under it, in place of the game's banner. Follows Motion effects (General > Appearance)."] = "Meleg fénycsík terül szét a képernyő tetején, beúszik az új szinted, alatta pedig az, amit kaptál, a játék szalagja helyett. A Mozgáseffekteket követi (Általános > Megjelenés)."
L["A warning when your health or mana drops low."] = "Figyelmeztetés, ha az életerőd vagy manád alacsonyra esik."
L["A word or phrase"] = "Egy szó vagy kifejezés"
L["A word when a fight starts and ends."] = "Egy szó, amikor egy harc kezdődik és véget ér."
L["AVOIDABLE"] = "ELKERÜLHETŐ"
L["AWAY"] = "TÁVOL"
L["Abandon"] = "Feladás"
L["Abandon \"%s\"?"] = "Feladod: \"%s\"?"
L["Abandon?"] = "Feladod?"
L["About 1 in %d of your attacks hits for double damage."] = "Nagyjából minden %d. támadásod dupla sebzést okoz."
L["About 1 in %d of your shots hits for double damage."] = "Nagyjából minden %d. lövésed dupla sebzést okoz."
L["About 1 in %d of your spells lands a critical hit for half again as much."] = "Nagyjából minden %d. varázslatod kritikus találat, másfélszeres erővel."
L["Above"] = "Fölötte"
L["Above or below the frame: moves the bar sideways from the middle."] = "A keret fölött vagy alatt: oldalra tolja a sávot a középről."
L["Above or below the frame: moves the bar up or down."] = "A keret fölött vagy alatt: fel vagy le tolja a sávot."
L["Above the frame"] = "A keret fölött"
L["Above the health bar"] = "Az életerősáv fölött"
L["Above the name tab by default, running inward. Yours come first."] = "Alapból a névfül fölött, befelé haladva. A tieid jönnek előbb."
L["Absorb shields"] = "Elnyelő pajzsok"
L["Absorbs"] = "Elnyelések"
L["Accent"] = "Kiemelés"
L["Accent color"] = "Kiemelőszín"
L["Accent line on top"] = "Kiemelővonal felül"
L["Accept"] = "Elfogadás"
L["Accept key"] = "Elfogadás gombja"
L["Accept quests automatically"] = "Küldetések automatikus elfogadása"
L["Account"] = "Fiók"
L["Achievement announcements."] = "Achievement-bejelentések."
L["Achievement color"] = "Achievement-szín"
L["Achievements"] = "Achievementek"
L["Across"] = "Keresztben"
L["Across the bar"] = "A sávon át"
L["Across the bar keeps it inside. Any other spot puts it there, on or round the frame, so a long name has room. You can also drag it in Design mode."] = "A sávon át: belül tartja. Bármely más hely oda teszi, a keretre vagy köré, hogy a hosszú névnek is legyen helye. Tervező módban húzással is mozgathatod."
L["Across, you shown, by role, icons in corners"] = "Keresztben, te is látszol, szerep szerint, ikonok a sarkokban"
L["Action Bar 1"] = "1. akciósáv"
L["Action Bar 1 in %s"] = "1. akciósáv itt: %s"
L["Action Bar 2"] = "2. akciósáv"
L["Action Bar 3"] = "3. akciósáv"
L["Action Bar 4"] = "4. akciósáv"
L["Action Bar 5"] = "5. akciósáv"
L["Action Bar 6"] = "6. akciósáv"
L["Action Bar 7"] = "7. akciósáv"
L["Action Bar 8"] = "8. akciósáv"
L["Action Bars"] = "Akciósávok"
L["Action bars"] = "Akciósávok"
L["Action bars, short"] = "Akciósávok, röviden"
L["Activate"] = "Aktiválás"
L["Activate this set first."] = "Előbb aktiváld ezt a szettet."
L["Active spell"] = "Aktív varázslat"
L["Active spell color"] = "Aktív varázslat színe"
L["Active spell opacity"] = "Aktív varázslat átlátszatlansága"
L["Activity"] = "Aktivitás"
L["Add"] = "Hozzáadás"
L["Add a friend: a BattleTag (Name#1234) or a character's name."] = "Barát hozzáadása: BattleTag (Név#1234) vagy egy karakter neve."
L["Add a group"] = "Csoport hozzáadása"
L["Add friend"] = "Barát hozzáadása"
L["Add to favorites"] = "Hozzáadás a kedvencekhez"
L["Added with Add piece in Design mode. Drag it on the preview to move it. Up to three parts in one line, each in its own color."] = "Tervező módban a Darab hozzáadása gombbal került ide. Húzd az előnézeten a mozgatáshoz. Egy sorban legfeljebb három rész, mindegyik a saját színében."
L["Added with Add piece in Design mode: one more row of auras, with its own filter."] = "Tervező módban a Darab hozzáadása gombbal került ide: még egy sor aura, saját szűrővel."
L["Addon button drawer"] = "Addon-gombok fiókja"
L["Addon options (Ace3)"] = "Addon-beállítások (Ace3)"
L["Addons' minimap buttons and the game's addon menu are gathered into one drawer. The button in the map's bottom-right corner opens it."] = "Az addonok minitérkép-gombjai és a játék addonmenüje egy fiókba gyűlnek. A térkép jobb alsó sarkában lévő gomb nyitja."
L["Adds a warm band inside the black outline, lit along the top. When off, the border is a plain dark line."] = "Meleg sávot ad a fekete körvonalon belül, felül megvilágítva. Kikapcsolva a keret egy sima sötét vonal."
L["Adds about %.0f damage per second to your melee attacks."] = "Kb. %.0f sebzést ad másodpercenként a közelharci támadásaidhoz."
L["Adds about %.0f damage per second to your shots."] = "Kb. %.0f sebzést ad másodpercenként a lövéseidhez."
L["Adds up to %.0f to your heals."] = "Legfeljebb %.0f-et ad a gyógyításaidhoz."
L["Adds up to %.0f to your spells' damage."] = "Legfeljebb %.0f-et ad a varázslataid sebzéséhez."
L["Adventure"] = "Kaland"
L["After /reload, the last messages in each chat tab come back, above a gray line."] = "/reload után minden chatfül utolsó üzenetei visszajönnek, egy szürke vonal fölött."
L["After a login or /reload the UI starts invisible and glides in. Anything set to fade ends faded."] = "Belépés vagy /reload után a felület láthatatlanul indul, és beúszik. Ami elhalványulásra van állítva, halványan végez."
L["After combat"] = "Harc után"
L["After the fight"] = "A harc után"
L["Aggro color"] = "Aggro színe"
L["Aggro colors"] = "Aggro színei"
L["Agility"] = "Ügyesség"
L["Ah, a fresh face. Goldshire isn't what it was, with kobolds in every mine. Still, a man has to keep his shop."] = "Á, egy új arc. Goldshire már nem a régi, minden bányában koboldok. De azért a boltot vinni kell."
L["All"] = "Mind"
L["All %d spells snapped together"] = "Mind a(z) %d varázslat összeillesztve"
L["All activities"] = "Minden tevékenység"
L["Combat Text"] = "Harci szöveg"
L["Dishonorable kills"] = "Becstelen ölések"
L["Game Frames"] = "Játékkeretek"
L["Group Frames"] = "Csoportkeretek"
L["HONOR"] = "BECSÜLET"
L["Honorable kills"] = "Becsületes ölések"
L["Item level in the icon"] = "Tárgyszint az ikonon"
L["Its own setup guide, shown once after Daylight UI's. Run it again any time."] = "Saját beállítási útmutató, egyszer megjelenik a Daylight UI-é után. Bármikor újra futtathatod."
L["Keep as a log"] = "Naplóként megtart"
L["Landing welcome scale"] = "Érkezési üdvözlés mérete"
L["Landing welcome text size"] = "Érkezési üdvözlés szövegmérete"
L["Leader tools open toward"] = "A vezetői eszközök iránya"
L["Left out"] = "Kimaradt"
L["Lifetime"] = "Összesen"
L["Loot feed style"] = "Zsákmánysáv stílusa"
L["Main hand bar angled left end"] = "Főkéz-sáv ferde bal vége"
L["Main hand bar angled right end"] = "Főkéz-sáv ferde jobb vége"
L["Makes tooltips bigger or smaller, text and all, on top of Daylight UI scale (General > Appearance)."] = "Nagyobbra vagy kisebbre állítja a súgóbuborékokat, szöveggel együtt, a Daylight UI mérete fölött (Általános > Megjelenés)."
L["Message alignment"] = "Üzenetek igazítása"
L["Micro menu button backgrounds"] = "Mikromenü-gombok háttere"
L["Micro menu icon color"] = "Mikromenü-ikonok színe"
L["No challenges match."] = "Nincs illeszkedő kihívás."
L["Not saved yet"] = "Még nincs mentve"
L["Nudges the bar up or down from its spot beside the info panel, in pixels. Only while it's attached to the panel."] = "Fel vagy le tolja a sávot az infópanel melletti helyéről, pixelben. Csak amíg a panelhez van csatolva."
L["Nudges the rez icon sideways from its position."] = "Oldalra tolja a feltámasztás ikonját a helyéről."
L["Nudges the rez icon up or down from its position."] = "Fel vagy le tolja a feltámasztás ikonját a helyéről."
L["Off hand bar angled left end"] = "Mellékkéz-sáv ferde bal vége"
L["Off hand bar angled right end"] = "Mellékkéz-sáv ferde jobb vége"
L["Off-hand damage"] = "Mellékkéz sebzése"
L["On a flight path, where you're going and the time left float near the top of the screen, with the route and its stops as a line. Every route has a time from your first flight, and your own flights keep it exact. Move it with /dui unlock."] = "Repülési útvonalon az úti cél és a hátralévő idő a képernyő tetején lebeg, az útvonallal és a megállóival egy vonalon. Minden útvonal az első repülésedtől kap időt, a saját repüléseid pontosan tartják. A /dui unlock paranccsal mozgathatod."
L["Only the chat's messages stay over the world, each fading after a while, like Chat hides set to Always (Chat page). It stays even with Fade everything at the campfire on."] = "Csak a chat üzenetei maradnak a világ fölött, mindegyik egy idő után elhalványul, mint ha a Chat elrejtése Mindig értéken állna (Chat oldal). Akkor is marad, ha a Minden elhalványítása a tábortűznél be van kapcsolva."
L["Only the party leader can do this."] = "Ezt csak a csoportvezető teheti meg."
L["Overheal"] = "Túlgyógyítás"
L["Percent and health (62% | 4.1K)"] = "Százalék és életerő (62% | 4.1K)"
L["Percent and power (80% | 2.3K)"] = "Százalék és erőforrás (80% | 2.3K)"
L["Personal display angled left end"] = "Személyes kijelző ferde bal vége"
L["Personal display angled right end"] = "Személyes kijelző ferde jobb vége"
L["Pick Lock"] = "Zárfeltörés"
L["Pick it up for an action bar"] = "Vedd fel egy akciósávhoz"
L["Plays it now. Also /dui landing."] = "Most lejátssza. A /dui landing is ezt teszi."
L["Power bar angled at both ends"] = "Erőforrássáv mindkét végén ferde"
L["Power bar background"] = "Erőforrássáv háttere"
L["Power bar texture"] = "Erőforrássáv textúrája"
L["Preview the welcome on landing"] = "Érkezési üdvözlés előnézete"
L["Priority quest title in its color"] = "Kiemelt küldetés címe a saját színében"
L["Puts this font on the game's own text as well: menus, tooltips, quest text, popups, nameplate names. Sizes and outlines stay the game's. It's put on once as you log in, so a change here, or a new font above, shows on the game's text after a /reload."] = "Ezt a betűtípust a játék saját szövegeire is ráteszi: menük, súgóbuborékok, küldetésszöveg, felugró ablakok, névtábla-nevek. A méretek és körvonalak a játéké maradnak. Belépéskor egyszer kerül fel, így az itteni változás vagy egy új betűtípus fent csak /reload után látszik a játék szövegein."
L["Puts this profile back the way it comes: its settings and frame positions replace yours. Your Edit Mode layout stays as it is."] = "Visszaállítja ezt a profilt az alapállapotára: a beállításai és keretpozíciói felülírják a tieidet. A Szerkesztő mód elrendezésed marad, ahogy van."
L["PvP flag crest"] = "PvP-jelzés címer"
L["Quartermaster"] = "Szállásmester"
L["Quests ready to hand in leave their zones and gather in a Ready to turn in section under the rest, so the quests still to do stay on top. Nothing moves in a fight."] = "A leadható küldetések kikerülnek a zónáikból, és egy Leadható szakaszba gyűlnek a többi alatt, így a még elvégzendők maradnak felül. Harc közben semmi sem mozdul."
L["Ranged bar angled left end"] = "Távolsági sáv ferde bal vége"
L["Ranged bar angled right end"] = "Távolsági sáv ferde jobb vége"
