L["An Item Level line on weapon and armor tooltips, in soft gold."] = "Tárgyszint sor a fegyverek és páncélok súgóbuborékán, lágy aranyban."
L["An arrow on your screen that points to the nearest mob or object you still need for the quest you picked, then to the quest giver once it's ready, with the yards under it. Nothing goes on the map. Needs the QuestieDB addon."] = "Egy nyíl a képernyődön, ami a kiválasztott küldetéshez még szükséges legközelebbi lényre vagy tárgyra mutat, majd ha kész, a küldetésadóra, alatta a távolsággal yardban. A térképre semmi sem kerül. Kell hozzá a QuestieDB addon."
L["An item's green Equip lines in a few words (\"Improves your chance to hit by 1%\" reads \"+1% Hit\"), and every stat in a color of its own: each school, hit, crit, spell power, healing, the base stats. Procs and use effects stay as they are."] = "Egy tárgy zöld Equip sorai néhány szóban (az \"Improves your chance to hit by 1%\" így olvasható: \"+1% Hit\"), és minden statisztika saját színben: minden iskola, találat, kritikus, varázserő, gyógyítás, az alapstatisztikák. A procok és a használati hatások maradnak, ahogy vannak."
L["An objective you've finished."] = "Egy teljesített feladat."
L["An outline around its bar, a soft glow around it, or nothing."] = "Körvonal a sávja körül, lágy fény körülötte, vagy semmi."
L["Anchor: %s"] = "Horgony: %s"
L["And %d more"] = "És még %d"
L["And %d more: keep typing to narrow it down."] = "És még %d: gépelj tovább a szűkítéshez."
L["Angled"] = "Ferde"
L["Angled end"] = "Ferde vég"
L["Angled ends"] = "Ferde végek"
L["Another action bar whose shape and fade to copy onto the one picked in Settings for."] = "Egy másik akciósáv, aminek az alakját és elhalványítását átmásolod arra, amelyik a Beállítások ehhez mezőben ki van választva."
L["Another bar whose look to copy onto the one picked in Settings for."] = "Egy másik sáv, aminek a kinézetét átmásolod arra, amelyik a Beállítások ehhez mezőben ki van választva."
L["Another layout to copy: your other talent set, your other characters', or a layout from before layouts were per character."] = "Egy másik másolandó elrendezés: a másik tehetségszetted, a többi karaktered elrendezése, vagy egy a karakterenkénti elrendezések előtti."
L["Another thing after the first on the same line, like the level after a name."] = "Még valami az első után ugyanabban a sorban, például a szint a név után."
L["Answers whispers for you, once per person every 15 minutes."] = "Válaszol helyetted a suttogásokra, személyenként 15 percenként egyszer."
