L["As a tank: the mob is attacking someone else. As damage or healer: it's attacking you."] = "Tankként: a mob valaki mást támad. Sebzőként vagy gyógyítóként: téged támad."
L["As a tank: you're about to lose the mob. As damage or healer: you're close to pulling it."] = "Tankként: mindjárt elveszíted a mobot. Sebzőként vagy gyógyítóként: közel vagy ahhoz, hogy magadra húzd."
