L["At the level cap it shows the reputation you're watching. Before that, it turns to that faction for a few seconds when you gain reputation, and while the mouse is over it."] = "A szintplafonon a figyelt hírnevet mutatja. Addig néhány másodpercre arra a frakcióra vált, amikor hírnevet kapsz, és amíg az egér rajta van."
