L["Automatic is your Appearance font when \"Use this font for the game's text\" is on, else the game's own. The sample above shows it at once; the numbers in the world change after you log out to the character screen and back in."] = "Az Automatikus a Megjelenés betűtípusa, ha \"A játék szövegeihez is ez a betűtípus\" be van kapcsolva, különben a játék saját betűtípusa. A fenti minta azonnal mutatja; a világban lévő számok csak akkor változnak, ha kilépsz a karakterválasztóba és vissza."
L["Automatic uses the same font as your damage numbers. Changes at once, no relog needed."] = "Az Automatikus ugyanazt a betűtípust használja, mint a sebzésszámaid. Azonnal változik, nem kell újra belépni."
