L["Cuts both ends of each line at an angle. When off, the ends are straight."] = "Minden sor mindkét végét ferdén levágja. Kikapcsolva a végek egyenesek."
L["Cuts each tile's right end at an angle, like your own frame; the bars follow it."] = "Minden csempe jobb végét ferdén levágja, mint a saját keretedet; a sávok követik."
