L["Cuts the end of your focus's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "A fókuszod varázslássávjának végét ferdén levágja. Kikapcsolva a vége egyenes. Nem, ha a kereten belül ül."
L["Cuts the end of your target's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "A célpontod varázslássávjának végét ferdén levágja. Kikapcsolva a vége egyenes. Nem, ha a kereten belül ül."
