L["Cuts the right end at an angle; the bars follow it."] = "A jobb végét ferdén levágja; a sávok követik."
L["Cutscenes and intro movies end at once. Hold Shift as one starts to watch it."] = "A bejátszások és bevezető videók azonnal véget érnek. Tartsd lenyomva a Shiftet, amikor egy elindul, ha meg akarod nézni."
