L["Daylight UI couldn't skin %s %s: it's left as it is."] = "A Daylight UI nem tudta átszínezni ezt: %s %s; marad, ahogy van."
L["Daylight UI's journal, marker and arrow stay either way. You can change it later on the Quests options page."] = "A Daylight UI naplója, jelölője és nyila így is, úgy is marad. Később a Küldetések beállításoldalon módosíthatod."
L["Daylight gradient"] = "Daylight színátmenet"
L["Daylight is the warm band inside a dark outline, Flat a plain outline. With None the icon fills the whole button."] = "A Daylight a sötét körvonalon belüli meleg sáv, a Lapos egy sima körvonal. A Nincs esetén az ikon kitölti az egész gombot."
L["Daylight look"] = "Daylight kinézet"
L["Daylight: Daylight UI's own chat box, with its own tabs. Classic: the game's chat windows and tabs in the Daylight look. Switching is instant, and both keep every message."] = "Daylight: a Daylight UI saját chatdoboza, saját fülekkel. Klasszikus: a játék chatablakai és fülei Daylight kinézetben. A váltás azonnali, és mindkettő megtart minden üzenetet."
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Each frame can pick its own on its page."] = "Daylight: a keret a nevével egy fülben fölötte, benne az erőforrássávval. Szalag: vékony sáv, fölötte lebeg a név és az életerő, alatta vékony vonalként az erőforrás. Minden keret a saját oldalán választhat magának."
L["DaylightMogul's mailbox is in use."] = "A DaylightMogul postaládája használatban van."
L["DaylightMogul's profession window is in use."] = "A DaylightMogul szakmaablaka használatban van."
L["DaylightMogul's vendor window is in use."] = "A DaylightMogul árusablaka használatban van."
L["DaylightUI (General)"] = "DaylightUI (Általános)"
L["DaylightUI has a new setup guide. Take the tour to see everything it can do, or keep your setup as it is."] = "A DaylightUI-nak új beállítási útmutatója van. Nézd végig a bemutatót, hogy lásd, mit tud, vagy tartsd meg a beállításaidat, ahogy vannak."
L["DaylightUI is set up on this character. Reload to put it in place?"] = "A DaylightUI be van állítva ezen a karakteren. Újratöltöd, hogy életbe lépjen?"
L["DaylightUI moved the quest tracker to fit the panel. Reload to put it in place?"] = "A DaylightUI áthelyezte a küldetéskövetőt, hogy illeszkedjen a panelhez. Újratöltöd, hogy életbe lépjen?"
L["DaylightUI put this profile's Edit Mode layout in place. Reload to use it?"] = "A DaylightUI beállította ennek a profilnak a Szerkesztő mód elrendezését. Újratöltöd a használatához?"
L["DaylightUI replaces your frames, bars, bags, chat and more with a soft, minimal look. Let's set this character up."] = "A DaylightUI puha, minimalista kinézetre cseréli a kereteidet, sávjaidat, táskáidat, chatedet és még sok mást. Állítsuk be ezt a karaktert."
L["DaylightUI saved the crowd control alert's position. Reload to put it in place?"] = "A DaylightUI elmentette a tömegirányítás-riasztás helyét. Újratöltöd, hogy életbe lépjen?"
L["DaylightUI saved the loot window's position. Reload to put it in place?"] = "A DaylightUI elmentette a zsákmányablak helyét. Újratöltöd, hogy életbe lépjen?"
L["DaylightUI saved the quest tracker's position. Reload to put it in place?"] = "A DaylightUI elmentette a küldetéskövető helyét. Újratöltöd, hogy életbe lépjen?"
L["DaylightUI saved these positions. Reload to put them in place?"] = "A DaylightUI elmentette ezeket a pozíciókat. Újratöltöd, hogy életbe lépjenek?"
L["DaylightUI tracker (works with Questie)"] = "DaylightUI követő (Questie-vel is működik)"
L["DaylightUI updated its layout. Reload to put it in place?"] = "A DaylightUI frissítette az elrendezését. Újratöltöd, hogy életbe lépjen?"
