L["Drag it to an action bar."] = "Húzd egy akciósávra."
L["Drag the pieces of the preview to move them: each stays where you let go, or catches on a dot right beside it. Click one, and the arrow keys nudge it (Shift for bigger steps). Every move changes the same settings as the cards below."] = "Húzd az előnézet darabjait a mozgatáshoz: mindegyik ott marad, ahol elengeded, vagy beakad egy mellette lévő pontra. Kattints egyre, és a nyílgombok finoman mozgatják (Shifttel nagyobbat lép). Minden mozgatás ugyanazokat a beállításokat változtatja, mint az alábbi kártyák."
L["Drag to move it, or click for its settings."] = "Húzd a mozgatáshoz, vagy kattints a beállításaiért."
L["Drag to move. Drop it beside another piece to hook it on, drag it away to free it. Delete removes it."] = "Húzd a mozgatáshoz. Egy másik darab mellé ejtve hozzáakad, elhúzva leválik. A Törlés eltávolítja."
L["Dragon around the portrait"] = "Sárkány a portré körül"
L["Dragon color"] = "Sárkány színe"
L["Drop an item here"] = "Tegyél ide egy tárgyat"
L["Druid mana in forms"] = "Druid mana formákban"
L["Dungeon"] = "Kazamata"
L["Dungeon Journal"] = "Kazamatanapló"
L["Dungeon and raid entrances"] = "Kazamata- és raidbejáratok"
L["Dungeon tag color"] = "Kazamata-címke színe"
L["Dungeons, raids and battlegrounds"] = "Kazamaták, raidek és csataterek"
L["Durability"] = "Tartósság"
L["Durability %s"] = "Tartósság: %s"
L["During a ready check, a tick, a cross or a question mark on each member: ready, not ready, or no answer yet. They stay a few seconds after the check ends."] = "Készenléti ellenőrzés közben pipa, kereszt vagy kérdőjel minden tagon: kész, nem kész, vagy még nem válaszolt. Az ellenőrzés vége után még néhány másodpercig maradnak."
L["ENEMY TAKEN"] = "ELLENSÉG KAPOTT"
L["Each bar in its player's class color, or all in one color."] = "Minden sáv a játékosa kasztszínében, vagy mind egy színben."
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar."] = "Minden sáv keze (vagy a sorban álló támadás) és a következő ütésig hátralévő idő, a sávra írva."
L["Each bar's shape and when it shows. Changes apply at once. Move bars in unlock mode."] = "Minden sáv alakja, és mikor látszik. A változások azonnal érvényesek. A sávokat feloldott módban mozgathatod."
L["Each bar's size, shape and when it shows. Pick the bar with Settings for."] = "Minden sáv mérete, alakja, és mikor látszik. A sávot a Beállítások ehhez mezőben választod."
L["Each character uses a profile (one per talent set, with dual spec). Everything on every page changes the profile in use."] = "Minden karakter egy profilt használ (tehetségszettenként egyet, kettős specializációval). Minden oldalon minden a használt profilt módosítja."
L["Each combo point you build on your target."] = "Minden kombópont, amit a célpontodon gyűjtesz."
L["Each icon darkens like a clock as its time runs out."] = "Minden ikon órához hasonlóan sötétedik, ahogy fogy az ideje."
L["Each icon's width and height."] = "Minden ikon szélessége és magassága."
L["Each item's name and item level next to its icon. When off, only the icons show, with the item level in each corner and more room for the model."] = "Minden tárgy neve és tárgyszintje az ikonja mellett. Kikapcsolva csak az ikonok látszanak, a sarkukban a tárgyszinttel, és több hely jut a modellnek."
L["Each its own"] = "Mind a sajátját"
L["Each main-hand swing hits for %.0f to %.0f before armor."] = "Minden főkezes ütés %.0f - %.0f sebzést okoz a páncél előtt."
L["Each member's health written on their tile."] = "Minden tag életereje a csempéjére írva."
L["Each member's name on their tile."] = "Minden tag neve a csempéjén."
L["Each new message fades in instead of appearing at once. Never in a fight."] = "Minden új üzenet beúszik, nem azonnal jelenik meg. Harcban soha."
L["Each objective line under a quest."] = "Minden feladatsor egy küldetés alatt."
L["Each person who whispers you gets a tab next to the others, and the whisper shows in your main tab as well. When off, whispers only show in the main tab."] = "Mindenki, aki suttog neked, saját fület kap a többi mellett, és a suttogás a fő fülön is megjelenik. Kikapcsolva a suttogások csak a fő fülön látszanak."
L["Each pip leans like the frames' angled ends. When off, their ends are straight."] = "Minden jelölő a keretek ferde végeihez hasonlóan dől. Kikapcsolva a végük egyenes."
L["Each pip's end cut at an angle, like the health bar's."] = "Minden jelölő vége ferdén levágva, mint az életerősávé."
L["Each quest's level in front of its title, like [15]."] = "Minden küldetés szintje a címe előtt, például [15]."
L["Each quest's title in the tracker."] = "Minden küldetés címe a követőben."
L["Each shot hits for %.0f to %.0f before armor."] = "Minden lövés %.0f - %.0f sebzést okoz a páncél előtt."
L["Each talent set has its own layout. Edit layout and Copy from work on this one."] = "Minden tehetségszettnek saját elrendezése van. Az Elrendezés szerkesztése és a Másolás innen erre vonatkozik."
L["Each text updates as it changes. Hover for details: gold on every character, each piece of gear, each bag, who's online."] = "Minden szöveg frissül, ahogy változik. Vidd fölé az egeret a részletekért: arany minden karakteren, minden felszerelésdarab, minden táska, ki van online."
L["Each threat bar in its player's class color, or all in one color."] = "Minden fenyegetéssáv a játékosa kasztszínében, vagy mind egy színben."
L["Early start"] = "Korai kezdés"
L["Earned"] = "Megszerzett"
L["Earned this session"] = "Ebben a menetben szerzett"
L["Eases class, reaction and power colors toward gray for a gentler look."] = "A kaszt-, viszony- és erőforrásszíneket a szürke felé tolja a lágyabb kinézetért."
L["Edit"] = "Szerkesztés"
L["Edit Mode hasn't loaded its layouts yet; try again in a moment"] = "A Szerkesztő mód még nem töltötte be az elrendezéseit; próbáld újra egy pillanat múlva"
L["Edit Mode is open; close it first"] = "A Szerkesztő mód nyitva van; előbb zárd be"
L["Edit layout"] = "Elrendezés szerkesztése"
L["Edit listing"] = "Hirdetés szerkesztése"
L["Edit on screen"] = "Szerkesztés a képernyőn"
L["Effects"] = "Effektek"
L["Eight candles, and hardly a dent in them! Here, pick something for your trouble."] = "Nyolc gyertya, és alig fogytak! Tessék, válassz valamit a fáradságodért."
L["Elite"] = "Elit"
L["Elite and rare crest"] = "Elit és ritka címer"
L["Elite crest"] = "Elit címer"
L["Elite dragon"] = "Elit sárkány"
L["Elite or rare"] = "Elit vagy ritka"
L["Elite tag color"] = "Elit címke színe"
L["Emote color"] = "Emote-szín"
L["Emotes"] = "Emote-ok"
L["Emotes like /wave and /e text."] = "Emote-ok, mint a /wave és a /e szöveg."
L["Empty"] = "Üres"
L["Empty slots"] = "Üres helyek"
L["Enchant"] = "Bűvölés"
L["Enchant all"] = "Mind bűvölése"
L["Enchant on"] = "Bűvölés erre"
L["End"] = "Vége"
L["Ends in %d day"] = "%d nap múlva véget ér"
L["Ends in %d days"] = "%d nap múlva véget ér"
L["Ends in %d hour"] = "%d óra múlva véget ér"
L["Ends in %d hours"] = "%d óra múlva véget ér"
L["Ends within the hour"] = "Egy órán belül véget ér"
L["Enemy damage taken"] = "Ellenség kapott sebzése"
L["Enemy pets and totems"] = "Ellenséges háziállatok és totemek"
L["Enemy pets and totems get a look of their own, totems in their element's color. In battlegrounds they're all red: the game hides which totem it is. When off, the game's setting for their plates is turned off too."] = "Az ellenséges háziállatok és totemek saját kinézetet kapnak, a totemek az elemük színében. Csatatéren mind piros: a játék elrejti, melyik totemről van szó. Kikapcsolva a játék névtábla-beállítása is kikapcsol rájuk."
L["Energy"] = "Energia"
L["Enter or Space"] = "Enter vagy Szóköz"
L["Enter says yes when someone asks you something: a group invite, a shared quest, a summon, a resurrect. Never on anything that binds, rolls or costs, and never in combat. Making an inn your home takes your Accept key too."] = "Az Enter igent mond, amikor valaki kérdez valamit: csoportmeghívás, megosztott küldetés, idézés, feltámasztás. Soha semmire, ami kötődik, dobással jár vagy pénzbe kerül, és harcban soha. A fogadó otthonná tétele is az Elfogadás gombodat használja."
L["Entering and leaving combat"] = "Harc kezdete és vége"
L["Epic (purple) and up"] = "Epikus (lila) és jobb"
L["Epic mount fund: %d%%. Keep saving!"] = "Epikus hátas alap: %d%%. Csak így tovább!"
L["Equipment sets"] = "Felszerelés-szettek"
L["Equipped"] = "Felszerelve"
L["Error messages"] = "Hibaüzenetek"
L["Error text"] = "Hibaszöveg"
L["Every area's fade in one place: in combat, on mouseover, or always shown."] = "Minden terület elhalványítása egy helyen: harcban, egér alatt, vagy mindig látható."
L["Every bag in one window, with search, sorting and categories."] = "Minden táska egy ablakban, kereséssel, rendezéssel és kategóriákkal."
L["Every color in the quest tracker."] = "A küldetéskövető minden színe."
L["Every debuff on you, over your frame. Off by default: your buff bars show them too."] = "Minden rajtad lévő debuff a kereted fölött. Alapból ki van kapcsolva: a buff-sávjaid is mutatják őket."
L["Every empty slot"] = "Minden üres hely"
L["Every font"] = "Minden betűtípus"
L["Every hand's bar in your class color, or your class's gradient with a two-color fill. A queued attack keeps its own color. Not with the Daylight gradient."] = "Minden kéz sávja a kasztszínedben, vagy kétszínű kitöltésnél a kasztod színátmenetében. A sorban álló támadás megtartja a saját színét. A Daylight színátmenettel nem."
L["Every health bar's color when Health bar color is One color."] = "Minden életerősáv színe, ha az Életerősáv színe beállítás Egy szín."
L["Every item you dragged onto a group, or moved with Alt-right-click, goes back to its own group."] = "Minden tárgy, amit egy csoportra húztál vagy Alt+jobb klikkel áthelyeztél, visszakerül a saját csoportjába."
L["Every line in the tooltips. General uses the font on General > Appearance."] = "A súgóbuborékok minden sora. Az Általános az Általános > Megjelenés betűtípusát használja."
L["Every line stays until the newest one's time is up, then they all go. When off, each line leaves on its own."] = "Minden sor marad, amíg a legújabb ideje le nem jár, aztán mind eltűnik. Kikapcsolva minden sor magától távozik."
L["Every other row on a faint stripe, in the stats and the long lists, so lines are easier to follow."] = "Minden második sor halvány csíkon, a statisztikákban és a hosszú listákban, hogy könnyebb legyen követni a sorokat."
L["Every part of DaylightUI and what it does. Switch off any you don't want; that applies when you reload."] = "A DaylightUI minden része, és mit csinál. Kapcsold ki, amire nincs szükséged; újratöltéskor érvényesül."
L["Every part's fade in one place. Each is the same setting as on that part's own page."] = "Minden rész elhalványítása egy helyen. Mindegyik ugyanaz a beállítás, mint az adott rész saját oldalán."
L["Every power bar's color when Power bar color is One color."] = "Minden erőforrássáv színe, ha az Erőforrássáv színe beállítás Egy szín."
L["Every quest in your log"] = "Minden küldetés a naplódban"
L["Every quest title's color while Quest title color is set to One color."] = "Minden küldetéscím színe, amíg a Küldetéscím színe Egy szín értéken áll."
L["Every reward earned."] = "Minden megszerzett jutalom."
L["Every setting for this piece"] = "Minden beállítás ehhez a darabhoz"
L["Every text in the loot feed. General uses the font on General > Appearance."] = "A zsákmánysáv minden szövege. Az Általános az Általános > Megjelenés betűtípusát használja."
L["Every text in the quest tracker. General uses the font on General > Appearance."] = "A küldetéskövető minden szövege. Az Általános az Általános > Megjelenés betűtípusát használja."
L["Every texture"] = "Minden textúra"
L["Every tracked quest, only the zone you're in, or every quest in your log without tracking them. The controls over the list switch the first two."] = "Minden követett küldetés, csak az aktuális zónád, vagy a naplód minden küldetése követés nélkül. A lista fölötti vezérlők az első kettő között váltanak."
L["Everyday"] = "Hétköznapi"
