L["Fade everything at the campfire"] = "Minden elhalványítása a tábortűznél"
L["Fade in"] = "Beúszás"
L["Fade in combat"] = "Elhalványítás harcban"
L["Fade in on login"] = "Beúszás belépéskor"
L["Fade only in the open world"] = "Elhalványítás csak a nyílt világban"
L["Fade other plates"] = "Más névtáblák halványítása"
L["Fade out"] = "Kihalványulás"
L["Fade out of combat"] = "Elhalványítás harcon kívül"
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP)."] = "Elhalványítás harcon kívül: harc után egy idővel elhalványul, harcban visszajön. Elhalványítás harcban: harcba lépve egy idővel elhalványul, utána visszajön. Elhalványítás egér alá vitelig: halvány marad, amíg az egér rá nem kerül. Csak változáskor: harcon kívül eltűnik, harcban visszajön, és változáskor egy pillanatra visszajön (buff kapása vagy elvesztése, életerő, küldetéshaladás, XP)."
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP). Hidden (in combat, out of combat or always): gone, and its buttons can't be clicked."] = "Elhalványítás harcon kívül: harc után egy idővel elhalványul, harcban visszajön. Elhalványítás harcban: harcba lépve egy idővel elhalványul, utána visszajön. Elhalványítás egér alá vitelig: halvány marad, amíg az egér rá nem kerül. Csak változáskor: harcon kívül eltűnik, harcban visszajön, és változáskor egy pillanatra visszajön (buff kapása vagy elvesztése, életerő, küldetéshaladás, XP). Rejtett (harcban, harcon kívül vagy mindig): eltűnik, és a gombjai nem kattinthatók."
L["Fade the UI while talking"] = "Felület halványítása beszélgetés közben"
L["Fade the icon"] = "Ikon halványítása"
L["Fade to"] = "Halványítás eddig"
L["Fade until mouseover"] = "Elhalványítás egér alá vitelig"
L["Fade when out of range"] = "Halványítás hatótávon kívül"
L["Faded opacity"] = "Halványított átlátszatlanság"
L["Fades only while your health is full; comes back as soon as it drops. Show on mouseover still works."] = "Csak teli életerőnél halványul el; amint csökken, visszajön. Az Egér alatt megjelenik továbbra is működik."
L["Fades only while your pet's health is full; comes back as soon as it drops. Show on mouseover still works."] = "Csak a háziállatod teli életerejénél halványul el; amint csökken, visszajön. Az Egér alatt megjelenik továbbra is működik."
