L["Hide shows the spell only while it's on cooldown. It keeps its gap: the other spells don't move."] = "Az Elrejtés csak akkor mutatja a varázslatot, amíg cooldownon van. Megtartja a helyét: a többi varázslat nem mozdul."
L["Hide shows the spell only while it's on cooldown. Only when usable shows it once you can cast it: Riposte after a parry, Overpower after a dodge, Execute on a low target. Both keep the gap: the other spells don't move."] = "Az Elrejtés csak akkor mutatja a varázslatot, amíg cooldownon van. A Csak ha használható akkor mutatja, amikor elvarázsolhatod: Riposte hárítás után, Overpower kitérés után, Execute alacsony életerejű célponton. Mindkettő megtartja a helyét: a többi varázslat nem mozdul."
L["Hide while mounted"] = "Elrejtés hátason"
L["Hides the higher raid groups, e.g. 4 for a 20-player raid."] = "Elrejti a magasabb sorszámú raidcsoportokat, pl. 4-et egy 20 fős raidnél."
L["Hides the red text and voice line from pressing a button too soon: not enough rage, mana or energy, not ready yet, out of range, no target. The useful ones still show: bags full, interrupted, line of sight, quest messages."] = "Elrejti a piros szöveget és a hangot, ami túl korai gombnyomásra jön: nincs elég düh, mana vagy energia, még nem kész, hatótávon kívül, nincs célpont. A hasznosak továbbra is látszanak: tele a táska, megszakítva, nincs rálátás, küldetésüzenetek."
