L["Hover a button and press a key to bind it, or Escape to clear it. Click Okay when you're done. Out of combat only."] = "Vidd az egeret egy gomb fölé, és nyomj meg egy billentyűt a kiosztáshoz, vagy Escape a törléshez. Ha végeztél, kattints az Oké gombra. Csak harcon kívül."
L["Hover a setting to see what it does; the arrow beside a changed setting puts it back."] = "Vidd az egeret egy beállítás fölé, hogy lásd, mit csinál; a módosított beállítás melletti nyíl visszaállítja."
L["Hover it for buttons: the fight (overall, current, and earlier fights by name), the mode, and reset."] = "Vidd fölé az egeret a gombokért: a harc (összes, jelenlegi és a korábbiak név szerint), a mód és a visszaállítás."
L["Hovering an item, spell or quest link in chat shows its tooltip, just above the chat."] = "A chatben egy tárgy-, varázslat- vagy küldetéslink fölé víve megjelenik a súgóbuboréka, közvetlenül a chat fölött."
L["How big a crit on you pops. It starts at half this and settles back. The game's own is 60."] = "Mekkorára pattan a rajtad ért kritikus találat. Ennek felénél kezd, majd visszaáll. A játék sajátja 60."
