L["How big each item slot is in the bag."] = "Mekkora minden tárgyhely a táskában."
L["How big each item slot is in the bank."] = "Mekkora minden tárgyhely a bankban."
L["How big it is, as a percent of its normal size. This is Edit Mode's own size setting, kept in your Edit Mode layout."] = "Mekkora, a normál méretének százalékában. Ez a Szerkesztő mód saját méretbeállítása, a Szerkesztő mód elrendezésedben tárolva."
L["How big the PvP flag is."] = "Mekkora a PvP-jelzés."
L["How big the arrow is on your screen, yards text included."] = "Mekkora a nyíl a képernyődön, a yard-szöveggel együtt."
L["How big the clock is."] = "Mekkora az óra."
L["How big the corner crown is."] = "Mekkora a sarokkorona."
L["How big the crowd control icon is."] = "Mekkora a tömegirányítás ikonja."
L["How big the data texts are."] = "Mekkorák az adatszövegek."
L["How big the framerate is."] = "Mekkora a képkockasebesség."
L["How big the health text is on this frame."] = "Mekkora az életerő-szöveg ezen a kereten."
L["How big the health text on the tiles is."] = "Mekkora az életerő-szöveg a csempéken."
L["How big the icons of buffs you can purge or steal are."] = "Mekkorák a levehető vagy ellopható buffok ikonjai."
L["How big the item names, counts and skill-up text are in the loot feed."] = "Mekkorák a tárgynevek, a darabszámok és a jártasság-szöveg a zsákmánysávban."
L["How big the large health number is."] = "Mekkora a nagy életerőszám."
L["How big the leader crown is."] = "Mekkora a vezetői korona."
L["How big the leader's crown is."] = "Mekkora a vezető koronája."
L["How big the name is on this frame."] = "Mekkora a név ezen a kereten."
L["How big the names on the tiles are."] = "Mekkorák a nevek a csempéken."
L["How big the pets' health text is."] = "Mekkora a háziállatok életerő-szövege."
L["How big the pets' names are."] = "Mekkorák a háziállatok nevei."
L["How big the portrait ring is next to the frame's height."] = "Mekkora a portrégyűrű a keret magasságához képest."
L["How big the quest marker is in the world, distance text included."] = "Mekkora a küldetésjelölő a világban, a távolság-szöveggel együtt."
L["How big the raid marker is."] = "Mekkora a raidjelölő."
L["How big the ready check answer is."] = "Mekkora a készenléti válasz."
L["How big the resting Zzz is."] = "Mekkora a pihenés Zzz-je."
L["How big the role icon is."] = "Mekkora a szerepikon."
L["How big the round badge of an enemy pet or totem is."] = "Mekkora egy ellenséges háziállat vagy totem kerek jelvénye."
L["How big the square minimap is."] = "Mekkora a szögletes minitérkép."
L["How big the window is."] = "Mekkora az ablak."
L["How big the window is. Other windows still open beside it when they fit."] = "Mekkora az ablak. Más ablakok továbbra is mellette nyílnak, ha elférnek."
L["How big this extra text is."] = "Mekkora ez az extra szöveg."
L["How big your buff icons on friendly plates are."] = "Mekkorák a buff-ikonjaid a barátságos névtáblákon."
L["How big your debuff icons are."] = "Mekkorák a debuff-ikonjaid."
L["How bright the light behind the arrow is."] = "Milyen erős a fény a nyíl mögött."
L["How bright the pips you haven't filled are, as a share of their color. Lower makes the filled ones stand out more."] = "Milyen világosak a ki nem töltött jelölők a színükhöz képest. Kisebb értéknél a kitöltöttek jobban kiugranak."
L["How bright the unexplored areas are. At 100% they look like the parts you've explored."] = "Milyen világosak a felfedezetlen területek. 100%-nál olyanok, mint a felfedezett részek."
L["How dark the shade that sweeps over a button on cooldown is."] = "Milyen sötét a cooldownon lévő gombon átsöprő árnyék."
L["How far above the cursor the tooltip's corner sits (below zero: lower down)."] = "Milyen messze ül a súgóbuborék sarka a kurzor fölött (nulla alatt: lejjebb)."
L["How far away plates show, in yards. 60 is the most the game allows."] = "Milyen messziről látszanak a névtáblák, yardban. A 60 a játék által engedett maximum."
L["How far from the target the numbers start."] = "Milyen messze indulnak a számok a célponttól."
L["How far it fades. At 0 it disappears fully. Never more than Opacity."] = "Mennyire halványul el. 0-nál teljesen eltűnik. Sosem több az Átlátszatlanságnál."
L["How far past the name and bar a click still selects the unit."] = "Milyen messze a néven és a sávon túl választja még ki egy kattintás az egységet."
L["How far right of the cursor the tooltip's corner sits (below zero: to the left)."] = "Milyen messze ül a súgóbuborék sarka a kurzortól jobbra (nulla alatt: balra)."
L["How far the camera can zoom out. 100% is the game's normal limit; the far right end is as far as this client allows. At 100% the game's own setting is left alone."] = "Milyen messzire tud kizoomolni a kamera. A 100% a játék normál határa; a jobb szélső érték az, amit ez a kliens enged. 100%-nál a játék saját beállítása érintetlen marad."
L["How far the frames' angled ends lean, on every unit frame and cast bar. 21% is the usual look."] = "Mennyire dőlnek a keretek ferde végei minden egységkereten és varázslássávon. A 21% a szokásos kinézet."
L["How far the name tab's shadow spreads. 0 leaves no shadow."] = "Milyen messzire terül a névfül árnyéka. A 0 árnyék nélkül hagyja."
L["How far the numbers fly out to the sides. At 0 they go straight up, the game's own way."] = "Milyen messzire repülnek oldalra a számok. 0-nál egyenesen felfelé mennek, ahogy a játékban."
L["How far the panel reaches past the buttons on every side."] = "Mennyire nyúlik túl a panel a gombokon minden oldalon."
L["How far this frame's shadow spreads. 0 leaves no shadow."] = "Milyen messzire terül ennek a keretnek az árnyéka. A 0 árnyék nélkül hagyja."
L["How far through the level you are, e.g. 24%. With the numbers on too, it sits between them and the rested XP."] = "Hol jársz a szinten belül, pl. 24%. Ha a számok is be vannak kapcsolva, közöttük és a pihent XP között ül."
L["How far through the standing you are, e.g. 60%."] = "Hol jársz a hírnévszinten belül, pl. 60%."
L["How health and power numbers are written on unit frames, extra texts and nameplates. Percents stay as they are."] = "Hogyan íródnak ki az életerő- és erőforrásszámok az egységkereteken, az extra szövegekben és a névtáblákon. A százalékok maradnak, ahogy vannak."
L["How long a new item stays in Recent before it goes to its own group."] = "Mennyi ideig marad egy új tárgy a Friss csoportban, mielőtt a sajátjába kerül."
L["How long each buff and debuff has left, on the top edge of its icon."] = "Mennyi ideje van hátra minden buffnak és debuffnak, az ikonja felső szélén."
L["How low the enemy's health has to be."] = "Milyen alacsony legyen az ellenség életereje."
L["How many bars sit on your screen. Each one can be changed on its own later."] = "Hány sáv van a képernyődön. Később mindegyik külön módosítható."
L["How many buttons this bar shows."] = "Hány gombot mutat ez a sáv."
L["How many data texts share the strip. Pick what each shows under Slots."] = "Hány adatszöveg osztozik a csíkon. Hogy melyik mit mutat, azt a Helyek alatt választod."
L["How many people's tiles slide out beside the chat at most."] = "Legfeljebb hány ember csempéje csúszik ki a chat mellé."
L["How many rows the buttons wrap into (columns when the bar is vertical)."] = "Hány sorba tördelődnek a gombok (függőleges sávnál oszlopba)."
L["How many slots fit in each row of the bag. More columns make it wider and shorter."] = "Hány hely fér a táska egy sorába. Több oszloppal szélesebb és alacsonyabb."
L["How much a block, absorb or resist saved you."] = "Mennyit mentett meg egy blokk, elnyelés vagy ellenállás."
L["How much of the health bar's width the row spans, centered."] = "Az életerősáv szélességének mekkora részét fogja át a sor, középre igazítva."
L["How much the shield can still soak, at the bar's right end."] = "Mennyit tud még elnyelni a pajzs, a sáv jobb végén."
L["How much the shield can still soak, on the icon in place of its time. Its size and color are the cooldown numbers'."] = "Mennyit tud még elnyelni a pajzs, az ikonon az ideje helyett. A mérete és színe a cooldown-számoké."
L["How objective lines show their progress: in the colors below, green once done, or shading from red to green as the count fills."] = "Hogyan mutatják a feladatsorok a haladásukat: az alábbi színekben, zölden ha kész, vagy pirosból zöldbe színeződve, ahogy telik a számláló."
L["How round the name tab's corners are. 0 keeps them sharp."] = "Mennyire kerekek a névfül sarkai. A 0 élesen hagyja őket."
L["How round this frame's corners are. 0 keeps them sharp."] = "Mennyire kerekek ennek a keretnek a sarkai. A 0 élesen hagyja őket."
L["How see-through a frame gets while its unit is out of range."] = "Mennyire áttetsző egy keret, amíg az egysége hatótávon kívül van."
L["How see-through a spell set to Fade gets, ready or on cooldown."] = "Mennyire áttetsző egy Halványítás beállítású varázslat, készen vagy cooldownon."
L["How see-through a spell set to Fade gets."] = "Mennyire áttetsző egy Halványítás beállítású varázslat."
L["How see-through a spell's icon is while it's on cooldown. The global cooldown doesn't count."] = "Mennyire áttetsző egy varázslat ikonja, amíg cooldownon van. A globális cooldown nem számít."
L["How see-through every window and panel is: bags, character, spellbook, NPC, group finder, the game's windows we restyle, and chat, the info panel, the quest box and the buff bars unless they have a separate one on their pages."] = "Mennyire áttetsző minden ablak és panel: táskák, karakter, varázskönyv, NPC, csoportkereső, a játék általunk átszínezett ablakai, valamint a chat, az infópanel, a küldetésdoboz és a buff-sávok, hacsak nincs saját beállításuk az oldalukon."
L["How see-through it is while shown, whatever the fade does."] = "Mennyire áttetsző, amíg látszik, bármit is csinál az elhalványítás."
L["How see-through party and raid frames get while a member is out of range."] = "Mennyire áttetszők a csoport- és raidkeretek, amíg egy tag hatótávon kívül van."
L["How see-through the info panel's boxes and the meters' own windows are."] = "Mennyire áttetszők az infópanel dobozai és a mérők saját ablakai."
L["How see-through the other plates get while you have a target."] = "Mennyire áttetszők a többi névtábla, amíg van célpontod."
L["How should it look?"] = "Hogyan nézzen ki?"
L["How solid the quest log's background is. Lower lets the world show through behind the list."] = "Mennyire tömör a küldetésnapló háttere. Alacsonyabb értéknél átlátszik mögötte a világ."
L["How strong the highlight on an active spell is."] = "Milyen erős az aktív varázslat kiemelése."
L["How strong the mouseover color over the icon is."] = "Milyen erős az ikon fölötti egér alatti szín."
L["How strong the pressed color over the icon is."] = "Milyen erős az ikon fölötti lenyomott szín."
L["How strongly it lights up once the enemy is in range."] = "Milyen erősen világít, amint az ellenség tartományba ér."
L["How strongly the debuff's color tints the health bar. Only for a Tint or Both highlight."] = "Milyen erősen színezi a debuff színe az életerősávot. Csak Színezés vagy Mindkettő kiemelésnél."
L["How strongly the spell cost shows on your power bar."] = "Milyen erősen látszik a varázslat költsége az erőforrássávodon."
L["How tall a friendly plate's health bar is."] = "Milyen magas egy barátságos névtábla életerősávja."
L["How tall each enemy plate's health bar is."] = "Milyen magas minden ellenséges névtábla életerősávja."
L["How tall each line of text over you is. The game's own is 25."] = "Milyen magas minden fölötted megjelenő szövegsor. A játék sajátja 25."
L["How tall each of the threat meter's bars is."] = "Milyen magas a fenyegetésmérő minden sávja."
L["How tall each of this meter's bars is."] = "Milyen magas ennek a mérőnek minden sávja."
L["How tall each pet bar is."] = "Milyen magas minden háziállat-sáv."
L["How tall each quest's row is in the quest log. Larger text keeps enough room however low this is set."] = "Milyen magas minden küldetés sora a küldetésnaplóban. A nagyobb szöveg akkor is elég helyet kap, ha ez nagyon alacsony."
L["How tall each raid tile is."] = "Milyen magas minden raidcsempe."
L["How tall each swing timer bar is."] = "Milyen magas minden ütésidőzítő-sáv."
L["How tall each tile's power bar is."] = "Milyen magas minden csempe erőforrássávja."
L["How tall the cast bar under an enemy plate is."] = "Milyen magas az ellenséges névtábla alatti varázslássáv."
L["How tall the experience bar is."] = "Milyen magas a tapasztalatsáv."
L["How tall the health bar is."] = "Milyen magas az életerősáv."
L["How tall the health bar under the tooltip is."] = "Milyen magas a súgóbuborék alatti életerősáv."
L["How tall the meter's own window is."] = "Milyen magas a mérő saját ablaka."
L["How tall the pets' power bars are."] = "Milyen magasak a háziállatok erőforrássávjai."
L["How tall the power bar is."] = "Milyen magas az erőforrássáv."
L["How tall the reputation bar is."] = "Milyen magas a hírnévsáv."
L["How tall the second meter's window is."] = "Milyen magas a második mérő ablaka."
L["How tall the tab holding the name above the frame is."] = "Milyen magas a keret fölötti, nevet tartó fül."
L["How tall this frame is."] = "Milyen magas ez a keret."
L["How tall your cast bar is."] = "Milyen magas a varázslássávod."
L["How tall your focus's cast bar is. Not inside the frame, where it takes the power bar's place."] = "Milyen magas a fókuszod varázslássávja. Nem a kereten belül, ahol az erőforrássáv helyét veszi át."
L["How tall your target's cast bar is. Not inside the frame, where it takes the power bar's place."] = "Milyen magas a célpontod varázslássávja. Nem a kereten belül, ahol az erőforrássáv helyét veszi át."
L["How tall your target's health bar is, as a share of Health bar height."] = "Milyen magas a célpontod életerősávja, az Életerősáv magasságának arányában."
L["How the health text on friendly plates reads: a percent, the health itself, health out of max, both, or what's missing."] = "Hogyan olvasható az életerő-szöveg a barátságos névtáblákon: százalék, maga az életerő, életerő a maximumhoz képest, mindkettő, vagy ami hiányzik."
L["How the health text reads: a percent, the health itself, health out of max, both, or what's missing."] = "Hogyan olvasható az életerő-szöveg: százalék, maga az életerő, életerő a maximumhoz képest, mindkettő, vagy ami hiányzik."
L["How the pets' health text is written."] = "Hogyan íródik ki a háziállatok életerő-szövege."
L["How the power text is written."] = "Hogyan íródik ki az erőforrás-szöveg."
L["How the tiles' health text is written. Missing health shows nothing while the member is at full."] = "Hogyan íródik ki a csempék életerő-szövege. A Hiányzó életerő semmit sem mutat, amíg a tag teli életerőn van."
L["How thick the border around each button is."] = "Milyen vastag a keret minden gomb körül."
L["How thick the name tab's outline is. 0 leaves none."] = "Milyen vastag a névfül körvonala. A 0 elhagyja."
L["How this category's buffs are edged: one color or a gradient. Click to change."] = "Milyen széle legyen ennek a kategóriának a buffjainak: egy szín vagy színátmenet. Kattints a módosításhoz."
L["How this extra text writes the health."] = "Hogyan írja ki ez az extra szöveg az életerőt."
L["How this extra text writes the power."] = "Hogyan írja ki ez az extra szöveg az erőforrást."
L["How wide a friendly plate's health bar is."] = "Milyen széles egy barátságos névtábla életerősávja."
L["How wide each combo point pip is. Not while the pips match the frame's width."] = "Milyen széles minden kombópont-jelölő. Nem, amíg a jelölők a keret szélességéhez igazodnak."
L["How wide each enemy plate's health bar is."] = "Milyen széles minden ellenséges névtábla életerősávja."
L["How wide each pet bar is."] = "Milyen széles minden háziállat-sáv."
L["How wide each raid tile is."] = "Milyen széles minden raidcsempe."
L["How wide the bars are."] = "Milyen szélesek a sávok."
L["How wide the damage meter is, in the panel or in its own window."] = "Milyen széles a sebzésmérő, a panelen vagy a saját ablakában."
L["How wide the list is."] = "Milyen széles a lista."
L["How wide the name tab is when Name tab width is Fixed width."] = "Milyen széles a névfül, ha a Névfül szélessége Rögzített szélesség."
L["How wide the reputation bar is. Dragging its corner in unlock mode sets this too."] = "Milyen széles a hírnévsáv. Feloldott módban a sarkát húzva is ezt állítod."
L["How wide the second meter's window is. Dragging its corner in unlock mode sets this too."] = "Milyen széles a második mérő ablaka. Feloldott módban a sarkát húzva is ezt állítod."
L["How wide the separate experience bar is. Dragging its corner in unlock mode sets this too."] = "Milyen széles a külön tapasztalatsáv. Feloldott módban a sarkát húzva is ezt állítod."
L["How wide the threat meter is."] = "Milyen széles a fenyegetésmérő."
L["How wide this frame is."] = "Milyen széles ez a keret."
L["How wide your focus's cast bar is. Not inside the frame, or while it matches the frame's width."] = "Milyen széles a fókuszod varázslássávja. Nem a kereten belül, és nem amíg a keret szélességéhez igazodik."
L["How wide your target's cast bar is. Not inside the frame, or while it matches the frame's width."] = "Milyen széles a célpontod varázslássávja. Nem a kereten belül, és nem amíg a keret szélességéhez igazodik."
L["How you find your way to quests, and how they show in the tracker."] = "Hogyan találsz el a küldetésekhez, és hogyan látszanak a követőben."
L["How you find your way to quests, how they show in the tracker, and how talking to NPCs looks."] = "Hogyan találsz el a küldetésekhez, hogyan látszanak a követőben, és milyen az NPC-kkel való beszélgetés."
L["How your target's plate stands out from the rest."] = "Hogyan emelkedik ki a célpontod névtáblája a többi közül."
L["Hunters: a line on the ranged bar where Auto Shot's wind-up starts, adjusted for haste and your ping. Moving past it holds the shot back, so the bar stays full and says Stop moving until you stand still."] = "Vadászok: egy vonal a távolsági sávon ott, ahol az Auto Shot felhúzása kezdődik, a sietséghez és a pingedhez igazítva. Ha utána mozogsz, a lövés visszatartódik, így a sáv teli marad, és azt írja, Állj meg, amíg meg nem állsz."
L["I'd like to train."] = "Tanulni szeretnék."
L["I'm away right now, I'll get back to you soon."] = "Most nem vagyok gépnél, hamarosan válaszolok."
L["INTERRUPTS"] = "MEGSZAKÍTÁSOK"
L["Icon"] = "Ikon"
L["Icon (the game's)"] = "Ikon (a játéké)"
L["Icon look"] = "Ikon kinézete"
L["Icon per class"] = "Kasztonkénti ikon"
L["Icon positions and sizes"] = "Ikonok helye és mérete"
L["Icon size"] = "Ikonméret"
L["Icon style"] = "Ikonstílus"
L["Icon zoom"] = "Ikonnagyítás"
L["Icons fill from the bar's right edge leftward, toward the middle of the screen."] = "Az ikonok a sáv jobb szélétől balra töltődnek, a képernyő közepe felé."
L["Icons on a row before it wraps to the next."] = "Ikonok egy sorban, mielőtt a következőbe tördelődik."
L["Icons on bars"] = "Ikonok a sávokon"
L["Icons per row"] = "Ikonok soronként"
L["Ignore"] = "Figyelmen kívül hagyás"
L["Ignored"] = "Figyelmen kívül hagyva"
L["Immersive"] = "Magával ragadó"
L["Immersive Preset"] = "Magával ragadó előbeállítás"
L["Import"] = "Importálás"
L["Import a Cooldown Manager layout"] = "Cooldown-kezelő elrendezés importálása"
L["Import profile"] = "Profil importálása"
L["Imported"] = "Importálva"
L["Imported the Cooldown Manager profile %s, used by talent set %d."] = "Importáltam a(z) %s Cooldown-kezelő profilt, a(z) %d. tehetségszett használja."
L["Imported the profile %s."] = "Importáltam a(z) %s profilt."
L["In a dungeon or raid"] = "Kazamatában vagy raidben"
L["In a fight"] = "Harcban"
L["In a group or with a pet, a small tag on the frame's top inner corner: your threat on it, where 100% means it turns on you. Orange as you get close, red once it's on you."] = "Csoportban vagy háziállattal kis címke a keret felső belső sarkában: a fenyegetésed rajta, ahol a 100% azt jelenti, hogy rád fordul. Narancs, ahogy közeledsz, piros, ha már rajtad van."
L["In a group, colors a mob by who it's attacking; solo plates never change. As a tank: red when it's attacking someone else, orange when you're about to lose it, normal while you hold it. As damage or healer: orange when you're close to pulling it, red once it's attacking you."] = "Csoportban a mobot aszerint színezi, kit támad; egyedül a névtáblák sosem változnak. Tankként: piros, ha valaki mást támad, narancs, ha mindjárt elveszíted, normál, amíg tartod. Sebzőként vagy gyógyítóként: narancs, ha közel vagy ahhoz, hogy magadra húzd, piros, ha már téged támad."
L["In a group or with a pet, the target's ring (and threat tag) turns this color as you get close to pulling it."] = "Csoportban vagy háziállattal a célpont gyűrűje (és fenyegetéscímkéje) ilyen színű lesz, ahogy közel kerülsz ahhoz, hogy magadra húzd."
L["In a raid, only the leader and assists can use the leader tools."] = "Raidben csak a vezető és a segédvezetők használhatják a vezetői eszközöket."
L["In columns"] = "Oszlopokban"
L["In combat"] = "Harcban"
L["In combat in a group or with a pet"] = "Harcban, csoportban vagy háziállattal"
L["In combat, when I'm the tank"] = "Harcban, ha én vagyok a tank"
L["In dungeons, raids, battlegrounds and arenas, everything set to fade stays shown, as if its fade were Never. It fades again once you're back outside."] = "Kazamatában, raidben, csatatéren és arénában minden, ami elhalványulásra van állítva, látható marad, mintha az elhalványítása Soha lenne. Ha újra kint vagy, megint elhalványul."
L["In fights"] = "Harcban"
L["In fights and when idle"] = "Harcban és tétlenül"
L["In fights: the panel and tabs float away and the messages stay over the world. When idle: the whole chat also fades when nothing new has come in for a while. Always: no panel or tabs while you play, only messages. The mouse over the chat or pressing Enter brings it back."] = "Harcban: a panel és a fülek eltűnnek, az üzenetek a világ fölött maradnak. Tétlenül: az egész chat is elhalványul, ha egy ideje nem jött új. Mindig: játék közben nincs panel és fül, csak üzenetek. Ha az egér a chat fölé kerül, vagy megnyomod az Entert, visszajön."
L["In progress"] = "Folyamatban"
L["In public channels (General, Trade, say...), the same words from the same person again within a minute are hidden. Guild, group and whispers are never hidden."] = "Nyilvános csatornákon (General, Trade, say...) ugyanattól a személytől ugyanazok a szavak egy percen belül újra elrejtve. A céh, a csoport és a suttogás sosem rejtett."
L["In rows"] = "Sorokban"
L["In screen pixels, so it stays sharp at any UI scale. Heavy border needs 3 or more."] = "Képernyőpixelben, így bármilyen felületméretnél éles marad. A Vastag kerethez 3 vagy több kell."
L["In the Daylight chat box (Chat style: Daylight)."] = "A Daylight chatdobozban (Chatstílus: Daylight)."
L["In the chat box, Up and Down step through what you sent. Alt+Up and Alt+Down still work as before. While the box is open, the arrow keys don't turn your character."] = "A chatdobozban a Fel és Le gombokkal lépkedsz az elküldött üzeneteken. Az Alt+Fel és Alt+Le ugyanúgy működik, mint eddig. Amíg a doboz nyitva van, a nyílgombok nem fordítják a karakteredet."
L["In the group"] = "A csoportban"
L["In the info panel"] = "Az infópanelen"
L["In the tooltip spot"] = "A súgóbuborék helyén"
L["In use"] = "Használatban"
L["In use: %s"] = "Használatban: %s"
L["In your accent color (Appearance), following it when it changes. When off, uses the color below."] = "A kiemelőszínedben (Megjelenés), és követi, ha változik. Kikapcsolva az alábbi színt használja."
L["In your bags"] = "A táskáidban"
L["In your layout: click to move it here."] = "Az elrendezésedben: kattints, hogy ide mozgasd."
L["In your layout: click to pick it."] = "Az elrendezésedben: kattints a kiválasztásához."
L["Inactive"] = "Inaktív"
L["Inbox"] = "Beérkezett levelek"
L["Incoming heals"] = "Érkező gyógyítások"
L["Info"] = "Infó"
L["Info Panel"] = "Infópanel"
L["Info panel"] = "Infópanel"
L["Inner end"] = "Belső vég"
L["Inside the frame"] = "A kereten belül"
L["Inside the frame it covers the power bar, as wide as it (in the Ribbon style it sits below the frame instead). Above, below or on its own it's a bar you size here; on its own you move it in unlock mode."] = "A kereten belül eltakarja az erőforrássávot, annak szélességében (a Szalag stílusban inkább a keret alatt ül). Fölötte, alatta vagy önállóan egy sáv, aminek itt állítod a méretét; önállóan feloldott módban mozgatod."
L["Inspect"] = "Megtekintés"
L["Inspecting a player opens DaylightUI's window, with their gear and talents. Turn it off to use the game's window."] = "Egy játékos megtekintése a DaylightUI ablakát nyitja meg, a felszerelésével és tehetségeivel. Kapcsold ki, ha a játék ablakát használnád."
L["Install the Jiberish Fabled Icons addon to unlock more class icon styles."] = "Telepítsd a Jiberish Fabled Icons addont, hogy több kasztikon-stílus elérhető legyen."
L["Instance chat, used in battlegrounds and groups made by the group finder."] = "Instance chat, csatatereken és a csoportkereső által összerakott csoportokban."
L["Instance color"] = "Instance szín"
L["Intellect"] = "Intelligencia"
L["Interrupt animation"] = "Megszakítás animációja"
L["Interrupted"] = "Megszakítva"
L["Interrupted color"] = "Megszakítva szín"
L["Interrupts"] = "Megszakítások"
L["Inventory is full."] = "Tele a tárhely."
L["Invert gradients"] = "Színátmenetek megfordítása"
L["Invite"] = "Meghívás"
L["It shows when the first meter would: the Damage meter page's \"Show only in a group\" and \"Show only in combat\" count for both. Reset clears the fights in both."] = "Akkor látszik, amikor az első mérő látszana: a Sebzésmérő oldal \"Csak csoportban\" és \"Csak harcban\" beállítása mindkettőre vonatkozik. A Visszaállítás mindkettőben törli a harcokat."
L["It slides back once the fight ends. A click on its tab overrides this until the next fight starts or ends."] = "A harc végén visszacsúszik. A fülére kattintás ezt felülírja a következő harc kezdetéig vagy végéig."
L["It takes a reload."] = "Újratöltés kell hozzá."
L["It's %s. Just one more quest?"] = "%s van. Csak még egy küldetés?"
L["Item"] = "Tárgy"
L["Item ID"] = "Tárgyazonosító"
L["Item icons"] = "Tárgyikonok"
L["Item level"] = "Tárgyszint"
L["Item level %s"] = "Tárgyszint: %s"
L["Item level line"] = "Tárgyszint sor"
L["Item names beside icons"] = "Tárgynevek az ikonok mellett"
L["Item names in their quality color, or all white. The icon's edge keeps the quality color."] = "A tárgynevek a minőségük színében, vagy mind fehérben. Az ikon széle megtartja a minőség színét."
L["Item quality border"] = "Tárgyminőség szerinti keret"
L["Items"] = "Tárgyak"
L["Items and loot"] = "Tárgyak és zsákmány"
L["Items below this quality don't show, like gray junk."] = "Az ennél gyengébb minőségű tárgyak nem látszanak, például a szürke szemét."
L["Items sorted into groups by type. To move an item to another group, drag it onto that group's heading or Alt-right-click it. Click a heading to collapse it. Alt-right-click also locks an item so it's never sold or disenchanted."] = "A tárgyak típus szerint csoportokba rendezve. Ha egy tárgyat másik csoportba tennél, húzd a csoport fejlécére, vagy Alt+jobb klikkelj rá. Egy fejlécre kattintva összecsukod. Az Alt+jobb klikk zárolja is a tárgyat, így soha nem adja el és nem bűvöli szét."
L["Items that are uncommon or better get a border in their quality color."] = "A nem közönséges vagy jobb tárgyak a minőségük színében kapnak keretet."
L["Items you loot, create, buy or get from a quest."] = "A zsákmányolt, készített, vásárolt vagy küldetésből kapott tárgyak."
L["Items your class, level or skills can't use yet, or that you already know, get a red icon, as at a vendor."] = "A tárgyak, amiket a kasztod, szinted vagy jártasságod még nem enged használni, vagy amiket már ismersz, piros ikont kapnak, mint az árusnál."
L["Its buff or debuff"] = "A buffja vagy debuffja"
L["Its cooldown"] = "A cooldownja"
L["Its options and My Journey windows, and its quest objective icons on the maps, each quest in its own color."] = "A beállításai és a My Journey ablakai, valamint a küldetésfeladat-ikonjai a térképeken, minden küldetés a saját színében."
L["Its own fade, apart from the panel's. With this page open it shows a sample group."] = "Saját elhalványítás, a panelétől függetlenül. Ha ez az oldal nyitva van, egy mintacsoportot mutat."
L["Its own window"] = "Saját ablak"
L["Its own window, in the bottom-right corner to start. Move it in unlock mode (/dui unlock) and drag its corner to size it."] = "Saját ablak, kezdetben a jobb alsó sarokban. Feloldott módban mozgasd (/dui unlock), és a sarkát húzva méretezd."
L["Its owner's class"] = "A gazdája kasztja"
L["Its owner's class tells at a glance whose pet it is."] = "A gazdája kasztjából első ránézésre látszik, kié a háziállat."
L["Its ring buttons in your action bar look. The ring, its spin and its options stay OPie's."] = "A gyűrűgombjai az akciósávod kinézetében. A gyűrű, a pörgése és a beállításai az OPie-éi maradnak."
L["Its timer bars in your font, bar texture and border. Sizes, colors and spots stay DBM's."] = "Az időzítősávjai a betűtípusodban, sávtextúrádban és keretedben. A méretek, színek és helyek a DBM-éi maradnak."
L["BigWigs and LittleWigs"] = "BigWigs és LittleWigs"
L["Leader crown left / right"] = "Vezetői korona balra / jobbra"
L["Leader crown up / down"] = "Vezetői korona fel / le"
L["Party pet"] = "Csoport háziállata"
L["Ready check left / right"] = "Készenléti ellenőrzés balra / jobbra"
L["Ready check up / down"] = "Készenléti ellenőrzés fel / le"
L["Request invite"] = "Meghívás kérése"
L["Role icon left / right"] = "Szerepikon balra / jobbra"
L["Role icon up / down"] = "Szerepikon fel / le"
L["Show every bag slot"] = "Minden táskahely mutatása"
L["Show in unlock mode"] = "Mutatás feloldott módban"
L["Areas"] = "Területek"
L["Show seconds"] = "Másodpercek mutatása"
L["Show the sweep"] = "A söprés mutatása"
L["Show where you flew from"] = "Az indulási hely mutatása"
L["Simple"] = "Egyszerű"
L["Sitting by a campfire warms the screen with firelight and embers, a soft crackle plays, and your action bars and unit frames fade away. Move, target or cast and everything comes back; a fight brings it back at once. The sounds follow Soft UI sounds (General > Appearance)."] = "Ha tábortűz mellett ülsz, tűzfény és parázs melegíti a képernyőt, halk pattogás szól, az akciósávjaid és egységkereteid pedig elhalványulnak. Mozdulj, vegyél célba valamit vagy varázsolj, és minden visszajön; egy harc azonnal visszahozza. A hangok a Halk felülethangokat követik (Általános > Megjelenés)."
L["Sold by"] = "Árusítja"
L["Targeting"] = "Célzás"
L["Text size of the time left on each totem timer."] = "Az egyes totem-időzítők hátralévő idejének szövegmérete."
L["The Daylight UI border, your accent color (General > Appearance), or a color you pick."] = "A Daylight UI keret, a kiemelőszíned (Általános > Megjelenés), vagy egy általad választott szín."
L["The clock reads 18:30:15, ticking every second."] = "Az óra így mutat: 18:30:15, másodpercenként ketyegve."
L["The color of the micro menu's icons in the Daylight UI style. Accent color runs your accent along the row, gradient and all."] = "A mikromenü ikonjainak színe a Daylight UI stílusban. A Kiemelőszín végigviszi a kiemelésedet a soron, színátmenettel együtt."
L["The colors the animation moves: the bar's own, your accent, your class's pair, or two of your own."] = "Az animáció színei: a sáv sajátja, a kiemelőszíned, a kasztod színpárja, vagy két saját szín."
L["The dark box behind the flight timer. When off, the text and line float on their own."] = "A sötét doboz a repülésidőzítő mögött. Kikapcsolva a szöveg és a vonal magában lebeg."
L["The dark square behind each micro menu icon. When off, the icons sit on their own."] = "A sötét négyzet minden mikromenü-ikon mögött. Kikapcsolva az ikonok magukban állnak."
L["The flight point you left, under the start of the line."] = "A repülési pont, ahonnan elindultál, a vonal eleje alatt."
L["The flight timer's border color when Flight timer border color is One color."] = "A repülésidőzítő keretszíne, ha a Repülésidőzítő keretszíne Egy szín."
L["The game's own setting: Clean Up packs your items into the last slots of your bags, so the empty slots sit at the top and what you loot next shows up in front of them. Best in the Grid view."] = "A játék saját beállítása: a Rendezés a táskáid utolsó helyeire pakolja a tárgyaidat, így az üres helyek felül vannak, és amit legközelebb zsákmányolsz, eléjük kerül. Rács nézetben a legjobb."
L["The game's own setting: how many empty slots you have left, written on the backpack button, so you can see your bag space without opening your bags."] = "A játék saját beállítása: hány üres helyed maradt, a hátizsák gombjára írva, így táskanyitás nélkül látod a helyet."
L["The game's own setting: shows each of your bags next to the backpack instead of folding them away behind the arrow."] = "A játék saját beállítása: minden táskádat a hátizsák mellett mutatja, nem csukja a nyíl mögé."
L["The icons wrap onto up to this many rows. Not used while icons per row is set."] = "Az ikonok legfeljebb ennyi sorba tördelődnek. Nem használt, ha a Soronkénti ikonok be van állítva."
L["The item level in the icon's corner instead of a line under the name, so long names have the room."] = "A tárgyszint az ikon sarkában, a név alatti sor helyett, így a hosszú neveknek több hely jut."
L["The left"] = "A bal oldal"
L["The line that fills as you fly, with a light at its front. When off, only the text shows."] = "A vonal, ami repülés közben telik, az elején fénnyel. Kikapcsolva csak a szöveg látszik."
L["The micro menu's icon color when Micro menu icon color is One color."] = "A mikromenü ikonszíne, ha a Mikromenü-ikonok színe Egy szín."
L["The middle of the screen"] = "A képernyő közepe"
L["The next color along your custom gradient."] = "Az egyedi színátmeneted következő színe."
L["The priority quest's title takes the Priority quest color too, so it stands out in the tracker and the quest log."] = "A kiemelt küldetés címe is a Kiemelt küldetés színét kapja, így kiugrik a követőben és a küldetésnaplóban."
L["The right"] = "A jobb oldal"
L["The same Alliance or Horde crest by the name of anyone flagged for PvP, players and NPCs alike, so you can tell before you attack that it would flag you."] = "Ugyanaz a Szövetség- vagy Horda-címer bárki neve mellett, aki PvP-jelzést visel, játékosnál és NPC-nél egyaránt, így támadás előtt látod, hogy téged is megjelölne."
L["The small \"Flying to\" above the destination."] = "A kis \"Úti cél\" a célállomás fölött."
L["The space between two totem timers."] = "Két totem-időzítő közti hely."
L["The spell's icon at the end of your cast bar. Not while under the frame, where the portrait ring covers that spot, or between the frames."] = "A varázslat ikonja a varázslássávod végén. Nem, ha a keret alatt van, ahol a portrégyűrű takarja azt a helyet, vagy a keretek között."
L["The standard profile, as it comes. Choose it above to use it. If the profile you're on has moved action bars, it offers to bring them along."] = "Az alapprofil, alapállapotban. Válaszd ki fent a használatához. Ha a jelenlegi profilodban áthelyezett akciósávok vannak, felajánlja, hogy átveszi őket."
L["The time until you land, under the end of the line. It turns amber in the last seconds."] = "A leszállásig hátralévő idő, a vonal vége alatt. Az utolsó másodpercekben borostyánszínű lesz."
L["The whole flight timer. Also the mouse wheel over its handle in /dui unlock."] = "Az egész repülésidőzítő. A /dui unlock alatt az egérgörgő is a fogantyúja fölött."
L["The whole landing welcome. Also the mouse wheel over its handle in /dui unlock."] = "Az egész érkezési üdvözlés. A /dui unlock alatt az egérgörgő is a fogantyúja fölött."
L["Their timer bars in your font, bar texture and border, on BigWigs' Default bar style. Sizes, colors and spots stay BigWigs'."] = "Az időzítősávjaik a betűtípusodban, sávtextúrádban és keretedben, a BigWigs Default sávstílusán. A méretek, színek és helyek a BigWigs-éi maradnak."
L["Its window, and each attunement chain drawn like the talent trees."] = "Az ablaka, és minden hangolási lánc a tehetségfákhoz hasonlóan megrajzolva."
L["Jiberish Fabled Icons is installed. Pick an icon for each class below, any style or one of its specs. The first icon on each line follows the Icon style."] = "A Jiberish Fabled Icons telepítve van. Válassz ikont minden kaszthoz alább, bármilyen stílusból, vagy valamelyik specializációjáét. Minden sor első ikonja az Ikonstílust követi."
L["Join a group to use the leader tools, or try them with /dui leader test."] = "Lépj be egy csoportba a vezetői eszközök használatához, vagy próbáld ki őket a /dui leader test paranccsal."
L["Join the DaylightUI Discord: press Ctrl+C to copy the link, then paste it in your browser."] = "Csatlakozz a DaylightUI Discordhoz: Ctrl+C-vel másold a linket, aztán illeszd be a böngésződbe."
L["Junk"] = "Szemét"
L["Just left of the panel, level with its top, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "Közvetlenül a panel bal oldalán, a tetejével egy vonalban, és követi, ahogy a minitérkép vagy a sebzésmérő mérete változik. Kapcsold ki, ha magad mozgatnád a sávot feloldott módban."
L["Just left of the panel, the first row resting on its bottom edge, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "Közvetlenül a panel bal oldalán, az első sor az alsó szélén nyugszik, és követi, ahogy a minitérkép vagy a sebzésmérő mérete változik. Kapcsold ki, ha magad mozgatnád a sávot feloldott módban."
L["Just this spell, for now"] = "Csak ez a varázslat, egyelőre"
L["Keep %s"] = "%s megtartása"
L["Keep channel numbers"] = "Csatornaszámok megtartása"
L["Keep chat after logging out"] = "Chat megtartása kilépés után"
L["Keep chat after reload"] = "Chat megtartása újratöltés után"
L["Keep it"] = "Megtartom"
L["Keep its spot"] = "Tartsa a helyét"
L["Keep my setup"] = "Beállításaim megtartása"
L["Keep old fights"] = "Régi harcok megtartása"
L["Keep these talents under a name and put them back later, or copy and paste a talent string."] = "Mentsd el ezeket a tehetségeket egy név alatt, és tedd vissza később, vagy másolj és illessz be egy tehetségszöveget."
L["Keeps the separate bar the same width as your main action bar. An upright bar keeps its own width."] = "A külön sávot a fő akciósávod szélességén tartja. A függőleges sáv megtartja a saját szélességét."
L["Kept for every character on this account, each with its own Edit Mode layout."] = "A fiók minden karakteréhez megmarad, mindegyik a saját Szerkesztő mód elrendezésével."
L["Keybind X offset"] = "Billentyű X eltolása"
L["Keybind Y offset"] = "Billentyű Y eltolása"
L["Keybind color"] = "Billentyű színe"
L["Keybind position"] = "Billentyű helye"
L["Keybind size"] = "Billentyű mérete"
L["Keybinds"] = "Billentyűk"
L["Keybinds, stack counts, macro names and cooldown numbers on every bar, the Cooldown Manager and totems. General uses the font on General > Appearance."] = "Billentyűk, halomszámok, makrónevek és cooldown-számok minden sávon, a Cooldown-kezelőn és a totemeken. Az Általános az Általános > Megjelenés betűtípusát használja."
L["Keys"] = "Gombok"
L["Kicked by"] = "Megszakította"
L["Third color"] = "Harmadik szín"
L["Those quiet errors play one soft, low tick in place of the voice line, never in a burst. Follows Soft UI sounds (General > Appearance)."] = "Ezek a csendes hibák egy halk, mély kattanást játszanak le a hang helyett, sosem sorozatban. A Halk felülethangokat követi (Általános > Megjelenés)."
L["Tips the angled ends the other way, so the bar is wider at the bottom than the top. Only while the power bar is on its own, and not while your cast bar slides out from under it."] = "A ferde végeket a másik irányba dönti, így a sáv alul szélesebb, mint felül. Csak ha az erőforrássáv önállóan áll, és nem, amíg a varázslássávod kicsúszik alóla."
L["Tips the angled ends the other way, so your cast bar is wider at the bottom than the top. Not while under the frame, between the frames or under the personal display."] = "A ferde végeket a másik irányba dönti, így a varázslássávod alul szélesebb, mint felül. Nem, ha a keret alatt, a keretek között vagy a személyes kijelző alatt van."
L["Tips the angled ends the other way, so your focus's cast bar is wider at the bottom than the top. Not inside the frame."] = "A ferde végeket a másik irányba dönti, így a fókuszod varázslássávja alul szélesebb, mint felül. Nem a kereten belül."
L["Tips the angled ends the other way, so your target's cast bar is wider at the bottom than the top. Not inside the frame or sliding out under it."] = "A ferde végeket a másik irányba dönti, így a célpontod varázslássávja alul szélesebb, mint felül. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["To spend"] = "Elkölthető"
L["Today"] = "Ma"
L["Tooltip style"] = "Súgóbuborék stílusa"
L["Totem and buff"] = "Totem és buff"
L["Totem and buff shows the totem's time while it stands, grayed and dimmed while you're out of range of its buff. Buff only shows it just while the buff is on you. Cooldown shows the game's own icon."] = "A Totem és buff a totem idejét mutatja, amíg áll, szürkén és halványan, amíg a buffja hatótávján kívül vagy. A Csak buff csak addig mutatja, amíg a buff rajtad van. A Cooldown a játék saját ikonját mutatja."
L["Totem shows the totem's time while it stands. Cooldown shows the game's own icon."] = "A Totem a totem idejét mutatja, amíg áll. A Cooldown a játék saját ikonját mutatja."
L["Tracked recipes"] = "Követett receptek"
L["Warlocks: the Soul Shards text shows how many your soul bag holds beside the count, and its tooltip the free slots. On the data bar too."] = "Warlockok: a Soul Shards szöveg a darabszám mellett azt is mutatja, mennyi fér a lélektáskádba, a súgóbuboréka pedig a szabad helyeket. Az adatsávon is."
L["Water totem"] = "Víz totem"
L["Welcome on landing"] = "Érkezési üdvözlés"
L["Welcome to"] = "Üdvözlünk itt:"
L["What shows"] = "Mi látszik"
L["When the accent color is a gradient (Daylight's, your class's or your own), every Daylight UI border runs along it: windows, panels, frames and nameplates. Needs Gradients on (General > Gradients)."] = "Ha a kiemelőszín színátmenet (a Daylighté, a kasztodé vagy a sajátod), minden Daylight UI keret ezt követi: ablakok, panelek, keretek és névtáblák. Kell hozzá a Színátmenetek bekapcsolása (Általános > Színátmenetek)."
L["When you land, \"Welcome to\" and the place's name slide in at the top of the screen, then fade away. Move it with /dui unlock."] = "Leszálláskor az \"Üdvözlünk itt:\" és a hely neve beúszik a képernyő tetejére, majd elhalványul. A /dui unlock paranccsal mozgathatod."
L["Where the rez icon sits on each frame, or just outside it."] = "Hol ül a feltámasztás ikonja minden kereten, vagy épp azon kívül."
L["Where the role, marker and crown sit on a tile, and the ready check, summon and rez icons."] = "Hol ül a szerep, a jelölő és a korona egy csempén, valamint a készenléti, idézési és feltámasztási ikonok."
L["Where you're going and the time left while on a flight path, and a welcome when you land."] = "Az úti cél és a hátralévő idő repülési útvonalon, és üdvözlés leszálláskor."
L["Where your custom gradient starts."] = "Ahol az egyedi színátmeneted kezdődik."
L["Which edge the messages line up on. Right suits a chat on the right side of your screen."] = "Melyik szélhez igazodnak az üzenetek. A Jobb a képernyőd jobb oldalán lévő chathez illik."
L["Which edge the second panel's messages line up on, for a loot or combat log panel on the right side of your screen."] = "Melyik szélhez igazodnak a második panel üzenetei, a képernyőd jobb oldalán lévő zsákmány- vagy harcinapló-panelhez."
L["Which way the card opens from the crown tab. The middle of the screen keeps it on screen wherever you move the tab."] = "Merre nyílik a kártya a koronás fülről. A képernyő közepe a képernyőn tartja, bárhová is mozgatod a fület."
L["Window icon flare"] = "Ablakikon felvillanása"
L["With the power bar on its own (Player > Power bar), the cast bar and the swing timer under it can slide out from under the power bar instead of the frame. Not while the power bar's angles are flipped."] = "Ha az erőforrássáv önállóan áll (Játékos > Erőforrássáv), az alatta lévő varázslássáv és ütésidőzítő az erőforrássáv alól is kicsúszhat a keret helyett. Nem, amíg az erőforrássáv szögei tükrözve vannak."
