L["Lootable quest objects sparkle, and so do quest givers (the game has no setting for one alone). The game only sparkles with its outline around what you point at off, so this keeps that outline off. Turning this off puts the outline back; the sparkle may stay until you restart the game."] = "A zsákmányolható küldetéstárgyak szikráznak, és a küldetésadók is (a játékban nincs külön beállítás csak az egyikre). A játék csak akkor szikráztat, ha a rámutatott dolog körvonala ki van kapcsolva, ezért ez kikapcsolva tartja azt a körvonalat. Ha ezt kikapcsolod, a körvonal visszajön; a szikrázás a játék újraindításáig maradhat."
