L["On a flight path, a bar at the top of the screen shows where you're going and the time left. Each route's time is learned the first time you fly it, for all your characters. Move it with /dui unlock."] = "Repülési útvonalon a képernyő tetején egy sáv mutatja az úti célt és a hátralévő időt. Minden útvonal idejét az első repüléskor tanulja meg, minden karakteredre. A /dui unlock paranccsal mozgathatod."
L["On a ready check, and when you enter a dungeon or raid in a group, a short line shows the group buffs you don't have yet: only ones someone in your group can give. It fades once they land. Move it in unlock mode."] = "Készenléti ellenőrzéskor, és amikor csoportban kazamatába vagy raidbe lépsz, egy rövid sor mutatja a még hiányzó csoportbuffokat: csak azokat, amiket valaki a csoportodban adni tud. Elhalványul, amint felkerülnek. Feloldott módban mozgathatod."
L["On cooldown"] = "Cooldownon"
L["On its own (unlock to move)"] = "Önállóan (feloldással mozgatható)"
L["On its own, the power bar leaves the frame and you can move it anywhere in unlock mode, like the middle of the screen. The frame is then all health."] = "Önállóan az erőforrássáv elhagyja a keretet, és feloldott módban bárhová mozgathatod, például a képernyő közepére. A keret ekkor csupa életerő."
L["On the portrait"] = "A portrén"
L["On the portrait rings of the player, target and focus frames."] = "A játékos-, célpont- és fókuszkeret portrégyűrűin."
L["One click sets where the auras and the name sit. Change anything after."] = "Egy kattintással beállítod, hol ülnek az aurák és a név. Utána bármit módosíthatsz."
L["One color"] = "Egy szín"
L["One color on every pip; colors shading from Combo point color to Full color along the row; your class color; or two-color pairs from the Gradients page (Combo points), one for all pips or one each. Your nameplates' combo points use the same colors."] = "Egy szín minden jelölőn; a Kombópont színétől a Teljes színig átmenő színek a sor mentén; a kasztszíned; vagy kétszínű párok a Színátmenetek oldalról (Kombópontok), egy minden jelölőre vagy egy-egy mindegyikre. A névtábláid kombópontjai ugyanezeket a színeket használják."
L["One custom color, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "Egy egyedi szín, a kasztszíned, vagy a kasztod két színe színátmenetként (a Színátmenetek oldalról)."
L["One more thing at the end of the same line, after the second part."] = "Még egy dolog ugyanannak a sornak a végén, a második rész után."
L["One row per group member and your pet on your target's threat list, highest first, with you always in it. The percent is of the pull: at 100% it turns on you."] = "Csoporttagonként és a háziállatodra egy sor a célpontod fenyegetéslistáján, a legnagyobbal elöl, te mindig benne vagy. A százalék a pullhoz képest értendő: 100%-nál rád fordul."
L["One switch per part of the game's windows."] = "Egy kapcsoló a játék ablakainak minden részéhez."
L["One tile with the count"] = "Egy csempe a darabszámmal"
L["Ones that matter in a fight"] = "Amik harcban számítanak"
