L["Only the chat's messages stay over the world, each fading after a while, like Floating chat (Chat > Floating). It stays even with Fade everything at the campfire on."] = "Csak a chat üzenetei maradnak a világ fölött, mindegyik egy idő után elhalványul, mint a Lebegő chatnél (Chat > Lebegő). Akkor is marad, ha a Minden elhalványítása a tábortűznél be van kapcsolva."
L["Only the debuffs you put on it, or yours first and then everyone else's."] = "Csak az általad rátett debuffok, vagy előbb a tieid, aztán mindenki másé."
