L["Opacity on cooldown"] = "Átlátszatlanság cooldownon"
L["Open"] = "Megnyitás"
L["Open DaylightUI options"] = "DaylightUI beállítások megnyitása"
L["Open a chat box first to link it."] = "Előbb nyiss meg egy chatdobozt a linkeléshez."
L["Open spot"] = "Szabad hely"
L["Open stat groups"] = "Statisztikacsoportok megnyitása"
L["Open this page at these settings."] = "Ennek az oldalnak a megnyitása ezekkel a beállításokkal."
L["Open world only"] = "Csak nyílt világ"
L["Opening a mailbox shows DaylightUI's window: your letters, sending, and a ledger of your gold. Turn it off to use the game's window. The ledger keeps counting either way."] = "Postaláda megnyitásakor a DaylightUI ablaka jelenik meg: a leveleid, a küldés és az aranyad főkönyve. Kapcsold ki, ha a játék ablakát használnád. A főkönyv így is, úgy is számol."
L["Opening a profession shows DaylightUI's window: your recipes on the left, the one you picked on the right. In a fight the game's own window opens. Turn it off to use the game's window."] = "Egy szakma megnyitásakor a DaylightUI ablaka jelenik meg: bal oldalt a receptjeid, jobb oldalt a kiválasztott. Harcban a játék saját ablaka nyílik. Kapcsold ki, ha a játék ablakát használnád."
L["Opening a vendor sells everything in the Junk group: gray items, and anything you've moved to Junk yourself. Chat shows how much you got."] = "Árus megnyitásakor mindent elad a Szemét csoportból: a szürke tárgyakat, és amit magad tettél a Szemétbe. A chat kiírja, mennyit kaptál."
L["Opening a vendor that repairs fixes all your gear, and chat shows the cost. Not in combat."] = "Javító árus megnyitásakor megjavítja az összes felszerelésedet, és a chat kiírja az árát. Harcban nem."
L["Opening the group finder shows DaylightUI's window: groups to join, listing yourself, and who's about. In a fight the game's own window opens. Turn it off to use the game's window."] = "A csoportkereső megnyitásakor a DaylightUI ablaka jelenik meg: csatlakozható csoportok, saját hirdetés, és ki van a környéken. Harcban a játék saját ablaka nyílik. Kapcsold ki, ha a játék ablakát használnád."
L["Opening your bag fills up part stacks of the same item (15 and 5 Linen Cloth become 20), so no slot is wasted. Not in combat, or while you trade or have the mailbox or auction house open."] = "A táska megnyitása feltölti ugyanannak a tárgynak a részhalmait (15 és 5 Linen Cloth-ból 20 lesz), így egy hely sem vész kárba. Harcban nem, és nem, amíg kereskedsz, vagy nyitva van a postaláda vagy az aukciósház."
L["Opens the Gradients page, where the Combo points pairs are."] = "Megnyitja a Színátmenetek oldalt, ahol a Kombópontok párjai vannak."
L["Opens the layout editor right on your screen: pull spells up from the tray, drag them where you want them, hook them together, click one to change it. Type /cdm to open it any time. Out of combat only."] = "Közvetlenül a képernyődön nyitja meg az elrendezésszerkesztőt: húzd fel a varázslatokat a tálcáról, tedd őket oda, ahová akarod, akaszd össze őket, kattints egyre a módosításához. Bármikor megnyitod a /cdm paranccsal. Csak harcon kívül."
L["Opens your spellbook with Click-cast switched on: click a spell with the mouse button you want. Close the spellbook when you're done and this page comes back."] = "Megnyitja a varázskönyvedet bekapcsolt kattintásos varázslással: kattints egy varázslatra a kívánt egérgombbal. Ha végeztél, zárd be a varázskönyvet, és ez az oldal visszajön."
L["Option toggles"] = "Beállítás-kapcsolók"
L["Options"] = "Beállítások"
L["Options (%s): %s"] = "Beállítások (%s): %s"
L["Options windows of addons built on Ace3, in the game's settings and their own windows: Questie, RestedXP and many more."] = "Ace3-ra épülő addonok beállításablakai, a játék beállításaiban és a saját ablakaikban: Questie, RestedXP és még sok más."
L["Or pick one here to skip the click"] = "Vagy válassz itt egyet, és kihagyhatod a kattintást"
L["Orange timer when running out"] = "Narancs időzítő, amikor fogy"
