L["Outside: top left"] = "Kívül: bal felül"
L["Outside: top right"] = "Kívül: jobb felül"
L["Over an hour away. Still here, still waiting."] = "Több mint egy órája távol. Még itt van, még vár."
L["Over its owner"] = "A gazdája fölött"
L["Over, under or beside the health bar. In Design mode on the preview, drag it there."] = "Az életerősáv fölött, alatt vagy mellett. Tervező módban az előnézeten húzd oda."
L["Over, under or beside the health bar. Rows sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "Az életerősáv fölött, alatt vagy mellett. Az egy helyen osztozó sorok a sávtól kifelé sorakoznak. Tervező módban az előnézeten húzd oda."
L["Over, under, beside or on a friendly plate's health bar. Without the health bar the name stays centered."] = "Egy barátságos névtábla életerősávja fölött, alatt, mellett vagy rajta. Életerősáv nélkül a név középen marad."
L["Over, under, beside or on the health bar. Pieces sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "Az életerősáv fölött, alatt, mellett vagy rajta. Az egy helyen osztozó darabok a sávtól kifelé sorakoznak. Tervező módban az előnézeten húzd oda."
L["Overall"] = "Összes"
L["Overlap (bunch up)"] = "Átfedés (összetömörülnek)"
L["Overlapping plates"] = "Átfedő névtáblák"
L["Own border and shadow"] = "Saját keret és árnyék"
L["Own name tab look"] = "Saját névfül-kinézet"
L["Parry"] = "Hárítás"
L["Parts of the world map you haven't explored yet show too, dimmed so you can still tell where you haven't been."] = "A világtérkép még fel nem fedezett részei is látszanak, halványítva, hogy azért tudd, merre nem jártál még."
