L["Party and instance"] = "Csoport és instance"
L["Party and raid frames fade to their own opacity instead of the one above."] = "A csoport- és raidkeretek a saját átlátszatlanságukra halványulnak a fenti helyett."
L["Party chat from everyone but the leader."] = "Csoportchat mindenkitől, kivéve a vezetőt."
L["Party chat from the group's leader."] = "Csoportchat a csoport vezetőjétől."
L["Party color"] = "Csoportszín"
