L["Party on the left, you and your target low in the middle."] = "A csoport bal oldalt, te és a célpontod lent középen."
L["Paste a DaylightUI profile (Ctrl+V) and name it. It becomes a new profile, chosen for this character (these talents, with dual spec); yours stay as they are."] = "Illessz be egy DaylightUI-profilt (Ctrl+V), és nevezd el. Új profil lesz belőle, ehhez a karakterhez kiválasztva (ezekhez a tehetségekhez, kettős specializációval); a tieid maradnak, ahogy vannak."
L["Paste a layout string from the game's Cooldown Manager (its Export), a guide or another UI (Ctrl+V). It becomes a new profile, used by talent set %d."] = "Illessz be egy elrendezésszöveget a játék Cooldown-kezelőjéből (az Exportjából), egy útmutatóból vagy egy másik felületből (Ctrl+V). Új profil lesz belőle, a(z) %d. tehetségszett használja."
L["Paste a talent string"] = "Tehetségszöveg beillesztése"
L["Paste someone's profile. It becomes a new profile; yours stay as they are."] = "Illeszd be valaki profilját. Új profil lesz belőle; a tieid maradnak, ahogy vannak."
L["Paste talent string..."] = "Tehetségszöveg beillesztése..."
