L["Pick a page on the left to shape your interface. Changes apply as you make them. Hover a setting to see what it does; the arrow beside a changed setting puts it back."] = "Válassz egy oldalt bal oldalt a felületed alakításához. A változások azonnal érvényesek. Vidd az egeret egy beállítás fölé, hogy lásd, mit csinál; a módosított beállítás melletti nyíl visszaállítja."
L["Pick a playstyle to list."] = "Válassz játékstílust a hirdetéshez."
