L["Picks a whole set of colors at once. Colors you changed yourself are kept; a row's reset button sets it back to the palette."] = "Egyszerre egy egész színkészletet választ. A saját magad által módosított színek megmaradnak; egy sor visszaállító gombja a palettára állítja vissza."
