L["Players"] = "Játékosok"
L["Players' and creatures' tooltips show while you're fighting. When off, they stay hidden in a fight; hold Shift to see one."] = "A játékosok és lények súgóbuborékai harc közben is látszanak. Kikapcsolva harcban rejtve maradnak; a Shiftet lenyomva megnézheted."
L["Players' last names after their first, on nameplates. Where the game hides names (in combat, in places) only the first name shows."] = "A játékosok vezetékneve a keresztnevük után, a névtáblákon. Ahol a játék elrejti a neveket (harcban, bizonyos helyeken), csak a keresztnév látszik."
L["Players' last names after their first, on this frame only. Where the game hides names (in combat, in places) only the first name shows."] = "A játékosok vezetékneve a keresztnevük után, csak ezen a kereten. Ahol a játék elrejti a neveket (harcban, bizonyos helyeken), csak a keresztnév látszik."
L["Players' last names after their first, on tooltips. Where the game hides names (in combat, in places) only the first name shows."] = "A játékosok vezetékneve a keresztnevük után, a súgóbuborékokon. Ahol a játék elrejti a neveket (harcban, bizonyos helyeken), csak a keresztnév látszik."
L["Players' last names after their first. When off, first names only, which fit the narrow rows better."] = "A játékosok vezetékneve a keresztnevük után. Kikapcsolva csak keresztnevek, ezek jobban elférnek a keskeny sorokban."
L["Players' names in their class color, in every kind of chat (the game's own setting)."] = "A játékosok neve a kasztszínükben, minden chatfajtában (a játék saját beállítása)."
