L["Press 1 to 9 to pick a line or a reward, Space for the next step (accept, continue, complete), Escape to back out. Space never jumps while you talk. Other keys still go to the game, and in combat every key is the game's."] = "Az 1-9 gombokkal választasz sort vagy jutalmat, a Szóközzel a következő lépés (elfogadás, tovább, teljesítés), az Escape-pel kilépsz. Beszéd közben a Szóköz sosem ugrat. A többi gomb továbbra is a játéké, és harcban minden gomb a játéké."
L["Press Bind in spellbook (or open %s and switch on Click-cast at its top), then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more). That click on any of your unit frames then casts it on that unit. Close the spellbook when you're done: this page comes back. Left-click still targets and right-click opens the menu unless you bind them."] = "Nyomd meg a Kötés a varázskönyvben gombot (vagy nyisd meg ezt: %s, és kapcsold be a tetején a Click-cast kapcsolót), majd kattints egy varázslatra a kívánt egérgombbal (több lehetőségért tartsd lenyomva a Shiftet, Ctrl-t vagy Altot). Ez a kattintás bármelyik egységkereteden aztán erre az egységre varázsolja. Ha végeztél, zárd be a varázskönyvet: ez az oldal visszajön. A bal klikk továbbra is célba vesz, a jobb klikk a menüt nyitja, hacsak nem kötöd őket."
L["Press Train again: it takes a profession slot"] = "Nyomd meg újra a Tanulás gombot: elfoglal egy szakmahelyet"
L["Pressed border color"] = "Lenyomott keretszín"
L["Pressed color"] = "Lenyomott szín"
L["Pressed opacity"] = "Lenyomott átlátszatlanság"
L["Pressing C opens DaylightUI's character window. Turn it off to use the game's."] = "A C megnyomása a DaylightUI karakterablakát nyitja. Kapcsold ki, ha a játékét használnád."
L["Pressing O shows DaylightUI's window: who's online, people you played with, friend requests and your raid's groups. Turn it off to use the game's window."] = "Az O megnyomása a DaylightUI ablakát mutatja: ki van online, akikkel játszottál, barátkérések és a raided csoportjai. Kapcsold ki, ha a játék ablakát használnád."
