L["Shows a grid while frames are unlocked, and snaps them to it."] = "Rácsot mutat, amíg a keretek feloldva vannak, és arra illeszti őket."
L["Shows a handle on every frame. Drag to move it; right-click a handle to reset that frame."] = "Minden kereten fogantyút mutat. Húzd a mozgatáshoz; jobb klikk egy fogantyún visszaállítja azt a keretet."
L["Shows a macro's name on its button. When off, macros show their icon only."] = "A makró nevét a gombján mutatja. Kikapcsolva a makróknak csak az ikonja látszik."
L["Shows a sample of just this frame while you edit it, and every change as you make it. Stays on across pages until you switch it off; combat ends it."] = "Szerkesztés közben csak ennek a keretnek a mintáját mutatja, minden változással együtt. Oldalváltáskor is bekapcsolva marad, amíg ki nem kapcsolod; a harc befejezi."
L["Shows a sample of the line where it sits."] = "A sor mintáját mutatja ott, ahol ül."
L["Shows crowd control icons on each member."] = "Tömegirányítás-ikonokat mutat minden tagon."
L["Shows each button's key on the button. When off, the keys still work, you just don't see them."] = "Minden gomb billentyűjét a gombon mutatja. Kikapcsolva a billentyűk továbbra is működnek, csak nem látod őket."
L["Shows each pet's health as text."] = "Minden háziállat életerejét szövegként mutatja."
L["Shows each pet's name."] = "Minden háziállat nevét mutatja."
L["Shows only while the buff is up, like Power Word: Shield."] = "Csak addig látszik, amíg a buff fent van, mint a Power Word: Shield."
L["Shows or hides the row of bag buttons. Your bag keys still open your bags when it's hidden."] = "Megjeleníti vagy elrejti a táskagombok sorát. Elrejtve is a táskabillentyűid nyitják a táskáidat."
L["Shows or hides the row of small buttons that open your character, spellbook, talents and other windows. Their keys still work when it's hidden."] = "Megjeleníti vagy elrejti a kis gombok sorát, amik a karaktert, a varázskönyvet, a tehetségeket és más ablakokat nyitják. Elrejtve is működnek a billentyűik."
L["Shows server time instead of your local time."] = "Szerveridőt mutat a helyi időd helyett."
L["Shows target, focus, pet, target of target and the party with sample units, and both cast bars mid-cast, so you can style and move them without a real target. Ends when combat starts."] = "Mintaegységekkel mutatja a célpontot, a fókuszt, a háziállatot, a célpont célpontját és a csoportot, és mindkét varázslássávot varázslás közben, hogy valódi célpont nélkül is alakíthasd és mozgathasd őket. A harc kezdete befejezi."
L["Shows the AFK screen now. Click or press any key to close it. Also /dui afk."] = "Most megmutatja az AFK-képernyőt. Kattints vagy nyomj meg egy gombot a bezáráshoz. A /dui afk is ezt teszi."
L["Shows the calendar and tracking buttons on the map's right edge while the mouse is over the map."] = "A naptár- és követésgombokat a térkép jobb szélén mutatja, amíg az egér a térkép fölött van."
L["Shows the game's countdown on buttons that are on cooldown."] = "A játék visszaszámlálását mutatja a cooldownon lévő gombokon."
L["Shows the game's small gold coin on gray items in the bank, like the default bags."] = "A játék kis aranyérméjét mutatja a bankban lévő szürke tárgyakon, mint az alap táskákban."
L["Shows the game's small gold coin on gray items, like the default bags."] = "A játék kis aranyérméjét mutatja a szürke tárgyakon, mint az alap táskákban."
L["Shows the healer's name next to a heal on you."] = "A gyógyító nevét mutatja a rajtad lévő gyógyítás mellett."
L["Shows the unit's name on this frame."] = "Az egység nevét mutatja ezen a kereten."
L["Shows these raid frames in a party too, in place of the party frames."] = "Csoportban is ezeket a raidkereteket mutatja, a csoportkeretek helyett."
L["Shows this square on each member while its spell is on them."] = "Ezt a négyzetet mutatja minden tagon, amíg rajta van a varázslata."
L["Shows where the range is before the enemy gets there, faintly."] = "Halványan mutatja, hol kezdődik a tartomány, mielőtt az ellenség odaér."
L["Shrink icon when pressed"] = "Ikon zsugorodása lenyomáskor"
L["Silk"] = "Selyem"
L["Silver"] = "Ezüst"
L["Since %s"] = "%s óta"
L["Since you logged in"] = "A belépés óta"
L["Sitting by a campfire warms the screen with firelight and embers, a soft crackle plays, and your action bars and unit frames fade away. Move, target or cast and everything comes back; a fight brings it back at once. The sounds follow Soft UI sounds (General > Sound)."] = "Ha tábortűz mellett ülsz, tűzfény és parázs melegíti a képernyőt, halk pattogás szól, az akciósávjaid és egységkereteid pedig elhalványulnak. Mozdulj, vegyél célba valamit vagy varázsolj, és minden visszajön; egy harc azonnal visszahozza. A hangok a Halk felülethangokat követik (Általános > Hang)."
L["Size"] = "Méret"
L["Size of every plate, friendly and enemy. Plates keep this size at any distance."] = "Minden névtábla mérete, barátságos és ellenséges is. A névtáblák bármilyen távolságból megtartják ezt a méretet."
L["Size of the names and numbers on this meter's bars."] = "A nevek és számok mérete ennek a mérőnek a sávjain."
L["Size of the names and percents on the threat meter."] = "A nevek és százalékok mérete a fenyegetésmérőn."
L["Size of the numbers on the experience bar."] = "A számok mérete a tapasztalatsávon."
L["Size of the quest names in the quest log on the map. Zone names, levels and progress follow it."] = "A küldetésnevek mérete a térkép küldetésnaplójában. A zónanevek, szintek és a haladás ezt követik."
L["Size of the text on the reputation bar. Its font is the experience bar's."] = "A szöveg mérete a hírnévsávon. A betűtípusa a tapasztalatsávé."
L["Size target separately"] = "Célpont külön méretezése"
L["Sizing"] = "Méretezés"
