L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for Bank and alts alone: their rows show below."] = "A helyméret, térköz, méret, a tárgyak elrendezése, az üres helyek és a tárgyikon-jelölések a Táskák oldalt követik. Kapcsold ki, ha csak a Bank és altokra állítanád: a soraik alább jelennek meg."
L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for the bank alone: their rows show below."] = "A helyméret, térköz, méret, a tárgyak elrendezése, az üres helyek és a tárgyikon-jelölések a Táskák oldalt követik. Kapcsold ki, ha csak a bankra állítanád: a soraik alább jelennek meg."
L["Slots"] = "Helyek"
L["Slots per row in the Bank and alts window."] = "Helyek soronként a Bank és altok ablakban."
L["Slots per row in the bank. It holds more than your bags, so it's wider by default."] = "Helyek soronként a bankban. Több fér bele, mint a táskáidba, ezért alapból szélesebb."
L["Slots with nothing on them show as empty frames. When off, they disappear and show again while you drag a spell or item."] = "Az üres helyek üres keretként látszanak. Kikapcsolva eltűnnek, és csak akkor jelennek meg újra, amikor varázslatot vagy tárgyat húzol."
L["Small helpers and the game's windows in DaylightUI style."] = "Kis segédek és a játék ablakai DaylightUI stílusban."
L["Small helpers for looting, quests, trainers and more."] = "Kis segédek zsákmányoláshoz, küldetésekhez, oktatókhoz és még sok mihez."
L["Small helpers that save time every day. Each one says what it does."] = "Kis segédek, amik minden nap időt spórolnak. Mindegyik leírja, mit csinál."
L["Small helpers: faster looting, quest automation, trainers and more."] = "Kis segédek: gyorsabb zsákmányolás, küldetés-automatizálás, oktatók és még sok más."
L["Small icons in their own row, under the frame by default."] = "Kis ikonok saját sorban, alapból a keret alatt."
L["Small icons over your frame, nearest it. Off by default: your buff bars show them too."] = "Kis ikonok a kereted fölött, közvetlenül mellette. Alapból kikapcsolva: a buff-sávjaid is mutatják őket."
