L["Thank you for making DaylightUI possible."] = "Köszönjük, hogy lehetővé teszed a DaylightUI-t."
L["Thank you to everyone who supports DaylightUI and keeps it growing."] = "Köszönjük mindenkinek, aki támogatja a DaylightUI-t és segít, hogy fejlődjön."
L["That's as many builds as a set keeps: delete one first."] = "Egy szett ennyi buildet tart meg: előbb törölj egyet."
L["The '?' and the hand-in line."] = "A '?' és a leadási sor."
L["The AFK screen can't show in combat, a boss fight, a keystone or a PvP match."] = "Az AFK-képernyő nem jelenhet meg harcban, boss-harcban, keystone-ban vagy PvP-meccsen."
L["The Daylight chat box's own look and motion (Chat style: Daylight)."] = "A Daylight chatdoboz saját kinézete és mozgása (Chatstílus: Daylight)."
L["Daylight UI's own icons, the game's own round class icons, or with the Jiberish Fabled Icons addon installed, its Fabled styles (art by JiberishUI and its artists, read from that addon's own folder)."] = "A Daylight UI saját ikonjai, a játék saját kerek kasztikonjai, vagy telepített Jiberish Fabled Icons addonnal annak Fabled stílusai (a grafika a JiberishUI és alkotóié, az addon saját mappájából olvasva)."
L["The Legacy button shows DaylightUI's window: how far the next reward is, the challenges and the Legacy trees. Turn it off to use the game's window."] = "A Legacy gomb a DaylightUI ablakát mutatja: mennyire van a következő jutalom, a kihívások és a Legacy-fák. Kapcsold ki, ha a játék ablakát használnád."
L["The NPC window is switched off (/dui > Talk)."] = "Az NPC-ablak ki van kapcsolva (/dui > Beszélgetés)."
L["The Quests header stays when nothing is tracked, so you can see where the tracker is."] = "A Küldetések fejléc akkor is marad, ha semmit sem követsz, így látod, hol a követő."
L["The bank in the same look as your bags. Groups and moved items are shared with your bags."] = "A bank ugyanabban a kinézetben, mint a táskáid. A csoportok és az áthelyezett tárgyak közösek a táskáiddal."
L["The bar shades from dark to bright in its standing's colors, editable on the Gradients page."] = "A sáv sötéttől világosig színeződik a hírnévszintje színeiben, ami a Színátmenetek oldalon állítható."
L["The bar shades from dark to bright instead of one flat color. Reputation gets one per standing, editable on the Gradients page."] = "A sáv sötéttől világosig színeződik egyetlen sima szín helyett. A hírnév szintenként egyet kap, a Színátmenetek oldalon állítható."
L["The bar's color while the cast can't be interrupted, whatever the fill style."] = "A sáv színe, amíg a varázslás nem szakítható meg, a kitöltési stílustól függetlenül."
L["The bar's color while the cast can't be interrupted."] = "A sáv színe, amíg a varázslás nem szakítható meg."
L["The bars over enemies' heads: how big they are, and what they show."] = "A sávok az ellenségek feje fölött: mekkorák, és mit mutatnak."
L["The bars shade from dark to bright instead of one flat color. The color pairs are on General > Gradients."] = "A sávok sötéttől világosig színeződnek egyetlen sima szín helyett. A színpárok itt vannak: Általános > Színátmenetek."
L["The bars that hang off the end of the health for incoming heals and absorb shields. An overshield (a shield bigger than the health missing) follows the shield."] = "Az életerő végén lógó sávok az érkező gyógyításoknak és az elnyelő pajzsoknak. A túlpajzs (a hiányzó életerőnél nagyobb pajzs) a pajzsot követi."
L["The bars' color when Bar color is One color."] = "A sávok színe, ha a Sáv színe Egy szín."
L["The boxes behind the experience bar, minimap and damage meter, and the meters' and threat meter's own windows. At 0 opacity the boxes disappear; the minimap and bars still show."] = "A dobozok a tapasztalatsáv, a minitérkép és a sebzésmérő mögött, valamint a mérők és a fenyegetésmérő saját ablakai. 0 átlátszatlanságnál a dobozok eltűnnek; a minitérkép és a sávok látszanak."
L["The buffs wrap onto up to this many rows."] = "A buffok legfeljebb ennyi sorba tördelődnek."
L["The button's border lights up while the mouse is over it."] = "A gomb kerete felvillan, amíg rajta van az egér."
L["The button's border lights up while you press it."] = "A gomb kerete felvillan, amíg lenyomod."
L["The character window and its tabs (reputation, skills, PvP, currency, statistics), inspecting others."] = "A karakterablak és a fülei (hírnév, jártasságok, PvP, pénznem, statisztikák), mások megtekintése."
L["The chat only"] = "Csak a chat"
L["The chat window's text and the chat bubbles. General uses the font on General > Appearance."] = "A chatablak szövege és a szövegbuborékok. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The clock reads 18:30 instead of 6:30 PM."] = "Az óra 18:30-at mutat 6:30 PM helyett."
L["The color of a Curse debuff's border and dispel icon."] = "Az Átok debuff keretének és levételikonjának színe."
L["The color of a Disease debuff's border and dispel icon."] = "A Betegség debuff keretének és levételikonjának színe."
L["The color of a Magic debuff's border and dispel icon."] = "A Mágia debuff keretének és levételikonjának színe."
L["The color of a Poison debuff's border and dispel icon."] = "A Méreg debuff keretének és levételikonjának színe."
L["The color of the glow around your target's bar."] = "A célpontod sávja körüli fény színe."
L["The color of the last pip, or the whole row at max points, and the end of Color to full color."] = "Az utolsó jelölő színe, vagy maximális pontnál az egész soré, és a Színből teljes színbe vége."
L["The color of the names on the threat meter."] = "A nevek színe a fenyegetésmérőn."
L["The color of the names on this meter's bars."] = "A nevek színe ennek a mérőnek a sávjain."
L["The color of the outline around your target's bar."] = "A célpontod sávja körüli körvonal színe."
L["The color of the pull line across the threat bars."] = "A fenyegetéssávokon átfutó pull-vonal színe."
L["The color of the shaded spell cost on your power bar."] = "A varázslatköltség színe az erőforrássávodon."
L["The color of the stretch for damage shields."] = "A sebzéspajzsok szakaszának színe."
L["The color of the stretch past the health for heals on their way."] = "Az érkező gyógyítások életerő utáni szakaszának színe."
L["The color the border lights up in while the mouse is over a button."] = "A szín, amire a keret felvillan, amíg az egér egy gombon van."
L["The color the border lights up in while you press a button."] = "A szín, amire a keret felvillan, amíg lenyomsz egy gombot."
L["The color the execute range lights up in."] = "A szín, amire a végzési tartomány felvillan."
L["The colored sweep over the icon while its buff is up. When off, only the timer shows."] = "A színes söprés az ikonon, amíg a buffja fent van. Kikapcsolva csak az időzítő látszik."
L["The colors below"] = "Az alábbi színek"
L["The colors, font and textures used everywhere. The screen changes as you pick."] = "A mindenhol használt színek, betűtípus és textúrák. A képernyő a választásod szerint változik."
L["The cooldown layout can't be edited during combat."] = "A cooldown-elrendezés harc közben nem szerkeszthető."
L["The cooldown manager's layout."] = "A cooldown-kezelő elrendezése."
L["The countdown icons for your totems, above the player frame. Move them in unlock mode."] = "A totemjeid visszaszámláló ikonjai a játékoskeret fölött. Feloldott módban mozgathatod őket."
L["The crowd control alert's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "A tömegirányítás-riasztás helyét a játék Szerkesztő módja tárolja, és saját Szerkesztő mód elrendezést használsz: ott mozgasd (Esc > Edit Mode)."
L["The currencies you're tracking (as the game's own backpack list shows them), with their icon and count, beside your money."] = "A követett pénznemeid (ahogy a játék saját hátizsák-listája mutatja őket), ikonnal és darabszámmal, a pénzed mellett."
L["The dark part shrinks away instead of filling in."] = "A sötét rész fogy el, nem kitöltődik."
L["The dark ribbon behind each line. When off, only the icon and text show."] = "A sötét szalag minden sor mögött. Kikapcsolva csak az ikon és a szöveg látszik."
L["The debuffs wrap onto up to this many rows."] = "A debuffok legfeljebb ennyi sorba tördelődnek."
L["The dim line under each item's name. Repair warnings still show when it's off."] = "A halvány sor minden tárgy neve alatt. Kikapcsolva is látszanak a javítási figyelmeztetések."
L["The dungeon journal, its favorites and settings windows; each dungeon's picture kept."] = "A kazamatanapló, a kedvencei és a beállításablakai; minden kazamata képe marad."
L["The elite dragon wraps your own portrait too."] = "Az elit sárkány a saját portrédat is körbeöleli."
L["The empty bar pulses while the buff is down."] = "Az üres sáv lüktet, amíg a buff nincs fent."
L["The empty part behind every bar's fill, tinted in the bar's color, except where a frame's own page picks another."] = "Minden sáv kitöltése mögötti üres rész, a sáv színével árnyalva, kivéve, ahol egy keret saját oldala mást választ."
L["The empty part of every bar in the group. A spell's own background, above, wins."] = "A csoport minden sávjának üres része. Egy varázslat fenti saját háttere elsőbbséget kap."
L["The empty part of the Cooldown Manager's bars, behind the fill. General uses the bar background on General > Appearance."] = "A Cooldown-kezelő sávjainak üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the cast bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "A varázslássáv üres része minden névtáblán, a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the combo points on your target's nameplate, behind the fill. General uses the bar background on General > Appearance."] = "A célpontod névtábláján lévő kombópontok üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the combo points, behind the fill. General uses the bar background on General > Appearance."] = "A kombópontok üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of every meter's and threat meter's bars, behind the fill. General uses the bar background on General > Appearance."] = "Minden mérő és a fenyegetésmérő sávjainak üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the experience and reputation bar, behind the fill. General uses the bar background on General > Appearance."] = "A tapasztalat- és hírnévsáv üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the health bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "Az életerősáv üres része minden névtáblán, a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the health bar under a unit's tooltip, behind the fill. General uses the bar background on General > Appearance."] = "Az egység súgóbuboréka alatti életerősáv üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the pets' health bars, behind the fill. General uses the bar background on General > Appearance."] = "A háziállatok életerősávjainak üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the pets' power bars, behind the fill. General uses the bar background on General > Appearance."] = "A háziállatok erőforrássávjainak üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the progress bars in the tracker and the pop-up, behind the fill. General uses the bar background on General > Appearance."] = "A követő és a felugró haladássávjainak üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the raid tiles' health bars, behind the fill. General uses the bar background on General > Appearance."] = "A raidcsempék életerősávjainak üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the raid tiles' power bars, behind the fill. General uses the bar background on General > Appearance."] = "A raidcsempék erőforrássávjainak üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the swing timer, behind the fill. General uses the bar background on General > Appearance."] = "Az ütésidőzítő üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of this frame's health bar, behind the fill. General uses the bar background on General > Appearance."] = "Ennek a keretnek az életerősávja üres részének háttere a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of this frame's power bar, behind the fill. General uses the bar background on General > Appearance."] = "Ennek a keretnek az erőforrássávja üres részének háttere a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of your cast bar, behind the fill. General uses the bar background on General > Appearance."] = "A varázslássávod üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of your focus's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "A fókuszod varázslássávjának üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of your target's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "A célpontod varázslássávjának üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The experience bar on top of the panel, or reputation at the level cap."] = "A tapasztalatsáv a panel tetején, a szintplafonon a hírnév."
L["The experience bar's text and its +XP. General uses the font on General > Appearance."] = "A tapasztalatsáv szövege és a +XP. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The experience bar, damage meter and minimap fade together (and the separate meter window, if used)."] = "A tapasztalatsáv, a sebzésmérő és a minitérkép együtt halványul el (és a külön mérőablak is, ha használod)."
L["The faction's name on the bar."] = "A frakció neve a sávon."
L["The fifth chat channel you joined, often a custom one."] = "Az ötödik chatcsatorna, amibe beléptél, gyakran egy egyedi."
L["The fifth pip fills in Full color (red to start with), so a full row stands out at a glance."] = "Az ötödik jelölő Teljes színnel töltődik (kezdetben piros), így a teli sor első ránézésre kiugrik."
L["The fill of every bar: health, power, cast bars, swing timers, experience, the damage meter, nameplates and more, except where a frame's own page picks another. Textures other addons share (SharedMedia) are listed after ours."] = "Minden sáv kitöltése: életerő, erőforrás, varázslássávok, ütésidőzítők, tapasztalat, a sebzésmérő, névtáblák és még sok más, kivéve, ahol egy keret saját oldala mást választ. A más addonok által megosztott textúrák (SharedMedia) a mieink után vannak listázva."
L["The fill of the Cooldown Manager's bars. General uses the bar texture on General > Appearance."] = "A Cooldown-kezelő sávjainak kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the cast bar on every nameplate. General uses the bar texture on General > Appearance."] = "A varázslássáv kitöltése minden névtáblán. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the combo points on your target's nameplate. General uses the bar texture on General > Appearance."] = "A célpontod névtábláján lévő kombópontok kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the combo points. General uses the bar texture on General > Appearance."] = "A kombópontok kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of every meter's and threat meter's bars. General uses the bar texture on General > Appearance."] = "Minden mérő és a fenyegetésmérő sávjainak kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the experience and reputation bar. General uses the bar texture on General > Appearance."] = "A tapasztalat- és hírnévsáv kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the health bar on every nameplate. General uses the bar texture on General > Appearance."] = "Az életerősáv kitöltése minden névtáblán. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the health bar under a unit's tooltip. General uses the bar texture on General > Appearance."] = "Az egység súgóbuboréka alatti életerősáv kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the pets' health bars. General uses the bar texture on General > Appearance."] = "A háziállatok életerősávjainak kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the pets' power bars. General uses the bar texture on General > Appearance."] = "A háziállatok erőforrássávjainak kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the progress bars in the tracker and the pop-up. General uses the bar texture on General > Appearance."] = "A követő és a felugró haladássávjainak kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the raid tiles' health bars. General uses the bar texture on General > Appearance."] = "A raidcsempék életerősávjainak kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the raid tiles' power bars. General uses the bar texture on General > Appearance."] = "A raidcsempék erőforrássávjainak kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the swing timer. General uses the bar texture on General > Appearance."] = "Az ütésidőzítő kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of this frame's health bar. General uses the bar texture on General > Appearance."] = "Ennek a keretnek az életerősáv-kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of this frame's power bar. General uses the bar texture on General > Appearance."] = "Ennek a keretnek az erőforrássáv-kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of your cast bar. General uses the bar texture on General > Appearance."] = "A varázslássávod kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of your focus's cast bar. General uses the bar texture on General > Appearance."] = "A fókuszod varázslássávjának kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of your target's cast bar. General uses the bar texture on General > Appearance."] = "A célpontod varázslássávjának kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The font above shows everywhere at once, except where a frame's own page or the window font below picks another. This puts every one of those back on the font above."] = "A fenti betűtípus egyszerre mindenhol megjelenik, kivéve, ahol egy keret saját oldala vagy az alábbi ablakbetűtípus mást választ. Ez mindegyiket visszaállítja a fenti betűtípusra."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar. Also the game's own character and inspect windows while Daylight UI's are off."] = "A játékmenü, az addonlista, a makrók, az óra, a zsákmány, a foglalatozás, a fejlesztés, a bontó, az aukciósház, a szakmakönyv, a világtérkép kerete, a levegősáv. Továbbá a játék saját karakter- és megtekintő ablakai, amíg a Daylight UI-éi ki vannak kapcsolva."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the world map's frame, the breath bar."] = "A játékmenü, az addonlista, a makrók, az óra, a zsákmány, a foglalatozás, a fejlesztés, a bontó, az aukciósház, a világtérkép kerete, a levegősáv."
L["The game only reports range for your group; anyone else stays at full opacity."] = "A játék csak a csoportodnak jelzi a hatótávot; mindenki más teljes átlátszatlanságon marad."
L["The game shows it as a bar."] = "A játék sávként mutatja."
L["The game shows it as an icon."] = "A játék ikonként mutatja."
L["The game's chat in the DaylightUI look, in the bottom-left corner. Chat itself works as normal."] = "A játék chatje DaylightUI kinézetben, a bal alsó sarokban. A chat maga a szokásos módon működik."
L["The game's numbers that pop off what you hit, and the scrolling combat text over you."] = "A játék számai, amik a megütött célpontról pattannak le, és a fölötted görgő harci szöveg."
L["The game's own"] = "A játék sajátja"
L["The game's own messages: logins, /played, errors and the like."] = "A játék saját üzenetei: belépések, /played, hibák és hasonlók."
L["The game's own setting: a quest you accept goes straight into the tracker."] = "A játék saját beállítása: az elfogadott küldetés egyből a követőbe kerül."
L["The game's own setting: the map turns with you, so the way you face is always up. When off, north is always up."] = "A játék saját beállítása: a térkép veled fordul, így amerre nézel, mindig felül van. Kikapcsolva mindig észak van felül."
L["The game's own settings for how the numbers leave the target."] = "A játék saját beállításai arra, hogyan hagyják el a számok a célpontot."
L["The game's own switches."] = "A játék saját kapcsolói."
L["The game's own windows in the DaylightUI look."] = "A játék saját ablakai DaylightUI kinézetben."
L["The game's quest tracker, placed under the panel."] = "A játék küldetéskövetője a panel alá helyezve."
L["The game's scrolling text over your own character: hits you take, heals, procs and more."] = "A játék görgő szövege a saját karaktered fölött: kapott ütések, gyógyítások, procok és még sok más."
L["The game's tooltips."] = "A játék súgóbuborékai."
L["The game's windows Daylight UI didn't rebuild. Rebuilt windows have their own switches under Extras."] = "A játék ablakai, amiket a Daylight UI nem épített újra. Az újraépített ablakoknak saját kapcsolójuk van az Extrák alatt."
L["The gap between buff icons."] = "Rés a buff-ikonok között."
L["The gap between combo point pips."] = "Rés a kombópont-jelölők között."
L["The gap between combo points."] = "Rés a kombópontok között."
L["The gap between debuff icons."] = "Rés a debuff-ikonok között."
L["The gap between icons."] = "Rés az ikonok között."
L["The gap between lines, when there's more than one."] = "Rés a sorok között, ha több van."
L["The gap between one party frame and the next."] = "Rés két csoportkeret között."
L["The gap between this bar's buttons."] = "Rés ennek a sávnak a gombjai között."
L["The gap between this bar's icons."] = "Rés ennek a sávnak az ikonjai között."
L["The glowing border on a button when its spell procs."] = "A gomb világító kerete, amikor a varázslata procol."
L["The gold at the bottom of the bag counts up or down to its new amount. Needs Motion effects (General > Appearance)."] = "A táska alján lévő arany felfelé vagy lefelé számol az új összegig. Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["The green numbers over who you heal."] = "A zöld számok azok fölött, akiket gyógyítasz."
L["The guide window (old and new), its steps and its item and target boxes."] = "Az útmutatóablak (régi és új), a lépései, a tárgy- és célpontdobozai."
L["The hand and time on each bar. Attached under the cast bar, it's kept small enough for the bar."] = "A kéz és az idő minden sávon. A varázslássáv alá csatolva elég kicsi marad a sávhoz."
L["The health bar fills bottom to top instead of across."] = "Az életerősáv alulról felfelé töltődik, nem keresztben."
L["The health bar fills from the opposite side."] = "Az életerősáv az ellenkező oldalról töltődik."
L["The health bar's color for a dead unit."] = "Az életerősáv színe halott egységnél."
L["The health bar's color for a friendly NPC."] = "Az életerősáv színe barátságos NPC-nél."
L["The health bar's color for a player who went offline."] = "Az életerősáv színe kilépett játékosnál."
L["The health bar's color for an NPC someone else tagged first."] = "Az életerősáv színe olyan NPC-nél, amit valaki más címkézett meg előbb."
L["The health bar's color for an NPC that attacks you."] = "Az életerősáv színe téged támadó NPC-nél."
L["The health bar's color for an NPC that leaves you alone until you hit it."] = "Az életerősáv színe olyan NPC-nél, ami békén hagy, amíg meg nem ütöd."
L["The health bar's color when Health bar color is One color."] = "Az életerősáv színe, ha az Életerősáv színe Egy szín."
L["The health text shows at full health too. When off, it disappears while the unit is at full."] = "Az életerő-szöveg teli életerőnél is látszik. Kikapcsolva eltűnik, amíg az egység teli életerőn van."
L["The highest rank"] = "A legmagasabb rang"
L["The highlight color: Daylight's own quiet tone, the Daylight gradient, your class's color or its gradient (from the Gradients page), or one of your own."] = "A kiemelőszín: a Daylight saját visszafogott árnyalata, a Daylight színátmenet, a kasztod színe vagy színátmenete (a Színátmenetek oldalról), vagy egy saját szín."
L["The icon of the quest the minimap arrow points to (click a quest's icon to pick it), and the light behind an icon under the mouse."] = "Annak a küldetésnek az ikonja, amelyre a minitérkép nyila mutat (kattints egy küldetés ikonjára a kiválasztásához), és a fény az egér alatti ikon mögött."
L["The info panel, meter, map and tracker."] = "Az infópanel, a mérő, a térkép és a követő."
L["The item level of weapons and armor in the bank, in the bottom left corner."] = "A fegyverek és páncélok tárgyszintje a bankban, a bal alsó sarokban."
L["The item level of weapons and armor in the bottom left corner."] = "A fegyverek és páncélok tárgyszintje a bal alsó sarokban."
L["The kobolds in the mine carry candles on their heads to see in the dark. Bring me eight of them and I'll make it worth your while."] = "A bányában a koboldok gyertyát hordanak a fejükön, hogy lássanak a sötétben. Hozz nekem nyolcat, és megéri majd a fáradságot."
L["The layer the focus frame draws in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = "A réteg, amibe a fókuszkeret rajzolódik. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["The layer the focus target frame draws in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = "A réteg, amibe a fókusz célpontja keret rajzolódik. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["The layer the party frames draw in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = "A réteg, amibe a csoportkeretek rajzolódnak. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["The layer the pet frame draws in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = "A réteg, amibe a háziállat-keret rajzolódik. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["The layer the player frame draws in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = "A réteg, amibe a játékoskeret rajzolódik. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["The layer the PvP frames draw in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = "A réteg, amibe a PvP-keretek rajzolódnak. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["The layer the raid frames draw in, for every raid size. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = "A réteg, amibe a raidkeretek rajzolódnak, minden raidmérethez. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["The layer the target frame draws in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = "A réteg, amibe a célpontkeret rajzolódik. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["The layer the target of target frame draws in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = "A réteg, amibe a célpont célpontja keret rajzolódik. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["The layout: %s."] = "Az elrendezés: %s."
L["The leader tools are off: Unit Frames > Raid > Leader tools."] = "A vezetői eszközök ki vannak kapcsolva: Egységkeretek > Raid > Vezetői eszközök."
L["The leader tools open after the fight."] = "A vezetői eszközök a harc után nyílnak meg."
L["The leader tools sit beside Daylight UI's party or raid frames, which are off."] = "A vezetői eszközök a Daylight UI csoport- vagy raidkeretei mellett ülnek, amik ki vannak kapcsolva."
L["The leader's crown stays in a fight. When off, it hides while you're fighting."] = "A vezető koronája harcban is marad. Kikapcsolva harc közben elrejtve."
L["The level in front of each quest name."] = "A szint minden küldetésnév előtt."
L["The line under the open tab at the top (Character, Reputation, Skills...)."] = "A vonal a fenti nyitott fül alatt (Karakter, Hírnév, Jártasságok...)."
L["The line where the range starts. 0 hides it."] = "A vonal, ahol a tartomány kezdődik. A 0 elrejti."
L["The lines in the middle of the screen (interrupted, bags full, a new area found) in your font, errors in a soft red, easing in and out. Move them with /dui unlock. Turn it off to see the game's own red and yellow text."] = "A képernyő közepén megjelenő sorok (megszakítva, tele a táska, új terület felfedezve) a betűtípusodban, a hibák lágy pirosban, finoman be- és kiúszva. A /dui unlock paranccsal mozgathatod őket. Kapcsold ki, ha a játék saját piros és sárga szövegét látnád."
L["The list grows up from its handle instead of down. For a tracker placed low on the screen."] = "A lista a fogantyújától felfelé nő, nem lefelé. A képernyőn lent elhelyezett követőhöz."
L["The look everything shares: the font, the accent color and the window background."] = "A mindenhol közös kinézet: a betűtípus, a kiemelőszín és az ablakháttér."
L["The loot browser's window, its lists, buttons and dialogs; its icons and maps kept."] = "A zsákmányböngésző ablaka, a listái, gombjai és párbeszédablakai; az ikonjai és térképei maradnak."
L["The loot window's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "A zsákmányablak helyét a játék Szerkesztő módja tárolja, és saját Szerkesztő mód elrendezést használsz: ott mozgasd (Esc > Edit Mode)."
L["The lower ranks of each spell sit under the highest, so you can cast an older rank for less mana. When off, the spellbook lists only the highest rank. The spellbook page has the same switch (Hide ranks)."] = "Minden varázslat alacsonyabb rangjai a legmagasabb alatt ülnek, így egy régebbi rangot kevesebb manáért is elvarázsolhatsz. Kikapcsolva a varázskönyv csak a legmagasabb rangot listázza. A varázskönyv oldalán ugyanez a kapcsoló (Rangok elrejtése)."
L["The main hand bar's color."] = "A főkéz-sáv színe."
L["The marker and the arrow fade back while you're in combat, so they're never in the way."] = "A jelölő és a nyíl harc közben elhalványul, így sosem vannak útban."
L["The marker in the world that leads you to your quest."] = "A világban lévő jelölő, ami a küldetésedhez vezet."
L["The melee bars' color while Heroic Strike, Cleave or Maul waits for your next swing."] = "A közelharci sávok színe, amíg a Heroic Strike, a Cleave vagy a Maul a következő ütésedre vár."
L["The meter hides while you play solo."] = "A mérő rejtve van, amíg egyedül játszol."
L["The most buff icons at once."] = "Egyszerre legfeljebb ennyi buff-ikon."
L["The most buffs you can purge or steal one plate shows."] = "Egy névtábla legfeljebb ennyi levehető vagy ellopható buffot mutat."
L["The most debuff icons at once."] = "Egyszerre legfeljebb ennyi debuff-ikon."
L["The most debuffs from other players, shown after yours. Only with Mine first, then others."] = "Más játékosok debuffjai legfeljebb ennyi, a tieid után. Csak az Előbb a sajátjaim, aztán a többiek beállítással."
L["The most group members the threat meter lists at once, under the damage meter."] = "A fenyegetésmérő egyszerre legfeljebb ennyi csoporttagot listáz, a sebzésmérő alatt."
L["The most group members the threat meter lists at once."] = "A fenyegetésmérő egyszerre legfeljebb ennyi csoporttagot listáz."
L["The most icons this group shows at once."] = "Ez a csoport egyszerre legfeljebb ennyi ikont mutat."
L["The most of your buffs one friendly plate shows."] = "Egy barátságos névtábla legfeljebb ennyi buffodat mutatja."
L["The most of your debuffs one plate shows."] = "Egy névtábla legfeljebb ennyi debuffodat mutatja."
L["The most of your own debuffs shown at once."] = "Egyszerre legfeljebb ennyi saját debuff látszik."
L["The name floats above the bar, at its outer end. Long names are cut short."] = "A név a sáv fölött lebeg, a külső végénél. A hosszú nevek rövidülnek."
L["The name of a buff or debuff as it lands on you."] = "Egy buff vagy debuff neve, ahogy rád kerül."
L["The names on every unit frame, unless a frame picks its own. Class and reaction: players by class color, others by friendly, neutral or hostile."] = "A nevek minden egységkereten, hacsak egy keret nem választ sajátot. Kaszt és viszony: a játékosok kasztszínben, mások barátságos, semleges vagy ellenséges színben."
L["The newest first. Click one to move it again."] = "A legújabb elöl. Kattints egyre az újbóli áthelyezéshez."
L["The note box shows after the fight."] = "A megjegyzésdoboz a harc után jelenik meg."
L["The number on an icon showing how many stacks it has."] = "A szám egy ikonon, ami mutatja, hány halma van."
L["The numbers change color for the last seconds of the cooldown."] = "A számok a cooldown utolsó másodperceiben színt váltanak."
L["The numbers in objectives, like 3/8."] = "A számok a feladatokban, például 3/8."
L["The numbers on the bar, e.g. 1,200 / 5,000 (+800), where +800 is your rested XP."] = "A számok a sávon, pl. 1,200 / 5,000 (+800), ahol a +800 a pihent XP-d."
L["The numbers on the bar, e.g. 1,800 / 3,000."] = "A számok a sávon, pl. 1,800 / 3,000."
L["The numbers over what you hit."] = "A számok afölött, amit megütsz."
L["The off hand bar's color."] = "A mellékkéz-sáv színe."
L["The order of the quests inside each zone in the quest log on the map."] = "A küldetések sorrendje minden zónán belül a térkép küldetésnaplójában."
L["The outline every button is cut to. The icon, border and cooldown shade all follow it."] = "A körvonal, amire minden gomb ki van vágva. Az ikon, a keret és a cooldown-árnyék mind ezt követi."
L["The outline or glow in your accent color (Appearance), following it when it changes. When off, uses the colors below."] = "A körvonal vagy fény a kiemelőszínedben (Megjelenés), és követi, ha változik. Kikapcsolva az alábbi színeket használja."
L["The panel behind the chat, with its border. When off, only the chat text shows."] = "A panel a chat mögött, a keretével. Kikapcsolva csak a chatszöveg látszik."
L["The panel's framed box behind the list, as tall as what's shown."] = "A panel keretes doboza a lista mögött, olyan magas, amennyi látszik."
L["The pet's health bar takes the mood color instead: red unhappy, yellow content, green happy. Turn the square off to have only this."] = "A háziállat életerősávja a hangulat színét kapja helyette: piros boldogtalan, sárga elégedett, zöld boldog. Kapcsold ki a négyzetet, ha csak ezt akarod."
L["The pets' health text. General uses the font on General > Appearance."] = "A háziállatok életerő-szövege. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The pets' names. General uses the font on General > Appearance."] = "A háziállatok nevei. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The piece of the bar you just earned flashes and \"+XP\" rises; a sweep on a level up. Needs Motion effects (General > Appearance)."] = "A sáv épp megszerzett darabja felvillan, és felemelkedik a \"+XP\"; szintlépéskor söprés. Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["The pips widen to span the whole frame, so the row reads like a bar."] = "A jelölők kiszélesednek, hogy az egész keretet átfogják, így a sor sávként olvasható."
L["The pips' color with One color, or the color they start from with Color to full color."] = "A jelölők színe Egy színnél, vagy a kezdőszínük a Színből teljes színbe beállításnál."
L["The players who keep DaylightUI going. Thank you."] = "A játékosok, akik életben tartják a DaylightUI-t. Köszönjük."
L["The power bar's color when Power bar color is One color."] = "Az erőforrássáv színe, ha az Erőforrássáv színe Egy szín."
L["The power text shows while mana, rage or energy is full too. When off, it disappears at full."] = "Az erőforrás-szöveg akkor is látszik, ha a mana, a düh vagy az energia tele van. Kikapcsolva telinél eltűnik."
L["The proc border's color when Proc border is set to Your own color."] = "A proc-keret színe, ha a Proc-keret beállítás Saját szín."
L["The profile %s is ready. Choose it for this character (or a talent set) to use it."] = "A(z) %s profil kész. Válaszd ki ehhez a karakterhez (vagy egy tehetségszetthez) a használatához."
L["The profile %s: its settings, frame positions and Edit Mode layout. Ctrl+C to copy, then share it."] = "A(z) %s profil: a beállításai, a keretpozíciói és a Szerkesztő mód elrendezése. Ctrl+C a másoláshoz, aztán oszd meg."
L["The profile for your first talent set. Changing it asks to reload."] = "Az első tehetségszetted profilja. Módosításkor újratöltést kér."
L["The profile for your second talent set; swapping talents asks to switch."] = "A második tehetségszetted profilja; tehetségcserénél váltást kér."
L["The profile in use as text to copy and share."] = "A használt profil szövegként, másoláshoz és megosztáshoz."
L["The profile is ready. Reload to use it."] = "A profil kész. Töltsd újra a használatához."
L["The profile is used as it is; nothing in it changes."] = "A profil úgy kerül használatba, ahogy van; semmi sem változik benne."
L["The profile this character uses. Changing it asks to reload."] = "A profil, amit ez a karakter használ. Módosításkor újratöltést kér."
L["The profile's Edit Mode layout will be set after the reload (%s)."] = "A profil Szerkesztő mód elrendezése az újratöltés után áll be (%s)."
L["The quest log on the world map."] = "A küldetésnapló a világtérképen."
L["The quest under the mouse stays bright, the others ease dimmer."] = "Az egér alatti küldetés világos marad, a többi halványabb lesz."
L["The raid frames for 11 to 20 players. Show, fade, textures and fonts are on the Raid 10 page."] = "A raidkeretek 11-20 játékoshoz. A megjelenítés, elhalványítás, textúrák és betűtípusok a Raid 10 oldalon vannak."
L["The raid frames for 21 to 40 players. Show, fade, textures and fonts are on the Raid 10 page."] = "A raidkeretek 21-40 játékoshoz. A megjelenítés, elhalványítás, textúrák és betűtípusok a Raid 10 oldalon vannak."
L["The raid tiles' health text. General uses the font on General > Appearance."] = "A raidcsempék életerő-szövege. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The raid tiles' names. General uses the font on General > Appearance."] = "A raidcsempék nevei. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The ranged bar shows how far your target is instead of its name: Melee, Dead zone, 10 to 35 yd, Max range or Out of range."] = "A távolsági sáv a célpontod neve helyett azt mutatja, milyen messze van: Közelharc, Holtzóna, 10-35 yd, Legnagyobb hatótáv vagy Hatótávon kívül."
L["The ranged bar's color."] = "A távolsági sáv színe."
L["The reputation you're watching, always, on its own bar. Pick the faction on the Reputation page of the character window. Move it in unlock mode; drag its corner to resize."] = "A figyelt hírnév mindig, saját sávon. A frakciót a karakterablak Hírnév oldalán választod. Feloldott módban mozgasd; a sarkát húzva méretezd."
L["The ring (or name tab, or raid tile) that turns red while something is attacking the unit; an elite's dragon keeps its color, its eyes catch fire."] = "A gyűrű (vagy a névfül, vagy a raidcsempe), ami pirosra vált, amíg valami támadja az egységet; egy elit sárkánya megtartja a színét, a szeme lángra kap."
L["The role icon stays in a fight. When off, it hides while you're fighting."] = "A szerepikon harcban is marad. Kikapcsolva harc közben elrejtve."
L["The row above the bar that holds the name and the health number."] = "A sáv fölötti sor, ami a nevet és az életerőszámot tartja."
L["The same click again removes it."] = "Ugyanaz a kattintás újra eltávolítja."
L["The same colors as in the game's chat settings: a change shows in every chat tab."] = "Ugyanazok a színek, mint a játék chatbeállításaiban: a változás minden chatfülön látszik."
L["The same size as the top-right panel with its damage meter out."] = "Ugyanakkora, mint a jobb felső panel kihúzott sebzésmérővel."
L["The search failed. Try Refresh."] = "A keresés nem sikerült. Próbáld a Frissítéssel."
L["The shade over the health your damage over time spells will still take, on the target and on enemy nameplates."] = "Az árnyék azon az életerőn, amit az időbeli sebzéseid még levisznek, a célponton és az ellenséges névtáblákon."
L["The shade that sweeps over a button while it's on cooldown."] = "Az árnyék, ami végigsöpör egy gombon, amíg cooldownon van."
L["The short tag before these messages. Left empty it stays [%s]."] = "A rövid címke ezek előtt az üzenetek előtt. Üresen hagyva [%s] marad."
L["The side the whisper tiles and conversations slide out from. Left suits a chat on the right of your screen."] = "Az oldal, ahonnan a suttogás-csempék és beszélgetések kicsúsznak. A Bal a képernyőd jobb oldalán lévő chathez illik."
L["The size of each whisper tile."] = "Minden suttogás-csempe mérete."
L["The size of the entrance, flight master, boat and zeppelin symbols on the world map. They keep this size as you zoom."] = "A bejárat-, repülésmester-, hajó- és zeppelinjelek mérete a világtérképen. Nagyításkor is megtartják ezt a méretet."
L["The slim health bar. The name, the health number and the power line sit outside it."] = "A vékony életerősáv. A név, az életerőszám és az erőforrásvonal rajta kívül ül."
L["The small tab on the meter's left edge (it shows while the mouse is near) slides it out or back by hand."] = "A mérő bal szélén lévő kis fül (akkor látszik, ha az egér a közelben van) kézzel ki- vagy becsúsztatja."
L["The small tab that holds the name above the frame: its own border, corners, shadow, place and width."] = "A keret fölötti, nevet tartó kis fül: saját kerete, sarkai, árnyéka, helye és szélessége."
L["The small zone names over each group of quests."] = "A kis zónanevek minden küldetéscsoport fölött."
L["The soft light behind the model on the Character page."] = "A lágy fény a modell mögött a Karakter oldalon."
L["The soft light behind the model on the Character page. When off, only the window's background shows."] = "A lágy fény a modell mögött a Karakter oldalon. Kikapcsolva csak az ablak háttere látszik."
L["The space between the health bar and the power line under it."] = "A hely az életerősáv és az alatta lévő erőforrásvonal között."
L["The spell an enemy is casting, under its health bar."] = "A varázslat, amit egy ellenség épp varázsol, az életerősávja alatt."
L["The spell being cast, as a small icon left of the cast bar."] = "Az épp varázsolt varázslat, kis ikonként a varázslássávtól balra."
L["The spell name and time on the cast bars. General uses the font on General > Appearance."] = "A varázslat neve és ideje a varázslássávokon. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The spell name and time on your cast bar."] = "A varázslat neve és ideje a varázslássávodon."
L["The spell name and time on your cast bar. General uses the font on General > Appearance."] = "A varázslat neve és ideje a varázslássávodon. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The spell name and time on your focus's cast bar. General uses the font on General > Appearance."] = "A varázslat neve és ideje a fókuszod varázslássávján. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The spell name and time on your focus's cast bar. Inside the frame it's kept small enough for the power bar."] = "A varázslat neve és ideje a fókuszod varázslássávján. A kereten belül elég kicsi marad az erőforrássávhoz."
L["The spell name and time on your target's cast bar. General uses the font on General > Appearance."] = "A varázslat neve és ideje a célpontod varázslássávján. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The spell name and time on your target's cast bar. Inside the frame it's kept small enough for the power bar, unless Text size inside the frame is set."] = "A varázslat neve és ideje a célpontod varázslássávján. A kereten belül elég kicsi marad az erőforrássávhoz, hacsak a Szövegméret a kereten belül nincs beállítva."
L["The spell name and timer on the target's cast bar."] = "A varázslat neve és időzítője a célpont varázslássávján."
L["The spell name and timer while the bar sits inside the target frame, even past the power bar's height. 0 uses Target cast bar text size, kept small enough for the power bar."] = "A varázslat neve és időzítője, amíg a sáv a célpontkereten belül ül, akár az erőforrássáv magasságán túl is. A 0 a Célpont varázslássávjának szövegméretét használja, az erőforrássávhoz elég kicsiben."
L["The spell's icon at the end of your focus's cast bar. Not while it sits inside the frame."] = "A varázslat ikonja a fókuszod varázslássávjának végén. Nem, amíg a kereten belül ül."
L["The spell's icon at the end of your target's cast bar. Not while it sits inside the frame."] = "A varázslat ikonja a célpontod varázslássávjának végén. Nem, amíg a kereten belül ül."
L["The spell's name on every cast bar."] = "A varázslat neve minden varázslássávon."
L["The spell's own"] = "A varázslat sajátja"
L["The spell's own color (Renew green, a shield blue), or one you pick."] = "A varázslat saját színe (a Renew zöld, egy pajzs kék), vagy egy általad választott."
L["The spellbook and talent keys open DaylightUI's window. In a fight the game's own book opens, so you can still drag spells to your bars. Turn it off to always use the game's window."] = "A varázskönyv és a tehetségek gombja a DaylightUI ablakát nyitja. Harcban a játék saját könyve nyílik, hogy továbbra is húzhass varázslatokat a sávjaidra. Kapcsold ki, ha mindig a játék ablakát használnád."
L["The spellbook and talents, the profession windows, the professions book, the stable."] = "A varázskönyv és a tehetségek, a szakmaablakok, a szakmakönyv, az istálló."
L["The square minimap in the panel."] = "A szögletes minitérkép a panelen."
L["The stat group headers and the headers on the other pages. Each its own: a color per stat group, used in turn on the other pages."] = "A statisztikacsoportok fejlécei és a többi oldal fejlécei. Mind a sajátját: statisztikacsoportonként egy szín, sorban a többi oldalon is."
L["The sweep can't start in combat."] = "A söprés harcban nem indítható."
L["The swing timer's hand and time. General uses the font on General > Appearance."] = "Az ütésidőzítő keze és ideje. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The tag after a PvP quest's title."] = "A címke egy PvP-küldetés címe után."
L["The tag after a dungeon quest's title."] = "A címke egy kazamatás küldetés címe után."
L["The tag after a raid quest's title."] = "A címke egy raides küldetés címe után."
L["The tag after an elite quest's title."] = "A címke egy elit küldetés címe után."
L["The talents you're using now."] = "A most használt tehetségeid."
L["The target's and target of target's class and power gradients run the other way, so they mirror yours. Only for a horizontal gradient."] = "A célpont és a célpont célpontja kaszt- és erőforrás-színátmenetei a másik irányba futnak, így a tieid tükörképei. Csak vízszintes színátmenetnél."
L["The textures above show on every bar at once, except where a frame's own page or the window bars below pick another. This puts every one of those back on the textures above."] = "A fenti textúrák egyszerre minden sávon látszanak, kivéve, ahol egy keret saját oldala vagy az alábbi ablaksávok mást választanak. Ez mindegyiket visszaállítja a fenti textúrákra."
L["The thin line under each header. Like the tab underline: whatever Tab underline below is set to. Class gradient uses your class's colors from the Gradients page."] = "A vékony vonal minden fejléc alatt. Mint a fül aláhúzása: amire az alábbi Fül aláhúzása be van állítva. A Kaszt-színátmenet a kasztod színeit használja a Színátmenetek oldalról."
L["The thin power bar under the health bar."] = "A vékony erőforrássáv az életerősáv alatt."
L["The thin strip under the minimap with gold, gear, bag space and more."] = "A vékony csík a minitérkép alatt arannyal, felszereléssel, táskahellyel és még sok mással."
L["The threat bars' color when Bar color is One color."] = "A fenyegetéssávok színe, ha a Sáv színe Egy szín."
L["The threat colors slowly brighten and dim, quicker when a mob is about to switch. Needs the health bar, border or glow above."] = "A fenyegetésszínek lassan erősödnek és halványulnak, gyorsabban, ha egy mob mindjárt célpontot vált. Kell hozzá a fenti életerősáv, keret vagy fény."
L["The tick next to a finished objective."] = "A pipa egy teljesített feladat mellett."
L["The time at the bottom of the minimap."] = "Az idő a minitérkép alján."
L["The time before each message (the game's own setting)."] = "Az időpont minden üzenet előtt (a játék saját beállítása)."
L["The time left as a number on each icon."] = "A hátralévő idő számként minden ikonon."
L["The time left on a timed quest once it's under a minute."] = "Egy időzített küldetés hátralévő ideje, ha már egy perc alatt van."
L["The time left on a timed quest."] = "Egy időzített küldetés hátralévő ideje."
L["The time on every cast bar: what's left, what's left out of the whole cast, or nothing."] = "Az idő minden varázslássávon: a hátralévő, a hátralévő az egész varázsláshoz képest, vagy semmi."
L["The tint on a button while your target is out of range, when Out of range is set to Tint the icon."] = "A színezés egy gombon, amíg a célpontod hatótávon kívül van, ha a Hatótávon kívül beállítás Ikon színezése."
L["The unit you set as focus."] = "Az egység, amit fókusznak állítottál be."
L["The unit's health written on this frame."] = "Az egység életereje erre a keretre írva."
L["The whole Bank and alts window, slots, text and buttons together."] = "Az egész Bank és altok ablak, helyek, szöveg és gombok együtt."
L["The whole bag window, slots, text and buttons together."] = "Az egész táskaablak, helyek, szöveg és gombok együtt."
L["The whole bank window, slots, text and buttons together."] = "Az egész bankablak, helyek, szöveg és gombok együtt."
L["The whole bar, icons, text and background together."] = "Az egész sáv, ikonok, szöveg és háttér együtt."
L["The whole feed. Also the mouse wheel over its handle in /dui unlock."] = "Az egész zsákmánysáv. A /dui unlock alatt az egérgörgő is a fogantyúja fölött."
L["The whole group shows only during a fight."] = "Az egész csoport csak harc közben látszik."
L["The whole group shows only in a party or raid."] = "Az egész csoport csak csoportban vagy raidben látszik."
L["The whole pop-up, text and bar together."] = "Az egész felugró, szöveg és sáv együtt."
L["The width of a whisper conversation. It slides out beside the tiles, as tall as the chat."] = "Egy suttogás-beszélgetés szélessége. A csempék mellett csúszik ki, olyan magasan, mint a chat."
L["The window's title shows the player's last name after their first name."] = "Az ablak címe a játékos vezetéknevét is mutatja a keresztneve után."
L["The zone or area you're in, at the top of the map (above the coordinates)."] = "A zóna vagy terület, ahol vagy, a térkép tetején (a koordináták fölött)."
L["The zone or area you're in, at the top of the minimap."] = "A zóna vagy terület, ahol vagy, a minitérkép tetején."
L["Their class icon"] = "A kasztikonjuk"
L["Their initial"] = "A kezdőbetűjük"
L["Their initial in their class's colors, or their class icon from the set picked in Unit Frames (Daylight UI's own or a Jiberish style)."] = "A kezdőbetűjük a kasztjuk színeiben, vagy a kasztikonjuk az Egységkeretekben választott készletből (a Daylight UI sajátja vagy egy Jiberish stílus)."
L["Their keybinds work even when hidden. Move them in unlock mode."] = "A billentyűik rejtve is működnek. Feloldott módban mozgathatod őket."
L["Their own window"] = "Saját ablakuk"
L["Their own window and the chat"] = "Saját ablakuk és a chat"
L["Their own window: a tile beside the chat for each person you talk to; click one to open the conversation. The chat only: whispers stay in the chat like any other message."] = "Saját ablakuk: minden beszélgetőtársadnak egy csempe a chat mellett; kattints egyre a beszélgetés megnyitásához. Csak a chat: a suttogások a chatben maradnak, mint bármely más üzenet."
L["These are for talent set %s; each talent set keeps its own."] = "Ezek a(z) %s. tehetségszetthez tartoznak; minden tehetségszett a sajátját tartja."
L["These talents use the profile %s. Switch to it?"] = "Ezek a tehetségek a(z) %s profilt használják. Átváltasz rá?"
L["They come back if you log in on them."] = "Visszajönnek, ha belépsz velük."
L["Thick"] = "Vastag"
L["Thin"] = "Vékony"
L["Thin lines split the bar into 20 parts, like the classic bar: each one is 5% of a level."] = "Vékony vonalak 20 részre osztják a sávot, mint a klasszikus sávot: mindegyik egy szint 5%-a."
L["This Legacy tree isn't available yet."] = "Ez a Legacy-fa még nem érhető el."
L["This bar's own name size. Text size, under Whole group, sizes every bar's."] = "Ennek a sávnak a saját névmérete. Az Egész csoport alatti Szövegméret minden sávét méretezi."
L["This character"] = "Ez a karakter"
L["This character hasn't finished the setup guide, so moved frames go back when you log out. Type /dui install to finish it."] = "Ez a karakter nem fejezte be a beállítási útmutatót, ezért a mozgatott keretek kilépéskor visszaállnak. Írd be: /dui install, és fejezd be."
L["This character hasn't finished the setup guide, so what you change or move is lost when you log out. Finish the guide first, then make your changes."] = "Ez a karakter nem fejezte be a beállítási útmutatót, ezért amit módosítasz vagy mozgatsz, kilépéskor elvész. Előbb fejezd be az útmutatót, utána módosíts."
L["This character's, for the talent set in use. Covers your player, target, target of target, pet, focus, party and raid frames."] = "Ennek a karakternek a beállításai a használt tehetségszetthez. A játékos-, célpont-, célpont célpontja, háziállat-, fókusz-, csoport- és raidkeretekre vonatkozik."
L["This client has no aura container; target auras are off."] = "Ennek a kliensnek nincs auratárolója; a célpont-aurák ki vannak kapcsolva."
L["This fight"] = "Ez a harc"
L["This frame's health text and large number. General uses the font on General > Appearance."] = "Ennek a keretnek az életerő-szövege és nagy száma. Az Általános az Általános > Megjelenés betűtípusát használja."
L["This frame's names, and its level badge. General uses the font on General > Appearance."] = "Ennek a keretnek a nevei és a szintjelvénye. Az Általános az Általános > Megjelenés betűtípusát használja."
L["This frame's own outline, corners and shadow, so it can stand apart from the rest of your UI."] = "Ennek a keretnek a saját körvonala, sarkai és árnyéka, hogy elkülönülhessen a felületed többi részétől."
L["This frame's power text. General uses the font on General > Appearance."] = "Ennek a keretnek az erőforrás-szövege. Az Általános az Általános > Megjelenés betűtípusát használja."
L["This group's header. The other pages use the six colors in turn."] = "Ennek a csoportnak a fejléce. A többi oldal sorban használja a hat színt."
L["This icon's own size. Whole group, below, sizes every icon in the group."] = "Ennek az ikonnak a saját mérete. Az alábbi Egész csoport a csoport minden ikonját méretezi."
