L["Under the frame (slides out)"] = "A keret alatt (kicsúszik)"
L["Under the frame it continues the frame's angle and slides out as you cast. Between your frame and the target's it fills the gap, both ends angled like the frames beside it, with the swing timers fanning out under it. Above the frame or on its own it has its own size."] = "A keret alatt folytatja a keret dőlését, és varázsláskor kicsúszik. A kereted és a célpontéé között kitölti a rést, mindkét vége a mellette lévő keretekhez hasonlóan ferde, alatta legyezőszerűen az ütésidőzítők. A keret fölött vagy önállóan saját mérete van."
L["Under the frame, it continues the frame's angle. When off, its end is straight."] = "A keret alatt folytatja a keret dőlését. Kikapcsolva a vége egyenes."
L["Under the frame, or over it, clear of the name. The target's buffs or debuffs on that side move out of the way."] = "A keret alatt, vagy fölötte, a névtől távol. A célpont azon az oldalon lévő buffjai vagy debuffjai kitérnek az útjából."
L["Under the meter"] = "A mérő alatt"
L["Under the meter it rises out of the damage meter's bottom inside the panel, as wide as the meter, and the meter's rows make room. Docked (left or under), it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode (/dui unlock) and drag its corner to size it."] = "A mérő alatt a panelen belül a sebzésmérő aljából emelkedik ki, a mérő szélességében, és a mérő sorai helyet adnak neki. Dokkolva (balra vagy alatta) csak akkor látszik, ha a sebzésmérő nyitva van. A saját ablaka bárhová kerülhet: feloldott módban mozgasd (/dui unlock), és a sarkát húzva méretezd."
L["Under the meter it's part of the panel, with no window of its own."] = "A mérő alatt a panel része, saját ablak nélkül."
L["Under the panel"] = "A panel alatt"
