L["What Alt-click on a quest in the tracker does."] = "Mit csinál az Alt+kattintás egy küldetésen a követőben."
L["What a button does while your target is out of range. Not enough mana, rage or energy does the same (blue when tinted)."] = "Mit csinál egy gomb, amíg a célpontod hatótávon kívül van. A kevés mana, düh vagy energia ugyanezt teszi (színezéskor kékkel)."
L["What a click on a quest in the tracker does. Clicking its icon always makes it your priority, and right-click opens its menu."] = "Mit csinál egy kattintás egy küldetésen a követőben. Az ikonjára kattintás mindig a prioritásoddá teszi, a jobb klikk pedig a menüjét nyitja."
L["What a friendly NPC does (Innkeeper, Flight Master...) under its name, smaller."] = "Mit csinál egy barátságos NPC (Innkeeper, Flight Master...), a neve alatt, kisebben."
L["What an NPC does (Skinner, Flight Master...) under its name, smaller. Not inside instances."] = "Mit csinál egy NPC (Skinner, Flight Master...), a neve alatt, kisebben. Instance-ben nem."
L["What an interrupted cast bar does: Blade slices it in two, Shatter breaks it into shards, Snap cracks it in the middle, Burn out burns the fill away, Rewind whips it back to empty, Shockwave bursts light from it, Fizzle lets its light leak out. Your own interrupts light up in your accent color. Point at a choice to see it on the preview."] = "Mit csinál egy megszakított varázslássáv: a Penge kettévágja, a Széttörés szilánkokra töri, az Elpattanás középen megrepeszti, a Kiégés elégeti a kitöltést, a Visszatekerés visszacsapja üresre, a Lökéshullám fényt robbant ki belőle, az Elfüstölés kiszivárogtatja a fényét. A saját megszakításaid a kiemelőszínedben villannak fel. Mutass egy lehetőségre, hogy az előnézeten lásd."
L["What changed in each version."] = "Mi változott az egyes verziókban."
L["What changed in each version. Click a version to open or close it."] = "Mi változott az egyes verziókban. Kattints egy verzióra a megnyitásához vagy bezárásához."
L["What each enemy plate shows on and around its bar, and its colors."] = "Mit mutat minden ellenséges névtábla a sávján és körülötte, és milyen színekkel."
L["What each item's icon shows in the Bank and alts window."] = "Mit mutat minden tárgy ikonja a Bank és altok ablakban."
L["What each item's icon shows in the bank."] = "Mit mutat minden tárgy ikonja a bankban."
L["What each item's icon shows."] = "Mit mutat minden tárgy ikonja."
L["What each slot shows, left to right. The clock, framerate and coordinates are on the minimap too."] = "Mit mutat az egyes helyek, balról jobbra. Az óra, a képkockasebesség és a koordináták a minitérképen is ott vannak."
L["What fades, and when"] = "Mi halványul el, és mikor"
L["What happens to the fights you have so far when you enter a dungeon, raid or battleground: keep them, ask whether to reset, or reset at once. Running back after you die doesn't count."] = "Mi történjen az eddigi harcokkal, amikor kazamatába, raidbe vagy csatatérre lépsz: megtartja, megkérdezi, visszaállítsa-e, vagy azonnal visszaállítja. A halál utáni visszafutás nem számít."
L["What happens to the fights you have so far when you join a group: keep them, ask whether to reset, or reset at once."] = "Mi történjen az eddigi harcokkal, amikor csoportba lépsz: megtartja, megkérdezi, visszaállítsa-e, vagy azonnal visszaállítja."
L["What it shows"] = "Mit mutat"
L["What sits between the text's parts."] = "Mi kerül a szöveg részei közé."
L["What the away message says."] = "Mit mond a távolléti üzenet."
L["What the meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more. The button on the meter changes it too."] = "Mit listáz a mérő: sebzés, gyógyítás, kapott sebzés, megszakítások, levételek, halálok és még sok más. A mérőn lévő gomb is ezt váltja."
L["What the second meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more."] = "Mit listáz a második mérő: sebzés, gyógyítás, kapott sebzés, megszakítások, levételek, halálok és még sok más."
L["What the tracker does when you enter a dungeon, raid or battleground. It comes back as you leave."] = "Mit csinál a követő, amikor kazamatába, raidbe vagy csatatérre lépsz. Kilépéskor visszajön."
L["What this extra text shows first, like the name, the level or the guild."] = "Mit mutat ez az extra szöveg elsőként, például a nevet, a szintet vagy a céhet."
L["What this group takes. Click to change."] = "Mit fogad ez a csoport. Kattints a módosításhoz."
L["What this slot on the data text strip shows. Slots count from the left."] = "Mit mutat ez a hely az adatszöveg-csíkon. A helyek balról számolódnak."
L["What you loot and your skill-ups, sliding in as ribbons at the bottom right."] = "Amit zsákmányolsz, és a jártasságnövekedéseid, szalagként becsúszva jobb lent."
L["What you loot slides in at the bottom right of the screen in its quality color, more of the same adding to its count, and fades a few seconds later. Point at a line for the item's tooltip. Move it with /dui unlock."] = "Amit zsákmányolsz, a minőségi színében becsúszik a képernyő jobb alsó részére, az ugyanilyenek a darabszámához adódnak, és néhány másodperc múlva elhalványul. Mutass egy sorra a tárgy súgóbuborékáért. A /dui unlock paranccsal mozgathatod."
L["What's Training is still reading your spells."] = "A What's Training még olvassa a varázslataidat."
L["What's included"] = "Mi van benne"
L["What's new"] = "Újdonságok"
L["Wheel: louder or quieter"] = "Görgő: hangosabb vagy halkabb"
L["When a buff runs out, the spells after it slide over to fill its spot. When off, every spell keeps its place. A spell set to Keep its spot (Behavior tab) keeps it either way."] = "Ha egy buff lejár, az utána lévő varázslatok odacsúsznak a helyére. Kikapcsolva minden varázslat megtartja a helyét. A Tartsa a helyét beállítású varázslat (Viselkedés fül) így is, úgy is megtartja."
L["When a cast is interrupted, the bar stays full for a moment and says Interrupted."] = "Ha egy varázslást megszakítanak, a sáv egy pillanatig teli marad, és azt írja: Megszakítva."
L["When a reputation goes up a standing, like Friendly to Honored, the new standing rises in at the top of the screen in its color, with the faction's name and a bar showing how far into it you are. Follows Motion effects (General > Appearance)."] = "Ha egy hírnév szintet lép, például Friendlyből Honoredre, az új szint a színében beúszik a képernyő tetejére, a frakció nevével és egy sávval, ami mutatja, hol jársz benne. A Mozgáseffekteket követi (Általános > Megjelenés)."
L["When an NPC has only one thing to offer (a vendor, flight master, banker or trainer) and no quests, its window opens straight away. Hold Shift to see the dialogue."] = "Ha egy NPC-nek csak egy dolga van (árus, repülésmester, bankár vagy oktató), és nincs küldetése, az ablaka azonnal megnyílik. Tartsd lenyomva a Shiftet a párbeszédhez."
L["When auto loot is on, everything is picked up at once instead of one item at a time."] = "Ha az automatikus zsákmányolás be van kapcsolva, mindent egyszerre vesz fel, nem tárgyanként."
L["When hovering a button shows its spell or item tooltip."] = "Mikor mutassa egy gomb fölé víve a varázslata vagy tárgya súgóbuborékát."
L["When it shows"] = "Mikor látszik"
L["When not usable"] = "Ha nem használható"
L["When off, any debuff with a type (Magic, Curse, Disease, Poison) shows, even one you can't remove."] = "Kikapcsolva minden típusos debuff (Mágia, Átok, Betegség, Méreg) látszik, akkor is, ha nem tudod levenni."
L["When off, the game's own bag windows are used."] = "Kikapcsolva a játék saját táskaablakai működnek."
L["When off, the game's tracker stays where Edit Mode puts it."] = "Kikapcsolva a játék követője ott marad, ahová a Szerkesztő mód teszi."
L["When ready"] = "Ha kész"
L["When someone writes your name where people talk, it lights up in your accent color and the tab it lands in glows."] = "Ha valaki leírja a nevedet ott, ahol beszélgetnek, a kiemelőszínedben felvillan, és a fül, ahová érkezett, világít."
L["When the away message answers."] = "Mikor válaszol a távolléti üzenet."
L["When the shown bag bar fades and how far."] = "Mikor és mennyire halványul el a látható táskasáv."
L["When the shown micro menu fades and how far."] = "Mikor és mennyire halványul el a látható mikromenü."
L["When to show"] = "Mikor látszik"
L["When you destroy a good item, the confirmation box is filled in. You still press the button."] = "Ha egy jó tárgyat semmisítesz meg, a megerősítő mező kitöltődik. A gombot továbbra is te nyomod meg."
L["When you dodge, parry or an attack misses you."] = "Ha kitérsz, hárítasz, vagy egy támadás mellétalál."
L["When you go away, the world dims, the UI fades and your character stands beside a card with your name, zone, rested XP and a fun fact. Move, click or press any key to come back. Never in combat, boss fights, keystones or PvP matches."] = "Ha távol vagy, a világ elsötétül, a felület elhalványul, a karaktered pedig egy kártya mellett áll a neveddel, zónáddal, pihent XP-ddel és egy érdekes ténnyel. Mozdulj, kattints vagy nyomj meg egy gombot a visszatéréshez. Harcban, boss-harcban, keystone-ban és PvP-meccsen soha."
L["When you have forms"] = "Ha vannak formáid"
L["When you have totems"] = "Ha vannak totemjeid"
L["When your next auto-attack lands: a bar for each hand you swing with."] = "Mikor ér célba a következő automatikus támadásod: egy sáv minden kézhez, amivel ütsz."
L["Where \"Kicked by\" and the name show: beside the cast bar or under it."] = "Hol látszik a \"Megszakította\" és a név: a varázslássáv mellett vagy alatta."
L["Where along the frame the row starts: the angled end facing the middle of your screen, the middle, or the far end."] = "Hol kezdődik a sor a keret mentén: a képernyőd közepe felé néző ferde végnél, középen, vagy a túlsó végen."
L["Where along the frame's top the tab sits. A full-width tab always starts at the outer end. Or drag the tab in Design mode."] = "Hol ül a fül a keret teteje mentén. A teljes szélességű fül mindig a külső végén kezdődik. Vagy húzd a fület Tervező módban."
L["Where along the power bar the power text sits."] = "Hol ül az erőforrás-szöveg az erőforrássáv mentén."
L["Where new lines come in."] = "Hol érkeznek az új sorok."
L["Where on the button its key shows."] = "Hol látszik a gombon a billentyűje."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text."] = "Hol jelenik meg a beviteli mező. A panel alatt a chat alatt tart neki egy csíkot, így sosem takar szöveget."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text. At the bottom, the Daylight chat box lifts its messages over the box while you type."] = "Hol jelenik meg a beviteli mező. A panel alatt a chat alatt tart neki egy csíkot, így sosem takar szöveget. Alul a Daylight chatdoboz gépelés közben a mező fölé emeli az üzeneteit."
L["Where the dispel icon sits on each frame, or just outside it."] = "Hol ül a levételikon minden kereten, vagy épp azon kívül."
L["Where the interrupter's name shows: right of the cast bar or under it."] = "Hol látszik a megszakító neve: a varázslássávtól jobbra vagy alatta."
L["Where the leader crown sits on each frame, or just outside it."] = "Hol ül a vezetői korona minden kereten, vagy épp azon kívül."
L["Where the name sits across the bar: left, center or right."] = "Hol ül a név a sávon: bal, közép vagy jobb."
L["Where the name sits inside its tab: left, center or right."] = "Hol ül a név a fülén belül: bal, közép vagy jobb."
L["Where the numbers open when you hover the bar. Automatic opens them toward the middle of the screen."] = "Merre nyílnak a számok, amikor a sáv fölé viszed az egeret. Az Automatikus a képernyő közepe felé nyitja."
L["Where the raid marker sits on each frame, or just outside it."] = "Hol ül a raidjelölő minden kereten, vagy épp azon kívül."
L["Where the ready check answer sits on each frame, or just outside it."] = "Hol ül a készenléti válasz minden kereten, vagy épp azon kívül."
L["Where the role icon sits on each frame, or just outside it."] = "Hol ül a szerepikon minden kereten, vagy épp azon kívül."
L["Where things sit on your screen."] = "Hol ülnek a dolgok a képernyődön."
L["Where this category sits on the bar."] = "Hol ül ez a kategória a sávon."
L["Where this extra text sits on the frame, or just outside it."] = "Hol ül ez az extra szöveg a kereten, vagy épp azon kívül."
L["Where this group sits in the bag."] = "Hol ül ez a csoport a táskában."
L["Where to start"] = "Hol kezdjük"
L["Where you put it"] = "Ahová teszed"
L["Where your frames sit. Healers get the group as big tiles in the middle of the screen."] = "Hol ülnek a kereteid. A gyógyítók nagy csempékként kapják a csoportot a képernyő közepén."
L["Whether each raid group is a column, side by side, or a row, stacked down."] = "Minden raidcsoport oszlop legyen egymás mellett, vagy sor egymás alatt."
L["Whether the meter counts the fight you're in or every fight since the last reset."] = "A mérő az aktuális harcot számolja, vagy az utolsó visszaállítás óta minden harcot."
L["Whether the name tab's end is cut at an angle. Same as the frame follows the frame's own end."] = "A névfül vége ferdén legyen-e levágva. Az Ugyanaz, mint a keret a keret saját végét követi."
L["Whether the party frames stack down or line up across."] = "A csoportkeretek egymás alá vagy egymás mellé sorakozzanak."
L["Whether the second meter counts the fight you're in or every fight since the last reset."] = "A második mérő az aktuális harcot számolja, vagy az utolsó visszaállítás óta minden harcot."
L["Whether this extra group shows debuffs or buffs."] = "Ez az extra csoport debuffokat vagy buffokat mutasson."
L["Whether your bars and your frame step aside when you're not fighting. Every part has its own Visible setting later."] = "A sávjaid és a kereted félreálljanak-e, amikor nem harcolsz. Később minden résznek saját Látható beállítása van."
L["Which bar the rows below set."] = "Melyik sávot állítják az alábbi sorok."
L["Which buffs show."] = "Mely buffok látszanak."
L["Which buffs this group shows."] = "Mely buffokat mutatja ez a csoport."
L["Which buttons the look rows on this page change. A bar keeps what you change for it; the rest follows All bars."] = "Mely gombokat módosítják ezen az oldalon a kinézeti sorok. Egy sáv megtartja, amit neki állítasz; a többi a Minden sávot követi."
L["Which corner of the button its count shows in."] = "A gomb melyik sarkában látszik a darabszám."
L["Which debuffs show."] = "Mely debuffok látszanak."
L["Which debuffs this group shows."] = "Mely debuffokat mutatja ez a csoport."
L["Which end of the group stays put when a spell in it hides."] = "A csoport melyik vége marad a helyén, ha egy varázslat elrejtőzik benne."
L["Which frame the pips sit on."] = "Melyik kereten ülnek a jelölők."
L["Which key accepts, continues and completes. Enter is also the key that opens chat."] = "Melyik gomb fogad el, lép tovább és teljesít. Az Enter a chatet is megnyitja."
L["Which numbers"] = "Melyik számok"
L["Which of the four squares the rows below set."] = "A négy négyzet közül melyiket állítják az alábbi sorok."
L["Which part's fade the rows below set."] = "Melyik rész elhalványítását állítják az alábbi sorok."
L["Which quest tracker?"] = "Melyik küldetéskövető?"
L["Which side of its owner's frame each pet bar sits on."] = "A gazdája keretének melyik oldalán ül minden háziállat-sáv."
L["Which side of the list the quest item buttons sit on."] = "A lista melyik oldalán ülnek a küldetéstárgy-gombok."
L["Which stat groups start open. By class and spec: Attributes and the one that matters for you. Groups you open or fold yourself are remembered for each character."] = "Mely statisztikacsoportok induljanak nyitva. Kaszt és specializáció szerint: a Tulajdonságok és az, ami neked számít. A magad által nyitott vagy összecsukott csoportokat karakterenként megjegyzi."
L["Which way the color runs along a bar."] = "Merre fut a szín a sáv mentén."
L["Which way the row adds its icons, starting from its position."] = "Merre adja hozzá a sor az ikonjait, a helyétől indulva."
L["Which way the row of icons fills from its first icon."] = "Merre töltődik az ikonsor az első ikonjától."
L["While Heroic Strike, Cleave or Maul waits for your next swing, the melee bars change color and show its name."] = "Amíg a Heroic Strike, a Cleave vagy a Maul a következő ütésedre vár, a közelharci sávok színt váltanak, és mutatják a nevét."
L["While it's off cooldown but you can't cast it: Overpower before a dodge, Riposte before a parry, Execute on a healthy target. Show leaves it dimmed. Hide keeps its gap: the other spells don't move."] = "Amíg nincs cooldownon, de nem varázsolhatod el: Overpower kitérés előtt, Riposte hárítás előtt, Execute egészséges célponton. A Mutatás halványítva hagyja. Az Elrejtés megtartja a helyét: a többi varázslat nem mozdul."
L["While moving frames, edges and centers line up with other frames. Hold Shift to drop anywhere."] = "Keretek mozgatása közben a szélek és a középpontok más keretekhez igazodnak. Tartsd lenyomva a Shiftet, ha bárhová ejtenéd."
L["While possessing"] = "Irányítás közben"
L["While swinging"] = "Ütés közben"
L["While swinging: each bar only while its swing runs, gone between swings. In combat: all your bars while you're fighting."] = "Ütés közben: minden sáv csak az ütése alatt látszik, ütések között eltűnik. Harcban: minden sávod, amíg harcolsz."
L["While the buff or debuff isn't up, it keeps its spot as a grayed icon or an empty bar, so you see what's missing."] = "Amíg a buff vagy debuff nincs fent, szürke ikonként vagy üres sávként tartja a helyét, így látod, mi hiányzik."
L["While you cast, the power the spell will use is shaded on your power bar."] = "Varázslás közben a varázslat által felhasznált erőforrás árnyékolva látszik az erőforrássávodon."
L["While you have a bow, gun, crossbow, thrown weapon or wand."] = "Amíg íj, puska, számszeríj, dobófegyver vagy pálca van nálad."
L["While you have a target, every other plate fades so your target stands out. A plate that starts casting comes back to full."] = "Amíg van célpontod, minden más névtábla elhalványul, hogy a célpontod kiugorjon. A varázslásba kezdő névtábla teljesen visszajön."
L["While you have a weapon in your off hand."] = "Amíg fegyver van a mellékkezedben."
L["Whisper"] = "Suttogás"
L["Whisper %s"] = "Suttogás neki: %s"
L["Whisper color"] = "Suttogás színe"
L["Whisper sound"] = "Suttogás hangja"
L["Whispered"] = "Suttogott"
L["Battle.net whispers"] = "Battle.net-suttogások"
L["Game window skins"] = "Játékablak-skinek"
L["More windows"] = "További ablakok"
L["Spellbook, inspect, professions, group finder, mailbox, social and Legacy: each window's switch, its size and its own extras."] = "Varázskönyv, megtekintés, szakmák, csoportkereső, postaláda, közösség és Legacy: minden ablak kapcsolója, mérete és saját extrái."
L["Whispers"] = "Suttogások"
L["Whispers are part of the Daylight chat box: /dui chat daylight to use it."] = "A suttogások a Daylight chatdoboz részei: a /dui chat daylight paranccsal használhatod."
L["Whispers button"] = "Suttogások gomb"
L["Whispers from your Battle.net friends, and yours to them."] = "A Battle.net-barátaid suttogásai, és a tieid nekik."
L["Whispers in their own tab"] = "Suttogások saját fülön"
L["Whispers show in"] = "A suttogások helye"
L["Whispers you get and send."] = "A kapott és küldött suttogások."
L["White"] = "Fehér"
L["White, the unit's class color, or one you pick."] = "Fehér, az egység kasztszíne, vagy egy általad választott."
L["Who"] = "Ki"
L["Who a player or creature is targeting, in their color (\">> You <<\" when it's you)."] = "Kit vesz célba egy játékos vagy lény, a színében (\">> Te <<\", ha téged)."
L["Who interrupted position"] = "A megszakító helye"
L["Who to whisper?"] = "Kinek suttogsz?"
L["Who your focus is looking at."] = "Kire néz a fókuszod."
L["Who your target is looking at."] = "Kire néz a célpontod."
L["Who's closest to pulling your target, in a small window that slides out of the damage meter's left edge, along its bottom, or anywhere on its own."] = "Ki van legközelebb ahhoz, hogy magára húzza a célpontodat, egy kis ablakban, ami a sebzésmérő bal széléből csúszik ki, az alja mentén, vagy önállóan bárhol."
L["Whole bar"] = "Egész sáv"
L["Whole group"] = "Egész csoport"
L["Whole row in full color at max points"] = "Maximális pontnál az egész sor teljes színben"
L["Width"] = "Szélesség"
L["Window"] = "Ablak"
L["Window background opacity"] = "Ablakháttér átlátszatlansága"
L["Window bar background"] = "Ablaksáv háttere"
L["Window bar texture"] = "Ablaksáv textúrája"
L["Window font"] = "Ablak betűtípusa"
L["Window height"] = "Ablak magassága"
L["Window: talking opens a window at the side. Immersive: the talk is a card on the right, the camera comes in over your shoulder and the rest of the UI fades away until you're done. Vendors and trainers stay a window."] = "Ablak: a beszélgetés oldalt ablakot nyit. Magával ragadó: a beszélgetés egy kártya jobb oldalt, a kamera a vállad fölé jön, a felület többi része pedig elhalványul, amíg végzel. Az árusok és az oktatók ablakban maradnak."
L["Windows"] = "Ablakok"
L["Windows glide in and out, tooltips fade in, a spell's icon pops when it's ready, gold and XP count up. When off, everything snaps into place."] = "Az ablakok be- és kiúsznak, a súgóbuborékok beúsznak, egy varázslat ikonja felpattan, amikor kész, az arany és az XP felfelé számol. Kikapcsolva minden azonnal a helyére ugrik."
L["Windows open & close"] = "Ablakok nyitása és zárása"
L["With Keep its spot (Buff missing), it shows only when you need to cast it, like Battle Shout."] = "A Tartsa a helyét (Hiányzó buff) beállítással csak akkor látszik, amikor fel kell raknod, mint a Battle Shout."
L["With Show under Buff missing, Hide makes it appear only when you need to cast it, like Battle Shout."] = "Ha a Hiányzó buff alatt Mutatás van, az Elrejtés csak akkor jeleníti meg, amikor fel kell raknod, mint a Battle Shout."
L["With a fishing pole equipped, a quick right-click on the world casts Fishing. With no bait on the pole, the first click puts on the best bait in your bags. Holding the button still turns the camera, and clicking an NPC, an object or the bobber works as usual. Hold Shift, Ctrl or Alt to skip the cast."] = "Felszerelt horgászbottal egy gyors jobb klikk a világra elindítja a Fishinget. Ha nincs csali a boton, az első kattintás felteszi a legjobb csalit a táskáidból. A gomb lenyomva tartása továbbra is forgatja a kamerát, és az NPC-re, tárgyra vagy úszóra kattintás a szokásos módon működik. Tartsd lenyomva a Shiftet, Ctrl-t vagy Altot a dobás kihagyásához."
L["With a pet"] = "Háziállattal"
L["With both on, it shows only when you're in a group and in combat. The second meter follows these too."] = "Ha mindkettő be van kapcsolva, csak akkor látszik, ha csoportban és harcban vagy. A második mérő is ezeket követi."
L["With no portrait and no name tab, the role, marker, crown and dispel icons sit in the frame's corners."] = "Portré és névfül nélkül a szerep-, jelölő-, korona- és levételikonok a keret sarkaiban ülnek."
L["With the chat input at the bottom: while you type, the messages slide up and the box you type in sits under them, so it never covers a line."] = "Ha a chat beviteli mezője alul van: gépelés közben az üzenetek felcsúsznak, a beviteli mező pedig alattuk ül, így sosem takar sort."
L["With the immersive look, the NPC's words appear letter by letter and the choices drift in after them. Click or press the accept key to see them all at once."] = "Magával ragadó kinézetnél az NPC szavai betűről betűre jelennek meg, a választási lehetőségek pedig utánuk úsznak be. Kattints vagy nyomd meg az elfogadás gombját, hogy mindet egyszerre lásd."
L["With the immersive look, the camera comes in over your shoulder and looks at the NPC while you talk, then goes back to how you had it. Not while mounted or in a fight."] = "Magával ragadó kinézetnél a kamera beszélgetés közben a vállad fölé jön, és az NPC-re néz, utána visszaáll arra, ahogy volt. Hátason és harcban nem."
L["With the immersive look, the whole UI fades away while you talk, so only the NPC and the talk are left. A fight brings everything back at once."] = "Magával ragadó kinézetnél beszélgetés közben az egész felület elhalványul, így csak az NPC és a beszélgetés marad. Egy harc azonnal mindent visszahoz."
L["Withdraw"] = "Kivétel"
L["Withdraw gold"] = "Arany kivétele"
L["Within each zone. Most recent progress moves a quest up when a kill, item or objective counts. Nearest first looks again every few seconds as you move, never in a fight or a dungeon. Nothing moves in a fight."] = "Minden zónán belül. A Legutóbbi haladás feljebb viszi a küldetést, ha egy ölés, tárgy vagy feladat beszámít. A Legközelebbi elöl mozgás közben néhány másodpercenként újranéz, harcban vagy kazamatában soha. Harc közben semmi sem mozdul."
L["Wood pop"] = "Fapattanás"
L["Words to light up"] = "Felvillanó szavak"
