L["You get back %.0f mana every 5 seconds while not casting."] = "%.0f manát kapsz vissza 5 másodpercenként, amíg nem varázsolsz."
L["You keep"] = "Megtartod"
L["You parry about 1 in %d attacks from the front."] = "Nagyjából minden %d. elölről jövő támadást hárítasz."
L["You shoot every %.2f seconds. Lower is faster."] = "%.2f másodpercenként lősz. Kisebb érték = gyorsabb."
