L["You're in a group: the leader tools work for real. Leave the group to practice with sample members."] = "Csoportban vagy: a vezetői eszközök élesben működnek. Lépj ki a csoportból, ha mintatagokkal gyakorolnál."
L["You're in combat; this finishes as soon as it ends."] = "Harcban vagy; amint véget ér, ez befejeződik."
L["You're not in a guild."] = "Nem vagy céhben."
L["You're not in a raid."] = "Nem vagy raidben."
L["You're on talent set %d, which has no profile. New and Import make one for it."] = "A(z) %d. tehetségszetten vagy, aminek nincs profilja. Az Új és az Importálás készít neki egyet."
L["You're on talent set %d. The buttons below work on its profile, %s."] = "A(z) %d. tehetségszetten vagy. Az alábbi gombok a profilján működnek: %s."
L["You've already learned talents this build doesn't have. A trainer can reset them."] = "Már tanultál olyan tehetségeket, amik ebben a buildben nincsenek. Egy oktató visszaállíthatja őket."
L["Your action bars and their buttons."] = "Az akciósávjaid és a gombjaik."
L["Your attacks don't land critical hits yet."] = "A támadásaid még nem okoznak kritikus találatot."
L["Your attacks and spells miss %.1f%% less often."] = "A támadásaid és varázslataid %.1f%%-kal ritkábban hibáznak."
L["Your bags are full."] = "Tele vannak a táskáid."
L["Your bank from anywhere, and your other characters' bags and banks."] = "A bankod bárhonnan, és a többi karaktered táskái és bankjai."
L["Your bindings"] = "A kötéseid"
L["Your buffs"] = "A buffjaid"
L["Your buffs and debuffs."] = "A buffjaid és debuffjaid."
L["Your buffs grow direction"] = "A buffjaid növekedési iránya"
L["Your buffs left / right"] = "A buffjaid balra / jobbra"
L["Your buffs position"] = "A buffjaid helye"
L["Your buffs sorted into color-coded groups; debuffs edged by type."] = "A buffjaid színkódolt csoportokba rendezve; a debuffok típus szerinti szegéllyel."
L["Your buffs up / down"] = "A buffjaid fel / le"
L["Your buffs, minimap and info panel, quest tracker and chat fade away too, so only the fire and the world are left. Point at any of them to see it."] = "A buffjaid, a minitérkép és az infópanel, a küldetéskövető és a chat is elhalványulnak, így csak a tűz és a világ marad. Mutass bármelyikre, hogy lásd."
L["Your buffs, sorted into colored categories. Right-click a buff to cancel it; shift-click to move it to another category. The bar sits beside the info panel; to move it, turn off Attach to the info panel."] = "A buffjaid színes kategóriákba rendezve. Jobb klikk egy buffon leveszi; Shift+kattintás áthelyezi egy másik kategóriába. A sáv az infópanel mellett ül; a mozgatásához kapcsold ki a Csatolás az infópanelhez beállítást."
L["Your cast bar's color for a moment after your cast is interrupted."] = "A varázslássávod színe egy pillanatig azután, hogy megszakították a varázslásodat."
L["Your cast bar's color while you cast."] = "A varázslássávod színe varázslás közben."
L["Your cast bar's color while you channel."] = "A varázslássávod színe csatornázás közben."
L["Your cast bar's colors"] = "A varázslássávod színei"
L["Your casts and channels in your class color, or your class's gradient with a two-color fill. Not with the Daylight gradient."] = "A varázslásaid és csatornázásaid a kasztszínedben, vagy kétszínű kitöltésnél a kasztod színátmenetében. A Daylight színátmenettel nem."
L["Your character window: gear, model, stats and the other pages. It opens with C, as always."] = "A karakterablakod: felszerelés, modell, statisztikák és a többi oldal. A C-vel nyílik, mint mindig."
L["Your chat also comes back the next time you log in on this character, under a gray line with when you left."] = "A chated a következő belépéskor is visszajön ezen a karakteren, egy szürke vonal alatt, azzal, hogy mikor léptél ki."
L["Your class"] = "A kasztod"
L["Your class can heal; pick Healer if you do."] = "A kasztod tud gyógyítani; válaszd a Gyógyítót, ha azt csinálod."
L["Your class's pick"] = "A kasztod választása"
L["Your class's pick (%s)"] = "A kasztod választása (%s)"
L["Your class's pick follows your class on every character. Pick one to watch it instead."] = "A kasztod választása minden karakteren a kasztodat követi. Válassz egyet, ha inkább azt figyelnéd."
L["Your damage over time spells: the end of the health they will still take is shaded darker."] = "Az időbeli sebzéseid: az életerő azon vége, amit még levisznek, sötétebb árnyékot kap."
L["Your debuffs"] = "A debuffjaid"
L["Your debuffs, crowd control and buffs you can remove, on enemy plates."] = "A debuffjaid, a tömegirányítás és a levehető buffok az ellenséges névtáblákon."
L["Your focus's cast bar fills from the right. Not while it sits inside the frame."] = "A fókuszod varázslássávja jobbról töltődik. Nem, amíg a kereten belül ül."
L["Your focus's casts, while they last. It uses the target cast bar's colors."] = "A fókuszod varázslásai, amíg tartanak. A célpont varázslássávjának színeit használja."
L["Your frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares; Daylight gradient is the logo's blue to orange."] = "A kereted saját életerőszíne, hogy eltérhessen a többitől. Az Ugyanaz, mint a Színek oldal azt a színt követi, amin minden keret osztozik; a Daylight színátmenet a logó kékjétől a narancsig tart."
L["Your frames"] = "A kereteid"
L["Your frames per second beside the clock."] = "A képkockasebességed az óra mellett."
L["Your frames per second beside the clock. Hover it for latency, addon CPU and memory."] = "A képkockasebességed az óra mellett. Vidd fölé az egeret a késleltetésért, az addonok CPU- és memóriahasználatáért."
L["Your group is too big for a %d-player activity."] = "A csoportod túl nagy egy %d fős tevékenységhez."
L["Your guild's officer chat."] = "A céhed tiszti chatje."
L["Your heals over time and shields, everything you cast, or all of them. A class without heals or shields shows none."] = "Az időbeli gyógyításaid és pajzsaid, mindent, amit varázsolsz, vagy az összeset. Gyógyítás és pajzs nélküli kasztnál semmi."
L["Your health and mana come back faster while you're not fighting or casting."] = "Az életerőd és manád gyorsabban jön vissza, amíg nem harcolsz és nem varázsolsz."
L["Your health and power just under your character, the way Legion's personal display sat at your feet."] = "Az életerőd és erőforrásod közvetlenül a karaktered alatt, ahogy a Legion személyes kijelzője ült a lábadnál."
L["Your health bar, your power under it and, for rogues and druids, your combo points, just under your character. It follows the camera as you zoom."] = "Az életerősávod, alatta az erőforrásod és zsiványoknál, druidáknál a kombópontjaid, közvetlenül a karaktered alatt. Zoomoláskor követi a kamerát."
L["Your health. Each point adds about 10; you have %.0f."] = "Az életerőd. Minden pont nagyjából 10-et ad; neked %.0f van."
L["Your last name after your first, at the top of the window."] = "A vezetékneved a keresztneved után, az ablak tetején."
L["Your listing"] = "A hirdetésed"
L["Your main hand swings every %.2f seconds. Lower is faster."] = "A főkezed %.2f másodpercenként üt. Kisebb érték = gyorsabb."
L["Your mana, rage or energy under the health bar."] = "A manád, dühöd vagy energiád az életerősáv alatt."
L["Your melee attacks hit harder: Strength adds attack power."] = "A közelharci támadásaid erősebben ütnek: az Erő támadóerőt ad."
L["Your own cooldown layout: every spell the Cooldown Manager tracks as an icon or a bar, placed where you like and snapped together. One layout per talent set, for this character."] = "A saját cooldown-elrendezésed: minden varázslat, amit a Cooldown-kezelő követ, ikonként vagy sávként, oda téve, ahová szeretnéd, és összeillesztve. Tehetségszettenként egy elrendezés, ennél a karakternél."
L["Your own frame sits with the party's. When off, only the rest of the party shows."] = "A saját kereted a csoportéval együtt ül. Kikapcsolva csak a csoport többi tagja látszik."
L["Your own frame."] = "A saját kereted."
L["Your own groups"] = "A saját csoportjaid"
