L["this game client's Edit Mode isn't one DaylightUI knows"] = "ennek a játékkliensnek a Szerkesztő módja nem olyan, amit a DaylightUI ismer"
L["today"] = "ma"
L["try again in a moment"] = "próbáld újra egy pillanat múlva"
L["version %s loaded. Type %s for options."] = "%s verzió betöltve. A beállításokhoz írd be: %s."
L["yesterday"] = "tegnap"
L["you have the most account layouts the game allows; delete one in Edit Mode first"] = "elérted a játék által engedett fiókszintű elrendezések maximumát; előbb törölj egyet a Szerkesztő módban"
L["you're in combat"] = "harcban vagy"
L["your spellbook"] = "a varázskönyved"
L["your spellbook (%s)"] = "a varázskönyved (%s)"
L["A ! after each crit."] = "Egy ! minden kritikus után."
L["A - before damage and a + before heals."] = "Egy - a sebzés előtt és egy + a gyógyítás előtt."
L["A color for each kind"] = "Saját szín minden fajtának"
L["A line of light under each crit."] = "Fénycsík minden kritikus alatt."
L["A mob that needs you slowly brightens and dims, quicker when it's about to switch. For a tank that's a mob you lost, for damage and healers one attacking you. Needs the health bar, border or glow above."] = "Egy mob, aminek rád van szüksége, lassan erősödik és halványul, gyorsabban, ha mindjárt célpontot vált. Tanknak ez az elvesztett mob, sebzőnek és gyógyítónak az, amelyik őt támadja. Kell hozzá a fenti életerősáv, keret vagy fény."
L["A moving glow around the button while its spell is queued or being cast."] = "Mozgó fény a gomb körül, amíg a varázslata sorban áll vagy épp varázsolod."
L["A new group starts empty and waits in your bag: drag items onto its name, or click the search beside it here to fill it by itself."] = "Egy új csoport üresen indul, és a táskádban vár: húzz tárgyakat a nevére, vagy kattints itt a mellette lévő keresésre, hogy magától töltse fel."
L["A profile from the Profiles page, used as it is."] = "Egy profil a Profilok oldalról, ahogy van."
L["A quest under the mouse shows its objectives and clicks beside the tracker. When off, nothing shows and clicks work the same."] = "Az egér alatti küldetés a követő mellett mutatja a feladatait és kattintásait. Kikapcsolva semmi sem látszik, a kattintások ugyanúgy működnek."
L["A second bar above it."] = "Egy második sáv fölötte."
L["A second chat box with its own tabs, for loot, guild or a combat log. Right-click a chat tab to move it over, or drag it onto the other panel. Typing and whispers stay in the main chat."] = "Egy második chatdoboz saját fülekkel, zsákmányhoz, céhhez vagy harci naplóhoz. Jobb klikk egy chatfülön az áthelyezéshez, vagy húzd a másik panelre. A gépelés és a suttogások a fő chatben maradnak."
L["A shield landing on you."] = "Rád kerülő pajzs."
L["A slim angled bar at the bottom of the screen: the clock in the middle, your data texts on both sides."] = "Vékony ferde sáv a képernyő alján: középen az óra, két oldalon az adatszövegeid."
L["A small badge at the foot of the portrait"] = "Kis jelvény a portré alján"
L["A small button at the top-right of the chat for the game's chat menu: pick the language you speak, emotes, say, yell and more."] = "Kis gomb a chat jobb felső sarkában a játék chatmenüjéhez: válaszd ki a beszélt nyelvet, emote-ok, mondás, kiabálás és még sok más."
L["A small crown tab that opens ready check, role check, a pull timer, and target and world markers. It shows while you lead the group or assist in a raid. When off, these are only in the game's slash commands."] = "Kis koronás fül, ami a készenléti ellenőrzést, a szerepellenőrzést, a pull-időzítőt, a célpont- és világjelölőket nyitja. Akkor látszik, ha vezeted a csoportot vagy segédvezető vagy raidben. Kikapcsolva ezek csak a játék perjeles parancsaiban érhetők el."
L["A small icon and count at the end of a quest's line when others in your party have it too, here and in the quest log on the map."] = "Kis ikon és szám egy küldetés sorának végén, ha a csoportodban másoknak is megvan, itt és a térkép küldetésnaplójában."
L["A small icon before each text, in your accent color."] = "Kis ikon minden szöveg előtt, a kiemelőszínedben."
L["A small skull by the bar once your damage over time is enough to finish that enemy."] = "Kis koponya a sáv mellett, amint az időbeli sebzésed elég az ellenség végzéséhez."
L["A small slanted mark beside each line, in its color."] = "Kis ferde jel minden sor mellett, a színében."
L["A soft shadow under each line."] = "Lágy árnyék minden sor alatt."
L["A warning that stays up while your health or mana is low."] = "Figyelmeztetés, ami fent marad, amíg az életerőd vagy manád alacsony."
L["A whole look at once. Daylight leans the numbers along the UI's slant and lights up crits. Calm is small and slow. Punchy is big and flung out both ways. Classic curves like the game's own. Changing a row below makes it Custom."] = "Egy egész kinézet egyszerre. A Daylight a felület dőlése mentén dönti a számokat, és felvillantja a kritikusokat. A Nyugodt kicsi és lassú. Az Ütős nagy, és két irányba repül. A Klasszikus a játékéhoz hasonlóan ível. Egy alábbi sor módosítása Egyedire állítja."
L["About to switch"] = "Mindjárt vált"
L["Absorb shields gained"] = "Kapott elnyelő pajzsok"
L["Active border and glow color"] = "Aktív keret- és fényszín"
L["Addons made by other people on top of DaylightUI: plugins with features of their own, and profile packs with ready-made setups."] = "Mások által a DaylightUI-ra épített addonok: saját funkciókkal bíró bővítmények és kész beállításokat tartalmazó profilcsomagok."
L["After you cast a spell that costs mana, a light crosses your mana bar for the 5 seconds until your Spirit regen is back. Shows on your player frame and personal display."] = "Egy manába kerülő varázslat után fény fut végig a manasávodon arra az 5 másodpercre, amíg a Szellem-visszatöltődésed visszajön. A játékoskereteden és a személyes kijelződön látszik."
L["Alerts & Loot Won"] = "Riasztások és nyert zsákmány"
L["Always shown"] = "Mindig látható"
L["Always, or only while you hold this key."] = "Mindig, vagy csak amíg ezt a gombot nyomva tartod."
L["Amounts shortened (12.3K) or in full (12,345), on both meters, the breakdown and reports."] = "Összegek rövidítve (12.3K) vagy teljesen (12,345), mindkét mérőn, a részletezőben és a jelentésekben."
L["An outline keeps the text readable over bright ground and spell effects."] = "A körvonal olvashatóan tartja a szöveget világos talajon és varázslateffekteken is."
L["Angled frame"] = "Ferde keret"
L["Answers whispers for you, once per person every 15 minutes. Someone you whispered in that time doesn't get it."] = "Válaszol helyetted a suttogásokra, személyenként 15 percenként egyszer. Akinek ebben az időben te suttogtál, az nem kapja meg."
L["Anything else you can use lights up too: doors, levers, mailboxes."] = "Minden más használható is felvillan: ajtók, karok, postaládák."
L["As the main chat"] = "Mint a fő chat"
L["Attacking you"] = "Téged támad"
L["Attacks that didn't land on you."] = "Támadások, amik nem találtak el."
L["Automatic is your Appearance font. The sample above shows it at once; the numbers in the world change after you restart the game."] = "Az Automatikus a Megjelenés betűtípusa. A fenti minta azonnal mutatja; a világban lévő számok a játék újraindítása után változnak."
L["Automatic uses your Appearance font."] = "Az Automatikus a Megjelenés betűtípusát használja."
L["Bag bar and menu"] = "Táskasáv és menü"
L["Bar background opacity"] = "Sávháttér átlátszatlansága"
L["Bars and your frame fade after a fight."] = "A sávok és a kereted harc után elhalványulnak."
L["Basics"] = "Alapok"
L["Battle.net Logins"] = "Battle.net-belépések"
L["Beside the meter"] = "A mérő mellett"
L["Boss color"] = "Boss-szín"
L["Boss health bars in the color below, so they stand out in a crowd. Threat colors still show over it."] = "A bossok életerősávjai az alábbi színben, hogy kiugorjanak a tömegből. A fenyegetésszínek fölötte is látszanak."
L["Bosses in their own color"] = "Bossok saját színben"
L["Breath bar"] = "Levegősáv"
L["Brew"] = "Főzet"
L["Brings in the pack's newer version of this profile: its settings and frame positions replace yours. Your Edit Mode layout stays as it is."] = "Behozza a csomag újabb verzióját ebből a profilból: a beállításai és keretpozíciói felülírják a tieidet. A Szerkesztő mód elrendezésed marad, ahogy van."
L["Buffs gained and lost"] = "Kapott és elvesztett buffok"
