L["Cuts the end of your target's cast bar at an angle. When off, its end is straight. Not inside the frame or sliding out under it."] = "A célpontod varázslássávjának végét ferdén levágja. Kikapcsolva a vége egyenes. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Cuts the right end of each bar at an angle. When off, the ends are square."] = "Minden sáv jobb végét ferdén levágja. Kikapcsolva a végek szögletesek."
L["Cuts the right end of the breath bar at an angle, on the fatigue and feign death bars too. When off, the end is straight."] = "A levegősáv jobb végét ferdén levágja, a kimerültség- és halálszínlelés-sávokon is. Kikapcsolva a vége egyenes."
L["Cuts the right end of the flight timer at an angle. When off, the end is straight."] = "A repülésidőzítő jobb végét ferdén levágja. Kikapcsolva a vége egyenes."
L["Data bar"] = "Adatsáv"
L["Data Bar"] = "Adatsáv"
