L["Draws the turning map a little closer, so its corners never go empty when you face a diagonal. Off: the full view, with the corners cut."] = "A forgó térképet kicsit közelebb rajzolja, így a sarkai sosem üresek, amikor átlósan nézel. Kikapcsolva a teljes nézet, levágott sarkokkal."
L["Each item in the loot window flashes in its color as the light running down it passes, and again as you take it. When off, the light still runs and the items still ease in, without the flash."] = "A zsákmányablak minden tárgya a saját színében villan fel, amikor a rajta végigfutó fény eléri, és újra, amikor elveszed. Kikapcsolva a fény továbbra is fut, és a tárgyak beúsznak, villanás nélkül."
L["Error Messages"] = "Hibaüzenetek"
L["Everything stays on screen."] = "Minden a képernyőn marad."
L["Experience bar fade"] = "Tapasztalatsáv elhalványítása"
L["Experience bar has its own fade"] = "A tapasztalatsávnak saját elhalványítása van"
L["Fill the corners while turning"] = "Sarkok kitöltése forgás közben"
L["Fire orange, frost blue, shadow purple. When off, they use the Spell hits color."] = "Tűz narancs, fagy kék, árny lila. Kikapcsolva a Varázslattalálatok színét használják."
L["Fishing water"] = "Horgászvíz"
L["Fixed"] = "Rögzített"
L["Flare lands big in a burst of soft light. Slam lands bigger and faster. Pop is a small bump. Plain is just bigger text."] = "A Fellobbanás nagyban érkezik lágy fény kíséretében. A Csapás nagyobban és gyorsabban. A Pattanás egy kis ugrás. A Sima csak nagyobb szöveg."
L["Flip the loot feed left and right"] = "A zsákmánysáv tükrözése balra-jobbra"
L["Forge"] = "Kovácsműhely"
L["Framerate color"] = "Képkockasebesség színe"
L["Full (12,345)"] = "Teljes (12,345)"
L["Full numbers, or short ones for high-level play."] = "Teljes számok, vagy rövidek magas szintű játékhoz."
L["Gives the box you type in its own text size, set in the row below. When off, it matches the messages' text size."] = "A beviteli mező saját szövegméretet kap, az alábbi sorban állítva. Kikapcsolva az üzenetek szövegméretét követi."
L["Gives the second chat panel its own background opacity, set in the row below. When off, it's as see-through as the main chat panel."] = "A második chatpanel saját háttér-átlátszatlanságot kap, az alábbi sorban állítva. Kikapcsolva ugyanolyan áttetsző, mint a fő chatpanel."
L["Gives the window its own background opacity, set in the row below. When off, it's as see-through as the info panel's boxes (General page)."] = "Az ablak saját háttér-átlátszatlanságot kap, az alábbi sorban állítva. Kikapcsolva ugyanolyan áttetsző, mint az infópanel dobozai (Általános oldal)."
L["Glow on an active spell"] = "Fény az aktív varázslaton"
L["Glow on chests"] = "Fény a ládákon"
L["Glow on everything else"] = "Fény minden máson"
L["Glow on ore and herbs"] = "Fény az érceken és a növényeken"
L["Glow on quest objects"] = "Fény a küldetéstárgyakon"
L["Glow on your fishing bobber"] = "Fény a horgászúszódon"
L["Gone until a fight or a change."] = "Eltűnik egy harcig vagy változásig."
L["Group name color"] = "Csoportnév színe"
L["Group names"] = "Csoportnevek"
L["Guild names in the player's class color, plain white, or one color."] = "Céhnevek a játékos kasztszínében, sima fehérben, vagy egy színben."
L["Guild size"] = "Céhnév mérete"
L["Heals"] = "Gyógyítások"
L["Heals over time"] = "Időbeli gyógyítások"
L["Heals you receive."] = "A kapott gyógyítások."
L["Hides messages with these in public channels, never guild, group or whispers. Whole words; capitals don't matter. Chat style: Daylight only."] = "Elrejti a nyilvános csatornák ezeket tartalmazó üzeneteit, a céh, a csoport és a suttogás soha. Egész szavak; a kis- és nagybetű nem számít. Csak Daylight chatstílusnál."
L["Hits you take from spells."] = "Varázslatoktól kapott találatok."
L["Hits you take from weapons."] = "Fegyverektől kapott találatok."
L["Hover a text for details, click it to open its window. Move it in unlock mode (/dui unlock). When it reaches the screen's corners, chat and the damage meters' windows start above it unless you've moved them."] = "Vidd az egeret egy szöveg fölé a részletekért, kattints rá az ablaka megnyitásához. Feloldott módban mozgasd (/dui unlock). Ha eléri a képernyő sarkait, a chat és a sebzésmérők ablakai fölötte kezdődnek, hacsak nem mozgattad el őket."
L["Hovering an icon says what it is. While the mouse is on an icon, mouseover casting misses that player. Clicks always go through to the frame."] = "Egy ikon fölé víve az egeret megmondja, mi az. Amíg az egér egy ikonon van, az egér alatti varázslás nem éri azt a játékost. A kattintások mindig a keretig jutnak."
L["How a big hit or heal, or a spell lighting up, lands."] = "Hogyan érkezik egy nagy találat vagy gyógyítás, vagy egy felvillanó varázslat."
L["How big the coordinates are."] = "Mekkorák a koordináták."
L["How big the number of stacks is on each buff icon."] = "Mekkora a halomszám minden buff-ikonon."
L["How big the number of stacks is on each debuff icon."] = "Mekkora a halomszám minden debuff-ikonon."
L["How big the texts are. The one in the middle is a little bigger."] = "Mekkorák a szövegek. A középső kicsit nagyobb."
L["How big the time left is on each buff icon."] = "Mekkora a hátralévő idő minden buff-ikonon."
L["How big the time left is on each debuff icon."] = "Mekkora a hátralévő idő minden debuff-ikonon."
L["How big the zone name is."] = "Mekkora a zónanév."
L["How bright the light behind a crit is. At 0 there is none."] = "Milyen erős a fény egy kritikus mögött. 0-nál nincs."
L["How far a line travels. Stack ignores this."] = "Milyen messzire megy egy sor. A Tornyozás ezt figyelmen kívül hagyja."
L["How far under the object's name the light sits once you can reach it. The game doesn't say how tall an object is, so this is a best fit for most of them."] = "Milyen mélyen ül a fény a tárgy neve alatt, amint eléred. A játék nem mondja meg, milyen magas egy tárgy, ezért ez a legtöbbhöz illő becslés."
L["How long each buff and debuff has left, on its icon."] = "Mennyi ideje van hátra minden buffnak és debuffnak, az ikonján."
L["How low your health or mana gets before the warning shows."] = "Milyen alacsonyra kell esnie az életerődnek vagy manádnak, hogy megjelenjen a figyelmeztetés."
L["How much of the screen's width the bar takes, in percent."] = "A képernyő szélességének mekkora részét foglalja el a sáv, százalékban."
L["How see-through the experience bar's box and the meters' own windows are."] = "Mennyire áttetsző a tapasztalatsáv doboza és a mérők saját ablakai."
L["How solid the second chat panel's background is: 0 is fully see-through."] = "Mennyire tömör a második chatpanel háttere: a 0 teljesen áttetsző."
L["How solid the window's background is: 0 is fully see-through, leaving only the bars."] = "Mennyire tömör az ablak háttere: a 0 teljesen áttetsző, csak a sávok maradnak."
L["How tall a crit is once it settles."] = "Milyen magas egy kritikus, miután megállapodott."
L["How tall a line of text is."] = "Milyen magas egy szövegsor."
L["How tall the data bar is."] = "Milyen magas az adatsáv."
L["Import a layout"] = "Elrendezés importálása"
L["In a group, colors a mob by who it's attacking; solo plates never change. Red while it's attacking you, yellow while it's attacking someone else, orange when it's about to switch."] = "Csoportban a mobot aszerint színezi, kit támad; egyedül a névtáblák sosem változnak. Piros, amíg téged támad, sárga, amíg valaki mást, narancs, ha mindjárt vált."
L["Its own section in the list on the left, under Plugins."] = "Saját szakasz a bal oldali listában, a Bővítmények alatt."
L["Its ready-made profiles are on the Profiles page and in the setup guide."] = "A kész profiljai a Profilok oldalon és a beállítási útmutatóban vannak."
L["Its tooltips in the Daylight UI frame, in your background opacity. Its layout, words and stat colors stay."] = "A súgóbuborékai a Daylight UI keretben, a te háttér-átlátszatlanságoddal. Az elrendezése, szövegei és statisztikaszínei maradnak."
