L["Meter numbers"] = "Mérőszámok"
L["Mining veins and herbs light up."] = "Az ércerek és a növények felvillannak."
L["Mirrors the feed: lines line up on the left, slide in from the left and leave to the right, with the icon at the right end. Handy when the feed sits on the left of the screen. When off, lines line up on the right."] = "Tükrözi a zsákmánysávot: a sorok balra igazodnak, balról csúsznak be és jobbra távoznak, az ikon a jobb végen. Hasznos, ha a zsákmánysáv a képernyő bal oldalán ül. Kikapcsolva a sorok jobbra igazodnak."
L["Mobs that use mana in the color below: the ones to interrupt or pull out of line of sight. A boss or rare keeps its own color. Threat colors still show over it."] = "A manát használó mobok az alábbi színben: azok, amiket meg kell szakítani vagy ki kell húzni a rálátásból. Egy boss vagy ritka megtartja a saját színét. A fenyegetésszínek fölötte is látszanak."
L["Mouseover casting"] = "Egér alatti varázslás"
L["Mouseover key"] = "Egér alatti gomb"
L["Move the text streams"] = "Szövegfolyamok mozgatása"
L["Moves your cast bar under the personal display, as wide as it."] = "A varázslássávodat a személyes kijelző alá teszi, annak szélességében."
L["Moves your swing timers under the personal display, as wide as it."] = "Az ütésidőzítőidet a személyes kijelző alá teszi, annak szélességében."
L["NPC jobs in soft tan, plain white, or one color."] = "NPC-foglalkozások lágy drappban, sima fehérben, vagy egy színben."
L["Names of the players in your party or raid in their own color."] = "A csoportod vagy raided játékosainak nevei saját színben."
L["New options"] = "Új beállítások"
L["Not attacking you"] = "Nem téged támad"
L["Nudges it left or right from under the health bar, in pixels. In Design mode on the preview, drag it there."] = "Balra vagy jobbra tolja az életerősáv alól, pixelben. Tervező módban az előnézeten húzd oda."
L["Nudges it up or down from under the health bar, in pixels. In Design mode on the preview, drag it there."] = "Fel vagy le tolja az életerősáv alól, pixelben. Tervező módban az előnézeten húzd oda."
L["Numbers"] = "Számok"
L["Object glow"] = "Tárgyfény"
L["Object glow color"] = "Tárgyfény színe"
L["Object glow height"] = "Tárgyfény magassága"
L["Object glow in dungeons and raids"] = "Tárgyfény kazamatában és raidben"
L["Object glow in fights"] = "Tárgyfény harcban"
L["Object glow look"] = "Tárgyfény kinézete"
L["Objects glow in dungeons, raids and battlegrounds too."] = "A tárgyak kazamatában, raidben és csatatéren is világítanak."
L["Objects in the world"] = "Tárgyak a világban"
L["Objects keep glowing while you're in a fight."] = "A tárgyak harc közben is világítanak."
L["Objects your quests need light up."] = "A küldetéseidhez szükséges tárgyak felvillannak."
L["Hits on you"] = "Rád mért találatok"
L["One color for each threat state, or a gradient for each. The gradients are also on General > Gradients."] = "Egy szín minden fenyegetési állapothoz, vagy mindegyikhez egy színátmenet. A színátmenetek itt is megvannak: Általános > Színátmenetek."
L["One row"] = "Egy sor"
L["Ore, herbs, chests, quest objects and your fishing bobber light up as you come near, dim from afar and bright once you can reach them. Ore and herbs only glow for a character who can gather them. This changes a few of the game's interact settings while it's on, and gives them back when it's off."] = "Az ércek, növények, ládák, küldetéstárgyak és a horgászúszód felvillannak, ahogy közeledsz, messziről halványan, elérhető távolságban erősen. Az ércek és a növények csak annak a karakternek világítanak, aki gyűjteni tudja őket. Amíg be van kapcsolva, a játék néhány interakciós beállítását módosítja, és kikapcsoláskor visszaadja őket."
L["Paging: this bar can show another page of buttons while you're in a stance or form, while you hold a key, or when your target is friendly or an enemy. Pick a spare page to fill it with spells of its own."] = "Lapozás: ez a sáv egy másik gomblapot mutathat, amíg egy tartásban vagy formában vagy, amíg egy gombot nyomva tartasz, vagy ha a célpontod barátságos vagy ellenséges. Válassz egy tartaléklapot, hogy saját varázslatokkal töltsd fel."
L["Party members on a quest"] = "Csoporttagok a küldetésen"
L["Paste a string"] = "Szöveg beillesztése"
L["Personal absorbs"] = "Személyes elnyelések"
L["Personal display angle"] = "Személyes kijelző dőlése"
L["Personal health bar"] = "Személyes életerősáv"
L["Personal incoming heals"] = "Személyes érkező gyógyítások"
L["Plays it in the middle of the screen. Also /dui glow."] = "Lejátssza a képernyő közepén. A /dui glow is ezt teszi."
L["Plays it now; move to end it. Also /dui brew."] = "Most lejátssza; mozdulj a befejezéshez. A /dui brew is ezt teszi."
L["Plays it now; move to end it. Also /dui fishing."] = "Most lejátssza; mozdulj a befejezéshez. A /dui fishing is ezt teszi."
L["Plays it now; move to end it. Also /dui forge."] = "Most lejátssza; mozdulj a befejezéshez. A /dui forge is ezt teszi."
L["Plays it now; move to end it. Also /dui sewing."] = "Most lejátssza; mozdulj a befejezéshez. A /dui sewing is ezt teszi."
L["Plays it now; move to end it. Also /dui workshop."] = "Most lejátssza; mozdulj a befejezéshez. A /dui workshop is ezt teszi."
L["Plus and minus signs"] = "Plusz és mínusz jelek"
L["Preview the brew"] = "A főzet előnézete"
L["Preview the fishing water"] = "A horgászvíz előnézete"
L["Preview the forge"] = "A kovácsműhely előnézete"
L["Preview the object glow"] = "A tárgyfény előnézete"
L["Preview the sewing"] = "A varrás előnézete"
L["Preview the workshop"] = "A műhely előnézete"
L["Puts this font on the game's own text as well: menus, tooltips, quest text, popups, nameplate names. Sizes and outlines stay the game's."] = "Ezt a betűtípust a játék saját szövegeire is ráteszi: menük, súgóbuborékok, küldetésszöveg, felugró ablakok, névtábla-nevek. A méretek és körvonalak a játéké maradnak."
L["QuestieDB isn't on, so the arrow is left out: it needs QuestieDB to know where each mob is."] = "A QuestieDB nincs bekapcsolva, ezért a nyíl kimarad: a QuestieDB kell ahhoz, hogy tudja, hol van minden mob."
L["Rare and rare elite health bars in the color below. Threat colors still show over it."] = "A ritka és ritka elit életerősávok az alábbi színben. A fenyegetésszínek fölötte is látszanak."
L["Rare color"] = "Ritka szín"
L["Rares in their own color"] = "Ritkák saját színben"
L["Replaces the game's damage meter window. The tab on the panel's edge, on the meter's side, also shows or hides it."] = "A játék sebzésmérő-ablakát váltja ki. A panel szélén, a mérő oldalán lévő fül is megjeleníti vagy elrejti."
L["Rest the mouse on a frame and press a spell on your action bars: it goes to that player, with no click and no change of target. Works on anyone the mouse is on, in the world too, and with mouse buttons bound to your bars. This is the game's own setting."] = "Vidd az egeret egy keretre, és nyomj meg egy varázslatot az akciósávjaidon: arra a játékosra megy, kattintás és célpontváltás nélkül. Bárkin működik, akin az egér van, a világban is, és az akciósávjaidra kötött egérgombokkal is. Ez a játék saját beállítása."
L["Right stream"] = "Jobb folyam"
L["Right stream alignment"] = "Jobb folyam igazítása"
L["Right stream crit size"] = "Jobb folyam kritikusmérete"
L["Right stream motion"] = "Jobb folyam mozgása"
L["Right stream text size"] = "Jobb folyam szövegmérete"
L["Right stream time on screen"] = "Jobb folyam ideje a képernyőn"
L["Right stream travel distance"] = "Jobb folyam útja"
L["Rows added after this version carry a NEW tag as you go through the pages. Search for new to list them all."] = "Az e verzió után hozzáadott sorok ÚJ címkét kapnak, ahogy végigmész az oldalakon. Keress rá erre: new, hogy mind listázva legyen."
L["Second chat panel"] = "Második chatpanel"
L["Second meter window background opacity"] = "Második mérőablak háttér-átlátszatlansága"
L["Second panel"] = "Második panel"
L["Second panel background opacity"] = "Második panel háttér-átlátszatlansága"
L["Second panel height"] = "Második panel magassága"
L["Second panel hides"] = "Második panel elrejtése"
L["Second panel width"] = "Második panel szélessége"
L["Seconds a line stays before it fades."] = "Egy sor ennyi másodpercig marad, mielőtt elhalványul."
L["Separate chat input text size"] = "Külön szövegméret a chat beviteli mezőjének"
L["Separate second meter window background opacity"] = "Külön háttér-átlátszatlanság a második mérőablaknak"
L["Separate second panel background opacity"] = "Külön háttér-átlátszatlanság a második panelnek"
L["Sewing"] = "Varrás"
L["Short (12.3K)"] = "Rövid (12.3K)"
L["Short labels like Gear, Bags and Guild before each number. They drop off when the bar is too narrow."] = "Rövid címkék, mint Felsz., Táskák és Céh minden szám előtt. Eltűnnek, ha a sáv túl keskeny."
L["Show NEW on options added since"] = "ÚJ címke az azóta hozzáadott beállításokon"
L["Show combat text"] = "Harci szöveg mutatása"
L["Show keybind"] = "Billentyű mutatása"
L["Show keybinds on icons"] = "Billentyűk mutatása az ikonokon"
L["Show leader tools"] = "Vezetői eszközök mutatása"
L["Show quest tooltips"] = "Küldetés-súgóbuborékok mutatása"
L["Show the data bar"] = "Adatsáv mutatása"
L["Show the left stream"] = "Bal folyam mutatása"
L["Show the right stream"] = "Jobb folyam mutatása"
L["Show the top stream"] = "Felső folyam mutatása"
L["Side bars that fade until you need them."] = "Oldalsávok, amik halványak, amíg nem kellenek."
L["Slant leans along the UI's angle. Rise and Fall go straight. Arc curves away from you. Fountain sprays both ways. Stack stays put, and new lines push the older ones up."] = "A Dőlés a felület szögét követi. Az Emelkedés és az Esés egyenesen mennek. Az Ív tőled elfelé kanyarodik. A Szökőkút két irányba szór. A Tornyozás helyben marad, és az új sorok feljebb tolják a régieket."
L["Small"] = "Kicsi"
L["Soft trail"] = "Lágy csóva"
L["Spark"] = "Szikra"
L["Special mobs"] = "Különleges mobok"
L["Spell hits"] = "Varázslattalálatok"
L["Spell icon side"] = "Varázslatikon oldala"
L["Streams"] = "Folyamok"
L["Sunrise"] = "Napkelte"
L["Sweep"] = "Söprés"
L["Sweep: a ring with a light running round it. Angled frame: the Daylight UI shape on the ground with a light running round it. Daybreak: a beam of light leaning down onto the object. Sunrise: a low sun rising behind it."] = "Söprés: gyűrű, körben futó fénnyel. Ferde keret: a Daylight UI alakja a földön, körben futó fénnyel. Hajnal: a tárgyra ferdén lehajló fénysugár. Napkelte: mögötte felkelő alacsony nap."
L["Swing timers on the personal display"] = "Ütésidőzítők a személyes kijelzőn"
L["Switching"] = "Váltás"
L["Tan"] = "Drapp"
L["The NPC job's color when Job color is One color."] = "Az NPC-foglalkozás színe, ha a Foglalkozás színe Egy szín."
L["The bar along the bottom of the screen."] = "A sáv a képernyő alján."
L["The bar's color when it's set to One color."] = "A sáv színe, ha Egy színre van állítva."
L["The button's border lights up while its spell is queued, like Heroic Strike waiting for your next swing, or being cast."] = "A gomb kerete felvillan, amíg a varázslata sorban áll, mint a következő ütésedre váró Heroic Strike, vagy amíg varázsolod."
L["The color of the clock."] = "Az óra színe."
L["The color of the coordinates."] = "A koordináták színe."
L["The color of the framerate."] = "A képkockasebesség színe."
L["The color of the lit border and the glow on an active spell."] = "A felvillanó keret és a fény színe egy aktív varázslaton."
L["The color of your party and raid members' names."] = "A csoport- és raidtagjaid nevének színe."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar, the crowd control alert. Also the game's own character and inspect windows while Daylight UI's are off."] = "A játékmenü, az addonlista, a makrók, az óra, a zsákmány, a foglalatozás, a fejlesztés, a bontó, az aukciósház, a szakmakönyv, a világtérkép kerete, a levegősáv, a tömegirányítás-riasztás. Továbbá a játék saját karakter- és megtekintő ablakai, amíg a Daylight UI-éi ki vannak kapcsolva."
L["The game's other short messages: an interrupt, a dispel, an extra attack."] = "A játék többi rövid üzenete: egy megszakítás, egy levétel, egy extra támadás."
L["The guild name's color when Guild color is One color."] = "A céhnév színe, ha a Céhszín Egy szín."
L["The healer's name beside each heal. In a fight the game can hide who it was, so your own heals may show your name too."] = "A gyógyító neve minden gyógyítás mellett. Harcban a játék elrejtheti, ki volt az, így a saját gyógyításaidnál is a neved látszhat."
L["The health bar's color on a boss."] = "Az életerősáv színe bossnál."
L["The health bar's color on a mob that uses mana."] = "Az életerősáv színe manát használó mobnál."
L["The health bar's color on a rare."] = "Az életerősáv színe ritkánál."
L["The health text shows at full health too. When off, it disappears while you're at full."] = "Az életerő-szöveg teli életerőnél is látszik. Kikapcsolva eltűnik, amíg teli életerőn vagy."
L["The key that casts each spell, on its icon. It reads your action bars, so a spell on no bar shows none. Any icon can change this in the layout editor."] = "Minden varázslatot elvarázsoló billentyű, az ikonján. Az akciósávjaidból olvassa, így a semmilyen sávon nem lévő varázslatnál nem látszik semmi. Bármelyik ikon módosíthatja ezt az elrendezésszerkesztőben."
L["The key that casts this spell, read from your action bars."] = "Az ezt a varázslatot elvarázsoló billentyű, az akciósávjaidból olvasva."
L["The line along the top of the bar, in your accent color."] = "A sáv tetején futó vonal, a kiemelőszínedben."
L["The mob is attacking you."] = "A mob téged támad."
L["The mob is in the fight, but attacking someone else."] = "A mob harcban van, de valaki mást támad."
L["The name of a buff as it lands on you or leaves."] = "Egy buff neve, ahogy rád kerül vagy lekerül."
L["The name of a debuff as it lands on you or leaves."] = "Egy debuff neve, ahogy rád kerül vagy lekerül."
L["The number's color when Threat % color is One color."] = "A szám színe, ha a Fenyegetés % színe Egy szín."
L["The size of the words on the chat tabs."] = "A chatfülek szövegének mérete."
L["The size of what you type in the chat box."] = "A chatdobozba gépelt szöveg mérete."
L["The small tab on the meter's outer edge (it shows while the mouse is near) slides it out or back by hand."] = "A mérő külső szélén lévő kis fül (akkor látszik, ha az egér a közelben van) kézzel ki- vagy becsúsztatja."
L["The spell being cast, as a small icon by the cast bar."] = "Az épp varázsolt varázslat, kis ikonként a varázslássáv mellett."
L["The spell's icon at the end of your target's cast bar. Not inside the frame or sliding out under it."] = "A varázslat ikonja a célpontod varázslássávjának végén. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["The text scrolling around your character. When off, none shows, the game's own included."] = "A karaktered körül görgő szöveg. Kikapcsolva semmi sem látszik, a játék sajátja sem."
L["The threat number on the nameplates. General uses the health text font."] = "A fenyegetésszám a névtáblákon. Az Általános az életerő-szöveg betűtípusát használja."
L["The ticks of a heal over time on you."] = "Egy rajtad lévő időbeli gyógyítás tickjei."
L["Threat %"] = "Fenyegetés %"
L["Threat % color"] = "Fenyegetés % színe"
L["Threat % font"] = "Fenyegetés % betűtípusa"
L["Threat % left / right"] = "Fenyegetés % balra / jobbra"
L["Threat % position"] = "Fenyegetés % helye"
L["Threat % size"] = "Fenyegetés % mérete"
L["Threat % up / down"] = "Fenyegetés % fel / le"
L["Threat color style"] = "Fenyegetésszín stílusa"
L["Threat: attacking you"] = "Fenyegetés: téged támad"
L["Threat: not attacking you"] = "Fenyegetés: nem téged támad"
L["Ticket Status"] = "Jegy állapota"
L["Time left position"] = "Hátralévő idő helye"
L["Top Center Status"] = "Felső középső állapot"
L["Top stream"] = "Felső folyam"
L["Top stream alignment"] = "Felső folyam igazítása"
L["Top stream crit size"] = "Felső folyam kritikusmérete"
L["Top stream motion"] = "Felső folyam mozgása"
L["Top stream text size"] = "Felső folyam szövegmérete"
L["Top stream time on screen"] = "Felső folyam ideje a képernyőn"
L["Top stream travel distance"] = "Felső folyam útja"
L["Tracking from a spell, like Find Minerals, comes back after you log out, change zones or die. Turn it off yourself and it stays off."] = "A varázslatból jövő követés, mint a Find Minerals, visszajön kilépés, zónaváltás vagy halál után. Ha magad kapcsolod ki, kikapcsolva marad."
L["Two rows"] = "Két sor"
L["Two rows and side bars"] = "Két sor és oldalsávok"
L["Under the meter it rises out of the damage meter's bottom inside the panel, as wide as the meter, and the meter's rows make room. Docked (beside or under), it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode (/dui unlock) and drag its corner to size it."] = "A mérő alatt a panelen belül a sebzésmérő aljából emelkedik ki, a mérő szélességében, és a mérő sorai helyet adnak neki. Dokkolva (mellette vagy alatta) csak akkor látszik, ha a sebzésmérő nyitva van. A saját ablaka bárhová kerülhet: feloldott módban mozgasd (/dui unlock), és a sarkát húzva méretezd."
L["Used when Nameplates > Threat > Threat color style is Two-color gradient."] = "Akkor használt, ha a Névtáblák > Fenyegetés > Fenyegetésszín stílusa Kétszínű színátmenet."
L["What the bar shows. Pick None to leave a slot empty, and the others close up."] = "Mit mutat a sáv. A Nincs üresen hagy egy helyet, a többi összezárkózik."
L["When off, nothing shows here, even for the messages that go to it."] = "Kikapcsolva itt semmi sem látszik, még az ide küldött üzenetek sem."
L["When the second panel gets out of the way, on its own: keep a loot or combat log panel up while the main chat floats away, or the other way round. Idle time and how long messages stay are the main chat's."] = "Mikor tér ki a második panel az útból, önállóan: tarts fent egy zsákmány- vagy harcinapló-panelt, amíg a fő chat ellebeg, vagy fordítva. A tétlenségi idő és az üzenetek maradási ideje a fő chaté."
L["When you're away"] = "Amikor távol vagy"
L["Where along the health bar the health text sits."] = "Hol ül az életerő-szöveg az életerősáv mentén."
L["Where the time sits: on the icon's top edge, across its middle, or on its bottom edge."] = "Hol ül az idő: az ikon felső szélén, a közepén át, vagy az alsó szélén."
L["Which end of the cast bar it sits at. In Design mode on the preview, drag it there."] = "A varázslássáv melyik végén ül. Tervező módban az előnézeten húzd oda."
L["Which side of the minimap the damage meter slides out of, with the threat meter beside it. Automatic picks the side toward the middle of the screen, so it follows when you move the panel."] = "A minitérkép melyik oldalán csúszik ki a sebzésmérő, mellette a fenyegetésmérővel. Az Automatikus a képernyő közepe felé eső oldalt választja, így követi, ha mozgatod a panelt."
L["Which side of the spot the lines line up on."] = "A hely melyik oldalához igazodnak a sorok."
L["While you do engineering, two brass gears turn at the bottom of the screen with sparks where they meet, a brass tide shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "Mérnökösködés közben két sárgaréz fogaskerék forog a képernyő alján, ahol összeérnek, szikrák pattannak, egy sárgaréz ár mutatja, hol jársz a sorozatban, az akciósávjaid és egységkereteid pedig elhalványulnak. Mozdulj, vegyél célba valamit vagy varázsolj mást, és minden visszajön; egy harc azonnal visszahozza."
L["While you make potions, a flask sits at the bottom of the screen with bubbles rising past it, a green tide shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "Bájitalkészítés közben egy lombik ül a képernyő alján, mellette buborékok szállnak fel, egy zöld ár mutatja, hol jársz a sorozatban, az akciósávjaid és egységkereteid pedig elhalványulnak. Mozdulj, vegyél célba valamit vagy varázsolj mást, és minden visszajön; egy harc azonnal visszahozza."
L["While you smith, an anvil and hammer work along the bottom of the screen with sparks on each finished item, a molten tide shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "Kovácsolás közben üllő és kalapács dolgozik a képernyő alján, minden kész tárgynál szikrákkal, egy olvadt ár mutatja, hol jársz a sorozatban, az akciósávjaid és egységkereteid pedig elhalványulnak. Mozdulj, vegyél célba valamit vagy varázsolj mást, és minden visszajön; egy harc azonnal visszahozza."
L["While you tailor, a spool sits at the bottom of the screen, a tide of cloth with a growing seam shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "Szabás közben egy orsó ül a képernyő alján, egy növekvő varrású szövetár mutatja, hol jársz a sorozatban, az akciósávjaid és egységkereteid pedig elhalványulnak. Mozdulj, vegyél célba valamit vagy varázsolj mást, és minden visszajön; egy harc azonnal visszahozza."
L["While your line is in, calm water lies along the bottom of the screen with a little bobber on it, and your action bars and unit frames fade away. When a fish comes in the water splashes. Move, target or cast something else and everything comes back; a fight brings it back at once. The game doesn't tell addons when a fish bites, so the splash comes on the catch, not the bite."] = "Amíg bent van a zsinórod, nyugodt víz terül el a képernyő alján egy kis úszóval, az akciósávjaid és egységkereteid pedig elhalványulnak. Amikor kifogsz egy halat, a víz csobban. Mozdulj, vegyél célba valamit vagy varázsolj mást, és minden visszajön; egy harc azonnal visszahozza. A játék nem szól az addonoknak, amikor a hal ráharap, ezért a csobbanás a fogáskor jön, nem a harapáskor."
L["Who else gets the crown tab in a party, for the markers: the party's tank, or everyone. Ready check and the pull timer stay with the leader. In a raid only the leader and assists can mark."] = "Ki kapja még meg csoportban a koronás fület a jelölőkhöz: a csoport tankja, vagy mindenki. A készenléti ellenőrzés és a pull-időzítő a vezetőnél marad. Raidben csak a vezető és a segédvezetők jelölhetnek."
L["Who's closest to pulling your target, in a small window that slides out beside the damage meter, along its bottom, or anywhere on its own."] = "Ki van legközelebb ahhoz, hogy magára húzza a célpontodat, egy kis ablakban, ami a sebzésmérő mellől csúszik ki, az alja mentén, vagy önállóan bárhol."
L["Words and phrases to hide"] = "Elrejtendő szavak és kifejezések"
L["Workshop"] = "Műhely"
L["You can also drag the panel's bottom-right corner to size it."] = "A panel jobb alsó sarkát húzva is méretezheted."
L["Your accent color, or a color that says what the object is: copper for ore, green for herbs, gold for quests, blue for chests."] = "A kiemelőszíned, vagy egy szín, ami elárulja, mi a tárgy: réz az érchez, zöld a növényhez, arany a küldetéshez, kék a ládához."
L["Your bobber lights up while your line is in the water."] = "Az úszód világít, amíg a zsinórod a vízben van."
L["Your health on the display. Turn it off to keep just your power bar. Needs the power bar on."] = "Az életerőd a kijelzőn. Kapcsold ki, ha csak az erőforrássávot tartanád meg. Kell hozzá az erőforrássáv bekapcsolása."
L["Your health written on the personal display's health bar."] = "Az életerőd a személyes kijelző életerősávjára írva."
L["Your mana, rage or energy under the health bar. Needs the health bar on."] = "A manád, dühöd vagy energiád az életerősáv alatt. Kell hozzá az életerősáv bekapcsolása."
L["Your mana, rage or energy written on the personal display's power bar."] = "A manád, dühöd vagy energiád a személyes kijelző erőforrássávjára írva."
L["Your target's cast bar fills from the right. Not inside the frame or sliding out under it."] = "A célpontod varázslássávja jobbról töltődik. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Your threat on each enemy as a number by its health bar: at 100% it turns on you. Shows in a group or with a pet. Works with Threat colors on or off."] = "A fenyegetésed minden ellenségen számként az életerősávja mellett: 100%-nál rád fordul. Csoportban vagy háziállattal látszik. A Fenyegetésszínek be- vagy kikapcsolt állapotában is működik."
L["Zone name text size"] = "Zónanév szövegmérete"
L["A new group starts empty. Hold Shift while dragging an item to see your empty groups in the bag, and drop it on one's name. Or click the search beside it here to fill it by itself."] = "Egy új csoport üresen indul. Tárgyhúzás közben tartsd lenyomva a Shiftet, hogy lásd az üres csoportjaidat a táskában, és ejtsd a tárgyat valamelyik nevére. Vagy kattints itt a mellette lévő keresésre, hogy magától töltse fel."
L["A ring over the outer end. Class icons show for players; NPCs show their face."] = "Gyűrű a külső végén. Játékosoknál kasztikon, NPC-knél az arcuk."
L["A small headset button at the top-right of the chat. It opens the game's Chat Channels window, where you join voice chat with your party, raid or a channel."] = "Kis fejhallgató-gomb a chat jobb felső sarkában. Megnyitja a játék Chat Channels ablakát, ahol hangcsevegéshez csatlakozhatsz a csoportoddal, raideddel vagy egy csatornával."
L["By difficulty: the game's gray, green, yellow, orange and red for how hard the enemy is for your level. Or always white, your accent color, or one color you pick. ?? stays red."] = "Nehézség szerint: a játék szürke, zöld, sárga, narancs és piros színe aszerint, mennyire nehéz az ellenség a szintedhez képest. Vagy mindig fehér, a kiemelőszíned, vagy egy általad választott szín. A ?? piros marad."
L["Caster"] = "Varázsló"
L["Custom level color"] = "Egyedi szintszín"
L["Detach as group"] = "Leválasztás csoportként"
L["Detach the main hand, off hand or ranged bar from the others to move and size it on its own."] = "A főkéz-, mellékkéz- vagy távolsági sáv leválasztása a többiről, hogy önállóan mozgasd és méretezd."
L["Detached bars"] = "Leválasztott sávok"
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar. A bar detached on its own has its own."] = "Minden sáv keze (vagy a sorban álló támadás) és a következő ütésig hátralévő idő, a sávra írva. Az önállóan leválasztott sávnak saját beállítása van."
L["Each bar's name and number in that player's class color."] = "Minden sáv neve és száma a játékosa kasztszínében."
L["Hide friendly plates in instances"] = "Barátságos névtáblák elrejtése instance-ben"
L["How big the number is. 0 fits it to the tag."] = "Mekkora a szám. A 0 a címkéhez igazítja."
L["How dungeons, quests and zones are listed when you list yourself: lowest level first, or A to Z. The Sort button on that page changes it too."] = "Hogyan listázódnak a kazamaták, küldetések és zónák, amikor magadat listázod: a legalacsonyabb szint elöl, vagy A-tól Z-ig. Az oldal Rendezés gombja is ezt váltja."
L["How solid the empty part and outline of each bar are. At 0 only the colored bars show."] = "Mennyire tömör minden sáv üres része és körvonala. 0-nál csak a színes sávok látszanak."
L["How tall the tag is. 0 matches the name tab."] = "Milyen magas a címke. A 0 a névfülhöz igazítja."
L["How wide the tag is."] = "Milyen széles a címke."
L["Level color"] = "Szintszín"
L["Level size"] = "Szint mérete"
L["Loot window animations"] = "Zsákmányablak animációi"
L["No plates over friendly players and NPCs in dungeons, raids, battlegrounds and arenas. They come back as you leave."] = "Nincsenek névtáblák barátságos játékosok és NPC-k fölött kazamatában, raidben, csatatéren és arénában. Kilépéskor visszajönnek."
L["Nudges the tag sideways. Only while it sits on the frame."] = "Oldalra tolja a címkét. Csak amíg a kereten ül."
L["Nudges the tag up or down. Only while it sits on the frame."] = "Fel vagy le tolja a címkét. Csak amíg a kereten ül."
L["On its own, the tag leaves the frame and you can move it anywhere in unlock mode, like near the middle of the screen."] = "Önállóan a címke elhagyja a keretet, és feloldott módban bárhová mozgathatod, például a képernyő közepe közelébe."
L["Opens the layout editor right on your screen, on the profile your talent set uses: pull spells up from the tray, drag them where you want them, hook them together, click one to change it. Type /cdm to open it any time. Out of combat only."] = "Közvetlenül a képernyődön nyitja meg az elrendezésszerkesztőt, a tehetségszetted által használt profilon: húzd fel a varázslatokat a tálcáról, tedd őket oda, ahová akarod, akaszd össze őket, kattints egyre a módosításához. Bármikor megnyitod a /cdm paranccsal. Csak harcon kívül."
L["Rare"] = "Ritka"
L["Roleplay names"] = "Szerepjátékos nevek"
L["Show empty groups"] = "Üres csoportok mutatása"
L["Sort activities by"] = "Tevékenységek rendezése"
L["Takes the bars out from under the player frame so you can move them together (/dui unlock); they slide out of their own box. When off, they hang under the player frame, under the cast bar while it hangs there, even with the cast bar detached."] = "Kiveszi a sávokat a játékoskeret alól, hogy együtt mozgathasd őket (/dui unlock); a saját dobozukból csúsznak ki. Kikapcsolva a játékoskeret alatt lógnak, a varázslássáv alatt, amíg az ott lóg, akkor is, ha a varázslássáv le van választva."
L["The hand (or the queued attack, or the range) written on the bar. Only when detached on its own."] = "A kéz (vagy a sorban álló támadás, vagy a hatótáv) a sávra írva. Csak önállóan leválasztva."
L["The hand and time on the bar. Only when detached on its own."] = "A kéz és az idő a sávon. Csak önállóan leválasztva."
L["The level's color when Level color is One color."] = "A szint színe, ha a Szintszín Egy szín."
L["The light running down the loot window as it opens, items easing in behind it, the shine on rare items, taken items rising away, and the window fading in and out. When off, the loot window opens and closes with none of them."] = "A zsákmányablakon nyitáskor végigfutó fény, a mögötte beúszó tárgyak, a ritka tárgyak csillogása, az elvett tárgyak felemelkedése, és az ablak be- és kiúszása. Kikapcsolva a zsákmányablak ezek nélkül nyílik és zárul."
L["The number's color. By threat goes orange as you get close to pulling, red once it's on you."] = "A szám színe. A Fenyegetés szerint narancs lesz, ahogy közeledsz a magadra húzáshoz, piros, ha már rajtad van."
L["The small framed box behind the number. When off, only the number shows."] = "A kis keretes doboz a szám mögött. Kikapcsolva csak a szám látszik."
L["The spell name and time on your target's cast bar. Not inside the frame: there it's Text size inside the frame."] = "A varázslat neve és ideje a célpontod varázslássávján. Nem a kereten belül: ott a Szövegméret a kereten belül érvényes."
L["The spell name and timer while the bar sits inside the target frame, even past the power bar's height. 0 sizes them to fit the power bar."] = "A varázslat neve és időzítője, amíg a sáv a célpontkereten belül ül, akár az erőforrássáv magasságán túl is. A 0 az erőforrássávhoz méretezi őket."
L["The tag's end is angled like the frame. When off, both ends are straight."] = "A címke vége a kerethez hasonlóan ferde. Kikapcsolva mindkét vége egyenes."
L["The time to the next swing, written on the bar. Only when detached on its own."] = "A következő ütésig hátralévő idő a sávra írva. Csak önállóan leválasztva."
L["The weapon's picture at the start of the bar. Only when detached on its own."] = "A fegyver képe a sáv elején. Csak önállóan leválasztva."
L["Threat tag angled end"] = "Fenyegetéscímke ferde vége"
L["Threat tag box"] = "Fenyegetéscímke doboza"
L["Threat tag color"] = "Fenyegetéscímke színe"
L["Threat tag height"] = "Fenyegetéscímke magassága"
L["Threat tag left / right"] = "Fenyegetéscímke balra / jobbra"
L["Threat tag position"] = "Fenyegetéscímke helye"
L["Threat tag text size"] = "Fenyegetéscímke szövegmérete"
L["Threat tag up / down"] = "Fenyegetéscímke fel / le"
L["Threat tag width"] = "Fenyegetéscímke szélessége"
L["Voice chat button"] = "Hangcsevegés gomb"
L["While swinging: each bar only while its swing runs, gone between swings. In combat: all your bars while you're fighting. A bar detached on its own has its own."] = "Ütés közben: minden sáv csak az ütése alatt látszik, ütések között eltűnik. Harcban: minden sávod, amíg harcolsz. Az önállóan leválasztott sávnak saját beállítása van."
L["While swinging: only while its swing runs. In combat: while you're fighting. Only when detached on its own."] = "Ütés közben: csak az ütése alatt. Harcban: amíg harcolsz. Csak önállóan leválasztva."
L["Your groups with nothing in them always show in the bag. When off, they show only while you hold Shift with an item on the cursor."] = "Az üres csoportjaid mindig látszanak a táskában. Kikapcsolva csak akkor, ha a Shiftet nyomva tartod egy tárggyal a kurzoron."
L["Your main hand's bar. Turn it off to keep only your other bars, like a hunter's ranged bar."] = "A főkezed sávja. Kapcsold ki, ha csak a többi sávot tartanád meg, mint egy vadász távolsági sávját."
L["Your own cooldown layout: every spell the Cooldown Manager tracks as an icon or a bar, placed where you like and snapped together. Layouts are profiles: as many per class as you like, one for each talent set."] = "A saját cooldown-elrendezésed: minden varázslat, amit a Cooldown-kezelő követ, ikonként vagy sávként, oda téve, ahová szeretnéd, és összeillesztve. Az elrendezések profilok: kasztonként annyi, amennyit szeretnél, tehetségszettenként egy."
L["DPS/Tank made calm for questing: your action bars and your own frame fade a while after a fight (back under the mouse, in a fight or when you're hurt), the damage meter starts folded (one click on the panel's tab brings it out), the minimap is a little smaller and the XP bar shows its percent. Nothing fades in dungeons, raids, battlegrounds or arenas (General > Appearance, Fade only in the open world). Choose it above to use it. "] = "DPS/Tank, nyugodtra hangolva küldetezéshez: az akciósávjaid és a saját kereted harc után egy idővel elhalványulnak (visszajönnek az egér alatt, harcban vagy ha sérült vagy), a sebzésmérő összecsukva indul (egy kattintás a panel fülén előhozza), a minitérkép kicsit kisebb, az XP-sáv pedig százalékot mutat. Kazamatában, raidben, csatatéren és arénában semmi sem halványul el (Általános > Megjelenés, Elhalványítás csak a nyílt világban). Válaszd ki fent a használatához. "
L["DPS/Tank with your party and raid as square tiles under you (you included, missing health on them, dispels easy to see), and your frame and your target's raised a little. Everything it sets is on the Party and Raid pages; move any of them in unlock mode. Choose it above to use it. "] = "DPS/Tank, a csoportod és raided négyzetes csempékként alattad (te is, rajtuk a hiányzó életerő, a levehetők jól láthatóan), a te kereted és a célpontodé pedig kicsit feljebb. Minden, amit beállít, a Csoport és a Raid oldalon van; feloldott módban bármelyiket mozgathatod. Válaszd ki fent a használatához. "
L["Another swing bar whose look to copy onto the one picked in Settings for."] = "Egy másik ütéssáv, aminek a kinézetét átmásolod arra, amelyik a Beállítások ehhez mezőben ki van választva."
L["By threat (orange, then red)"] = "Fenyegetés szerint (narancs, aztán piros)"
L["Data bar left slot 1"] = "Adatsáv 1. bal hely"
L["Data bar left slot 2"] = "Adatsáv 2. bal hely"
L["Data bar left slot 3"] = "Adatsáv 3. bal hely"
L["Data bar left slot 4"] = "Adatsáv 4. bal hely"
L["Data bar middle slot"] = "Adatsáv középső hely"
L["Data bar right slot 1"] = "Adatsáv 1. jobb hely"
L["Data bar right slot 2"] = "Adatsáv 2. jobb hely"
L["Data bar right slot 3"] = "Adatsáv 3. jobb hely"
L["Data bar right slot 4"] = "Adatsáv 4. jobb hely"
L["Detach the main hand bar"] = "Főkéz-sáv leválasztása"
L["Detach the off hand bar"] = "Mellékkéz-sáv leválasztása"
L["Detach the ranged bar"] = "Távolsági sáv leválasztása"
L["Left of the cast bar"] = "A varázslássávtól balra"
L["On the frame"] = "A kereten"
L["Players with a Total RP 3 profile show by their roleplay name on unit frames, nameplates, the threat meter and windows. Each frame's First and last names switch still picks first name or full name."] = "A Total RP 3 profillal rendelkező játékosok a szerepjátékos nevükkel látszanak az egységkereteken, névtáblákon, a fenyegetésmérőn és az ablakokban. Minden keret Kereszt- és vezetéknevek kapcsolója továbbra is a keresztnév és a teljes név között választ."
L["What the angled tab in the middle of the bar shows. Pick None to leave the tab out."] = "Mit mutat a sáv közepén lévő ferde fül. A Nincs kihagyja a fület."
L["What this slot on the left side of the data bar shows, counted from the screen's edge."] = "Mit mutat ez a hely az adatsáv bal oldalán, a képernyő szélétől számolva."
L["What this slot on the right side of the data bar shows, counted from the screen's edge."] = "Mit mutat ez a hely az adatsáv jobb oldalán, a képernyő szélétől számolva."
L["all"] = "mind"
L["block"] = "blokk"
L["both"] = "mindkettő"
L["center"] = "közép"
L["close"] = "bezárás"
L["color"] = "szín"
L["dispel"] = "levétel"
L["fade"] = "halványítás"
L["forget"] = "elfelejtés"
L["game"] = "játék"
L["gradient"] = "színátmenet"
L["grey"] = "szürke"
L["heals"] = "gyógyítások"
L["hide"] = "elrejtés"
L["left"] = "bal"
L["lock"] = "zárolás"
L["mine"] = "saját"
L["none"] = "nincs"
L["note"] = "megjegyzés"
L["pin"] = "kitűzés"
L["shield"] = "pajzs"
L["solid"] = "tömör"
L["time"] = "idő"
L["whisper"] = "suttogás"
L["A green part after your experience shows what the quests you can turn in will give. Hover the bar for the total."] = "A tapasztalatod utáni zöld rész azt mutatja, mennyit adnak a leadható küldetéseid. Vidd a sáv fölé az egeret az összegért."
L["One line for the rail's tooltip."] = "Egy sor a sín súgóbuborékához."
L["One line on what it is."] = "Egy sor arról, mi ez."
L["Players' last names after their first, on this frame only."] = "A játékosok vezetékneve a keresztnevük után, csak ezen a kereten."
L["Show XP from finished quests"] = "XP mutatása a kész küldetésekből"
L["%d quests to turn in"] = "%d leadható küldetés"
L["How big the numbers are. 1 is the game's own size."] = "Mekkorák a számok. Az 1 a játék saját mérete."
L["By power type: mana blue, rage red, energy yellow, each as its gradient from General > Gradients. Or one color you pick."] = "Erőforrás szerint: mana kék, düh piros, energia sárga, mindegyik a színátmenetével az Általános > Színátmenetek oldalról. Vagy egy általad választott szín."
L["Mana, rage or energy as a thin bar under the health bar: see a caster running dry, or a rogue saving up energy. The cast bar moves down under it."] = "Mana, düh vagy energia vékony sávként az életerősáv alatt: lásd, ha egy varázsló kifogy, vagy egy zsivány energiát gyűjt. A varázslássáv alá kerül."
L["Players and mana users: every enemy player, and the mobs that cast. Everyone with power: warriors' rage and the like too. Your target only: just the one you have selected."] = "Játékosok és manahasználók: minden ellenséges játékos, és a varázsló mobok. Mindenki, akinek erőforrása van: a harcosok dühe és hasonlók is. Csak a célpontod: csak az, akit kiválasztottál."
L["Players and mana users"] = "Játékosok és manahasználók"
L["Everyone with power"] = "Mindenki, akinek erőforrása van"
L["Your target only"] = "Csak a célpontod"
L["Power bar gap"] = "Erőforrássáv rés"
L["Power bar on"] = "Erőforrássáv bekapcsolva"
L["The space between the health bar and the power bar. Set to 0 to join them."] = "A hely az életerősáv és az erőforrássáv között. A 0 összeilleszti őket."
L["Their mana, rage or energy as a thin bar under the health bar: see a healer running low. Who gets one, its size and color follow Health & Names > Power bar."] = "A manájuk, dühük vagy energiájuk vékony sávként az életerősáv alatt: lásd, ha egy gyógyító kifogyóban van. Hogy ki kap ilyet, a mérete és a színe az Életerő és nevek > Erőforrássáv beállítást követi."
L["When off, every bar, border and highlight uses one flat color instead of two blended ones. The colors below still pick that color: the middle of each pair."] = "Kikapcsolva minden sáv, keret és kiemelés egy sima színt használ két összemosott helyett. Az alábbi színek továbbra is kiválasztják ezt a színt: minden pár közepét."
L["Main hand bar width"] = "Főkéz-sáv szélessége"
L["Main hand bar height"] = "Főkéz-sáv magassága"
L["Main hand bar text size"] = "Főkéz-sáv szövegmérete"
L["Main hand bar name"] = "Főkéz-sáv neve"
L["Main hand bar time left"] = "Főkéz-sáv hátralévő ideje"
