L["Off hand bar time left"] = "Mellékkéz-sáv hátralévő ideje"
L["Off hand bar weapon icon"] = "Mellékkéz-sáv fegyverikonja"
L["Off hand bar angled end"] = "Mellékkéz-sáv ferde vége"
