L["Takes the main hand bar out of the group onto a handle of its own (/dui unlock), with the settings below. It rises into place as it fades in."] = "Kiveszi a főkéz-sávot a csoportból egy saját fogantyúra (/dui unlock), az alábbi beállításokkal. Beúszáskor a helyére emelkedik."
L["Takes the off hand bar out of the group onto a handle of its own (/dui unlock), with the settings below. It rises into place as it fades in."] = "Kiveszi a mellékkéz-sávot a csoportból egy saját fogantyúra (/dui unlock), az alábbi beállításokkal. Beúszáskor a helyére emelkedik."
L["Takes the ranged bar out of the group onto a handle of its own (/dui unlock), with the settings below. It rises into place as it fades in."] = "Kiveszi a távolsági sávot a csoportból egy saját fogantyúra (/dui unlock), az alábbi beállításokkal. Beúszáskor a helyére emelkedik."
L["Paging: this bar can show another page of buttons while you hold a key. Your stances and forms still change it as before. Pick a spare page to fill it with spells of its own."] = "Lapozás: ez a sáv egy másik gomblapot mutathat, amíg egy gombot nyomva tartasz. A tartásaid és formáid továbbra is váltják, mint eddig. Válassz egy tartaléklapot, hogy saját varázslatokkal töltsd fel."
L["Shift page"] = "Shift-lap"
L["Ctrl page"] = "Ctrl-lap"
L["Alt page"] = "Alt-lap"
L["Prowl page"] = "Prowl-lap"
L["Cat Form page"] = "Cat Form-lap"
L["Bear Form page"] = "Bear Form-lap"
L["Stealth page"] = "Stealth-lap"
L["Battle Stance page"] = "Battle Stance-lap"
L["Defensive Stance page"] = "Defensive Stance-lap"
L["Berserker Stance page"] = "Berserker Stance-lap"
L["Which page of buttons this bar shows while you hold Shift. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv, amíg a Shiftet nyomva tartod. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Which page of buttons this bar shows while you hold Ctrl. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv, amíg a Ctrl-t nyomva tartod. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Which page of buttons this bar shows while you hold Alt. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv, amíg az Altot nyomva tartod. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Which page of buttons this bar shows while you prowl. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv, amíg lopakodsz (Prowl). A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Which page of buttons this bar shows in Cat Form. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv Cat Formban. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Which page of buttons this bar shows in Bear Form. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv Bear Formban. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Which page of buttons this bar shows in Stealth. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv Stealthben. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Which page of buttons this bar shows in Battle Stance. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv Battle Stance-ben. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Which page of buttons this bar shows in Defensive Stance. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv Defensive Stance-ben. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Which page of buttons this bar shows in Berserker Stance. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv Berserker Stance-ben. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Spell casts for you, your target, focus and party."] = "Varázslások neked, a célpontodnak, a fókusznak és a csoportnak."
L["Party cast bars"] = "Csoport varázslássávjai"
L["Show party cast bars"] = "Csoport varázslássávjainak mutatása"
L["Each party member's casts on their own frame, while they last. They use the target cast bar's colors."] = "Minden csoporttag varázslásai a saját keretén, amíg tartanak. A célpont varázslássávjának színeit használják."
L["Which side of each party frame a detached cast bar sits on."] = "Minden csoportkeret melyik oldalán ül egy leválasztott varázslássáv."
L["Moves the detached cast bars sideways from their side."] = "Oldalra tolja a leválasztott varázslássávokat a helyükről."
L["Moves the detached cast bars up or down from their side."] = "Fel vagy le tolja a leválasztott varázslássávokat a helyükről."
L["How wide each detached cast bar is. Under the frame it matches the frame's width."] = "Milyen széles minden leválasztott varázslássáv. A keret alatt a keret szélességéhez igazodik."
L["How tall each party cast bar is. Not inside the frame, where it takes the power bar's place."] = "Milyen magas minden csoporttag varázslássávja. Nem a kereten belül, ahol az erőforrássáv helyét veszi át."
L["The spell's icon at the end of each detached cast bar."] = "A varázslat ikonja minden leválasztott varázslássáv végén."
L["Cuts the end of each detached cast bar at an angle. When off, its end is straight."] = "Minden leválasztott varázslássáv végét ferdén levágja. Kikapcsolva a vége egyenes."
L["Party cast bar text size"] = "Csoport varázslássávjainak szövegmérete"
L["The spell name and time on the party's cast bars. Inside the frame it's kept small enough for the power bar."] = "A varázslat neve és ideje a csoport varázslássávjain. A kereten belül elég kicsi marad az erőforrássávhoz."
L["The spell name and timer while the bar sits inside a party frame, even past the power bar's height. 0 sizes them to fit the power bar."] = "A varázslat neve és időzítője, amíg a sáv egy csoportkereten belül ül, akár az erőforrássáv magasságán túl is. A 0 az erőforrássávhoz méretezi őket."
L["Each detached cast bar fills from the right."] = "Minden leválasztott varázslássáv jobbról töltődik."
L["The spell name and time on the party's cast bars. General uses the font on General > Appearance."] = "A varázslat neve és ideje a csoport varázslássávjain. Az Általános az Általános > Megjelenés betűtípusát használja."
L["When short of power"] = "Ha nincs elég erőforrás"
L["While it's off cooldown but you lack the energy, rage or mana for it: Kick shows only once you can afford it. Show tints it blue. Hide keeps its gap: the other spells don't move."] = "Amíg nincs cooldownon, de nincs hozzá elég energiád, dühöd vagy manád: a Kick csak akkor látszik, ha már telik rá. A Mutatás kékre színezi. Az Elrejtés megtartja a helyét: a többi varázslat nem mozdul."
L["Glows while the buff is up: Clearcasting, Nightfall."] = "Világít, amíg a buff fent van: Clearcasting, Nightfall."
L["PvP Frames"] = "PvP-keretek"
L["PvP frames"] = "PvP-keretek"
L["Show the PvP frames"] = "PvP-keretek mutatása"
L["Be a VIP supporter"] = "Légy VIP-támogató"
L["Become a Daylight UI VIP on Patreon: press Ctrl+C to copy the link, then paste it in your browser."] = "Légy Daylight UI VIP a Patreonon: Ctrl+C-vel másold a linket, aztán illeszd be a böngésződbe."
L["Click again to train all"] = "Kattints újra a mindet tanuláshoz"
L["Tip Daylight"] = "Borravaló Daylightnak"
L["A light running round the ring, a slow breath, or no movement."] = "Körben futó fény a gyűrűn, lassú lélegzés, vagy semmi mozgás."
L["A ring follows your mouse cursor, so it's easy to find in a busy fight."] = "Egy gyűrű követi az egérkurzort, így zsúfolt harcban is könnyű megtalálni."
L["A soft light around the ring."] = "Lágy fény a gyűrű körül."
L["A square in the spell's color, or the spell's own icon edged in that color."] = "Egy négyzet a varázslat színében, vagy a varázslat saját ikonja ilyen színű szegéllyel."
L["A trail of light follows the cursor as it moves."] = "Fénycsóva követi a kurzort, ahogy mozog."
L["All the time, or only during a fight."] = "Mindig, vagy csak harc közben."
L["Both keeps it in its spot: the buff's time while it's up, then the cooldown. Buff only shows it just while the buff is up."] = "A Mindkettő a helyén tartja: amíg a buff fent van, annak az idejét, utána a cooldownt. A Csak buff csak addig mutatja, amíg a buff fent van."
L["Casts on the cursor ring"] = "Varázslások a kurzorgyűrűn"
L["Change with forms and stances"] = "Váltás formákkal és tartásokkal"
L["Paging: this bar can show another page of buttons while you hold a key, or when your target is friendly or an enemy. Your stances and forms change it too, unless you switch that off below. Pick a spare page to fill it with spells of its own."] = "Lapozás: ez a sáv egy másik gomblapot mutathat, amíg egy gombot nyomva tartasz, vagy ha a célpontod barátságos vagy ellenséges. A tartásaid és formáid is váltják, hacsak lent ki nem kapcsolod. Válassz egy tartaléklapot, hogy saját varázslatokkal töltsd fel."
L["Class uses your class's pair from the Gradients page. Daylight is the Daylight UI gradient."] = "A Kaszt a kasztod párját használja a Színátmenetek oldalról. A Daylight a Daylight UI színátmenete."
L["Copy its setup"] = "A beállításának másolása"
L["Cursor ring"] = "Kurzorgyűrű"
L["Cursor ring color"] = "Kurzorgyűrű színe"
L["Cursor ring glow"] = "Kurzorgyűrű fénye"
L["Cursor ring motion"] = "Kurzorgyűrű mozgása"
L["Cursor ring opacity"] = "Kurzorgyűrű átlátszatlansága"
L["Cursor ring size"] = "Kurzorgyűrű mérete"
L["Cursor trail"] = "Kurzorcsóva"
L["Custom cursor ring color"] = "Egyedi kurzorgyűrű-szín"
L["Druid bars height"] = "Druidsávok magassága"
L["Druid bars numbers"] = "Druidsávok számai"
L["Druid bars width"] = "Druidsávok szélessége"
L["Druid resource bars"] = "Druid erőforrássávok"
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar. Each bar's own switches under Detached bars can turn off one or the other."] = "Minden sáv keze (vagy a sorban álló támadás) és a következő ütésig hátralévő idő, a sávra írva. A Leválasztott sávok alatt minden sáv saját kapcsolói kikapcsolhatják az egyiket vagy a másikat."
L["Fills by"] = "Kitöltés ez alapján"
L["Flash when the global cooldown ends"] = "Villanás a globális cooldown végén"
L["Frames grow"] = "A keretek növekedése"
L["Lines grow"] = "A sorok növekedése"
L["Gives the second chat panel its own text size, set in the row below. When off, it matches the main chat's text size."] = "A második chatpanel saját szövegméretet kap, az alábbi sorban állítva. Kikapcsolva a fő chat szövegméretét követi."
L["Happiness left / right"] = "Boldogság balra / jobbra"
L["Happiness look"] = "Boldogság kinézete"
L["Happiness position"] = "Boldogság helye"
L["Happiness size"] = "Boldogság mérete"
L["Happiness up / down"] = "Boldogság fel / le"
L["Heal indicator look"] = "Gyógyításjelző kinézete"
L["Hide on cooldown"] = "Elrejtés cooldownon"
L["Hide on global cooldown"] = "Elrejtés globális cooldownon"
L["Hide while buff is up"] = "Elrejtés, amíg a buff fent van"
L["How long each bar is."] = "Milyen hosszú minden sáv."
L["How much of each power you have, on its bar."] = "Mennyi van az egyes erőforrásokból, a sávján."
L["How solid the ring is."] = "Mennyire tömör a gyűrű."
L["How tall each bar is."] = "Milyen magas minden sáv."
L["How wide the ring is."] = "Milyen széles a gyűrű."
L["In a fight the window stays: scroll it, switch tabs and click a spell to cast it. The search and section buttons wait until the fight ends. Turn it off to get the game's own book in a fight, where you can drag spells to your bars."] = "Harcban az ablak marad: görgetheted, fület válthatsz, és egy varázslatra kattintva elvarázsolhatod. A keresés és a szakaszgombok a harc végéig várnak. Kapcsold ki, ha harcban a játék saját könyvét szeretnéd, ahonnan varázslatokat húzhatsz a sávjaidra."
L["Instances are dungeons, raids and battlegrounds."] = "Az instance-ek a kazamaták, raidek és csataterek."
L["Items sorted into groups by type. To move an item to another group, drag it onto that group's heading or Alt-right-click it. Click a heading to collapse it; right-click Recent to clear it. Alt-right-click also locks an item so it's never sold or disenchanted."] = "A tárgyak típus szerint csoportokba rendezve. Ha egy tárgyat másik csoportba tennél, húzd a csoport fejlécére, vagy Alt+jobb klikkelj rá. Egy fejlécre kattintva összecsukod; jobb klikk a Frissen törli. Az Alt+jobb klikk zárolja is a tárgyat, így soha nem adja el és nem bűvöli szét."
L["Keep the spellbook in a fight"] = "A varázskönyv harcban is marad"
L["Move back"] = "Mozgatás hátra"
L["Move forward"] = "Mozgatás előre"
L["No dark sweep over the icon while the spell is on cooldown."] = "Nincs sötét söprés az ikonon, amíg a varázslat cooldownon van."
L["Not usable"] = "Nem használható"
L["Pet happiness (hunters)"] = "Háziállat boldogsága (vadászok)"
L["Pet happiness"] = "Háziállat boldogsága"
L["Happiness side"] = "Boldogság oldala"
L["Which end of the frame the stripe sits in. On an angled end it follows the angle."] = "A keret melyik végén ül a csík. Ferde végen követi a dőlést."
L["In the frame"] = "A keretben"
L["Replaces this frame's size, bars, names, texts, icons and auras with the frame above's. Whether it's shown, its fade, where it sits and how a group is laid out stay."] = "Ennek a keretnek a méretét, sávjait, neveit, szövegeit, ikonjait és auráit a fenti keretére cseréli. Hogy látszik-e, az elhalványítása, a helye és egy csoport elrendezése marad."
L["Ring around the cursor"] = "Gyűrű a kurzor körül"
L["Second panel text size"] = "Második panel szövegmérete"
L["Separate second panel text size"] = "Külön szövegméret a második panelnek"
L["Share your groups"] = "Csoportjaid megosztása"
L["Short of power"] = "Kevés erőforrás"
L["Show when alone"] = "Mutatás egyedül is"
L["Small bars for the druid powers you're not using right now: rage and energy in caster form, mana in bear or cat form. Each shows once you know its form. Move them in unlock mode."] = "Kis sávok azokhoz a druid erőforrásokhoz, amiket épp nem használsz: düh és energia varázslóformában, mana medve- vagy macskaformában. Mindegyik akkor jelenik meg, ha ismered a formáját. Feloldott módban mozgathatod őket."
L["Start from another frame's setup instead of setting this one up from scratch."] = "Egy másik keret beállításából indulj, ne a nulláról állítsd be ezt."
L["Swap with the one after"] = "Csere a következővel"
L["Swap with the one before"] = "Csere az előzővel"
L["The empty part of every bar in the group. A spell's own background wins."] = "A csoport minden sávjának üres része. Egy varázslat saját háttere elsőbbséget kap."
L["The frame whose setup to copy onto this one."] = "A keret, aminek a beállítását erre átmásolod."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar, the box that splits a stack. Also the game's own character and inspect windows while Daylight UI's are off."] = "A játékmenü, az addonlista, a makrók, az óra, a zsákmány, a foglalatozás, a fejlesztés, a bontó, az aukciósház, a szakmakönyv, a világtérkép kerete, a levegősáv, a halomosztó doboz. Továbbá a játék saját karakter- és megtekintő ablakai, amíg a Daylight UI-éi ki vannak kapcsolva."
L["The global cooldown sweeps around the ring after each spell, so you see when the next one is ready."] = "A globális cooldown minden varázslat után körbefut a gyűrűn, így látod, mikor kész a következő."
L["The hand (or the queued attack, or the range) written on the bar, attached or detached."] = "A kéz (vagy a sorban álló támadás, vagy a hatótáv) a sávra írva, csatolva vagy leválasztva."
L["The pet's health bar takes the mood color instead: red unhappy, yellow content, green happy. Turn Pet happiness off to have only this."] = "A háziállat életerősávja a hangulat színét kapja helyette: piros boldogtalan, sárga elégedett, zöld boldog. Kapcsold ki a Háziállat boldogságát, ha csak ezt akarod."
L["The ring lights up the moment your next spell is ready."] = "A gyűrű felvillan, amint a következő varázslatod kész."
L["The size of the messages on the second chat panel."] = "Az üzenetek mérete a második chatpanelen."
L["The spellbook and talent keys open DaylightUI's window. Turn it off to always use the game's window."] = "A varázskönyv és a tehetségek gombja a DaylightUI ablakát nyitja. Kapcsold ki, ha mindig a játék ablakát használnád."
L["The time to the next swing, written on the bar, attached or detached."] = "A következő ütésig hátralévő idő a sávra írva, csatolva vagy leválasztva."
L["This icon's own size. Whole group sizes every icon in the group."] = "Ennek az ikonnak a saját mérete. Az Egész csoport a csoport minden ikonját méretezi."
L["Trades places with the spell after it in the group. Each keeps its own look and options."] = "Helyet cserél a csoportban utána következő varázslattal. Mindegyik megtartja a saját kinézetét és beállításait."
L["Trades places with the spell before it in the group. Each keeps its own look and options."] = "Helyet cserél a csoportban előtte lévő varázslattal. Mindegyik megtartja a saját kinézetét és beállításait."
L["Where the next line of frames goes once one is full."] = "Hová kerül a keretek következő sora, ha egy betelt."
L["Which way the frames run from the first one. Up or Left starts them at the bottom or the right, so a small group sits by that edge."] = "Merre sorakoznak a keretek az elsőtől. A Fel vagy a Balra alulról vagy jobbról indítja őket, így egy kis csoport ahhoz a szélhez ül."
L["Your accent color (a gradient accent runs across the ring), your class's colors, or one you pick."] = "A kiemelőszíned (a színátmenetes kiemelés végigfut a gyűrűn), a kasztod színei, vagy egy általad választott."
L["Your casts and channels fill a thin ring around it."] = "A varázslásaid és csatornázásaid egy vékony gyűrűt töltenek körülötte."
L["Your own frame shows here even when you're not in a group."] = "A saját kereted akkor is itt látszik, ha nem vagy csoportban."
L["Your pet's mood beside the frame: red while it's unhappy, yellow while content, green while happy. Hover for its damage, loyalty and diet."] = "A háziállatod hangulata a keret mellett: piros, amíg boldogtalan, sárga, ha elégedett, zöld, ha boldog. Vidd fölé az egeret a sebzéséért, hűségéért és étrendjéért."
L["Light runs round it"] = "Körben futó fény"
L["Breathes"] = "Lélegzik"
L["Still"] = "Mozdulatlan"
L["Mood face"] = "Hangulatarc"
L["Color square"] = "Színes négyzet"
L["Colored square"] = "Színes négyzet"
L["Instances"] = "Instance-ek"
L["Open world"] = "Nyílt világ"
L["%d groups: %s%s."] = "%d csoport: %s%s."
L["%s is no longer junk."] = "A(z) %s már nem szemét."
L["%s on the options' Home page runs it any time."] = "A beállítások Kezdőlapján a(z) %s bármikor elindítja."
L["%s will be sold as junk."] = "A(z) %s szemétként lesz eladva."
L[", and %d more"] = ", és még %d"
L["/dui platefix - run while nameplates are invisible, one step each time, and say which step brought them back"] = "/dui platefix - futtasd, amíg a névtáblák láthatatlanok, minden alkalommal egy lépés, és mondd meg, melyik lépés hozta vissza őket"
