L["A minute to see what Daylight UI does that the game doesn't: the damage meter, buff and bag groups, moving frames and where every setting lives."] = "Egy perc, hogy lásd, mit tud a Daylight UI, amit a játék nem: a sebzésmérő, a buff- és táskacsoportok, a keretek mozgatása, és hol van minden beállítás."
