L["Copy the text in the box and send it to the Daylight UI team, then /reload."] = "Másold ki a dobozban lévő szöveget, küldd el a Daylight UI csapatának, aztán /reload."
L["Crit"] = "Kritikus"
L["Ctrl + mouse wheel"] = "Ctrl + egérgörgő"
L["Damage, healing and more for every fight, beside the minimap. Hover it for its buttons: which fight, what it counts, %s and reset. Hover a name for the breakdown of that player's spells."] = "Sebzés, gyógyítás és még sok más minden harcról, a minitérkép mellett. Vidd fölé az egeret a gombjaiért: melyik harc, mit számol, %s és visszaállítás. Vidd egy név fölé az egeret az adott játékos varázslatainak részletezéséért."
L["Dragging spells to your bars works out of combat."] = "A varázslatok sávokra húzása harcon kívül működik."
L["Dressing room"] = "Próbafülke"
L["Every piece of Daylight UI moves. %s shows a handle on each: drag it, scroll to resize, right-click to put it back. %s shows every frame with sample units, to style them without a group."] = "A Daylight UI minden darabja mozgatható. A(z) %s mindegyiken fogantyút mutat: húzd, görgess az átméretezéshez, jobb klikk a visszatevéshez. A(z) %s minden keretet mintaegységekkel mutat, hogy csoport nélkül is alakíthasd őket."
L["Every setting"] = "Minden beállítás"
L["Export bag groups"] = "Táskacsoportok exportálása"
L["Export groups"] = "Csoportok exportálása"
L["Find your perfect setup"] = "Találd meg a tökéletes beállításodat"
L["Flying"] = "Repülés"
L["Forget this profession and every recipe you know in it, to make room for another. You can learn it again from a trainer, starting over from skill 1."] = "Elfelejted ezt a szakmát és minden receptedet benne, hogy helyet csinálj egy másiknak. Egy oktatónál újra megtanulhatod, 1-es jártasságról kezdve."
L["Form or stance"] = "Forma vagy tartás"
L["From your mount, talents, gear and buffs."] = "A hátasodból, tehetségeidből, felszerelésedből és buffjaidból."
L["Gold, gear, free bag slots and who's online, turning amber then red when gear or bags run low. Hover one for details, click it for its window."] = "Arany, felszerelés, szabad táskahelyek és ki van online, borostyánra, majd pirosra váltva, ha a felszerelés vagy a táska fogyóban. Vidd fölé az egeret a részletekért, kattints rá az ablakáért."
