L["Play the quest's voice"] = "A küldetés hangjának lejátszása"
L["Press Escape and pick Daylight UI in the game menu, or type %s. %s over any Daylight UI window sizes it. %s on Home runs this tour again."] = "Nyomd meg az Escape-et, és válaszd a Daylight UI-t a játékmenüben, vagy írd be: %s. A(z) %s bármelyik Daylight UI ablak fölött méretezi azt. A Kezdőlapon a(z) %s újra elindítja ezt a bemutatót."
L["Find any setting"] = "Találj meg bármilyen beállítást"
L["Type a word in %s and every setting that matches shows up here, ready to change on the spot. No digging through pages."] = "Írj be egy szót ide: %s, és minden illeszkedő beállítás itt jelenik meg, azonnal módosítható. Nem kell oldalakon kutatni."
L["Profiles shared by Daylight UI players: press Ctrl+C to copy the link, then paste it in your browser."] = "Daylight UI-játékosok által megosztott profilok: Ctrl+C-vel másold a linket, aztán illeszd be a böngésződbe."
L["Put on a controller bar"] = "Kontrollersávra tétel"
L["Ready-made profiles from other Daylight UI players, from calm questing looks to raid healer layouts. Pick one you like, copy its string, import it in a click."] = "Kész profilok más Daylight UI-játékosoktól, a nyugodt küldetezős kinézettől a raidgyógyító-elrendezésekig. Válassz egyet, ami tetszik, másold a szövegét, importáld egy kattintással."
L["Remove point"] = "Pont eltávolítása"
