L["You move at %.0f%% of a normal run: on foot, mounted, swimming or flying, by what you're doing."] = "A normál futás %.0f%%-ával mozogsz: gyalog, hátason, úszva vagy repülve, attól függően, mit csinálsz."
L["Your bags sort items into groups by kind. Press %s to open them."] = "A táskáid fajta szerint csoportokba rendezik a tárgyakat. Nyomd meg ezt a megnyitásukhoz: %s."
L["Your buffs sort themselves into groups. A buff in the wrong one? %s it and pick its group."] = "A buffjaid maguktól csoportokba rendeződnek. Rossz helyen van egy buff? %s rajta, és válaszd ki a csoportját."
L["Your own groups as text to copy: paste it on another character, or give it to a friend."] = "A saját csoportjaid szövegként, másoláshoz: illeszd be egy másik karakteren, vagy add oda egy barátodnak."
L["Your own groups: their names, searches and the items you moved to them. Ctrl+C to copy, then share it."] = "A saját csoportjaid: a nevük, a kereséseik és az általad beléjük tett tárgyak. Ctrl+C a másoláshoz, aztán oszd meg."
L["Only while you lead"] = "Csak amíg vezetsz"
L["A party's tank too"] = "A csoport tankja is"
L["Everyone in a party"] = "Mindenki a csoportban"
L["This bar's own outline, corners and shadow, to match a power bar of its own or stand apart."] = "Ennek a sávnak a saját körvonala, sarkai és árnyéka, hogy illeszkedjen egy saját erőforrássávhoz, vagy elkülönüljön."
L["Gives this bar the border, corners and shadow below. When off, it follows General > Appearance."] = "Ez a sáv megkapja az alábbi keretet, sarkokat és árnyékot. Kikapcsolva az Általános > Megjelenés beállítást követi."
L["%s and %s both want to paint the %s of %s; %s keeps it."] = "A(z) %s és a(z) %s is ki akarja festeni ezt: %s (%s); a(z) %s tartja meg."
