L["The height of a whisper conversation above the chat or dragged away. Beside the chat it's as tall as the chat."] = "Egy suttogás-beszélgetés magassága a chat fölött vagy elhúzva. A chat mellett olyan magas, mint a chat."
L["Where a whisper conversation opens. Drag one by its top to put it anywhere on your screen, and drag its corner to resize it."] = "Hol nyílik meg egy suttogás-beszélgetés. A tetejénél fogva húzd, hogy bárhová tedd a képernyőn, és a sarkát húzva méretezd."
L["The width of a whisper conversation."] = "Egy suttogás-beszélgetés szélessége."
