L["%sClick|r%s: details  ·  |r%sShift-click|r%s: report|r"] = "%sKattintás|r%s: részletek  ·  |r%sShift+kattintás|r%s: jelentés|r"
L["ABSORBS"] = "ELNYELÉSEK"
L["A friendly player's buffs as a row of small icons, so you can see what they're missing before you rebuff. Not in combat: the game hides other players' buffs then."] = "Egy barátságos játékos buffjai kis ikonok soraként, hogy újrabuffolás előtt lásd, mi hiányzik nekik. Harcban nem: a játék ilyenkor elrejti más játékosok buffjait."
L["A small diamond by the names of the players in your party or raid, so they stand out in a crowd while their names keep their class color."] = "Kis rombusz a csoportod vagy raided játékosainak neve mellett, hogy kiugorjanak a tömegből, miközben a nevük megtartja a kasztszínét."
L["A square filled with the mood's color, the pet's mood face, or a stripe inside the frame."] = "Egy négyzet a hangulat színével kitöltve, a háziállat hangulatarca, vagy egy csík a kereten belül."
L["A thin line across the bars where your threat would pull the mob: 110% of the tank's in melee, 130% at range. Not shown against a boss, whose numbers the game keeps hidden."] = "Vékony vonal a sávokon ott, ahol a fenyegetésed magadra húzná a mobot: közelharcban a tank 110%-a, távolról 130%. Boss ellen nem látszik, mert a játék elrejti a számait."
L["A window showing an earlier fight goes back to this fight (or Overall) as the next one starts."] = "Egy korábbi harcot mutató ablak visszatér erre a harcra (vagy az Összesre), amikor a következő elkezdődik."
L["All meters"] = "Minden mérő"
L["Always show yourself"] = "Saját magad mindig látszik"
L["Amounts shortened (12.3K) or in full (12,345), on every meter, the breakdowns and reports."] = "Összegek rövidítve (12.3K) vagy teljesen (12,345), minden mérőn, a részletezőkben és a jelentésekben."
L["An Alliance or Horde crest by the names of players of the other faction, on enemy and friendly plates alike."] = "Szövetség- vagy Horda-címer a másik frakció játékosainak neve mellett, ellenséges és barátságos névtáblákon egyaránt."
L["Angled bar ends"] = "Ferde sávvégek"
L["Arrow size"] = "Nyíl mérete"
L["Arrows pointing at your target's plate, on both sides of it or over it, so it's easy to find in a crowd."] = "Nyilak, amik a célpontod névtáblájára mutatnak, mindkét oldalról vagy fölülről, hogy tömegben is könnyű legyen megtalálni."
L["Attackers"] = "Támadók"
L["Avoidable"] = "Elkerülhető"
L["Back to the current fight on a pull"] = "Pullnál vissza a jelenlegi harcra"
L["Bar gradient"] = "Sáv színátmenete"
