L["Between the frames"] = "A keretek között"
L["Both ends"] = "Mindkét vég"
L["Both sides"] = "Mindkét oldal"
L["By threat"] = "Fenyegetés szerint"
L["Choose"] = "Választás"
L["Click a name to rename it. A click on Settings edits that window on the other tabs."] = "Kattints egy névre az átnevezéséhez. A Beállítások gombra kattintás a többi fülön azt az ablakot szerkeszti."
L["Controller mode"] = "Kontroller mód"
L["Controller mode uses the profile %s. Switch to it?"] = "A kontroller mód a(z) %s profilt használja. Átváltasz rá?"
L["Ctrl+C to copy, then paste it in a bug report on the Daylight UI Discord. After that, /reload."] = "Ctrl+C a másoláshoz, aztán illeszd be egy hibajelentésbe a Daylight UI Discordon. Utána /reload."
L["Custom overshield color"] = "Egyedi túlpajzs-szín"
L["Cuts the ends of each line at an angle. When off, the ends are straight."] = "Minden sor végeit ferdén levágja. Kikapcsolva a végek egyenesek."
L["Damage or healing per second, in brackets after the total."] = "Sebzés vagy gyógyítás másodpercenként, zárójelben az összeg után."
L["Damage per second"] = "Sebzés másodpercenként"
L["Damage, healing and more for every fight, beside the minimap: the mode, the fight and its length on top, and its buttons there while the mouse is over it (which fight, what it counts, %s, reset, %s). Hover a name for their spells; click it for everything. More windows: %s."] = "Sebzés, gyógyítás és még sok más minden harcról, a minitérkép mellett: felül a mód, a harc és a hossza, és ott vannak a gombjai, amíg rajta van az egér (melyik harc, mit számol, %s, visszaállítás, %s). Vidd egy név fölé az egeret a varázslataiért; kattints rá mindenért. További ablakok: %s."
L["Damage, healing and threat meters: the one in the info panel, the threat meter beside it, and as many windows of your own as you like."] = "Sebzés-, gyógyítás- és fenyegetésmérők: az infópanelen lévő, mellette a fenyegetésmérő, és annyi saját ablak, amennyit szeretnél."
L["Dark end"] = "Sötét vég"
L["Deadly"] = "Halálos"
L["Death"] = "Halál"
L["Each bar in its player's class color or all in one color; a threat meter can color each bar by how close that player is to pulling."] = "Minden sáv a játékosa kasztszínében vagy mind egy színben; a fenyegetésmérő aszerint is színezheti a sávokat, mennyire közel van az adott játékos a magára húzáshoz."
L["Each player's place, before their icon."] = "Minden játékos helyezése, az ikonja előtt."
L["Each player's share of everyone's total, in brackets. The game hides the numbers during a fight, so it shows once the fight is over."] = "Minden játékos része mindenki összegéből, zárójelben. A játék harc közben elrejti a számokat, ezért a harc végén jelenik meg."
L["Each player's total, the first number on their bar."] = "Minden játékos összege, az első szám a sávján."
L["Everyone's total for the fight, beside its length."] = "Mindenki összege a harcra, a hossza mellett."
L["Every number, by player"] = "Minden szám, játékosonként"
L["Fall"] = "Esés"
L["Fight on: updates when it ends."] = "Harc folyik: a végén frissül."
L["Fight summary"] = "Harc összegzése"
