L["Healing per second"] = "Gyógyítás másodpercenként"
L["Hold: %s"] = "Nyomva tartva: %s"
L["How big the arrows are."] = "Mekkorák a nyilak."
L["How big your target's name is. 0 keeps it the same as every plate's Name size."] = "Mekkora a célpontod neve. A 0 ugyanakkorán tartja, mint minden névtábla Névméretét."
L["How much a plate lights up while your mouse is over it. At 0% it doesn't light up."] = "Mennyire világosodik ki egy névtábla, amíg rajta van az egér. 0%-nál nem világosodik ki."
L["How solid the empty part of every health and power bar is. Lower lets the world show through it, like the game's own frames."] = "Mennyire tömör minden életerő- és erőforrássáv üres része. Alacsonyabb értéknél átlátszik rajta a világ, mint a játék saját keretein."
L["How solid the empty part of every plate's health and power bar is. Lower lets the world show through it, like the game's own plates."] = "Mennyire tömör minden névtábla életerő- és erőforrássávjának üres része. Alacsonyabb értéknél átlátszik rajta a világ, mint a játék saját névtábláin."
L["How tall the window is. Dragging its corner in unlock mode sets it too."] = "Milyen magas az ablak. Feloldott módban a sarkát húzva is ezt állítod."
L["How thick the ring is. A thicker ring leaves a smaller picture inside. The red aggro ring and its lights follow it."] = "Milyen vastag a gyűrű. A vastagabb gyűrű kisebb képet hagy belül. A piros aggrógyűrű és a fényei ezt követik."
L["How wide the window is. Dragging its corner in unlock mode sets it too."] = "Milyen széles az ablak. Feloldott módban a sarkát húzva is ezt állítod."
L["In a group or with a pet"] = "Csoportban vagy háziállattal"
L["In the middle, the swing timers fanning out under it."] = "Középen, alatta legyezőszerűen az ütésidőzítők."
L["Info Panel > Meters"] = "Infópanel > Mérők"
L["Its bag, bank and guild bank windows, slots and buttons. Another look can still be picked in Bagnon's own options."] = "A táska-, bank- és céhbankablakai, helyei és gombjai. A Bagnon saját beállításaiban továbbra is választható másik kinézet."
L["Its bag, bank and guild bank windows, slots, buttons and settings, while its own Blizzard look is picked."] = "A táska-, bank- és céhbankablakai, helyei, gombjai és beállításai, amíg a saját Blizzard kinézete van kiválasztva."
L["Killing blow"] = "Halálos csapás"
L["Left end"] = "Bal vég"
L["Left of the frame"] = "A kerettől balra"
L["Light end"] = "Világos vég"
L["Line round the middle"] = "Vonal középen körben"
L["Meters"] = "Mérők"
L["Missing health opacity"] = "Hiányzó életerő átlátszatlansága"
L["Mouseover light"] = "Fény egér alatt"
L["New meter window"] = "Új mérőablak"
L["New ranks on your bars"] = "Új rangok a sávjaidon"
L["New window"] = "Új ablak"
L["No absorbs yet."] = "Még nincsenek elnyelések."
L["No avoidable damage yet."] = "Még nincs elkerülhető sebzés."
L["No damage taken yet."] = "Még nincs kapott sebzés."
L["No damage yet."] = "Még nincs sebzés."
L["No death in this fight."] = "Ebben a harcban nem volt halál."
L["No deaths yet."] = "Még nincsenek halálok."
L["No dispels yet."] = "Még nincsenek levételek."
L["No enemies yet."] = "Még nincsenek ellenségek."
L["No fights yet."] = "Még nincsenek harcok."
L["No form"] = "Nincs forma"
L["No healing yet."] = "Még nincs gyógyítás."
L["No interrupts yet."] = "Még nincsenek megszakítások."
L["Not now"] = "Most nem"
L["Not while under the frame (the portrait ring covers that spot) or between the frames."] = "Nem, ha a keret alatt van (ott a portrégyűrű takarja azt a helyet) vagy a keretek között."
L["Not while under the frame or between the frames."] = "Nem, ha a keret alatt vagy a keretek között van."
L["Not while under the frame or between the frames: there it fills the space it has."] = "Nem, ha a keret alatt vagy a keretek között van: ott kitölti a rendelkezésre álló helyet."
L["Nothing here for this player yet."] = "Ennél a játékosnál itt még nincs semmi."
L["Off, the addon stays installed but doesn't load on this character after a reload."] = "Kikapcsolva az addon telepítve marad, de újratöltés után nem töltődik be ezen a karakteren."
L["Off: the spell hides while you're in it, and the group's Slide over closes its gap."] = "Kikapcsolva a varázslat elrejtőzik, amíg ebben vagy, és a csoport Odacsúszás beállítása bezárja a rését."
L["On for this character"] = "Bekapcsolva ennél a karakternél"
L["One line for the sidebar tooltip."] = "Egy sor az oldalsáv súgóbuborékához."
L["Only from its tab"] = "Csak a füléről"
L["Other faction's crest"] = "A másik frakció címere"
L["Out of Stealth"] = "Stealthen kívül"
L["Over it"] = "Fölötte"
L["Over the frame"] = "A keret fölött"
L["Overkill %s"] = "Túlsebzés: %s"
L["Overshield color"] = "Túlpajzs színe"
L["Overshield from the other end"] = "Túlpajzs a másik végéről"
L["Overshield texture"] = "Túlpajzs textúrája"
L["Own window"] = "Saját ablak"
L["Pages"] = "Lapok"
L["Per second"] = "Másodpercenként"
L["Picking an earlier fight in one window shows it in every window on This fight. Windows on Overall stay there."] = "Ha egy ablakban korábbi harcot választasz, minden Ez a harc beállítású ablakban az látszik. Az Összes beállítású ablakok maradnak."
L["Players' last names after their first on the threat meters. When off, first names only, which fit the narrow rows better."] = "A játékosok vezetékneve a keresztnevük után a fenyegetésmérőkön. Kikapcsolva csak keresztnevek, ezek jobban elférnek a keskeny sorokban."
L["Pop"] = "Pattanás"
L["Portrait rings"] = "Portrégyűrűk"
L["Powershifting: the game takes a moment to confirm a new form, and shows your caster bar until it does. Put /click DaylightUICat (or DaylightUIBear, DaylightUIMoonkin) at the top of your shift macro and this bar swaps the moment you press it."] = "Powershifting: a játéknak kell egy pillanat, hogy megerősítsen egy új formát, és addig a varázslósávodat mutatja. Tedd a /click DaylightUICat (vagy DaylightUIBear, DaylightUIMoonkin) sort a formaváltó makród tetejére, és ez a sáv abban a pillanatban vált, amikor megnyomod."
L["Quest list beside the map"] = "Küldetéslista a térkép mellett"
L["Rank numbers"] = "Helyezési számok"
L["Rare elite"] = "Ritka elit"
L["Reaction"] = "Viszony"
L["Reaction: every enemy name in red, players too, so friend and foe tell apart at a glance. Or players in their class color, a class gradient, or plain white."] = "Viszony: minden ellenséges név pirosban, a játékosoké is, így első ránézésre megkülönböztethető a barát és az ellenség. Vagy a játékosok a kasztszínükben, kaszt-színátmenetben, vagy sima fehérben."
L["Red to green by count"] = "Pirosból zöldbe a számláló szerint"
L["Removes this window and its settings. Click twice."] = "Eltávolítja ezt az ablakot és a beállításait. Kattints kétszer."
L["Report to chat"] = "Jelentés a chatbe"
L["Reset every fight"] = "Minden harc visszaállítása"
L["Right end"] = "Jobb vég"
L["Right of the frame"] = "A kerettől jobbra"
L["Right-click: pick which attack power"] = "Jobb klikk: melyik támadóerő"
L["Right-click: pin, invite, note, ignore, close"] = "Jobb klikk: kitűzés, meghívás, megjegyzés, figyelmen kívül hagyás, bezárás"
L["Ring thickness"] = "Gyűrű vastagsága"
L["Rise"] = "Emelkedés"
L["Same as shields"] = "Ugyanaz, mint a pajzsok"
L["Settings"] = "Beállítások"
L["Show only in an instance"] = "Csak instance-ben"
L["Show per second"] = "Másodpercenkénti érték mutatása"
L["Show share"] = "Részesedés mutatása"
L["Show this window"] = "Ennek az ablaknak a mutatása"
L["Show totals"] = "Összegek mutatása"
L["Size of the names and numbers on the bars."] = "A nevek és számok mérete a sávokon."
L["Skip tour"] = "Bemutató kihagyása"
L["Slam"] = "Csapás"
L["Slides out from under your frame as you cast."] = "Varázslás közben kicsúszik a kereted alól."
L["Spells"] = "Varázslatok"
L["Stack"] = "Tornyozás"
L["Switched off, the window is gone (its settings stay). The threat meter beside the meter shows by its own rules below."] = "Kikapcsolva az ablak eltűnik (a beállításai megmaradnak). A mérő melletti fenyegetésmérő az alábbi saját szabályai szerint látszik."
L["Takes the bars out from under the player frame so you can move them together (/dui unlock); they slide out of their own box. When off, they hang under the player frame, under the cast bar while it hangs there, even with the cast bar detached. With your cast bar between your frame and the target's, they fan out under it instead, each a little wider."] = "Kiveszi a sávokat a játékoskeret alól, hogy együtt mozgathasd őket (/dui unlock); a saját dobozukból csúsznak ki. Kikapcsolva a játékoskeret alatt lógnak, a varázslássáv alatt, amíg az ott lóg, akkor is, ha a varázslássáv le van választva. Ha a varázslássávod a kereted és a célpontéé között van, inkább alatta nyílnak legyezőszerűen, mindegyik kicsit szélesebben."
L["Takes the damage meter out of the panel into its own window in the bottom-right corner; move it in unlock mode."] = "Kiveszi a sebzésmérőt a panelből egy saját ablakba a jobb alsó sarokban; feloldott módban mozgasd."
L["Target arrows"] = "Célpontnyilak"
L["Target: name size"] = "Célpont: névméret"
L["Targets"] = "Célpontok"
L["Taken"] = "Kapott"
L["The arrows in your accent color, or one you pick below."] = "A nyilak a kiemelőszínedben, vagy egy alább választott színben."
L["The bars' filled part ends in a slanted edge. When off, it ends square."] = "A sávok kitöltött része ferde éllel végződik. Kikapcsolva szögletesen."
L["The color of the names on the bars."] = "A nevek színe a sávokon."
L["The color of your party and raid members' names (with Group names on) and of the Group mark."] = "A csoport- és raidtagjaid nevének színe (bekapcsolt Csoportnevekkel), és a Csoportjelé."
L["The game hides who's who here for now: it updates once it can."] = "A játék egyelőre elrejti, ki kicsoda: frissül, amint lehet."
L["The last one follows your target when you can attack it, else the mob your friendly target is on: handy for a healer watching the tank."] = "Az utolsó a célpontodat követi, ha megtámadhatod, különben azt a mobot, amin a barátságos célpontod van: hasznos egy gyógyítónak, aki a tankot figyeli."
L["The line on top: the mode, the fight and its length (a meter), or the mob and your own threat (a threat meter). A meter's buttons show in it while the mouse is over the window."] = "A felső sor: a mód, a harc és a hossza (mérőnél), vagy a mob és a saját fenyegetésed (fenyegetésmérőnél). A mérő gombjai itt jelennek meg, amíg az egér az ablak fölött van."
L["The most group members it lists at once."] = "Egyszerre legfeljebb ennyi csoporttagot listáz."
L["The most group members it lists under the damage meter."] = "Legfeljebb ennyi csoporttagot listáz a sebzésmérő alatt."
L["The outline round the time and stack count on buffs and debuffs, apart from General > Appearance's, so the time stays easy to read over any icon."] = "A buffok és debuffok idejét és halomszámát körülvevő körvonal, az Általános > Megjelenésétől függetlenül, hogy az idő bármilyen ikonon könnyen olvasható maradjon."
L["The overshield grows from where the health starts instead of from the frame's end."] = "A túlpajzs onnan nő, ahol az életerő kezdődik, nem a keret végétől."
L["The overshield in the absorb shields' color, or a color of its own."] = "A túlpajzs az elnyelő pajzsok színében, vagy saját színben."
L["The overshield's look: the same as the shield texture, or its own."] = "A túlpajzs kinézete: ugyanaz, mint a pajzs textúrája, vagy saját."
L["The player frame"] = "A játékoskeret"
L["The power bar"] = "Az erőforrássáv"
L["The ring round every portrait, on every frame. Each frame picks its ring's color on its own page."] = "A gyűrű minden portré körül, minden kereten. Minden keret a saját oldalán választja ki a gyűrűje színét."
L["The small square before each name: the player's class icon, or nothing."] = "A kis négyzet minden név előtt: a játékos kasztikonja, vagy semmi."
L["The space between two bars."] = "A hely két sáv között."
L["The thin dark line round the middle of the ring. When off, the ring is one smooth band."] = "A vékony sötét vonal a gyűrű közepén körben. Kikapcsolva a gyűrű egy sima sáv."
L["The threat meter and your threat windows fade together, apart from the panel."] = "A fenyegetésmérő és a fenyegetésablakaid együtt halványulnak el, a paneltől függetlenül."
L["The window hides outside dungeons, raids, battlegrounds and arenas."] = "Az ablak rejtve van kazamatán, raiden, csatatéren és arénán kívül."
L["The window hides while you play solo."] = "Az ablak rejtve van, amíg egyedül játszol."
L["There are already %d meter windows of your own: remove one to make another."] = "Már %d saját mérőablakod van: távolíts el egyet, hogy újat készíthess."
L["Threat meter fade"] = "Fenyegetésmérő elhalványítása"
L["Threat meter position"] = "Fenyegetésmérő helye"
L["Threat meter rows under the meter"] = "Fenyegetésmérő sorai a mérő alatt"
L["Turn off"] = "Kikapcsolás"
L["Turn on"] = "Bekapcsolás"
L["Under the frame"] = "A keret alatt"
L["Under the meter it rises out of the damage meter's bottom, as wide as the meter. Docked, it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode."] = "A mérő alatt a sebzésmérő aljából emelkedik ki, a mérő szélességében. Dokkolva csak akkor látszik, ha a sebzésmérő nyitva van. A saját ablaka bárhová kerülhet: feloldott módban mozgasd."
L["Under your frame"] = "A kereted alatt"
L["Up to %d of your own, each with its own settings and spot. Move them in unlock mode."] = "Legfeljebb %d saját, mindegyik saját beállításokkal és hellyel. Feloldott módban mozgathatod őket."
L["Usable"] = "Használható"
L["Utility"] = "Segédképesség"
L["What this meter lists: damage, DPS, healing, absorbs, damage taken, interrupts, dispels, deaths and more. The button in its header changes it too."] = "Mit listáz ez a mérő: sebzés, DPS, gyógyítás, elnyelések, kapott sebzés, megszakítások, levételek, halálok és még sok más. A fejlécében lévő gomb is ezt váltja."
L["When a shield is bigger than the health missing, the part that doesn't fit runs back over the health with a bright line. When off, only the shield that fits shows."] = "Ha egy pajzs nagyobb a hiányzó életerőnél, a be nem férő rész fényes vonallal visszafut az életerőn. Kikapcsolva csak a beférő pajzs látszik."
L["When I'm the tank"] = "Ha én vagyok a tank"
L["When you learn a new rank of a spell, it takes the place of the rank before it on your bars. A lower rank you keep on purpose, like rank 1 to save mana, stays. Not macros."] = "Ha egy varázslat új rangját tanulod meg, az a sávjaidon az előző rang helyére kerül. A szándékosan megtartott alacsonyabb rang, például az 1-es a mana spórolásához, marad. A makrókat nem érinti."
L["When you'd be scrolled out of view, your bar stays in the last row with your place."] = "Ha kigörgetődnél a látómezőből, a sávod a helyezéseddel az utolsó sorban marad."
L["Whether the summary shows this column."] = "Mutassa-e az összegzés ezt az oszlopot."
L["Whether this window counts the fight you're in or every fight since the last reset."] = "Ez az ablak az aktuális harcot számolja, vagy az utolsó visszaállítás óta minden harcot."
L["Which ends of each line are cut at an angle. The other end stays straight."] = "Minden sor melyik végei legyenek ferdén levágva. A másik vég egyenes marad."
L["Whose threat"] = "Kinek a fenyegetése"
L["Window header"] = "Ablakfejléc"
L["Windows show the same fight"] = "Az ablakok ugyanazt a harcot mutatják"
L["With the map maximized, the quest list opens beside it, as it does on the small map, instead of taking its room from the map. On a narrow screen the map gives up only what doesn't fit."] = "Teljes méretű térképnél a küldetéslista mellette nyílik meg, ahogy a kis térképen, nem a térkép helyéből vesz el. Keskeny képernyőn a térkép csak annyit ad fel, amennyi nem fér el."
L["With the power bar on its own (Player > Power bar), the cast bar and the swing timer under it can slide out from under the power bar instead of the frame."] = "Ha az erőforrássáv önállóan áll (Játékos > Erőforrássáv), az alatta lévő varázslássáv és ütésidőzítő az erőforrássáv alól is kicsúszhat a keret helyett."
L["Without the controller, this character uses the profile %s. Switch to it?"] = "Kontroller nélkül ez a karakter a(z) %s profilt használja. Átváltasz rá?"
L["Your focus"] = "A fókuszod"
L["Your target"] = "A célpontod"
L["Your target, else your target's target"] = "A célpontod, különben a célpontod célpontja"
L["Your windows"] = "Az ablakaid"
L["new window"] = "új ablak"
L["A crown on the party leader's frame. It rides with the name tab or portrait until you pick a spot for it."] = "Korona a csoportvezető keretén. A névfüllel vagy a portréval együtt mozog, amíg nem választasz neki helyet."
L["Adds a chat tab, or a combat log tab."] = "Chatfület vagy harcinapló-fület ad hozzá."
L["Alerts and timers"] = "Riasztások és időzítők"
L["Answers to a ready check, and who's being summoned, on each party frame."] = "Válaszok a készenléti ellenőrzésre, és ki van idézve, minden csoportkereten."
L["Calm scenes along the bottom of the screen while you fish or craft."] = "Nyugodt jelenetek a képernyő alján horgászás vagy barkácsolás közben."
L["Cast bar gradients"] = "Varázslássáv-színátmenetek"
L["Change status"] = "Állapot módosítása"
L["Combo Points & Range"] = "Kombópontok és hatótáv"
L["Combo points for rogues and druids, and how frames fade out of range."] = "Kombópontok zsiványoknak és druidáknak, és hogyan halványulnak a keretek hatótávon kívül."
L["Copy your BattleTag"] = "BattleTag másolása"
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Default uses the style set for every frame on Unit Frames > Look. Each style keeps its own heights."] = "Daylight: a keret a nevével egy fülben fölötte, benne az erőforrássávval. Szalag: vékony sáv, fölötte lebeg a név és az életerő, alatta vékony vonalként az erőforrás. Az Alapértelmezett az Egységkeretek > Kinézet alatt minden keretre beállított stílust használja. Minden stílus megtartja a saját magasságait."
L["Docked bars"] = "Dokkolt sávok"
L["Drag the tab row to move it and a corner to resize it."] = "Húzd a fülsort a mozgatáshoz, egy sarkát az átméretezéshez."
L["Friendly plates"] = "Barátságos névtáblák"
L["Health and names"] = "Életerő és nevek"
L["How a debuff you can remove shows on each raid tile: an icon, a highlight or a glow."] = "Hogyan látszik egy levehető debuff minden raidcsempén: ikon, kiemelés vagy fény."
L["How each hand's bar is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per hand, set on the Gradients page. A queued attack always keeps its own color."] = "Hogyan töltődik az egyes kezek sávja: egy-egy szín, a Daylight színátmenet (a logó kékjétől a narancsig), vagy kezenként kétszínű színátmenet, a Színátmenetek oldalon állítva. A sorban álló támadás mindig megtartja a saját színét."
L["How every cast bar (yours, target's, focus's and party's) is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per kind of cast, set on the Gradients page."] = "Hogyan töltődik minden varázslássáv (a tiéd, a célpontodé, a fókuszé és a csoporté): egy-egy szín, a Daylight színátmenet (a logó kékjétől a narancsig), vagy varázslásfajtánként kétszínű színátmenet, a Színátmenetek oldalon állítva."
L["How far the angled end leans, docked bars included. Set to 0 to use the Slant angle on Unit Frames > Look."] = "Mennyire dől a ferde vég, a dokkolt sávokat is beleértve. A 0 az Egységkeretek > Kinézet Dőlésszögét használja."
L["Item and spell lines"] = "Tárgy- és varázslatsorok"
L["Keeps its spot and size so a stray drag can't move it."] = "Megtartja a helyét és méretét, hogy egy véletlen húzás ne mozdíthassa el."
L["Lock the chat"] = "Chat zárolása"
L["Marks"] = "Jelek"
L["Opens the Gradients page, where the Casts pairs are."] = "Megnyitja a Színátmenetek oldalt, ahol a Varázslások párjai vannak."
L["Opens the Gradients page, where the Swing timers pairs are."] = "Megnyitja a Színátmenetek oldalt, ahol az Ütésidőzítők párjai vannak."
L["Opens the chat's text so you can select it and copy it with Ctrl+C."] = "Megnyitja a chat szövegét, hogy kijelölhesd és Ctrl+C-vel másolhasd."
L["Opens the game's voice chat and channels window."] = "Megnyitja a játék hangcsevegés- és csatornaablakát."
L["Player and creature lines"] = "Játékos- és lénysorok"
L["Press and mouseover"] = "Lenyomás és egér alatt"
L["Profession scenes"] = "Szakmai jelenetek"
L["Range and cooldown"] = "Hatótáv és cooldown"
L["Ready check and summon"] = "Készenléti ellenőrzés és idézés"
L["Rogues and druids in cat form: your combo points on your target's plate. Colors follow Unit Frames > Combo Points & Range."] = "Zsiványok és macskaformás druidák: a kombópontjaid a célpontod névtábláján. A színek az Egységkeretek > Kombópontok és hatótáv beállítást követik."
L["Rogues and druids: your combo points under the bars, in the colors from Unit Frames > Combo Points & Range."] = "Zsiványok és druidák: a kombópontjaid a sávok alatt, az Egységkeretek > Kombópontok és hatótáv színeiben."
L["Rogues and druids: your combo points under the personal display's bars."] = "Zsiványok és druidák: a kombópontjaid a személyes kijelző sávjai alatt."
L["Same as the Look page"] = "Ugyanaz, mint a Kinézet oldal"
L["Say, yell, language and emotes, from the game's own chat menu."] = "Mondás, kiabálás, nyelv és emote-ok, a játék saját chatmenüjéből."
L["Scenes"] = "Jelenetek"
L["Set yourself as Available, Away or Busy for your Battle.net friends, or send them a broadcast."] = "Állítsd magad Elérhetőre, Távolra vagy Elfoglaltra a Battle.net-barátaid felé, vagy küldj nekik üzenetet."
L["Shows your BattleTag selected, to copy it with Ctrl+C and give it to a friend."] = "Kijelölve mutatja a BattleTagedet, hogy Ctrl+C-vel másolhasd és odaadhasd egy barátodnak."
L["Skull, cross and the rest on a marked member's frame. It rides with the name tab or portrait until you pick a spot for it."] = "Koponya, kereszt és a többi a megjelölt tag keretén. A névfüllel vagy a portréval együtt mozog, amíg nem választasz neki helyet."
L["Swing timer gradients"] = "Ütésidőzítő-színátmenetek"
L["Tabs, look, filters and the rest of the chat's settings."] = "Fülek, kinézet, szűrők és a chat többi beállítása."
L["Tank, healer or damage on each party frame. It rides with the name tab or portrait until you pick a spot for it."] = "Tank, gyógyító vagy sebző minden csoportkereten. A névfüllel vagy a portréval együtt mozog, amíg nem választasz neki helyet."
L["The bar's own color, so it can look unlike your player frame. Same as the Look page follows the color every frame shares."] = "A sáv saját színe, hogy eltérhessen a játékoskeretedtől. Az Ugyanaz, mint a Kinézet oldal azt a színt követi, amin minden keret osztozik."
L["The empty part of this frame's health bar, behind the fill: a darker copy of the bar's color, or one you pick. Same as the Look page follows the look every frame shares."] = "Ennek a keretnek az életerősávja üres része a kitöltés mögött: a sáv színének sötétebb másolata, vagy egy általad választott. Az Ugyanaz, mint a Kinézet oldal azt a kinézetet követi, amin minden keret osztozik."
L["The empty part of this frame's power bar, behind the fill: a darker copy of the bar's color, or one you pick. Same as the Look page follows the look every frame shares."] = "Ennek a keretnek az erőforrássávja üres része a kitöltés mögött: a sáv színének sötétebb másolata, vagy egy általad választott. Az Ugyanaz, mint a Kinézet oldal azt a kinézetet követi, amin minden keret osztozik."
L["The frames' shape, class icons, and the bars' and names' colors on every unit frame."] = "A keretek alakja, a kasztikonok, és a sávok és nevek színei minden egységkereten."
L["The raid tiles' own name color. Same as the Look page follows the name color every frame shares."] = "A raidcsempék saját névszíne. Az Ugyanaz, mint a Kinézet oldal azt a névszínt követi, amin minden keret osztozik."
L["The unit's health as text by the bar."] = "Az egység életereje szövegként a sáv mellett."
L["The unit's level by the bar; ?? for one far above you, + for an elite."] = "Az egység szintje a sáv mellett; ?? a nálad jóval erősebbnél, + az elitnél."
L["This frame's own health color, so it can look unlike the others. Same as the Look page follows the color every frame shares."] = "Ennek a keretnek a saját életerőszíne, hogy eltérhessen a többitől. Az Ugyanaz, mint a Kinézet oldal azt a színt követi, amin minden keret osztozik."
L["This frame's own name color. Same as the Look page follows the name color every frame shares."] = "Ennek a keretnek a saját névszíne. Az Ugyanaz, mint a Kinézet oldal azt a névszínt követi, amin minden keret osztozik."
L["This frame's own power color. Same as the Look page follows the color every frame shares."] = "Ennek a keretnek a saját erőforrásszíne. Az Ugyanaz, mint a Kinézet oldal azt a színt követi, amin minden keret osztozik."
L["Unlock the chat"] = "Chat feloldása"
L["Used when the combo points color on Unit Frames > Combo Points & Range is a gradient: All points fills every pip with one pair, Point 1 to 5 give each pip its own."] = "Akkor használt, ha az Egységkeretek > Kombópontok és hatótáv kombópontszíne színátmenet: a Minden pont minden jelölőt egy párral tölt, az 1-5. pont mindegyiknek sajátot ad."
L["Where the role, marker and crown sit on a tile, and the ready check and summon icons."] = "Hol ül a szerep, a jelölő és a korona egy csempén, valamint a készenléti és idézési ikonok."
L["Your BattleTag. Press Ctrl+C to copy it."] = "A BattleTaged. Ctrl+C a másoláshoz."
L["Your cast bar and swing timers under the personal display, as wide as it and cut like it."] = "A varázslássávod és az ütésidőzítőid a személyes kijelző alatt, annak szélességében és vágásával."
L["Your damage over time spells: the end of the health they will still take is shaded darker. The color is on Unit Frames > Look."] = "Az időbeli sebzéseid: az életerő azon vége, amit még levisznek, sötétebb árnyékot kap. A szín az Egységkeretek > Kinézet alatt van."
L["Your frame's own health color, so it can look unlike the others. Same as the Look page follows the color every frame shares; Daylight gradient is the logo's blue to orange; Accent color follows your accent on General > Appearance, gradient included."] = "A kereted saját életerőszíne, hogy eltérhessen a többitől. Az Ugyanaz, mint a Kinézet oldal azt a színt követi, amin minden keret osztozik; a Daylight színátmenet a logó kékjétől a narancsig tart; a Kiemelőszín az Általános > Megjelenés kiemelésedet követi, színátmenettel együtt."
L["Where the name sits across the bar: left, center or right. With a portrait, the name sits beside it instead."] = "Hol ül a név a sávon: bal, közép vagy jobb. Portréval a név inkább mellette ül."
L["Turn the party frames on or off. While Use raid frames in a party (Unit Frames > Raid 10) is on, the raid frames show in a party instead and the rows on this page do nothing."] = "A csoportkeretek be- vagy kikapcsolása. Amíg a Raidkeretek használata csoportban (Egységkeretek > Raid 10) be van kapcsolva, csoportban a raidkeretek látszanak helyettük, és ennek az oldalnak a sorai nem csinálnak semmit."
L["When the accent color is a gradient (Daylight's or your class's), every Daylight UI border runs along it: windows, panels, frames and nameplates. Needs Gradients on (General > Gradients)."] = "Ha a kiemelőszín színátmenet (a Daylighté vagy a kasztodé), minden Daylight UI keret ezt követi: ablakok, panelek, keretek és névtáblák. Kell hozzá a Színátmenetek bekapcsolása (Általános > Színátmenetek)."
L["A dark edge around the letters on Daylight UI's frames, so text stays readable over a busy world. Combat text has its own (General > Combat text)."] = "Sötét szegély a betűk körül a Daylight UI keretein, hogy a szöveg zsúfolt világ fölött is olvasható maradjon. A harci szövegnek sajátja van (Általános > Harci szöveg)."
L["A small soft drop shadow under text. Combat text has its own (General > Combat text)."] = "Kis lágy vetett árnyék a szöveg alatt. A harci szövegnek sajátja van (Általános > Harci szöveg)."
L["Sets Visible to Only when something changes on every part that has it: gone out of a fight, back in one, and back for a moment when it changes. Turned off, each goes back to what it was before. Each part's own Visible on its page still works on its own."] = "Minden résznél, ahol van ilyen, a Láthatót Csak változáskor értékre állítja: harcon kívül eltűnik, harcban visszajön, és változáskor egy pillanatra visszajön. Kikapcsolva mindegyik visszaáll arra, ami előtte volt. Minden rész saját oldalán lévő Látható beállítása továbbra is önállóan működik."
L["Reputation bars in their colors from the Gradients page, skill, PvP and currency bars in the accent's. When off, they're plain fills. Needs Gradients on (General > Gradients)."] = "A hírnévsávok a Színátmenetek oldal színeiben, a jártasság-, PvP- és pénznemsávok a kiemelésében. Kikapcsolva sima kitöltések. Kell hozzá a Színátmenetek bekapcsolása (Általános > Színátmenetek)."
L["Buffs and debuffs slide in as they land and lift away as they leave. Needs Motion effects (General > Appearance)."] = "A buffok és debuffok beúsznak, amikor rád kerülnek, és felemelkednek, amikor lekerülnek. Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["Questie is on: when off, Questie's own tracker shows instead and the tracker rows on this page do nothing. Daylight UI's journal, marker and arrow stay either way."] = "A Questie be van kapcsolva: kikapcsolva a Questie saját követője látszik helyette, és ennek az oldalnak a követősorai nem csinálnak semmit. A Daylight UI naplója, jelölője és nyila így is, úgy is marad."
L["Hovering a Questie icon on the map or minimap, or a quest in the quest log, makes that quest's icons a little bigger and fades the other quests' icons. Needs the Questie addon."] = "Ha egy Questie-ikon fölé viszed az egeret a térképen vagy a minitérképen, vagy egy küldetés fölé a küldetésnaplóban, annak a küldetésnek az ikonjai kicsit nagyobbak lesznek, a többi küldetésé pedig elhalványul. Kell hozzá a Questie addon."
L["A soft glow behind a message that says your name or one of your words. Needs Light up your name, or some Words to light up."] = "Lágy fény egy olyan üzenet mögött, ami a nevedet vagy valamelyik szavadat mondja. Kell hozzá A neved felvillanása, vagy néhány Felvillanó szó."
L["Stop keeping"] = "Megtartás vége"
L["The color of this group's heading and its name in menus. Click to change."] = "Ennek a csoportnak a fejlécszíne és a neve a menükben. Kattints a módosításhoz."
L["%s an item to move it to another group, lock it so it's never sold, or sell it as junk. %s the bag icon at the top to open your %s or your %s, from anywhere."] = "%s egy tárgyon áthelyezi egy másik csoportba, zárolja, hogy soha ne add el, vagy szemétként eladja. %s a felül lévő táskaikonon bárhonnan megnyitja ezt: %s, vagy ezt: %s."
L["%s an item to move it to another group, lock it so it's never sold, or sell it as junk. %s the bag icon at the top to open your %s."] = "%s egy tárgyon áthelyezi egy másik csoportba, zárolja, hogy soha ne add el, vagy szemétként eladja. %s a felül lévő táskaikonon megnyitja ezt: %s."
L["%s of %d free"] = "%s / %d szabad"
L["%s · %s of %d free"] = "%s · %s / %d szabad"
L["(drag items here)"] = "(húzz ide tárgyakat)"
L["Alts"] = "Altok"
L["Each character's bags are saved when you log out, and its bank each time you visit a banker. See them anywhere: right-click the bag icon at the top of your bags, or /dui bank. When off, Alts leaves that menu and nothing new is saved."] = "Minden karakter táskái kilépéskor mentődnek, a bankja pedig minden bankárlátogatáskor. Bárhol megnézheted őket: jobb klikk a táskáid tetején lévő táskaikonon, vagy /dui bank. Kikapcsolva az Altok kikerül abból a menüből, és semmi új nem mentődik."
L["Grid (bag by bag)"] = "Rács (táskánként)"
L["Grid (tab by tab)"] = "Rács (fülenként)"
L["Quest"] = "Küldetés"
L["Right-click"] = "Jobb klikk"
L["Right-click: your bank and alts"] = "Jobb klikk: a bankod és az altok"
L["Saved %s"] = "Mentve: %s"
L["Shelf (grouped by kind)"] = "Polc (fajta szerint csoportosítva)"
L["Shelf groups items by kind. Grid shows them bag by bag. You can also switch with the button next to the search box."] = "A Polc fajta szerint csoportosítja a tárgyakat. A Rács táskánként mutatja őket. A keresőmező melletti gombbal is válthatsz."
L["Shelf groups the bank by kind. Grid shows it tab by tab. You can also switch with the button next to the search box."] = "A Polc fajta szerint csoportosítja a bankot. A Rács fülenként mutatja. A keresőmező melletti gombbal is válthatsz."
L["Shelf groups your items by kind, with a heading for each group. Grid is one even grid, bag by bag. You can also switch with the button next to the search box. In the grid, Alt-right-click an item to keep it in its slot when you clean up."] = "A Polc fajta szerint csoportosítja a tárgyaidat, minden csoportnak fejléccel. A Rács egyetlen egyenletes rács, táskánként. A keresőmező melletti gombbal is válthatsz. A rácsban Alt+jobb klikk egy tárgyon a helyén tartja rendezéskor."
L["Shelf or grid"] = "Polc vagy rács"
L["Switch between Shelf, grouped by kind, and Grid, bag by bag."] = "Váltás a Polc (fajta szerint csoportosítva) és a Rács (táskánként) között."
L["Switch between Shelf, grouped by kind, and Grid, tab by tab."] = "Váltás a Polc (fajta szerint csoportosítva) és a Rács (fülenként) között."
L["Your whisper conversations. The number is how many have unread messages."] = "A suttogás-beszélgetéseid. A szám azt mutatja, hánynak van olvasatlan üzenete."
L["that isn't a Daylight UI or Baganator bag groups string"] = "ez nem Daylight UI- vagy Baganator-táskacsoport szöveg"
L["%s (left out: %s)"] = "%s (kimaradt: %s)"
L["items moved to %s"] = "ide áthelyezett tárgyak: %s"
L["battle pets"] = "harci háziállatok"
L["grouping by type or quality"] = "csoportosítás típus vagy minőség szerint"
L["sections and dividers"] = "szakaszok és elválasztók"
L["hidden categories"] = "rejtett kategóriák"
L["Paste bag groups (Ctrl+V), from Daylight UI or Baganator. A group with the same name as one of yours is updated; the others are added."] = "Illessz be táskacsoportokat (Ctrl+V), a Daylight UI-ból vagy a Baganatorból. Egy a tieiddel azonos nevű csoport frissül; a többi hozzáadódik."
L["Only items moved to Baganator's own categories: they go to the same groups here."] = "Csak a Baganator saját kategóriáiba áthelyezett tárgyak: itt ugyanazokba a csoportokba kerülnek."
L["Some Baganator rules have no match here. Chat lists them after you import."] = "Néhány Baganator-szabálynak itt nincs megfelelője. Importálás után a chat listázza őket."
L["Not brought over from Baganator: %s."] = "A Baganatorból nem került át: %s."
L["Bag groups someone shared, or your Baganator categories, added to yours."] = "Valaki által megosztott táskacsoportok, vagy a Baganator-kategóriáid, a tieidhez adva."
L["this game client can't read bag groups"] = "ez a játékkliens nem tud táskacsoportokat olvasni"
L["Gems"] = "Drágakövek"
L["Item enhancements"] = "Tárgyfejlesztések"
L["Battle pets"] = "Harci háziállatok"
L["Profession items"] = "Szakmai tárgyak"
L["Toys"] = "Játékok"
L["Gear by slot"] = "Felszerelés hely szerint"
L["items moved to %s, a group you deleted"] = "ide áthelyezett tárgyak: %s, egy általad törölt csoport"
L["%d items marked as junk. They'll be sold at the next vendor."] = "%d tárgy szemétnek jelölve. A következő árusnál eladásra kerülnek."
L["%d items moved to %s."] = "%d tárgy áthelyezve ide: %s."
L["Editing the text here took out its spaces, so paste it again to keep them."] = "Az itteni szövegszerkesztés kivette a szóközöket, ezért illeszd be újra, hogy megmaradjanak."
L["%.2f / %.2f s"] = "%.2f / %.2f mp"
L["%s an item to move it to another group, lock it so it's never sold, or sell it as junk. The %s and %s tabs at the top show your bank and your other characters' bags from anywhere."] = "%s egy tárgyon áthelyezi egy másik csoportba, zárolja, hogy soha ne add el, vagy szemétként eladja. A felül lévő %s és %s fül bárhonnan mutatja a bankodat és a többi karaktered táskáit."
L["/dui bug - your version, addons and setup, ready to copy into the Discord bug form"] = "/dui bug - a verziód, addonjaid és beállításod, készen a Discord-hibaűrlapba másolásra"
L["Add to \"Error text, if one popped up\""] = "Hozzáadás ide: \"Error text, if one popped up\""
L["Armor penetration"] = "Páncéláthatolás"
L["Bind"] = "Kötés"
L["Click a box and press Ctrl+C, then paste it into the Discord form."] = "Kattints egy dobozba, nyomd meg a Ctrl+C-t, aztán illeszd be a Discord-űrlapba."
L["Classic dresses every frame and window in stone and gold with red buttons, the way the game's own windows look. The angled shapes stay."] = "A Klasszikus minden keretet és ablakot kőbe és aranyba öltöztet, piros gombokkal, ahogy a játék saját ablakai kinéznek. A ferde formák maradnak."
L["Crowd control alert"] = "Tömegirányítás-riasztás"
L["Daylight UI version"] = "Daylight UI verzió"
L["Daylight: Daylight UI's own chat box, with its own tabs. Classic: the game's chat windows and tabs in the Daylight look. Switching is instant, and both keep every message. With the game's controller mode on, chat is Classic, since the game's chat windows have its controller buttons."] = "Daylight: a Daylight UI saját chatdoboza, saját fülekkel. Klasszikus: a játék chatablakai és fülei Daylight kinézetben. A váltás azonnali, és mindkettő megtart minden üzenetet. Bekapcsolt kontroller módban a chat Klasszikus, mert a játék chatablakain vannak a kontrollergombjai."
L["Destroy"] = "Megsemmisítés"
L["Each off-hand swing hits for %.0f to %.0f before armor."] = "Minden mellékkezes ütés %.0f - %.0f sebzést okoz a páncél előtt."
L["Equip"] = "Felvétel"
L["From Stamina, gear and buffs."] = "Az Állóképességből, a felszerelésből és a buffokból."
L["From your class, gear and buffs."] = "A kasztodból, a felszerelésedből és a buffokból."
L["From your gear, buffs and talents."] = "A felszerelésedből, a buffokból és a tehetségekből."
L["From your quiver, gear and buffs."] = "A tegezedből, a felszerelésedből és a buffokból."
L["Gold accent"] = "Arany kiemelés"
L["Health bars of mobs your quests still need in the color below, so they're easy to pick out of a pack. A boss or rare keeps its own color. Threat colors still show over it. Not inside instances."] = "A küldetéseidhez még szükséges mobok életerősávjai az alábbi színben, hogy könnyű legyen kiválasztani őket egy falkából. Egy boss vagy ritka megtartja a saját színét. A fenyegetésszínek fölötte is látszanak. Instance-ben nem."
L["Mobs that use mana in the color below: the ones to interrupt or pull out of line of sight. A boss, rare or quest mob keeps its own color. Threat colors still show over it."] = "A manát használó mobok az alábbi színben: azok, amiket meg kell szakítani vagy ki kell húzni a rálátásból. Egy boss, ritka vagy küldetésmob megtartja a saját színét. A fenyegetésszínek fölötte is látszanak."
L["Moves the cast time sideways from its position."] = "Oldalra tolja a varázslási időt a helyéről."
L["Moves the cast time up or down. It can sit outside the bar."] = "Fel vagy le tolja a varázslási időt. A sávon kívülre is kerülhet."
L["Moves the spell name and time sideways together while the bar sits inside the target frame."] = "Együtt oldalra tolja a varázslat nevét és idejét, amíg a sáv a célpontkereten belül ül."
L["Moves the spell name and time up or down together while the bar sits inside the target frame. They can sit outside the bar."] = "Együtt fel vagy le tolja a varázslat nevét és idejét, amíg a sáv a célpontkereten belül ül. A sávon kívülre is kerülhetnek."
L["Moves the spell name sideways from its position."] = "Oldalra tolja a varázslat nevét a helyéről."
L["Moves the spell name up or down. It can sit outside the bar."] = "Fel vagy le tolja a varázslat nevét. A sávon kívülre is kerülhet."
L["Other UI addons (bars, plates, bags...)"] = "Más felület-addonok (sávok, névtáblák, táskák...)"
L["Other bars"] = "Más sávok"
L["Page %d"] = "%d. lap"
L["Place in bags"] = "Táskákba helyezés"
L["Press the button to put it on. Hold a trigger for its bar."] = "Nyomd meg a gombot a felvételéhez. Tarts lenyomva egy ravaszt a sávjához."
L["PvP Frame"] = "PvP-keret"
L["Quest mob color"] = "Küldetésmob színe"
L["Quest mobs in their own color"] = "Küldetésmobok saját színben"
L["Read"] = "Elolvasás"
L["Report a bug"] = "Hiba jelentése"
L["Sell"] = "Eladás"
L["Spell penetration"] = "Varázslatáthatolás"
L["Tab settings"] = "Fül beállításai"
L["Talent sets"] = "Tehetségszettek"
L["Target text left / right inside the frame"] = "Célpont szövege balra / jobbra a kereten belül"
L["Target text up / down inside the frame"] = "Célpont szövege fel / le a kereten belül"
L["The alert in the middle of the screen when you're stunned, feared or silenced, as a light line in Daylight UI style. When off, the game's own alert shows instead."] = "A képernyő közepén megjelenő riasztás, amikor elkábítanak, megfélemlítenek vagy elnémítanak, világos vonalként Daylight UI stílusban. Kikapcsolva a játék saját riasztása látszik helyette."
L["The game didn't send this quest's reward choices. Close and talk to them again to pick one."] = "A játék nem küldte el ennek a küldetésnek a jutalomválasztékát. Zárd be, és beszélj vele újra, hogy választhass."
L["The health bar's color on a mob your quests still need."] = "Az életerősáv színe olyan mobnál, ami a küldetéseidhez még kell."
L["The most you can hold for your abilities."] = "A képességeidhez legfeljebb ennyit tarthatsz."
L["The spell name and time while the bar sits inside the frame, even past the power bar's height. 0 keeps each text's own size, shrinking a default one to fit the power bar."] = "A varázslat neve és ideje, amíg a sáv a kereten belül ül, akár az erőforrássáv magasságán túl is. A 0 minden szöveg saját méretét tartja meg, az alapértelmezettet az erőforrássávhoz zsugorítva."
L["To the bank"] = "A bankba"
L["To your bags"] = "A táskáidba"
L["Turns the accent color gold to match the Classic look. When off, Classic keeps your own accent color."] = "A kiemelőszínt aranyra állítja, hogy illeszkedjen a Klasszikus kinézethez. Kikapcsolva a Klasszikus megtartja a saját kiemelőszínedet."
L["What's left of the cast, or what's left out of the whole cast."] = "A varázslásból hátralévő, vagy a hátralévő az egész varázsláshoz képest."
L["You can take %.0f damage before you die."] = "%.0f sebzést bírsz ki, mielőtt meghalsz."
L["You cast %.1f%% faster."] = "%.1f%%-kal gyorsabban varázsolsz."
L["You get back %.0f mana every 5 seconds while casting."] = "%.0f manát kapsz vissza 5 másodpercenként varázslás közben."
L["You shoot %.1f%% faster."] = "%.1f%%-kal gyorsabban lősz."
