L["/dui sleepingbag - preview the sleeping bag timer"] = "/dui sleepingbag - a hálózsák-időzítő előnézete"
L["80% rather than 80, when the power text shows a percent."] = "80 helyett 80%, ha az erőforrás-szöveg százalékot mutat."
L["; works like |, so one search can list several words: ore; bar; stone"] = "A ; úgy működik, mint a |, így egy kereséssel több szót is listázhatsz: ore; bar; stone"
L["A dark tab behind the name while it sits outside the tile, like the player frame's name. When off, the name floats on its own."] = "Sötét fül a név mögött, amíg a csempén kívül ül, mint a játékoskeret neve. Kikapcsolva a név magában lebeg."
L["A small Alliance or Horde banner before each friend's character, and their faction in the tooltip."] = "Kis Szövetség- vagy Horda-zászló minden barát karaktere előtt, és a frakciója a súgóbuborékban."
L["A small dot on the bottom left corner of the gray item worth the least, so when your bag is full you know what to throw away. Its tooltip says what it sells for."] = "Kis pont a legkevesebbet érő szürke tárgy bal alsó sarkában, hogy tele táskánál tudd, mit dobj ki. A súgóbuboréka megmondja, mennyiért adható el."
L["A small switch on each letter. Tick a few and the button under the list collects only those."] = "Kis kapcsoló minden levélen. Pipálj be néhányat, és a lista alatti gomb csak azokat veszi át."
L["A sound when someone writes in guild or officer chat. Never for your own messages, and at most once every few seconds. Picking one plays it once."] = "Hang, amikor valaki céh- vagy tisztichatbe ír. A saját üzeneteidnél soha, és legfeljebb néhány másodpercenként egyszer. Kiválasztáskor egyszer lejátssza."
L["Alarm"] = "Riasztó"
L["Alliance"] = "Szövetség"
L["Between your frame and the target's"] = "A kereted és a célpontéé között"
L["Blessing"] = "Áldás"
L["Boss warning"] = "Boss-figyelmeztetés"
L["Button height"] = "Gombmagasság"
L["Carry more and the bag shows a Delete extra shards button above your money. It deletes nothing until you click it twice. At 0 it never shows."] = "Ha többet viszel, a táska egy Fölösleges szilánkok törlése gombot mutat a pénzed fölött. Semmit sem töröl, amíg kétszer nem kattintasz. 0-nál sosem látszik."
L["Cast target"] = "Varázslás célpontja"
L["Cheapest junk: %s"] = "A legolcsóbb szemét: %s"
L["Chime"] = "Csengés"
L["Class buffs share one row, then weapon, consumable, world and other buffs each start a row of their own, in the order set on the Categories page. A long row still wraps at Icons per row."] = "A kasztbuffok egy sorban osztoznak, aztán a fegyver-, fogyóeszköz-, világ- és egyéb buffok mind saját sort kezdenek, a Kategóriák oldalon beállított sorrendben. Egy hosszú sor továbbra is a Soronkénti ikonoknál tördelődik."
L["Click, then click a scroll to comprehend it. Not during a fight."] = "Kattints, majd kattints egy tekercsre a megfejtéséhez. Harc közben nem."
L["Click: open the recipe"] = "Kattintás: a recept megnyitása"
L["Collect this letter"] = "Ennek a levélnek az átvétele"
L["Collect ticked (%d)"] = "Kipipáltak átvétele (%d)"
