L["Damage meters have their own fade"] = "A sebzésmérőknek saját elhalványításuk van"
L["Deaths column"] = "Halálok-oszlop"
L["Delete 1 of %d extra shards"] = "1 törlése a(z) %d fölösleges szilánkból"
L["Delete 1 extra shard"] = "1 fölösleges szilánk törlése"
L["Deleted %d Soul Shards."] = "%d Soul Shard törölve."
L["Deleted 1 Soul Shard."] = "1 Soul Shard törölve."
L["Detached, beside the frame"] = "Leválasztva, a keret mellett"
L["Dim friends you can't play with"] = "Nem együtt játszható barátok halványítása"
L["Dispels column"] = "Levételek-oszlop"
L["Druid Resource Bars"] = "Druid erőforrássávok"
L["Each button's height as a percent of its width. 100 is square; lower makes wide, flat buttons. The icon is cropped to fit, never stretched."] = "Minden gomb magassága a szélessége százalékában. A 100 négyzet; alacsonyabbnál széles, lapos gombok. Az ikon levágódik, hogy illeszkedjen, sosem nyúlik."
L["Each name in its player's class color, or all in one color. The numbers stay as they are, so a dark bar with class-colored names reads well."] = "Minden név a játékosa kasztszínében, vagy mind egy színben. A számok maradnak, ahogy vannak, így egy sötét sáv kasztszínű nevekkel jól olvasható."
L["Each pet's health bar fills bottom to top instead of across, for tall, narrow pet bars."] = "Minden háziállat életerősávja alulról felfelé töltődik, nem keresztben, magas, keskeny háziállat-sávokhoz."
L["Each recipe shows its chance of giving a skill point, and the recipe you pick shows where it turns yellow, green and gray."] = "Minden recept mutatja, mekkora eséllyel ad jártasságpontot, a kiválasztott recept pedig azt, hol vált sárgára, zöldre és szürkére."
L["Earlier error"] = "Korábbi hiba"
L["Enemy players carrying a flag in a battleground, one frame each. Right-click one to set it as your focus."] = "Csatatéren zászlót vivő ellenséges játékosok, mindegyik saját kerettel. Jobb klikk egyen fókusznak állítja."
L["Enemy target page"] = "Ellenséges célpont lapja"
L["Execute icon"] = "Végzésikon"
