L["Execute icon position"] = "Végzésikon helye"
L["Execute icon up / down"] = "Végzésikon fel / le"
L["Experience bar orientation"] = "Tapasztalatsáv tájolása"
L["Faction"] = "Frakció"
L["Faction icons"] = "Frakcióikonok"
L["Fill"] = "Kitöltés"
L["Focus Portrait"] = "Fókusz portréja"
L["Focus Power Bar"] = "Fókusz erőforrássávja"
L["Focus cast bar layer"] = "Fókusz varázslássávjának rétege"
L["Focus target"] = "Fókusz célpontja"
L["Free slots"] = "Szabad helyek"
L["Friendly target page"] = "Barátságos célpont lapja"
L["Friends in another game or on another ruleset show dimmed, like the ones who are offline."] = "A másik játékban vagy más szabályrendszeren lévő barátok halványítva látszanak, mint az offline-ok."
L["Full charge"] = "Teljes töltés"
L["Fully rested"] = "Teljesen kipihent"
L["General and Trade first"] = "General és Trade elöl"
L["Group focus mark"] = "Csoportfókusz-jel"
L["Group's"] = "A csoporté"
L["Guild chat sound"] = "Céhchat hangja"
L["HPS column"] = "HPS-oszlop"
L["Healing and power"] = "Gyógyítás és erőforrás"
L["Healing column"] = "Gyógyítás-oszlop"
L["Horde"] = "Horda"
L["Horizontal"] = "Vízszintes"
L["How big the role icon is. With the name or portrait it fits there until you change this."] = "Mekkora a szerepikon. A névvel vagy a portréval odaillik, amíg ezt nem módosítod."
L["How many of an item fit in one bag slot (\"Stacks to 20\"), on items that stack."] = "Hány darab fér egy tárgyból egy táskahelyre (\"Stacks to 20\"), halmozható tárgyakon."
L["How tall each pet bar is. It can be as tall as a party frame, for a narrow pet bar standing beside each member."] = "Milyen magas minden háziállat-sáv. Lehet olyan magas, mint egy csoportkeret, keskeny, minden tag mellett álló háziállat-sávhoz."
L["How tall the combo point pips under the personal display are. Set to 0 for automatic height."] = "Milyen magasak a kombópont-jelölők a személyes kijelző alatt. A 0 automatikus magasságot ad."
L["How wide each combo point pip under the personal display is. Not while the pips match the display's width."] = "Milyen széles minden kombópont-jelölő a személyes kijelző alatt. Nem, amíg a jelölők a kijelző szélességéhez igazodnak."
L["Icons stay on the frame"] = "Az ikonok a kereten maradnak"
L["In a group, each enemy's plate takes the size of its threat state, so the mobs that need you stand out. Made for tanks: small while you hold a mob, big once it's on someone else. Your target keeps its own size. Works with Threat colors on or off."] = "Csoportban minden ellenség névtáblája a fenyegetési állapota szerinti méretet kapja, így kiugranak azok a mobok, amiknek rád van szükségük. Tankoknak készült: kicsi, amíg tartod a mobot, nagy, ha már valaki máson van. A célpontod megtartja a saját méretét. A Fenyegetésszínek be- vagy kikapcsolt állapotában is működik."
L["In a party or raid, a double arrow in your accent color over the enemy most of your group is targeting, so you can follow the kill target. Needs at least two of you on it. Battlegrounds and arenas hide who's targeting what, so it doesn't show there."] = "Csoportban vagy raidben egy dupla nyíl a kiemelőszínedben afölött az ellenség fölött, akit a csoportod többsége célba vett, így követheted a fő célpontot. Legalább kettőtöknek kell rajta lennie. A csatatereken és arénákban a játék elrejti, ki kit vesz célba, ezért ott nem látszik."
L["Inside the frame it covers the power bar (in the Ribbon style, or with power bars off, it slides out under the frame instead). Under the frame it slides out during a cast: give it room with the party's spacing. Detached, it's a bar you size here, beside each frame."] = "A kereten belül eltakarja az erőforrássávot (Szalag stílusban vagy kikapcsolt erőforrássávoknál inkább a keret alól csúszik ki). A keret alatt varázslás közben kicsúszik: adj neki helyet a csoport térközével. Leválasztva egy itt méretezett sáv minden keret mellett."
L["Inside the frame it covers the power bar, as wide as it (in the Ribbon style it sits below the frame instead). Above, below or on its own it's a bar you size here; on its own you move it in unlock mode. Under the frame it slides out during a cast, and the buffs below keep room for it."] = "A kereten belül eltakarja az erőforrássávot, annak szélességében (a Szalag stílusban inkább a keret alatt ül). Fölötte, alatta vagy önállóan egy sáv, aminek itt állítod a méretét; önállóan feloldott módban mozgatod. A keret alatt varázslás közben kicsúszik, és az alatta lévő buffok helyet hagynak neki."
L["Interrupt ready mark"] = "Megszakítás kész jel"
L["Interrupts column"] = "Megszakítások-oszlop"
L["Keep at most this many Soul Shards"] = "Legfeljebb ennyi Soul Shard megtartása"
L["Keep at most this many Soul Shards in a raid"] = "Legfeljebb ennyi Soul Shard megtartása raidben"
L["Keeps the name inside the bar. When off, it sits in a small tab above the frame, like the other frames' names."] = "A nevet a sávon belül tartja. Kikapcsolva egy kis fülben ül a keret fölött, mint a többi keret neve."
L["Later error"] = "Későbbi hiba"
L["Level font"] = "Szint betűtípusa"
L["Levels beside names"] = "Szintek a nevek mellett"
L["Main Hand Swing Timer"] = "Főkéz ütésidőzítője"
L["Mark the cheapest junk"] = "A legolcsóbb szemét jelölése"
L["Meter windows"] = "Mérőablakok"
L["Minimap shape"] = "Minitérkép alakja"
L["Normal"] = "Normál"
L["Notices"] = "Értesítések"
L["Nudges the personal display's row of combo points sideways."] = "Oldalra tolja a személyes kijelző kombópont-sorát."
L["Nudges the personal display's row of combo points up or down. Docked cast and swing bars stay below it."] = "Fel vagy le tolja a személyes kijelző kombópont-sorát. A dokkolt varázslás- és ütéssávok alatta maradnak."
L["Off Hand Swing Timer"] = "Mellékkéz ütésidőzítője"
L["On its own, the portrait leaves the frame and you can move it anywhere in unlock mode. The frame is then all bars."] = "Önállóan a portré elhagyja a keretet, és feloldott módban bárhová mozgathatod. A keret ekkor csupa sáv."
L["On the Training page, a weapon skill's tooltip names each weapon master's city and district, not just their name."] = "A Tanulás oldalon egy fegyverjártasság súgóbuboréka minden fegyvermester városát és negyedét is megnevezi, nem csak a nevét."
L["Open Clique"] = "Clique megnyitása"
L["Overshield"] = "Túlpajzs"
L["Personal display layer"] = "Személyes kijelző rétege"
L["Pets fill upward"] = "A háziállatok felfelé töltődnek"
L["Plate size by threat"] = "Névtábla mérete fenyegetés szerint"
L["Play guild chat sound"] = "Céhchat hangjának lejátszása"
L["Player Portrait"] = "Játékos portréja"
L["Plays once as the buff lands, like Clearcasting or Nightfall."] = "Egyszer lejátszódik, amikor a buff felkerül, mint a Clearcasting vagy a Nightfall."
L["Plays once as the buff runs out or is used up, like a Seal, so you can hear it's time to cast it again."] = "Egyszer lejátszódik, amikor a buff lejár vagy elhasználódik, mint egy Seal, így hallod, hogy ideje újra felrakni."
L["Plays once as the spell comes off cooldown, never on the global cooldown."] = "Egyszer lejátszódik, amikor a varázslat cooldownja lejár, a globális cooldownnál soha."
L["Plays once as you become able to cast it: Revenge after a block, Overpower after a dodge, Execute on a low target. Rage or mana coming back doesn't count."] = "Egyszer lejátszódik, amikor elvarázsolhatóvá válik: Revenge blokk után, Overpower kitérés után, Execute alacsony életerejű célponton. A visszatérő düh vagy mana nem számít."
L["Plays the guild chat sound picked above."] = "Lejátssza a fent kiválasztott céhchat-hangot."
L["Portrait position"] = "Portré helye"
L["Power (2,300)"] = "Erőforrás (2,300)"
L["Preview the sleeping bag timer"] = "A hálózsák-időzítő előnézete"
L["Raid warning"] = "Raid-figyelmeztetés"
L["Ranged Swing Timer"] = "Távolsági ütésidőzítő"
L["Rank up"] = "Rangemelés"
L["Remove Favorite"] = "Kedvenc eltávolítása"
L["Replaces the picked bar's size, text and look with the one above's. Whether it's detached and where it sits stay."] = "A kiválasztott sáv méretét, szövegét és kinézetét a fentiére cseréli. Hogy le van-e választva, és hol ül, marad."
L["Reputation bar orientation"] = "Hírnévsáv tájolása"
L["Reverse"] = "Fordított"
L["Right-click: stop tracking"] = "Jobb klikk: követés leállítása"
L["Round"] = "Kerek"
L["Round gives the map a thin ring with N at the top. While Rotate as you turn is on, the map is always round."] = "A Kerek vékony gyűrűt ad a térképnek, felül N betűvel. Amíg a Forgás a fordulással be van kapcsolva, a térkép mindig kerek."
L["Same game"] = "Ugyanaz a játék"
L["Second Chat Panel"] = "Második chatpanel"
L["Set Favorite"] = "Kedvencnek jelölés"
L["Shadowform page"] = "Shadowform-lap"
L["Shows it now; move to end it. Also /dui sleepingbag."] = "Most megmutatja; mozdulj a befejezéshez. A /dui sleepingbag is ezt teszi."
L["Skill-up chance"] = "Jártasságnövekedés esélye"
L["Skill-up range"] = "Jártasságnövekedés tartománya"
L["Sleeping bag timer"] = "Hálózsák-időzítő"
L["Soft bell"] = "Lágy harang"
L["Soul bag size"] = "Lélektáska mérete"
L["Sound when usable"] = "Hang, ha használható"
L["Spare page 10"] = "10. tartaléklap"
L["Spare page 11"] = "11. tartaléklap"
L["Spare page 12"] = "12. tartaléklap"
L["Spare page 2"] = "2. tartaléklap"
L["Spare page 7"] = "7. tartaléklap"
L["Spare page 8"] = "8. tartaléklap"
L["Spare page 9"] = "9. tartaléklap"
L["Spreads the combo point pips across the personal display. Turn it off to set the pips' own width."] = "Szétteríti a kombópont-jelölőket a személyes kijelzőn. Kapcsold ki, ha a jelölők saját szélességét állítanád."
L["Stack size"] = "Halomméret"
L["Stacks to %s"] = "%s darabig halmozható"
L["Start corner"] = "Kezdősarok"
L["Swell"] = "Duzzadás"
L["Swing timer layer"] = "Ütésidőzítő rétege"
L["Target Portrait"] = "Célpont portréja"
L["Target Power Bar"] = "Célpont erőforrássávja"
L["Target Threat %"] = "Célpont fenyegetés %"
L["Target cast bar layer"] = "Célpont varázslássávjának rétege"
L["The corner the first button sits in. The buttons fill away from it, row by row (column by column on a vertical bar). Bottom left with 3 buttons a row puts 1, 2, 3 along the bottom, like a side-button mouse."] = "A sarok, ahol az első gomb ül. A gombok tőle távolodva töltődnek, soronként (függőleges sávnál oszloponként). Bal alul, soronként 3 gombbal az 1, 2, 3 alul sorakozik, mint egy oldalgombos egéren."
L["The empty part of the bar, behind the fill. General uses your player frame's, or the one on General > Appearance when that has none."] = "A sáv üres része a kitöltés mögött. Az Általános a játékoskereted sajátját használja, vagy ha annak nincs, az Általános > Megjelenését."
L["The empty part of the party's cast bars, behind the fill. General uses the bar background on General > Appearance."] = "A csoport varázslássávjainak üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The empty part of the power bar on the nameplates, behind the fill. General uses the bar background on General > Appearance."] = "Az erőforrássáv üres része a névtáblákon, a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The fill of the bar. General uses your player frame's, or the one on General > Appearance when that has none."] = "A sáv kitöltése. Az Általános a játékoskereted sajátját használja, vagy ha annak nincs, az Általános > Megjelenését."
L["The fill of the party's cast bars. General uses the bar texture on General > Appearance."] = "A csoport varázslássávjainak kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The fill of the power bar on the nameplates. General uses the bar texture on General > Appearance."] = "Az erőforrássáv kitöltése a névtáblákon. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The gap between one PvP frame and the next."] = "Rés két PvP-keret között."
L["The layer the personal display draws in. Low keeps it under your other frames. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = "A réteg, amibe a személyes kijelző rajzolódik. Az Alacsony a többi kereted alatt tartja. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["The layer the swing timer draws in when detached, as a group or a bar on its own. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue. Hung under the player frame or the cast bar, it draws with them instead."] = "A réteg, amibe az ütésidőzítő rajzolódik leválasztva, csoportként vagy önálló sávként. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue. A játékoskeret vagy a varázslássáv alá akasztva inkább velük együtt rajzolódik."
L["The layer your cast bar draws in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue. Under the frame, between the frames or under the personal display, it draws with the frame instead."] = "A réteg, amibe a varázslássávod rajzolódik. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue. A keret alatt, a keretek között vagy a személyes kijelző alatt inkább a kerettel együtt rajzolódik."
L["The layer your focus's cast bar draws in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue. Inside the frame, it draws with the frame instead."] = "A réteg, amibe a fókuszod varázslássávja rajzolódik. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue. A kereten belül inkább a kerettel együtt rajzolódik."
L["The layer your target's cast bar draws in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue. Inside the frame or sliding out under it, it draws with the frame instead."] = "A réteg, amibe a célpontod varázslássávja rajzolódik. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue. A kereten belül vagy alóla kicsúszva inkább a kerettel együtt rajzolódik."
L["The level number on the nameplates. General uses the health text font."] = "A szintszám a névtáblákon. Az Általános az életerő-szöveg betűtípusát használja."
L["The names' color when Name color is One color."] = "A nevek színe, ha a Névszín Egy szín."
L["The number on the bar. General uses your player frame's, or the one on General > Appearance when that has none."] = "A szám a sávon. Az Általános a játékoskereted sajátját használja, vagy ha annak nincs, az Általános > Megjelenését."
L["The plate's size while the mob is about to switch targets."] = "A névtábla mérete, amíg a mob mindjárt célpontot vált."
L["The plate's size while the mob is attacking you."] = "A névtábla mérete, amíg a mob téged támad."
L["The plate's size while the mob is in the fight but attacking someone else."] = "A névtábla mérete, amíg a mob harcban van, de valaki mást támad."
L["The quest tracker's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "A küldetéskövető helyét a játék Szerkesztő módja tárolja, és saját Szerkesztő mód elrendezést használsz: ott mozgasd (Esc > Edit Mode)."
L["The same, while you're in a raid, where you may want more on hand. At 0 it never shows in a raid."] = "Ugyanez raidben, ahol lehet, hogy többet akarsz kéznél tartani. 0-nál raidben sosem látszik."
L["The threat number. General uses this frame's health text font."] = "A fenyegetésszám. Az Általános ennek a keretnek az életerő-szöveg betűtípusát használja."
L["Threat size: about to switch"] = "Fenyegetésméret: mindjárt vált"
L["Threat size: attacking you"] = "Fenyegetésméret: téged támad"
L["Threat size: not attacking you"] = "Fenyegetésméret: nem téged támad"
L["Threat tag font"] = "Fenyegetéscímke betűtípusa"
L["Threat: about to switch gradient"] = "Fenyegetés: mindjárt vált színátmenet"
L["Threat: attacking you gradient"] = "Fenyegetés: téged támad színátmenet"
L["Threat: not attacking you gradient"] = "Fenyegetés: nem téged támad színátmenet"
L["Tick letters and the button under the list takes only those. Shift-click a letter to take everything in it."] = "Pipálj be leveleket, és a lista alatti gomb csak azokat veszi át. Shift+kattintás egy levélen mindent átvesz belőle."
L["Tick letters to collect"] = "Pipáld be az átveendő leveleket"
L["Track Recipe"] = "Recept követése"
L["Turn the Focus Target frame on or off."] = "A fókusz célpontja keret be- vagy kikapcsolása."
L["Turn the PvP frames on or off. When off, the game shows its own after a reload."] = "A PvP-keretek be- vagy kikapcsolása. Kikapcsolva a játék a sajátjait mutatja újratöltés után."
L["Use the game's experience bar instead"] = "A játék tapasztalatsávjának használata helyette"
L["Vertical"] = "Függőleges"
L["Vertical stands the bar upright, filling from the bottom to the top. Its width is then how tall it stands, and its height how thick."] = "A Függőleges felállítja a sávot, alulról felfelé töltődve. A szélessége ekkor azt jelenti, milyen magasan áll, a magassága pedig, milyen vastag."
L["Vertical stands the separate bar upright, filling from the bottom to the top. Its width is then how tall it stands, and its height how thick."] = "A Függőleges felállítja a külön sávot, alulról felfelé töltődve. A szélessége ekkor azt jelenti, milyen magasan áll, a magassága pedig, milyen vastag."
L["Warlocks: the Soul Shards text shows how many your soul bag holds beside the count, and its tooltip the free slots."] = "Warlockok: a Soul Shards szöveg a darabszám mellett azt is mutatja, mennyi fér a lélektáskádba, a súgóbuboréka pedig a szabad helyeket."
L["When another addon joins its own channels before General and Trade, they take /1 and /2. This puts General, Trade and the other world channels back on the first numbers."] = "Ha egy másik addon a General és a Trade előtt lép be a saját csatornáiba, azok kapják a /1-et és a /2-t. Ez a General, a Trade és a többi világcsatornát visszateszi az első számokra."
L["Where the leader crown sits: with the name tab or portrait (in a corner when the frame has neither), or any spot on or around the frame."] = "Hol ül a vezetői korona: a névfüllel vagy a portréval (sarokban, ha a keretnek egyik sincs), vagy bármely helyen a kereten vagy körülötte."
L["Where the raid marker sits: with the name tab or portrait (in a corner when the frame has neither), or any spot on or around the frame."] = "Hol ül a raidjelölő: a névfüllel vagy a portréval (sarokban, ha a keretnek egyik sincs), vagy bármely helyen a kereten vagy körülötte."
L["Where the role icon sits: with the name tab or portrait (in a corner when the frame has neither), or any spot on or around the frame."] = "Hol ül a szerepikon: a névfüllel vagy a portréval (sarokban, ha a keretnek egyik sincs), vagy bármely helyen a kereten vagy körülötte."
L["Which page of buttons this bar shows in Shadowform. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv Shadowformban. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Which page of buttons this bar shows while your target is friendly. Your keybinds cast what the bar shows. No change keeps the bar's own buttons. A held key's page comes first, then this one, then your stance or form."] = "Melyik gomblapot mutatja ez a sáv, amíg a célpontod barátságos. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg. A nyomva tartott gomb lapja jön előbb, aztán ez, aztán a tartásod vagy formád."
L["Which page of buttons this bar shows while your target is one you can attack. Your keybinds cast what the bar shows. No change keeps the bar's own buttons. A held key's page comes first, then this one, then your stance or form."] = "Melyik gomblapot mutatja ez a sáv, amíg a célpontod megtámadható. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg. A nyomva tartott gomb lapja jön előbb, aztán ez, aztán a tartásod vagy formád."
L["While you rest in a sleeping bag, a timer near the bottom of the screen counts down until Well-Rested is full (one stack a minute, three in all), so you can see it with your UI faded at the campfire."] = "Amíg hálózsákban pihensz, egy időzítő a képernyő alja közelében visszaszámol, amíg a Well-Rested be nem telik (percenként egy halom, összesen három), így a tábortűznél elhalványított felülettel is látod."
L["While your interrupt is on cooldown, a thin line on an enemy target's or focus's cast bar shows where it comes back. No line: it's ready now, or it won't be back before the cast ends."] = "Amíg a megszakításod cooldownon van, egy vékony vonal egy ellenséges célpont vagy fókusz varázslássávján mutatja, hol jön vissza. Nincs vonal: most kész, vagy nem jön vissza a varázslás vége előtt."
L["While your interrupt is on cooldown, a thin line on an enemy's cast bar shows where it comes back. No line: it's ready now, or it won't be back before the cast ends."] = "Amíg a megszakításod cooldownon van, egy vékony vonal egy ellenség varázslássávján mutatja, hol jön vissza. Nincs vonal: most kész, vagy nem jön vissza a varázslás vége előtt."
L["Who an enemy's spell is aimed at, in their class color, on the right of its cast bar. Spells with no one target (an area spell, a self heal) show none."] = "Kire irányul egy ellenség varázslata, a kasztszínében, a varázslássávjától jobbra. A célpont nélküli varázslatoknál (területi varázslat, öngyógyítás) nem látszik semmi."
L["With the mouse over it"] = "Amíg rajta van az egér"
L["With the name or portrait"] = "A névvel vagy a portréval"
L["Yellow from %s, green from %s, gray from %s. Orange recipes always give a point; yellow ones usually, green ones sometimes, gray ones never."] = "Sárga ettől: %s, zöld ettől: %s, szürke ettől: %s. A narancs receptek mindig adnak pontot; a sárgák általában, a zöldek néha, a szürkék soha."
L["You: %s"] = "Te: %s"
L["[60] before a player's name, for anyone in your group, guild or friends list, found with /who, or you've targeted or moused over. Someone you haven't seen yet shows no level."] = "[60] egy játékos neve előtt bárkinél, aki a csoportodban, céhedben vagy barátlistádon van, akit /who-val találtál, vagy akit célba vettél vagy fölé vitted az egeret. Akit még nem láttál, annál nincs szint."
L["%s (drag items here)"] = "%s (húzz ide tárgyakat)"
L["%s an item to move it to another group, lock it so it's never sold, or sell it as junk. %s at the top shows your bank and your other characters' bags from anywhere."] = "%s egy tárgyon áthelyezi egy másik csoportba, zárolja, hogy soha ne add el, vagy szemétként eladja. A felül lévő %s bárhonnan mutatja a bankodat és a többi karaktered táskáit."
L["Categories or bags"] = "Kategóriák vagy táskák"
L["Switch between items grouped by kind and the plain bag-by-bag grid."] = "Váltás a fajta szerint csoportosított tárgyak és a sima, táskánkénti rács között."
L["Switch between items grouped by kind and the plain tab-by-tab grid."] = "Váltás a fajta szerint csoportosított tárgyak és a sima, fülenkénti rács között."
L["Your bank and your other characters' bags, from anywhere."] = "A bankod és a többi karaktered táskái, bárhonnan."
L[" A held key's page comes first, then this one, then your stance or form."] = " A nyomva tartott gomb lapja jön előbb, aztán ez, aztán a tartásod vagy formád."
L[" Hidden (in combat, out of combat or always): gone, and its buttons can't be clicked."] = " Rejtett (harcban, harcon kívül vagy mindig): eltűnik, és a gombjai nem kattinthatók."
L[" Hung under the player frame or the cast bar, it draws with them instead."] = " A játékoskeret vagy a varázslássáv alá akasztva inkább velük együtt rajzolódik."
L[" Inside the frame or sliding out under it, it draws with the frame instead."] = " A kereten belül vagy alóla kicsúszva inkább a kerettel együtt rajzolódik."
L[" Inside the frame, it draws with the frame instead."] = " A kereten belül inkább a kerettel együtt rajzolódik."
L[" Under the frame, between the frames or under the personal display, it draws with the frame instead."] = " A keret alatt, a keretek között vagy a személyes kijelző alatt inkább a kerettel együtt rajzolódik."
L[" Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = " Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["%d ranks"] = "%d rang"
L["%s (in Russian: %s)"] = "%s (oroszul: %s)"
L["%s and %s both want to change %s; %s keeps it."] = "A(z) %s és a(z) %s is módosítani akarja ezt: %s; a(z) %s tartja meg."
L["%s: a bag group needs a key, a label and a match function."] = "%s: egy táskacsoporthoz kulcs, felirat és egyeztető függvény kell."
L["%s: a buff category needs a key, a label and a list of spell ids."] = "%s: egy buff-kategóriához kulcs, felirat és varázslatazonosító-lista kell."
L["%s: a data panel needs a key and a frame."] = "%s: egy adatpanelhez kulcs és keret kell."
L["%s: a data text needs a key, a label and a text function."] = "%s: egy adatszöveghez kulcs, felirat és szövegfüggvény kell."
L["%s: an aura filter needs a key, a label and a list of spell ids."] = "%s: egy aura-szűrőhöz kulcs, felirat és varázslatazonosító-lista kell."
L["%s: the game doesn't let aura filter %s pick out any of its spells on group members."] = "%s: a játék nem engedi, hogy a(z) %s aura-szűrő kiválassza bármelyik varázslatát a csoporttagokon."
L["%s: the setup step was left out (%s)."] = "%s: a beállítási lépés kimaradt (%s)."
L["%s: tooltip lines need a kind (unit, item, spell, world or compare) and a function."] = "%s: a súgóbuborék-sorokhoz fajta (unit, item, spell, world vagy compare) és függvény kell."
L["1 item marked as junk. It'll be sold at the next vendor."] = "1 tárgy szemétnek jelölve. A következő árusnál eladásra kerül."
L["1 item moved to %s."] = "1 tárgy áthelyezve ide: %s."
L["A friendly totem shows as a small round badge with its picture, ringed in its element's color, instead of its long name."] = "Egy barátságos totem kis kerek jelvényként látszik a képével, az eleme színében gyűrűzve, a hosszú neve helyett."
L["A hide list leaves its spells off every aura row that picks it; Hidden is picked everywhere until you change it. A show-only list makes a row show nothing else. Each frame's Buffs and Debuffs cards pick the lists they use."] = "Egy elrejtőlista kihagyja a varázslatait minden aurasorból, amelyik kiválasztja; a Rejtett mindenhol ki van választva, amíg nem módosítod. A csak-mutató lista mellett egy sor semmi mást nem mutat. Minden keret Buffok és Debuffok kártyája választja ki a használt listákat."
L["A line on enemy health bars where your finishing moves start to work. The bar's end up to it lights up in your accent color once the enemy is that low. Your class: warriors (Execute) and paladins (Hammer of Wrath)."] = "Egy vonal az ellenséges életerősávokon ott, ahol a befejező mozdulataid elkezdenek működni. A sáv vége eddig a kiemelőszínedben világít, amint az ellenség ennyire lement. Kasztod: harcosok (Execute) és paladinok (Hammer of Wrath)."
L["A list of spells an aura row shows on its own, leaving everything else off."] = "Varázslatok listája, amit egy aurasor egyedül mutat, minden mást kihagyva."
L["A list of spells to leave off the aura rows that pick it."] = "Varázslatok listája, amit kihagynak az azt kiválasztó aurasorok."
L["A marker and breadcrumbs to your quest."] = "Jelölő és nyomvonal a küldetésedhez."
L["A ring over the outer end. Class icons show for players; NPCs show their face. Needs a frame at least "] = "Gyűrű a külső végén. Játékosoknál kasztikon, NPC-knél az arcuk. Ennyi magas keret kell hozzá legalább: "
L["A round ring, a square, or a square with its outer side angled like the frame's end. The aggro fill, arrival light and elite frame follow the shape."] = "Kerek gyűrű, négyzet, vagy négyzet, aminek a külső oldala a keret végéhez hasonlóan ferde. Az aggró-kitöltés, az érkezési fény és az elit keret az alakot követik."
L["A small frame beside each party member showing who they're targeting."] = "Kis keret minden csoporttag mellett, ami mutatja, kit vesz célba."
L["A soft light round the "] = "Lágy fény körben: "
L["A spell's name or ID"] = "Egy varázslat neve vagy azonosítója"
L["A square filled with the mood's color, or the pet's mood face edged in it."] = "Egy négyzet a hangulat színével kitöltve, vagy a háziállat hangulatarca ilyen színű szegéllyel."
L["A square filled with the mood's color, or the pet's mood face."] = "Egy négyzet a hangulat színével kitöltve, vagy a háziállat hangulatarca."
L["A swirl on a member who's being summoned: in your accent while they decide, green once they accept, red if they decline."] = "Örvény az idézett tagon: a kiemelőszínedben, amíg dönt, zöld, ha elfogadta, piros, ha elutasította."
L["A thin ring just outside the cursor's runs down after each spell, so you see when the next one is ready."] = "Egy vékony gyűrű közvetlenül a kurzoré körül minden varázslat után lefut, így látod, mikor kész a következő."
L["Accepting this quest will flag you for PvP. Accept anyway?"] = "Ennek a küldetésnek az elfogadása PvP-jelzést ad neked. Mégis elfogadod?"
L["Add a spell"] = "Varázslat hozzáadása"
L["Adds %d data panel."] = "%d adatpanelt ad hozzá."
L["Adds %d data panels."] = "%d adatpanelt ad hozzá."
L["Adds %d data text."] = "%d adatszöveget ad hozzá."
L["Adds %d data texts."] = "%d adatszöveget ad hozzá."
L["All buffs"] = "Minden buff"
L["Amount"] = "Mennyiség"
L["Arrow to nearby gathering nodes"] = "Nyíl a közeli gyűjtőhelyekhez"
L["Aura Lists"] = "Auralisták"
L["Bag Bar"] = "Táskasáv"
L["Band: the bar's end up to the line lights up. Line only: just the line. Whole bar: the whole health bar lights up. Band, breathing: the band, gently pulsing."] = "Sáv: a sáv vége a vonalig kivilágosodik. Csak vonal: csak a vonal. Egész sáv: az egész életerősáv kivilágosodik. Sáv, lélegző: a sáv, finoman lüktetve."
L["Bar 1: page %d (the game's bar 1: %s, ActionButton1: %s, ours: %s); the game would pick %s: %s"] = "1. sáv: %d. lap (a játék 1. sávja: %s, ActionButton1: %s, a miénk: %s); a játék ezt választaná: %s: %s"
L["Before step 1:"] = "Az 1. lépés előtt:"
L["Big defensive left / right"] = "Nagy védekező balra / jobbra"
L["Big defensive position"] = "Nagy védekező helye"
L["Big defensive up / down"] = "Nagy védekező fel / le"
L["Big defensives"] = "Nagy védekezők"
L["Bonus bar offset: "] = "Bónuszsáv eltolása: "
L["Buff bar"] = "Buff-sáv"
L["Buff filter"] = "Buff-szűrő"
L["CC Alert"] = "Tömegirányítás-riasztás"
L["Can be sold again."] = "Újra eladható."
L["Carry Offered"] = "Felajánlott cipelés"
L["Change how it works"] = "Működés módosítása"
L["Change your raid frames' auras and name to the "] = "A raidkereteid auráinak és nevének módosítása erre: "
L["Chests, quest objects and your fishing bobber light up as you come near, dim from afar and bright once you can reach them. This changes a few of the game's interact settings while it's on, and gives them back when it's off."] = "A ládák, küldetéstárgyak és a horgászúszód felvillannak, ahogy közeledsz, messziről halványan, elérhető távolságban erősen. Amíg be van kapcsolva, a játék néhány interakciós beállítását módosítja, és kikapcsoláskor visszaadja őket."
L["Click"] = "Kattintás"
L["Click a spell on screen, press a %s on one of its sides and pick another spell: it hooks on there. A group moves as one and shares its look, so drag any of its spells to move them all."] = "Kattints egy varázslatra a képernyőn, nyomj meg egy %s gombot az egyik oldalán, és válassz másik varázslatot: oda akad. Egy csoport egyben mozog és közös a kinézete, így bármelyik varázslatát húzva mindet mozgatod."
L["Click a spell to open its card. %s: size, border and text. %s: what it does when it's ready, on cooldown, or when its buff is up or missing, like a glow, a fade or a sound. %s: where the group sits and which way it grows."] = "Kattints egy varázslatra a kártyája megnyitásához. %s: méret, keret és szöveg. %s: mit csinál, amikor kész, cooldownon van, vagy amikor a buffja fent van vagy hiányzik, például fény, halványítás vagy hang. %s: hol ül a csoport, és merre nő."
L["Click: switch to the game's window"] = "Kattintás: váltás a játék ablakára"
L["Combo point"] = "Kombópont"
L["Cooldown bar"] = "Cooldown-sáv"
L["Cooldowns"] = "Cooldownok"
L["Couldn't read the talents."] = "Nem sikerült beolvasni a tehetségeket."
L["Count"] = "Darabszám"
L["Crowd control grow direction"] = "Tömegirányítás növekedési iránya"
L["Custom "] = "Egyedi "
L["Data bar "] = "Adatsáv "
L["Data text slot "] = "Adatszöveg-hely "
L["Daylight UI %s. Game plates %d, ours %d, spare %d, hidden by platefps=%s"] = "Daylight UI %s. Játék névtáblái %d, mieink %d, tartalék %d, platefps által rejtve=%s"
L["Daylight UI's own icons, the Classic class icons, or with the Jiberish Fabled Icons addon installed, its Fabled styles (art by JiberishUI and its artists, read from that addon's own folder)."] = "A Daylight UI saját ikonjai, a Classic kasztikonok, vagy telepített Jiberish Fabled Icons addonnal annak Fabled stílusai (a grafika a JiberishUI és alkotóié, az addon saját mappájából olvasva)."
L["Daylight UI's quest tracker"] = "A Daylight UI küldetéskövetője"
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it."] = "Daylight: a keret a nevével egy fülben fölötte, benne az erőforrássávval. Szalag: vékony sáv, fölötte lebeg a név és az életerő, alatta vékony vonalként az erőforrás."
L["Debuff bar"] = "Debuff-sáv"
L["Debuffs on this list never show here. The game only lets addons hide a few harmless debuffs on you and your group, like Sated; the Aura Lists page marks which. Make and fill lists on Unit Frames > Aura Lists."] = "Az ezen a listán lévő debuffok itt sosem látszanak. A játék csak néhány ártalmatlan debuff elrejtését engedi az addonoknak rajtad és a csoportodon, például a Sated-ét; az Auralisták oldal jelöli, melyeket. Listákat az Egységkeretek > Auralisták alatt készíthetsz és tölthetsz fel."
L["Delete this list"] = "Ennek a listának a törlése"
L["Deletes the list picked above; rows that used it then use none. Hidden and Watch list are only emptied."] = "Törli a fent kiválasztott listát; az azt használó sorok ezután egyiket sem használják. A Rejtett és a Figyelőlista csak kiürül."
L["Detach the "] = "Leválasztás: "
L["Disp."] = "Lev."
L["Do you really want to unlearn %s?"] = "Biztosan elfelejted ezt: %s?"
L["DoT skull grow direction"] = "DoT-koponya növekedési iránya"
L["Each talent set has its own layout: click it up here to switch. %s brings in a layout from the game's Cooldown Manager. Everything saves as you go, and %s shows this tour again."] = "Minden tehetségszettnek saját elrendezése van: itt fent kattints rá a váltáshoz. A(z) %s behoz egy elrendezést a játék Cooldown-kezelőjéből. Minden menet közben mentődik, és a(z) %s újra megmutatja ezt a bemutatót."
L["Edit a list"] = "Lista szerkesztése"
L["Empty slot"] = "Üres hely"
L["Enemy plates fade while your class's attacks can't reach them: casters by their main spell, melee by their strikes, hunters by their shots and melee strikes. Your target and a plate that's casting stay full."] = "Az ellenséges névtáblák elhalványulnak, amíg a kasztod támadásai nem érik el őket: a varázslók a fő varázslatuk szerint, a közelharcosok az ütéseik szerint, a vadászok a lövéseik és közelharci ütéseik szerint. A célpontod és a varázsló névtábla teljesen látszik."
L["Enemy target"] = "Ellenséges célpont"
L["Every buff on your pet, or only the ones you cast on it."] = "Minden buff a háziállatodon, vagy csak az általad rárakottak."
L["Every buff, only the ones your class can take off an enemy, or only the ones you cast. A class that can't purge shows none with the second."] = "Minden buff, csak azok, amiket a kasztod le tud venni egy ellenségről, vagy csak az általad rakottak. Levételre képtelen kasztnál a második semmit sem mutat."
L["Every debuff on you, or only the ones your class can remove."] = "Minden debuff rajtad, vagy csak azok, amiket a kasztod le tud venni."
L["Every debuff on your pet, or only the ones your class can remove."] = "Minden debuff a háziállatodon, vagy csak azok, amiket a kasztod le tud venni."
L["Every line in the tooltips"] = "A súgóbuborékok minden sora"
L["Every text in the loot feed"] = "A zsákmánysáv minden szövege"
L["Every text in the quest tracker"] = "A küldetéskövető minden szövege"
L["Extra aura group "] = "Extra auracsoport "
L["Extra text "] = "Extra szöveg "
L["Fade out of range enemies"] = "Hatótávon kívüli ellenségek halványítása"
L["Fades only while "] = "Csak akkor halványul el, ha "
L["Fades only while your mana is full; stays while it refills after a spell or a fight. Does nothing while your bar shows rage or energy."] = "Csak teli manánál halványul el; marad, amíg egy varázslat vagy harc után újratöltődik. Semmit sem csinál, amíg a sávod dühöt vagy energiát mutat."
L["Finishing move"] = "Befejező mozdulat"
L["Flight maps, books and letters, tabards and petitions, the stable."] = "Repülési térképek, könyvek és levelek, tabardok és petíciók, az istálló."
L["Friendly name grow direction"] = "Barátságos név növekedési iránya"
