L["Gives the micro menu and bag bar the Daylight UI look: square frames in your action button border style."] = "Daylight UI kinézetet ad a mikromenünek és a táskasávnak: szögletes keretek az akciógombjaid keretstílusában."
L["Glow to recast"] = "Fény az újravarázsláshoz"
L["Glows when it's time to cast it again: your next cast would land just as it runs out. Cast any sooner and a damage over time spell loses the ticks it had left."] = "Világít, amikor ideje újra elvarázsolni: a következő varázslásod épp akkor érne célba, amikor lejár. Ha korábban varázsolod, egy időbeli sebzés elveszíti a hátralévő tickjeit."
