L["How big the dispel icon is. With the name or portrait it fits there until you change this."] = "Mekkora a levételikon. A névvel vagy a portréval odaillik, amíg ezt nem módosítod."
L["How big the icons on the map are: herbs and ore, party members, quest spots and the like. The map keeps its size. This is Edit Mode's own setting, kept in your Edit Mode layout."] = "Mekkorák az ikonok a térképen: növények és ércek, csoporttagok, küldetéshelyek és hasonlók. A térkép megtartja a méretét. Ez a Szerkesztő mód saját beállítása, a Szerkesztő mód elrendezésedben tárolva."
L["How big the leader crown is. With the name or portrait it fits there until you change this."] = "Mekkora a vezetői korona. A névvel vagy a portréval odaillik, amíg ezt nem módosítod."
