L["Paging: this bar can show another page of buttons while you're in a stance or form, or while you hold a key. Pick a spare page to fill it with spells of its own."] = "Lapozás: ez a sáv egy másik gomblapot mutathat, amíg egy tartásban vagy formában vagy, vagy amíg egy gombot nyomva tartasz. Válassz egy tartaléklapot, hogy saját varázslatokkal töltsd fel."
L["Party Targets"] = "Csoportcélpontok"
