L["Press Escape and pick Daylight UI in the game menu, or type %s. Search finds any setting. %s over any Daylight UI window sizes it. %s on Home runs this tour again."] = "Nyomd meg az Escape-et, és válaszd a Daylight UI-t a játékmenüben, vagy írd be: %s. A keresés bármilyen beállítást megtalál. A(z) %s bármelyik Daylight UI ablak fölött méretezi azt. A Kezdőlapon a(z) %s újra elindítja ezt a bemutatót."
