L["Right of the member"] = "A tagtól jobbra"
L["Round rings, squares, or squares with an angled outer side like the frames' ends. The aggro fill, arrival light and elite frame follow the shape."] = "Kerek gyűrűk, négyzetek, vagy a keretek végeihez hasonlóan ferde külső oldalú négyzetek. Az aggró-kitöltés, az érkezési fény és az elit keret az alakot követik."
L["Second meter window"] = "Második mérőablak"
L["Sell %d"] = "%d eladása"
L["Sells for"] = "Eladási ár"
L["Separate "] = "Külön "
L["Shape"] = "Alak"
L["Shared media"] = "Közös média"
L["Shelf groups your items by kind, with a heading for each group. Grid is one even grid, bag by bag. List shows a row per item under the same groups, with its kind, level, count and price; click a column to sort. You can also switch with the button next to the search box. In the grid, Alt-right-click an item to keep it in its slot when you clean up."] = "A Polc fajta szerint csoportosítja a tárgyaidat, minden csoportnak fejléccel. A Rács egyetlen egyenletes rács, táskánként. A Lista ugyanazokban a csoportokban soronként egy tárgyat mutat, a fajtájával, szintjével, darabszámával és árával; kattints egy oszlopra a rendezéshez. A keresőmező melletti gombbal is válthatsz. A rácsban Alt+jobb klikk egy tárgyon a helyén tartja rendezéskor."
L["Shelf, grid or list"] = "Polc, rács vagy lista"
L["Shift+right-click: pick a text"] = "Shift+jobb klikk: szöveg választása"
L["Show "] = "Mutatás: "
L["Show only list"] = "Csak-mutató lista"
L["Show party targets"] = "Csoportcélpontok mutatása"
L["Show the "] = "Mutatás: "
L["Show the damage meter"] = "Sebzésmérő mutatása"
L["Shows "] = "Mutatja: "
L["Shows only the buffs on this list, with the filter above still applying. An empty list shows them all. Buffs on an enemy can't be matched, so none show there while a list is picked."] = "Csak az ezen a listán lévő buffokat mutatja, a fenti szűrő továbbra is érvényes. Az üres lista mindet mutatja. Az ellenségen lévő buffok nem egyeztethetők, ezért ott semmi sem látszik, amíg egy lista ki van választva."
L["Shows only the debuffs a boss puts on you, the ones a fight is about."] = "Csak azokat a debuffokat mutatja, amiket egy boss tesz rád, amelyekről a harc szól."
L["Shows only the debuffs on this list, with the filter above still applying. An empty list shows them all."] = "Csak az ezen a listán lévő debuffokat mutatja, a fenti szűrő továbbra is érvényes. Az üres lista mindet mutatja."
L["Shows the game's profession window, where SkillUp Forever draws its skill-up chances, costs and route. Daylight UI's window comes back the next time you open a profession."] = "A játék szakmaablakát mutatja, ahol a SkillUp Forever kirajzolja a jártasságnövekedési esélyeket, költségeket és az útvonalat. A Daylight UI ablaka a következő szakmanyitáskor jön vissza."
L["Small icons over the frame from its left end by default."] = "Kis ikonok a keret fölött, alapból a bal végétől."
L["Social window"] = "Közösségi ablak"
L["Sold %d items for %s."] = "%d tárgy eladva %s áron."
L["Sold 1 item for %s."] = "1 tárgy eladva %s áron."
L["Some spells have both, like Bloodrage. Pick which one this piece shows."] = "Néhány varázslatnak mindkettő van, mint a Bloodrage-nek. Válaszd ki, melyiket mutassa ez a darab."
L["Spells on this list"] = "Varázslatok ezen a listán"
L["Stack count"] = "Halomszám"
L["Summon"] = "Idézés"
L["Summon icon"] = "Idézés ikonja"
L["Summon left / right"] = "Idézés balra / jobbra"
L["Summon size"] = "Idézés mérete"
L["Summon up / down"] = "Idézés fel / le"
L["Switch between Shelf, grouped by kind, Grid, bag by bag, and List, a row per item."] = "Váltás a Polc (fajta szerint csoportosítva), a Rács (táskánként) és a Lista (soronként egy tárgy) között."
L["Switch between Shelf, grouped by kind, Grid, tab by tab, and List, a row per item."] = "Váltás a Polc (fajta szerint csoportosítva), a Rács (fülenként) és a Lista (soronként egy tárgy) között."
L["Takes the "] = "Kiveszi: "
L["Target, focus and the PvP frames fade when this spell can't reach someone outside your group, like an enemy you want to cast on. Units it can't be cast on stay as they are."] = "A célpont, a fókusz és a PvP-keretek elhalványulnak, ha ez a varázslat nem éri el a csoportodon kívüli egységet, például egy ellenséget, akire varázsolnál. Azok az egységek, akikre nem varázsolható, maradnak, ahogy vannak."
L["That isn't a talent string."] = "Ez nem tehetségszöveg."
L["That talent string is from another game version."] = "Ez a tehetségszöveg egy másik játékverzióból való."
L["The "] = "A(z) "
L["The Fabled styles are art by JiberishUI and its artists, from the Jiberish Fabled Icons addon, read from its own folder. Without it installed, every style shows Daylight UI's own icons."] = "A Fabled stílusok grafikája a JiberishUI és alkotóié, a Jiberish Fabled Icons addonból, annak saját mappájából olvasva. Ha nincs telepítve, minden stílus a Daylight UI saját ikonjait mutatja."
L["The buffs on this list never show here. Make and fill lists on Unit Frames > Aura Lists."] = "Az ezen a listán lévő buffok itt sosem látszanak. Listákat az Egységkeretek > Auralisták alatt készíthetsz és tölthetsz fel."
L["The chat window's text and the chat bubbles"] = "A chatablak szövege és a szövegbuborékok"
L["The damage meter and minimap fade together (and the separate meter window, if used). So does the experience bar, unless you give it its own fade below."] = "A sebzésmérő és a minitérkép együtt halványul el (és a külön mérőablak is, ha használod). A tapasztalatsáv is, hacsak alább nem adsz neki saját elhalványítást."
L["The data texts, and the clock and framerate on the minimap. General uses the font on General > Appearance."] = "Az adatszövegek, valamint az óra és a képkockasebesség a minitérképen. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The data texts, and the clock, framerate, zone name and coordinates on the minimap"] = "Az adatszövegek, valamint az óra, a képkockasebesség, a zónanév és a koordináták a minitérképen"
L["The debuffs on this list never show here. Make and fill lists on Unit Frames > Aura Lists."] = "Az ezen a listán lévő debuffok itt sosem látszanak. Listákat az Egységkeretek > Auralisták alatt készíthetsz és tölthetsz fel."
L["The empty part of the bar, behind the fill."] = "A sáv üres része a kitöltés mögött."
L["The empty part of the damage, healing and threat meters' bars, behind the fill. General uses the bar background on General > Appearance."] = "A sebzés-, gyógyítás- és fenyegetésmérők sávjainak üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["The experience bar's text and its +XP"] = "A tapasztalatsáv szövege és a +XP"
L["The fill of the bar."] = "A sáv kitöltése."
L["The fill of the damage, healing and threat meters' bars. General uses the bar texture on General > Appearance."] = "A sebzés-, gyógyítás- és fenyegetésmérők sávjainak kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar, the box that splits a stack."] = "A játékmenü, az addonlista, a makrók, az óra, a zsákmány, a foglalatozás, a fejlesztés, a bontó, az aukciósház, a szakmakönyv, a világtérkép kerete, a levegősáv, a halomosztó doboz."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar, the crowd control alert, the box that splits a stack. Also the game's own character and inspect windows while Daylight UI's are off."] = "A játékmenü, az addonlista, a makrók, az óra, a zsákmány, a foglalatozás, a fejlesztés, a bontó, az aukciósház, a szakmakönyv, a világtérkép kerete, a levegősáv, a tömegirányítás-riasztás, a halomosztó doboz. Továbbá a játék saját karakter- és megtekintő ablakai, amíg a Daylight UI-éi ki vannak kapcsolva."
L["The game only lets addons match buffs on anyone you can help and debuffs on enemies by spell. On debuffs on you and your group, only a few harmless ones like Sated can be hidden: those say so in the list."] = "A játék csak a segíthető egységeken lévő buffok és az ellenségeken lévő debuffok varázslat szerinti egyeztetését engedi az addonoknak. A rajtad és a csoportodon lévő debuffok közül csak néhány ártalmatlan, például a Sated rejthető el: ezeknél a lista jelzi."
L["The global cooldown's ring lights up the moment your next spell is ready."] = "A globális cooldown gyűrűje felvillan, amint a következő varázslatod kész."
L["The health and level numbers on the nameplates"] = "Az életerő- és szintszámok a névtáblákon"
L["The layer the PvP frames draw in."] = "A réteg, amibe a PvP-keretek rajzolódnak."
L["The layer the party frames draw in."] = "A réteg, amibe a csoportkeretek rajzolódnak."
L["The layer the party targets draw in."] = "A réteg, amibe a csoportcélpontok rajzolódnak."
L["The layer the party targets draw in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = "A réteg, amibe a csoportcélpontok rajzolódnak. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue."
L["The layer the personal display draws in. Low keeps it under your other frames."] = "A réteg, amibe a személyes kijelző rajzolódik. Az Alacsony a többi kereted alatt tartja."
L["The layer the raid frames draw in, for every raid size."] = "A réteg, amibe a raidkeretek rajzolódnak, minden raidmérethez."
L["The layer the swing timer draws in when detached, as a group or a bar on its own."] = "A réteg, amibe az ütésidőzítő rajzolódik leválasztva, csoportként vagy önálló sávként."
L["The layer your cast bar draws in."] = "A réteg, amibe a varázslássávod rajzolódik."
L["The layer your focus's cast bar draws in."] = "A réteg, amibe a fókuszod varázslássávja rajzolódik."
L["The layer your target's cast bar draws in."] = "A réteg, amibe a célpontod varázslássávja rajzolódik."
L["The number of stacks in the corner of each icon."] = "A halomszám minden ikon sarkában."
L["The pet's mood face edged in its color, or a square filled with it."] = "A háziállat hangulatarca a színével szegélyezve, vagy egy vele kitöltött négyzet."
L["The pets' health text"] = "A háziállatok életerő-szövege"
L["The pets' names"] = "A háziállatok nevei"
L["The picture at the frame's outer end: what it shows, its shape, size and ring."] = "A kép a keret külső végén: mit mutat, az alakja, mérete és gyűrűje."
L["The raid tiles' health text"] = "A raidcsempék életerő-szövege"
L["The raid tiles' names"] = "A raidcsempék nevei"
L["The size of the whole interface, the game's windows too. Daylight UI keeps it the same when the game changes its own (a new resolution, another monitor), so your frames stay where you put them. It takes the place of the game's UI scale setting, for every character on this account."] = "Az egész felület mérete, a játék ablakaival együtt. A Daylight UI ugyanazon tartja, amikor a játék a sajátját módosítja (új felbontás, másik monitor), így a kereteid ott maradnak, ahová tetted őket. A játék felületméret-beállítását váltja ki, a fiók minden karakterénél."
L["The spell name and time on the cast bars"] = "A varázslat neve és ideje a varázslássávokon"
L["The spell name and time on the party's cast bars"] = "A varázslat neve és ideje a csoport varázslássávjain"
L["The spell name and time on your cast bar"] = "A varázslat neve és ideje a varázslássávodon"
L["The spell name and time on your focus's cast bar"] = "A varázslat neve és ideje a fókuszod varázslássávján"
L["The spell name and time on your target's cast bar"] = "A varázslat neve és ideje a célpontod varázslássávján"
L["The spell name and time while the bar sits inside the frame, even past the power bar's height. 0 sizes them to fit the power bar."] = "A varázslat neve és ideje, amíg a sáv a kereten belül ül, akár az erőforrássáv magasságán túl is. A 0 az erőforrássávhoz méretezi őket."
L["The spell name and timer on the party's cast bars."] = "A varázslat neve és időzítője a csoport varázslássávjain."
L["The spell's name on "] = "A varázslat neve itt: "
L["The swing timer's hand and time"] = "Az ütésidőzítő keze és ideje"
L["The time on "] = "Az idő itt: "
L["The tray lists every spell your class can track. %s one to add it, or drag it up to where you want it, then pick %s or %s."] = "A tálca minden varázslatot listáz, amit a kasztod követhet. %s egyet a hozzáadáshoz, vagy húzd fel oda, ahová szeretnéd, majd válaszd ezt: %s vagy ezt: %s."
L["This frame's health text and large number"] = "Ennek a keretnek az életerő-szövege és nagy száma"
L["This frame's names, and its level badge"] = "Ennek a keretnek a nevei és a szintjelvénye"
L["This frame's power text"] = "Ennek a keretnek az erőforrás-szövege"
L["Threat % grow direction"] = "Fenyegetés % növekedési iránya"
L["Tiles grow"] = "A csempék növekedése"
L["Totems"] = "Totemek"
L["Totems as badges"] = "Totemek jelvényként"
L["Tour skipped. %s shows it again."] = "Bemutató kihagyva. A(z) %s újra megmutatja."
L["Turn off Recent"] = "A Friss kikapcsolása"
L["Turn the focus frame on or off."] = "A fókuszkeret be- vagy kikapcsolása."
L["Turn the party frame on or off."] = "A csoportkeret be- vagy kikapcsolása."
L["Turn the pet frame on or off."] = "A háziállat-keret be- vagy kikapcsolása."
L["Turn the player frame on or off."] = "A játékoskeret be- vagy kikapcsolása."
L["Turn the target frame on or off."] = "A célpontkeret be- vagy kikapcsolása."
L["Type /reload to finish."] = "A befejezéshez írd be: /reload."
L["UI scale"] = "Felületméret"
L["Under the frame it continues the frame's angle and slides out as you cast. Above the frame or on its own it has its own size."] = "A keret alatt folytatja a keret dőlését, és varázsláskor kicsúszik. A keret fölött vagy önállóan saját mérete van."
L["Under the member"] = "A tag alatt"
L["Watch list"] = "Figyelőlista"
L["Watch list (show only)"] = "Figyelőlista (csak mutatás)"
L["What"] = "Mi"
L["What this slot on the "] = "Mit mutat ez a hely itt: "
L["When"] = "Mikor"
L["When GatherMate2 knows a node within 100 yards, the arrow points there first, with its name under the yards, then goes back to your quest once you reach it. Which nodes count follows GatherMate2's own settings: the kinds it shows on your map and its node filter. Needs the GatherMate2 addon."] = "Ha a GatherMate2 ismer egy gyűjtőhelyet 100 yardon belül, a nyíl előbb oda mutat, a nevével a yardok alatt, majd ha odaértél, visszatér a küldetésedhez. Hogy mely helyek számítanak, a GatherMate2 saját beállításait követi: a térképeden mutatott fajtákat és a helyszűrőjét. Kell hozzá a GatherMate2 addon."
L["Where the "] = "Hol ül: "
L["Where the dispel icon sits: with the name tab or portrait (in a corner when the frame has neither), or any spot on or around the frame."] = "Hol ül a levételikon: a névfüllel vagy a portréval (sarokban, ha a keretnek egyik sincs), vagy bármely helyen a kereten vagy körülötte."
L["Where the ready check sits on each frame, or just outside it."] = "Hol ül a készenléti jel minden kereten, vagy épp azon kívül."
L["Where the ready check sits: with the name tab or portrait (in a corner when the frame has neither), or any spot on or around the frame."] = "Hol ül a készenléti jel: a névfüllel vagy a portréval (sarokban, ha a keretnek egyik sincs), vagy bármely helyen a kereten vagy körülötte."
L["Where the summon icon sits on each frame, or just outside it."] = "Hol ül az idézés ikonja minden kereten, vagy épp azon kívül."
L["Which "] = "Melyik: "
L["Which list the spells below belong to."] = "Melyik listához tartoznak az alábbi varázslatok."
L["Which page of buttons this bar shows "] = "Melyik gomblapot mutatja ez a sáv: "
L["Which page of buttons this bar shows %s. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "Melyik gomblapot mutatja ez a sáv %s. A billentyűid azt varázsolják, amit a sáv mutat. A Nincs változás a sáv saját gombjait tartja meg."
L["Which side of the party member's frame their target sits on. Past a party pet on the same side."] = "A csoporttag keretének melyik oldalán ül a célpontja. Ha ugyanazon az oldalon csoport-háziállat van, azon túl."
L["Who each party member is targeting, in a small frame beside them. Click one to target it too."] = "Kit vesz célba minden csoporttag, egy kis keretben mellettük. Kattints egyre, hogy te is célba vedd."
L["Yes, the quest helper"] = "Igen, a küldetéssegéd"
L["You must restart the game for the new damage numbers font to take effect."] = "Újra kell indítanod a játékot, hogy az új sebzésszám-betűtípus életbe lépjen."
L["Your accent color, or a color that says what the object is: gold for quests, blue for chests."] = "A kiemelőszíned, vagy egy szín, ami elárulja, mi a tárgy: arany a küldetéshez, kék a ládához."
L["Your casts and channels fill a ring further out, with a spark at the tip."] = "A varázslásaid és csatornázásaid egy kijjebb lévő gyűrűt töltenek, a csúcsán szikrával."
L["Your debuffs, crowd control, big defensives and buffs you can remove, on enemy plates."] = "A debuffjaid, a tömegirányítás, a nagy védekezők és a levehető buffok az ellenséges névtáblákon."
L["Your group fades by your heal's range, or the game's own check without one. Anyone else fades only with a range spell picked below."] = "A csoportod a gyógyításod hatótávja szerint halványul, vagy anélkül a játék saját ellenőrzése szerint. Bárki más csak egy alább választott hatótáv-varázslattal halványul."
L["Your heals over time and shields, everything you cast, or all of them. A class without heals sees everything it casts."] = "Az időbeli gyógyításaid és pajzsaid, mindent, amit varázsolsz, vagy az összeset. Gyógyítás nélküli kaszt mindent lát, amit varázsol."
