L["A hide list leaves its spells off every aura row that picks it; Hidden is picked everywhere until you change it. A show-only list makes a row show nothing else. Each frame's Buffs and Debuffs cards pick the lists they use, and so do the buff and debuff bars (Buffs > Filter)."] = "Egy elrejtőlista kihagyja a varázslatait minden aurasorból, amelyik kiválasztja; a Rejtett mindenhol ki van választva, amíg nem módosítod. A csak-mutató lista mellett egy sor semmi mást nem mutat. Minden keret Buffok és Debuffok kártyája választja ki a használt listákat, és a buff- és debuff-sávok is (Buffok > Szűrő)."
L["Bag by bag"] = "Táskánként"
L["Bag groups someone shared, added to yours."] = "Valaki által megosztott táskacsoportok, a tieidhez adva."
L["Card picture"] = "Kártyakép"
L["Debuffs on this list never show here. The game only lets addons hide a few harmless debuffs on you, like Sated; the Aura Lists page marks which. Make and fill lists on Unit Frames > Aura Lists."] = "Az ezen a listán lévő debuffok itt sosem látszanak. A játék csak néhány ártalmatlan debuff elrejtését engedi az addonoknak rajtad, például a Sated-ét; az Auralisták oldal jelöli, melyeket. Listákat az Egységkeretek > Auralisták alatt készíthetsz és tölthetsz fel."
L["Each character's bags are saved when you log out, and its bank each time you visit a banker. See them anywhere with the chest button in your bags, or /dui bank. When off, the button goes away and nothing new is saved."] = "Minden karakter táskái kilépéskor mentődnek, a bankja pedig minden bankárlátogatáskor. Bárhol megnézheted őket a táskáidban lévő láda gombbal, vagy /dui bank. Kikapcsolva a gomb eltűnik, és semmi új nem mentődik."
L["Health strip height"] = "Életerőcsík magassága"
L["Lock (never sold or disenchanted)"] = "Zárolás (soha nem adja el és nem bűvöli szét)"
L["Paste bag groups (Ctrl+V). A group with the same name as one of yours is updated; the others are added."] = "Illessz be táskacsoportokat (Ctrl+V). Egy a tieiddel azonos nevű csoport frissül; a többi hozzáadódik."
L["Shows only the buffs on this list. An empty list shows them all. Make and fill lists on Unit Frames > Aura Lists."] = "Csak az ezen a listán lévő buffokat mutatja. Az üres lista mindet mutatja. Listákat az Egységkeretek > Auralisták alatt készíthetsz és tölthetsz fel."
L["Stop keeping in this slot"] = "Megtartás vége ezen a helyen"
L["Tab by tab"] = "Fülenként"
L["The health bar along the card's foot. The picture takes the rest of the card."] = "Az életerősáv a kártya alján. A kép kitölti a kártya többi részét."
L["The name sits on the card's picture, at its top outer corner. Long names are cut short."] = "A név a kártya képén ül, a felső külső sarkánál. A hosszú nevek rövidülnek."
L["What fills the card behind the name: the 3D model, the face, or the class icon (NPCs show their face). None leaves only the unit's colors."] = "Mi tölti ki a kártyát a név mögött: a 3D modell, az arc, vagy a kasztikon (NPC-knél az arcuk). A Nincs csak az egység színeit hagyja meg."
L["Which buffs show, from the lists on Unit Frames > Aura Lists."] = "Mely buffok látszanak, az Egységkeretek > Auralisták listáiból."
L["Which debuffs show on this bar."] = "Mely debuffok látszanak ezen a sávon."
L["You can also switch with the button next to its search box."] = "A keresőmezője melletti gombbal is válthatsz."
L["You can also switch with the button next to the bank's search box."] = "A bank keresőmezője melletti gombbal is válthatsz."
L["You can also switch with the button next to the search box. Bag by bag, Alt-right-click an item to keep it in its slot when you clean up."] = "A keresőmező melletti gombbal is válthatsz. Táskánkénti nézetben Alt+jobb klikk egy tárgyon a helyén tartja rendezéskor."
L["DaylightUI saved the breath bar's position. Reload to put it in place?"] = "A DaylightUI elmentette a levegősáv helyét. Újratöltöd, hogy életbe lépjen?"
L["The breath bar's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "A levegősáv helyét a játék Szerkesztő módja tárolja, és saját Szerkesztő mód elrendezést használsz: ott mozgasd (Esc > Edit Mode)."
L["Type a name or a keyword. You can combine several."] = "Írj be egy nevet vagy kulcsszót. Többet is kombinálhatsz."
L["Binding"] = "Kötődés"
L["Equipment set"] = "Felszerelés-szett"
L["Compare"] = "Összehasonlítás"
L["Combine terms"] = "Kifejezések kombinálása"
L["Example"] = "Példa"
L["boe (binds on equip), bou (binds on use), %s"] = "boe (felvételkor kötődik), bou (használatkor kötődik), %s"
L["%s, or the set's name"] = "%s, vagy a szett neve"
L["& means all, | means any, ! means not"] = "Az & jelentése mind, a | jelentése bármelyik, a ! jelentése nem"
L["Any other word searches names. Start with # to match the keyword only."] = "Minden más szó a nevekben keres. Kezdd #-tel, ha csak a kulcsszóra szűrnél."
L["Quality"] = "Minőség"
L["Locked"] = "Zárolt"
L["%s is in an equipment set, so it can't be sold or disenchanted. Take it out of the set first."] = "A(z) %s egy felszerelés-szettben van, ezért nem adható el és nem bűvölhető szét. Előbb vedd ki a szettből."
L["%s: a glow style needs a key, a label and a draw function."] = "%s: egy ragyogásstílushoz kulcs, felirat és rajzoló függvény kell."
L["A soft animated light on the outline around your target, like on the main buttons of Daylight UI windows."] = "Lágy, animált fény a célpontod körüli körvonalon, mint a Daylight UI ablakok fő gombjain."
L["Animation colors"] = "Animáció színei"
L["Animation speed"] = "Animáció sebessége"
L["Animation strength"] = "Animáció erőssége"
L["Animations that react (Tide) move with every heal and hit. When off, they keep their steady pace."] = "A reagáló animációk (Ár) minden gyógyítással és találattal mozdulnak. Kikapcsolva megtartják az egyenletes tempójukat."
L["Bar animation"] = "Sáv-animáció"
L["Bar styles"] = "Sávstílusok"
L["Bars that move: their colors roll along them and react to the fight."] = "Mozgó sávok: a színeik végiggördülnek rajtuk, és reagálnak a harcra."
L["Breathing"] = "Lélegző"
L["Cast bar animation"] = "Varázslássáv animációja"
L["Change its icon"] = "Ikonjának módosítása"
L["Circling"] = "Körbefutó"
L["Class colors"] = "Kasztszínek"
L["Class tint"] = "Kasztárnyalat"
L["Collections, achievements, the dungeon journal, the game's Legacy window, the dressing room."] = "Gyűjtemények, achievementek, a kazamatanapló, a játék Legacy-ablaka, a próbafülke."
L["Comet"] = "Üstökös"
L["Custom colors"] = "Egyedi színek"
L["Custom health background color"] = "Egyedi életerő-háttérszín"
L["Custom power background color"] = "Egyedi erőforrás-háttérszín"
L["Cuts the left end at an angle too, leaning like the target frame's end. Not while under the frame, between the frames or under the personal display."] = "A bal végét is ferdén levágja, a célpontkeret végéhez hasonló dőléssel. Nem, ha a keret alatt, a keretek között vagy a személyes kijelző alatt van."
L["Cuts the left end of your focus's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "A fókuszod varázslássávjának bal végét ferdén levágja. Kikapcsolva a vége egyenes. Nem, amíg a kereten belül ül."
L["Cuts the left end of your target's cast bar at an angle, leaning like the frame's own end, so a bar above or below it can match. Not inside the frame or sliding out under it."] = "A célpontod varázslássávjának bal végét ferdén levágja, a keret saját végéhez hasonló dőléssel, hogy egy fölötte vagy alatta lévő sáv illeszkedhessen. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Cuts the right end at an angle. Under the frame it continues the frame's angle, and between the frames both ends lean. When off, its ends are straight."] = "A jobb végét ferdén levágja. A keret alatt folytatja a keret dőlését, a keretek között mindkét vége dől. Kikapcsolva a végei egyenesek."
L["Cuts the right end of your focus's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "A fókuszod varázslássávjának jobb végét ferdén levágja. Kikapcsolva a vége egyenes. Nem, amíg a kereten belül ül."
L["Cuts the right end of your target's cast bar at an angle. When off, its end is straight. Not inside the frame or sliding out under it."] = "A célpontod varázslássávjának jobb végét ferdén levágja. Kikapcsolva a vége egyenes. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Daylight UI window"] = "Daylight UI ablak"
L["Embers"] = "Parázs"
L["Equip after combat"] = "Felvétel harc után"
L["First color"] = "Első szín"
L["Flight maps, books and letters, tabards and petitions, the stable, and the game's own talk, vendor and trainer windows when you pick them over Daylight UI's."] = "Repülési térképek, könyvek és levelek, tabardok és petíciók, az istálló, valamint a játék saját beszélgetés-, árus- és oktatóablakai, ha azokat választod a Daylight UI-éi helyett."
L["Flow"] = "Folyás"
L["Focus cast bar animation"] = "Fókusz varázslássávjának animációja"
L["Gear in one of your equipment sets can't be sold to a vendor or disenchanted by accident. Clicking it there tells you why."] = "A felszerelés-szetteidben lévő felszerelés nem adható el véletlenül árusnak és nem bűvölhető szét. Ha ott rákattintasz, megmondja, miért."
L["Glow style"] = "Ragyogásstílus"
L["Guild and communities, the calendar, trading, the guild bank, the game's mailbox, friends window and group finder."] = "Céh és közösségek, a naptár, a kereskedés, a céhbank, a játék postaládája, barátablaka és csoportkeresője."
L["Health background brightness"] = "Életerő-háttér fényereje"
L["Health background color"] = "Életerő-háttér színe"
L["Health background opacity"] = "Életerő-háttér átlátszatlansága"
L["Health bar animation"] = "Életerősáv animációja"
L["How a spell glows when its card asks for it (ready, usable, buff up or missing, time to recast): the game's spell alert ring, or a soft light moving round its edge."] = "Hogyan világít egy varázslat, amikor a kártyája kéri (kész, használható, buff fent van vagy hiányzik, ideje újravarázsolni): a játék varázslatriasztó gyűrűje, vagy a széle mentén körbefutó lágy fény."
L["How big a reaction is. The game doesn't say how big a hit or heal was, so every one moves the same."] = "Mekkora egy reakció. A játék nem mondja meg, mekkora volt egy találat vagy gyógyítás, így mindegyik ugyanannyit mozdít."
L["How fast the animation moves. 1x is its usual pace."] = "Milyen gyorsan mozog az animáció. Az 1x a szokásos tempója."
L["How much of the bar's color the empty part keeps. Lower is darker."] = "Mennyit tart meg az üres rész a sáv színéből. Kisebb érték = sötétebb."
L["How solid the empty part of this frame's health bar is. Lower lets the world show through it."] = "Mennyire tömör ennek a keretnek az életerősávja üres része. Alacsonyabb értéknél átlátszik rajta a világ."
L["How solid the empty part of this frame's power bar is. Lower lets the world show through it."] = "Mennyire tömör ennek a keretnek az erőforrássávja üres része. Alacsonyabb értéknél átlátszik rajta a világ."
L["How strongly the animation shows over the bar's own fill. Lower blends it in softly."] = "Milyen erősen látszik az animáció a sáv saját kitöltése fölött. Alacsonyabb érték lágyan belesimítja."
L["How the bar moves. Flow rolls the bar's colors along it; Tide does too and surges with every heal and hit. By power type picks one that suits mana, rage or energy. Needs Motion effects (General > Appearance)."] = "Hogyan mozog a sáv. A Folyás végiggörgeti a sáv színeit; az Ár szintén, és minden gyógyításnál és találatnál megemelkedik. Az Erőforrás szerint a manához, dühhöz vagy energiához illőt választ. Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["How the bar moves. Flow rolls the bar's colors along it; Tide does too and surges with every heal and hit. Needs Motion effects (General > Appearance)."] = "Hogyan mozog a sáv. A Folyás végiggörgeti a sáv színeit; az Ár szintén, és minden gyógyításnál és találatnál megemelkedik. Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["How this spell glows when its other settings ask for it (ready, usable, buff up or missing, time to recast): the game's spell alert ring, or a soft light moving round its edge."] = "Hogyan világít ez a varázslat, amikor a többi beállítása kéri (kész, használható, buff fent van vagy hiányzik, ideje újravarázsolni): a játék varázslatriasztó gyűrűje, vagy a széle mentén körbefutó lágy fény."
L["Lock equipment set items"] = "Felszerelés-szett tárgyainak zárolása"
L["Main button glow"] = "Fő gomb fénye"
L["Name the new set:"] = "Az új szett neve:"
L["New set from what I'm wearing"] = "Új szett abból, ami rajtam van"
L["New: bars that move. Their colors roll slowly along your health, power, cast and swing bars. Turn them on? Each frame's page has more styles under Bar animation."] = "Új: mozgó sávok. A színeik lassan végiggördülnek az életerő-, erőforrás-, varázslás- és ütéssávjaidon. Bekapcsolod őket? Minden keret oldalán a Sáv-animáció alatt több stílus van."
L["No sets yet"] = "Még nincsenek szettek"
L["No sets yet."] = "Még nincsenek szettek."
L["Nothing in this set yet."] = "Ebben a szettben még nincs semmi."
L["One end of the custom pair."] = "Az egyedi pár egyik vége."
L["Outline light"] = "Körvonal fénye"
L["Party cast bars animation"] = "Csoport varázslássávjainak animációja"
L["Pets' health bar"] = "Háziállatok életerősávja"
L["Pets' health bar animation"] = "Háziállatok életerősávjának animációja"
L["Pets' power bar"] = "Háziállatok erőforrássávja"
L["Pets' power bar animation"] = "Háziállatok erőforrássávjának animációja"
L["Power background brightness"] = "Erőforrás-háttér fényereje"
L["Power background color"] = "Erőforrás-háttér színe"
L["Power background opacity"] = "Erőforrás-háttér átlátszatlansága"
L["Power bar animation"] = "Erőforrássáv animációja"
L["Rank %d"] = "%d. rang"
L["React to hits and heals"] = "Reakció találatokra és gyógyításokra"
L["Reaction size"] = "Reakció mérete"
L["Right-click: your alts"] = "Jobb klikk: az altjaid"
L["Save"] = "Mentés"
L["Save the gear you're wearing as a set, then put the whole outfit on with one click."] = "Mentsd el a rajtad lévő felszerelést szettként, aztán egy kattintással vedd fel az egész öltözetet."
L["Save what you're wearing as %s?"] = "Elmented, ami rajtad van, ezen a néven: %s?"
L["Second color"] = "Második szín"
L["Set %d"] = "%d. szett"
L["Shine"] = "Csillogás"
L["Show the bag's header"] = "A táska fejlécének mutatása"
L["Swing timer animation"] = "Ütésidőzítő animációja"
L["Target cast bar animation"] = "Célpont varázslássávjának animációja"
L["Target outline light"] = "Célpont körvonalának fénye"
L["The bar's own"] = "A sáv sajátja"
L["The color behind every window and panel: Daylight's own dark tone, a dark tint of your class color, or a color you pick."] = "A szín minden ablak és panel mögött: a Daylight saját sötét tónusa, a kasztszíned sötét árnyalata, vagy egy általad választott szín."
L["The colors the animation moves: the ones the bar already has, your accent, your class's pair, or two of your own."] = "Az animáció színei: amik a sávon már vannak, a kiemelőszíned, a kasztod párja, vagy két saját szín."
L["The empty part's color when Health background color is One color."] = "Az üres rész színe, ha az Életerő-háttér színe Egy szín."
L["The empty part's color when Power background color is One color."] = "Az üres rész színe, ha az Erőforrás-háttér színe Egy szín."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the game's character, spellbook, profession and inspect windows, the world map's frame, the breath bar, the box that splits a stack."] = "A játékmenü, az addonlista, a makrók, az óra, a zsákmány, a foglalatozás, a fejlesztés, a bontó, az aukciósház, a szakmakönyv, a játék karakter-, varázskönyv-, szakma- és megtekintő ablakai, a világtérkép kerete, a levegősáv, a halomosztó doboz."
L["The other end of the custom pair."] = "Az egyedi pár másik vége."
L["Tide"] = "Ár"
L["Turn them on"] = "Bekapcsolás"
L["Twinkle"] = "Pislákolás"
L["Use Daylight UI's window from now on. The button in its header brings this one back."] = "Mostantól a Daylight UI ablakát használja. A fejlécében lévő gomb visszahozza ezt."
L["Use the game's own window"] = "A játék saját ablakának használata"
L["Which of this page's bars the rows below set."] = "Ennek az oldalnak melyik sávját állítják az alábbi sorok."
L["You can't have more sets."] = "Nem lehet több szetted."
L["Your bank, from anywhere."] = "A bankod, bárhonnan."
L["Your cast bar"] = "A varázslássávod"
L["Your cast bar animation"] = "A varázslássávod animációja"
L["\"Kicked by\" and the player's name in their class color, beside a target's, focus's or party member's cast bar for a moment."] = "\"Megszakította\" és a játékos neve a kasztszínében, egy pillanatra a célpont, a fókusz vagy egy csoporttag varázslássávja mellett."
L["A buff's time turns orange and gently pulses in its last 5 seconds. Debuffs keep their usual time color."] = "Egy buff ideje az utolsó 5 másodpercében narancs lesz és finoman lüktet. A debuffok megtartják a szokásos időszínüket."
L["A button on the game's class trainer window that learns every spell you can afford in one click. The Daylight UI style NPC window's trainer page has its own, so this is for the game's window (NPC window > Trainer window off)."] = "Egy gomb a játék kasztoktató ablakán, ami egy kattintással megtanul minden varázslatot, amire telik. A Daylight UI stílusú NPC-ablak oktatóoldalának sajátja van, így ez a játék ablakához való (NPC-ablak > Oktatóablak kikapcsolva)."
L["A copy of the cooldown layout you're using, used by the talent set you're in from now on."] = "A használt cooldown-elrendezés másolata, mostantól azt a tehetségszett használja, amelyikben vagy."
L["A gradient per point"] = "Pontonként egy színátmenet"
L["A layout string from the game's own Cooldown Manager (its Export), a guide or another UI. It becomes a new cooldown layout, used by the talent set you're in."] = "Elrendezésszöveg a játék saját Cooldown-kezelőjéből (az Exportjából), egy útmutatóból vagy egy másik felületből. Új cooldown-elrendezés lesz belőle, a tehetségszetted használja, amelyikben vagy."
L["A mark by the bar of anything your quests still need. Not inside instances."] = "Jelölés a sáv mellett mindenen, ami a küldetéseidhez még kell. Instance-ben nem."
L["A new name for the cooldown layout you're using."] = "A használt cooldown-elrendezés új neve."
L["A one-minute walk past what Daylight UI adds: the damage meter, buff and bag groups, moving frames and these options."] = "Egyperces séta azon, amit a Daylight UI hozzáad: a sebzésmérő, a buff- és táskacsoportok, a keretek mozgatása és ezek a beállítások."
L["A player's guild rank, after their guild name."] = "Egy játékos céhrangja, a céhneve után."
L["A small line at the bottom of spell and item tooltips with its ID, the word in your accent color: handy for macros, other addons and bug reports. Buff and debuff icons use the game's own tooltip, which can't show it."] = "Kis sor a varázslat- és tárgy-súgóbuborékok alján az azonosítójával, a szó a kiemelőszínedben: hasznos makrókhoz, más addonokhoz és hibajelentésekhez. A buff- és debuff-ikonok a játék saját súgóbuborékát használják, ami nem tudja mutatni."
L["A small square or icon on each member while one of your heals over time or shields is on them. On in the Healer setup. Each class has its own picks; change them below."] = "Kis négyzet vagy ikon minden tagon, amíg egy időbeli gyógyításod vagy pajzsod rajta van. A Gyógyító beállításban be van kapcsolva. Minden kasztnak saját választásai vannak; alább módosíthatod őket."
L["A stun, fear, polymorph and the like, as a bigger icon by the health bar."] = "Kábítás, félelem, polymorph és hasonlók, nagyobb ikonként az életerősáv mellett."
L["Above or below the frame, the bar is as wide as the frame. When off, it takes the width below."] = "A keret fölött vagy alatt a sáv olyan széles, mint a keret. Kikapcsolva az alábbi szélességet veszi fel."
L["Accent color follows the accent on General > Appearance, gradient and all."] = "A Kiemelőszín az Általános > Megjelenés kiemelését követi, színátmenettel együtt."
L["Accent color follows the accent on General > Appearance, including the Daylight gradient."] = "A Kiemelőszín az Általános > Megjelenés kiemelését követi, a Daylight színátmenettel együtt."
L["Accent color follows your accent (General > Appearance). One color uses the one you pick."] = "A Kiemelőszín a kiemelésedet követi (Általános > Megjelenés). Az Egy szín az általad választottat használja."
L["Across the bar keeps the name inside, with the alignment below. Any other spot puts it there, on or round the frame; outside spots need space between frames."] = "A sávon át a nevet belül tartja, az alábbi igazítással. Bármely más hely oda teszi, a keretre vagy köré; a külső helyekhez a keretek között hely kell."
L["All, Same game and Online buttons over the friends list, to show only the friends you can play with or the ones who are on."] = "Mind, Ugyanaz a játék és Online gombok a barátlista fölött, hogy csak azokat a barátokat lásd, akikkel játszhatsz, vagy akik fent vannak."
L["An empty cooldown layout, used by the talent set you're in."] = "Üres cooldown-elrendezés, a tehetségszetted használja, amelyikben vagy."
L["An item link shows your equipped item beside it, as the game's own compare setting says. When off, it shows only while Shift is held."] = "Egy tárgylink mellett a felszerelt tárgyad is látszik, ahogy a játék saját összehasonlító beállítása mondja. Kikapcsolva csak a Shift lenyomásakor."
L["An item's tooltip in your bags and bank shows the gear you have on beside it. When off, only while you hold Shift."] = "A táskáidban és a bankodban lévő tárgy súgóbuboréka mellette mutatja a rajtad lévő felszerelést. Kikapcsolva csak a Shift lenyomásakor."
L["Another player's gear and talents in one window, in Daylight UI style."] = "Egy másik játékos felszerelése és tehetségei egy ablakban, Daylight UI stílusban."
