L["By zone: green in friendly lands, amber in contested ones, red in hostile ones, blue in sanctuaries. One color: always Custom minimap zone name color."] = "Zóna szerint: zöld barátságos területen, borostyán vitatottban, piros ellenségesben, kék menedékben. Egy szín: mindig az Egyedi minitérkép-zónanévszín."
