L["Cuts the power bar's end at an angle, on the same side as the frame's. Only while it's on its own. When off, both ends are straight."] = "Az erőforrássáv végét ferdén levágja, a keretével azonos oldalon. Csak amíg önállóan áll. Kikapcsolva mindkét vége egyenes."
