L["Cuts the ranged bar's right end at an angle. Only when detached on its own."] = "A távolsági sáv jobb végét ferdén levágja. Csak önállóan leválasztva."
L["DPS/Tank with your party and raid as square tiles under you (you included, missing health on them, dispels easy to see), and your frame and your target's raised a little. Everything it sets is on the Party and Raid pages; move any of them in unlock mode. Choose it above to use it. If the profile you're on has moved action bars, it offers to bring them along."] = "DPS/Tank, a csoportod és raided négyzetes csempékként alattad (te is, rajtuk a hiányzó életerő, a levehetők jól láthatóan), a te kereted és a célpontodé pedig kicsit feljebb. Minden, amit beállít, a Csoport és a Raid oldalon van; feloldott módban bármelyiket mozgathatod. Válaszd ki fent a használatához. Ha a jelenlegi profilodban áthelyezett akciósávok vannak, felajánlja, hogy átveszi őket."
