L["Dims units that are out of reach: target, focus, their targets, party, party targets, raid and PvP frames. Your group by your heal, anyone else by the spell you pick."] = "Halványítja az elérhetetlen egységeket: célpont, fókusz, a célpontjaik, csoport, csoportcélpontok, raid- és PvP-keretek. A csoportodat a gyógyításod szerint, bárki mást a választott varázslat szerint."
