L["Divine Shield, Ice Block and the like, as a bigger icon by the health bar, so you know not to waste your damage."] = "Divine Shield, Ice Block és hasonlók, nagyobb ikonként az életerősáv mellett, hogy tudd: kár rá pazarolni a sebzést."
L["Each category on its own row"] = "Minden kategória saját sorban"
