L["Every debuff on you, over your frame from its right end. Your buff bars show them too."] = "Minden rajtad lévő debuff, a kereted fölött a jobb végétől. A buff-sávjaid is mutatják őket."
L["Every debuff on your pet, under its frame."] = "Minden debuff a háziállatodon, a kerete alatt."
