L["Friendly power bar"] = "Barátságos erőforrássáv"
L["Friendly reputation"] = "Friendly hírnév"
L["Group finder scale"] = "Csoportkereső mérete"
L["Hand-in color"] = "Leadási szín"
L["Hated reputation"] = "Hated hírnév"
L["Heal indicator cooldown swipe"] = "Gyógyításjelző cooldown-söprése"
L["Heal indicator on"] = "Gyógyításjelző bekapcsolva"
L["Health bar angled end"] = "Életerősáv ferde vége"
L["Health bar background texture"] = "Életerősáv háttértextúrája"
L["Health bar width"] = "Életerősáv szélessége"
L["Health text % sign"] = "% jel az életerő-szövegen"
L["Hidden boss debuffs"] = "Rejtett boss-debuffok"
L["Honored reputation"] = "Honored hírnév"
L["Hostile reputation"] = "Hostile hírnév"
L["Hovering a quest in the quest log shows its tooltip beside the log, as the game's own log does. When off, it shows at the mouse."] = "Ha egy küldetés fölé viszed az egeret a küldetésnaplóban, a súgóbuboréka a napló mellett jelenik meg, ahogy a játék saját naplójában. Kikapcsolva az egérnél jelenik meg."
L["Hovering an icon says what it is. When off, the mouse goes straight through to what's behind it."] = "Egy ikon fölé víve az egeret megmondja, mi az. Kikapcsolva az egér egyenesen átmegy a mögötte lévőre."
L["Hovering an item, spell or quest link in chat shows its tooltip. When off, clicking a link still opens it."] = "A chatben egy tárgy-, varázslat- vagy küldetéslink fölé víve megjelenik a súgóbuboréka. Kikapcsolva a linkre kattintás továbbra is megnyitja."
L["How a debuff you can remove shows on each party frame: an icon, a highlight or a glow."] = "Hogyan látszik egy levehető debuff minden csoportkereten: ikon, kiemelés vagy fény."
L["How big every indicator is."] = "Mekkora minden jelző."
L["How big the NPC job line is. Set to 0 to follow the name size."] = "Mekkora az NPC-foglalkozás sora. A 0 a névmérethez igazítja."
L["How big the NPC job line on friendly plates is. Set to 0 to follow the name size."] = "Mekkora az NPC-foglalkozás sora a barátságos névtáblákon. A 0 a névmérethez igazítja."
L["How big the guild line is. Set to 0 to follow the name size."] = "Mekkora a céhsor. A 0 a névmérethez igazítja."
L["How big the guild line on friendly plates is. Set to 0 to follow the name size."] = "Mekkora a céhsor a barátságos névtáblákon. A 0 a névmérethez igazítja."
L["How big the happiness square or face is."] = "Mekkora a boldogság-négyzet vagy -arc."
L["How big the health text is. 0 fits it to the bar."] = "Mekkora az életerő-szöveg. A 0 a sávhoz igazítja."
L["How big the health text is. Set to 0 to match the bar height."] = "Mekkora az életerő-szöveg. A 0 a sáv magasságához igazítja."
L["How big the health text on friendly plates is. Set to 0 to match the bar height."] = "Mekkora az életerő-szöveg a barátságos névtáblákon. A 0 a sáv magasságához igazítja."
L["How big the level is. Set to 0 to match the bar height."] = "Mekkora a szint. A 0 a sáv magasságához igazítja."
L["How big the power text is. 0 fits it to the bar."] = "Mekkora az erőforrás-szöveg. A 0 a sávhoz igazítja."
L["How big the skull, star and other raid markers by the bar are."] = "Mekkorák a koponya, a csillag és a többi raidjelölő a sáv mellett."
L["How big the threat number is. Set to 0 to match the bar height."] = "Mekkora a fenyegetésszám. A 0 a sáv magasságához igazítja."
L["How dark the shadow around Daylight UI's frames and windows is."] = "Milyen sötét az árnyék a Daylight UI keretei és ablakai körül."
L["Animation, fill, colors and interrupts for every cast bar. Each bar's own settings are on its frame's page."] = "Animáció, kitöltés, színek és megszakítások minden varázslássávhoz. Minden sáv saját beállításai a keretének oldalán vannak."
L["How far along that quest objective is (4/10, or 45%), small, beside the quest mark."] = "Hol tart az a küldetésfeladat (4/10, vagy 45%), kicsiben, a küldetésjel mellett."
L["How far the soft shadow around Daylight UI's frames and windows reaches."] = "Milyen messzire ér a lágy árnyék a Daylight UI keretei és ablakai körül."
L["How long it waits before it fades, in seconds: after a fight ends, once a fight starts, after your mouse leaves it, after you clear your target, or after a change it shows."] = "Mennyit vár, mielőtt elhalványul, másodpercben: egy harc vége után, egy harc kezdete után, miután az egér elhagyta, miután elengedted a célpontot, vagy egy általa mutatott változás után."
L["How many lines show at once. Past this the oldest line leaves early, so a big pull never floods the screen."] = "Hány sor látszik egyszerre. Ezen felül a legrégebbi sor hamarabb távozik, így egy nagy pull sosem árasztja el a képernyőt."
L["How many minutes a new item stays in Recent before it goes to its own group. Right-click Recent to clear it sooner."] = "Hány percig marad egy új tárgy a Frissben, mielőtt a saját csoportjába kerül. Jobb klikk a Frissen, ha hamarabb törölnéd."
L["How many of the newest messages per chat tab come back after /reload, and after logging out while Keep chat after logging out is on."] = "Chatfülenként hány legújabb üzenet jön vissza /reload után, és kilépés után, amíg a Chat megtartása kilépés után be van kapcsolva."
L["How many seconds a line stays on screen before it fades away."] = "Hány másodpercig marad egy sor a képernyőn, mielőtt elhalványul."
L["How many seconds a new whisper's preview stays."] = "Hány másodpercig marad egy új suttogás előnézete."
L["How many seconds each line stays after your last loot of it."] = "Hány másodpercig marad minden sor az utolsó ilyen zsákmány után."
L["How many seconds the line stays before fading, unless the buffs land first."] = "Hány másodpercig marad a sor, mielőtt elhalványul, hacsak a buffok előbb fel nem kerülnek."
L["How many seconds the mouse rests on a link before its tooltip shows, so sweeping across the chat leaves it quiet."] = "Hány másodpercig kell az egérnek egy linken pihennie, mielőtt a súgóbuboréka megjelenik, hogy a chaten átsöpörve csend maradjon."
L["How many seconds with no new messages before the chat fades."] = "Hány másodperc új üzenet nélkül, mielőtt a chat elhalványul."
L["How many yards away it is, under the marker."] = "Hány yardra van, a jelölő alatt."
L["How many yards away the spot is, under the arrow."] = "Hány yardra van a hely, a nyíl alatt."
L["How much color the empty part of every health and power bar keeps. Lower is darker."] = "Mennyi színt tart meg minden életerő- és erőforrássáv üres része. Kisebb érték = sötétebb."
L["How solid it is while shown, whatever the fade does. At 0 it never shows, even under the mouse or in a fight."] = "Mennyire tömör, amíg látszik, bármit is csinál az elhalványítás. 0-nál sosem látszik, egér alatt vagy harcban sem."
L["How solid it is, when it fades and how far. Unlocked, in test mode or with this page open, it shows at its opacity."] = "Mennyire tömör, mikor halványul el és mennyire. Feloldva, teszt módban vagy nyitott oldallal az átlátszatlanságán látszik."
L["How solid its background is: at 0 it's fully see-through."] = "Mennyire tömör a háttere: 0-nál teljesen áttetsző."
L["How solid the borders around Daylight UI's frames and windows are: at 0 they're fully see-through."] = "Mennyire tömörek a keretek a Daylight UI keretei és ablakai körül: 0-nál teljesen áttetszők."
L["How solid the world map's symbols are. Lower it to see more of the map under them."] = "Mennyire tömörek a világtérkép jelei. Csökkentsd, hogy többet láss alattuk a térképből."
L["How tall every other plate's health bar is while you have a target, as a share of Health bar height. Plate size by threat (Nameplates > Threat) wins while it's on."] = "Milyen magas minden más névtábla életerősávja, amíg van célpontod, az Életerősáv magasságának arányában. A Névtábla mérete fenyegetés szerint (Névtáblák > Fenyegetés) elsőbbséget kap, amíg be van kapcsolva."
L["How tall the main hand bar is. Only when detached on its own."] = "Milyen magas a főkéz-sáv. Csak önállóan leválasztva."
L["How tall the off hand bar is. Only when detached on its own."] = "Milyen magas a mellékkéz-sáv. Csak önállóan leválasztva."
L["How tall the quest tracker can grow. Past this, the list scrolls with the mouse wheel."] = "Milyen magasra nőhet a küldetéskövető. Ezen túl a lista egérgörgővel görgethető."
L["How tall the ranged bar is. Only when detached on its own."] = "Milyen magas a távolsági sáv. Csak önállóan leválasztva."
L["How the health text is written. Missing health shows nothing while the unit is at full."] = "Hogyan íródik ki az életerő-szöveg. A Hiányzó életerő semmit sem mutat, amíg az egység teli életerőn van."
L["How the health text is written. Missing health shows nothing while you're at full."] = "Hogyan íródik ki az életerő-szöveg. A Hiányzó életerő semmit sem mutat, amíg teli életerőn vagy."
L["How thick the border round each pip is. 0 leaves none."] = "Milyen vastag a keret minden jelölő körül. A 0 elhagyja."
L["How this frame's name looks and where it sits: its text, color and size, and the tab behind it."] = "Hogyan néz ki ennek a keretnek a neve, és hol ül: a szövege, színe és mérete, és a mögötte lévő fül."
L["How wide every other plate is while you have a target, as a share of Health bar width. Plate size by threat (Nameplates > Threat) wins while it's on."] = "Milyen széles minden más névtábla, amíg van célpontod, az Életerősáv szélességének arányában. A Névtábla mérete fenyegetés szerint (Névtáblák > Fenyegetés) elsőbbséget kap, amíg be van kapcsolva."
L["How wide the main hand bar is. Only when detached on its own."] = "Milyen széles a főkéz-sáv. Csak önállóan leválasztva."
L["How wide the off hand bar is. Only when detached on its own."] = "Milyen széles a mellékkéz-sáv. Csak önállóan leválasztva."
L["How wide the power bar is. Only while it's on its own."] = "Milyen széles az erőforrássáv. Csak amíg önállóan áll."
L["How wide the ranged bar is. Only when detached on its own."] = "Milyen széles a távolsági sáv. Csak önállóan leválasztva."
L["How wide the swing timer bars are. Only when detached as a group. Hung under the player frame, the bars match its width."] = "Milyen szélesek az ütésidőzítő-sávok. Csak csoportként leválasztva. A játékoskeret alá akasztva a sávok annak szélességéhez igazodnak."
L["How wide your target's plate is, as a share of Health bar width."] = "Milyen széles a célpontod névtáblája, az Életerősáv szélességének arányában."
L["Icon opacity on cooldown"] = "Ikon átlátszatlansága cooldownon"
L["In the Shelf and List views, stacks of the same item show as one, with the total. They show apart while you trade or have the mailbox or auction house open, so you can Shift-click one to split it."] = "A Polc és Lista nézetben ugyanannak a tárgynak a halmai egyként látszanak, az összeggel. Külön látszanak, amíg kereskedsz, vagy nyitva van a postaláda vagy az aukciósház, hogy Shift+kattintással szétoszthasd."
L["In the Shelf and List views, your Soul Shards show as one, with how many you have, though each still takes its own slot."] = "A Polc és Lista nézetben a Soul Shardjaid egyként látszanak, azzal, hány van, bár mindegyik továbbra is saját helyet foglal."
L["Info panel border"] = "Infópanel kerete"
L["Inspect window scale"] = "Megtekintő ablak mérete"
L["Inspecting a player opens Daylight UI's window, with their gear and talents. Turn it off to use the game's own window, in Daylight UI's look. Each window also has a button to switch to the other."] = "Egy játékos megtekintése a Daylight UI ablakát nyitja meg, a felszerelésével és tehetségeivel. Kapcsold ki, ha a játék saját ablakát használnád, Daylight UI kinézetben. Mindkét ablakon van egy gomb a másikra váltáshoz."
L["Keep new items in Recent"] = "Új tárgyak a Frissben tartása"
L["Leader crown position"] = "Vezetői korona helye"
L["Left stream max shown"] = "Bal folyam legfeljebb"
L["Legacy window scale"] = "Legacy-ablak mérete"
L["Link tooltip delay"] = "Linkek súgóbuborékának késleltetése"
L["Loot and XP don't wake the chat"] = "A zsákmány és az XP nem ébreszti fel a chatet"
L["Loot feed angled side"] = "Zsákmánysáv ferde oldala"
L["Loot feed line time"] = "Zsákmánysáv sorának ideje"
L["Loot feed lowest quality"] = "Zsákmánysáv legalacsonyabb minősége"
L["Low health and mana warning at"] = "Figyelmeztetés alacsony életerőre és manára ennél"
L["Mailbox scale"] = "Postaláda mérete"
L["Main hand at the bottom, the others above it. Only when detached as a group."] = "A főkéz alul, a többi fölötte. Csak csoportként leválasztva."
L["Main hand bar visibility"] = "Főkéz-sáv láthatósága"
L["Makes all text on Daylight UI's frames bigger or smaller, on top of each frame's own text size."] = "A Daylight UI keretein minden szöveget nagyobbra vagy kisebbre állít, az egyes keretek saját szövegmérete fölött."
L["Makes every Daylight UI frame and window bigger or smaller. To size one frame alone, unlock the frames and scroll over it."] = "Minden Daylight UI keretet és ablakot nagyobbra vagy kisebbre állít. Ha csak egy keretet méreteznél, oldd fel a kereteket, és görgess fölötte."
L["Marker distance"] = "Jelölő távolsága"
L["Max buffs shown"] = "Buffok legfeljebb"
L["Max debuffs shown"] = "Debuffok legfeljebb"
L["Max friendly buffs shown"] = "Barátságos buffok legfeljebb"
L["Max whisper tiles"] = "Suttogás-csempék legfeljebb"
L["Meter text size"] = "Mérő szövegmérete"
L["Minimap zone name color"] = "Minitérkép-zónanév színe"
L["Minimap zone name text size"] = "Minitérkép-zónanév szövegmérete"
L["Missing buffs shown for"] = "Hiányzó buffok mutatása ennyi ideig"
L["NPC window scale"] = "NPC-ablak mérete"
L["Nameplate scale"] = "Névtábla mérete"
L["Names of the other faction's players you can't attack (not flagged for PvP) when Friendly name color is Custom colors."] = "A másik frakció nem támadható (PvP-jelzés nélküli) játékosainak nevei, ha a Barátságos névszín Egyedi színek."
L["Names on friendly plates in their class or reaction color, a class gradient, or plain white. Reaction: players in green too. Custom colors: pick a color for players, NPCs and the other faction below."] = "Nevek a barátságos névtáblákon a kaszt- vagy viszonyszínükben, kaszt-színátmenetben, vagy sima fehérben. Viszony: a játékosok is zöldben. Egyedi színek: alább választhatsz színt a játékosoknak, az NPC-knek és a másik frakciónak."
L["Neutral reputation"] = "Neutral hírnév"
L["New cooldown layout"] = "Új cooldown-elrendezés"
L["No modules loaded yet. Turn on Daylight UI modules in the AddOns list."] = "Még nincs betöltött modul. Kapcsold be a Daylight UI modulokat az AddOns listában."
L["Nudges the buffs sideways from their position."] = "Oldalra tolja a buffokat a helyükről."
L["Nudges the buffs up or down from their position."] = "Fel vagy le tolja a buffokat a helyükről."
L["Nudges the crowd control icons sideways from their position."] = "Oldalra tolja a tömegirányítás-ikonokat a helyükről."
L["Nudges the crowd control icons up or down from their position."] = "Fel vagy le tolja a tömegirányítás-ikonokat a helyükről."
L["Nudges the debuffs sideways from their position."] = "Oldalra tolja a debuffokat a helyükről."
L["Nudges the debuffs up or down from their position."] = "Fel vagy le tolja a debuffokat a helyükről."
L["Nudges the dispel icon sideways from its position."] = "Oldalra tolja a levételikont a helyéről."
L["Nudges the dispel icon up or down from its position."] = "Fel vagy le tolja a levételikont a helyéről."
L["Nudges the extra auras sideways from their position."] = "Oldalra tolja az extra aurákat a helyükről."
L["Nudges the extra auras up or down from their position."] = "Fel vagy le tolja az extra aurákat a helyükről."
L["Nudges the happiness square or face sideways."] = "Oldalra tolja a boldogság-négyzetet vagy -arcot."
L["Nudges the happiness square or face up or down."] = "Fel vagy le tolja a boldogság-négyzetet vagy -arcot."
L["Nudges the leader crown sideways from its position."] = "Oldalra tolja a vezetői koronát a helyéről."
L["Nudges the leader crown up or down from its position."] = "Fel vagy le tolja a vezetői koronát a helyéről."
L["Nudges the raid marker sideways from its position."] = "Oldalra tolja a raidjelölőt a helyéről."
L["Nudges the raid marker up or down from its position."] = "Fel vagy le tolja a raidjelölőt a helyéről."
L["Nudges the ready check answer sideways from its position."] = "Oldalra tolja a készenléti választ a helyéről."
L["Nudges the ready check answer up or down from its position."] = "Fel vagy le tolja a készenléti választ a helyéről."
L["Nudges the role icon sideways from its position."] = "Oldalra tolja a szerepikont a helyéről."
L["Nudges the role icon up or down from its position."] = "Fel vagy le tolja a szerepikont a helyéről."
L["Nudges the summon icon sideways from its position."] = "Oldalra tolja az idézés ikonját a helyéről."
L["Nudges the summon icon up or down from its position."] = "Fel vagy le tolja az idézés ikonját a helyéről."
L["Nudges this indicator sideways from its position."] = "Oldalra tolja ezt a jelzőt a helyéről."
L["Nudges this indicator up or down from its position."] = "Fel vagy le tolja ezt a jelzőt a helyéről."
L["Objective text size"] = "Feladatszöveg mérete"
L["Off hand bar visibility"] = "Mellékkéz-sáv láthatósága"
L["Once you're warmed by the fire, sitting on doesn't fade your UI away again for this many minutes, so you can chat by the fire. 0 fades it every minute."] = "Ha már felmelegített a tűz, a további üldögélés ennyi percig nem halványítja el újra a felületedet, így a tűz mellett csevegni is tudsz. A 0 minden percben elhalványítja."
L["One color you pick, the accent color, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "Egy általad választott szín, a kiemelőszín, a kasztszíned, vagy a kasztod két színe színátmenetként (a Színátmenetek oldalról)."
L["One color, the Daylight gradient, or the Cast and Channel gradients from General > Gradients."] = "Egy szín, a Daylight színátmenet, vagy a Varázslás és Csatornázás színátmenetek az Általános > Színátmenetek oldalról."
L["One gradient"] = "Egy színátmenet"
L["Opening a mailbox shows Daylight UI's window: your letters, sending, and a ledger of your gold. Turn it off to use the game's own window, in Daylight UI's look, for addons that build on it. Each window also has a button to switch to the other. The ledger keeps counting either way."] = "Postaláda megnyitásakor a Daylight UI ablaka jelenik meg: a leveleid, a küldés és az aranyad főkönyve. Kapcsold ki, ha a játék saját ablakát használnád, Daylight UI kinézetben, a rá épülő addonokhoz. Mindkét ablakon van egy gomb a másikra váltáshoz. A főkönyv így is, úgy is számol."
L["Opening a profession shows Daylight UI's window: your recipes on the left, the one you picked on the right. Turn it off to use the game's own window, in Daylight UI's look, for addons that build on it. Each window also has a button to switch to the other."] = "Egy szakma megnyitásakor a Daylight UI ablaka jelenik meg: bal oldalt a receptjeid, jobb oldalt a kiválasztott. Kapcsold ki, ha a játék saját ablakát használnád, Daylight UI kinézetben, a rá épülő addonokhoz. Mindkét ablakon van egy gomb a másikra váltáshoz."
L["Opening and closing windows: bags, character, spellbook, quest log, the game menu and Daylight UI's own windows."] = "Ablakok nyitása és zárása: táskák, karakter, varázskönyv, küldetésnapló, a játékmenü és a Daylight UI saját ablakai."
L["Opening the group finder shows Daylight UI's window: groups to join, listing yourself, and who's about. Turn it off to use the game's own window, in Daylight UI's look. Each window also has a button to switch to the other."] = "A csoportkereső megnyitásakor a Daylight UI ablaka jelenik meg: csatlakozható csoportok, saját hirdetés, és ki van a környéken. Kapcsold ki, ha a játék saját ablakát használnád, Daylight UI kinézetben. Mindkét ablakon van egy gomb a másikra váltáshoz."
L["Other addons' windows in Daylight UI style. One switch per addon you have installed."] = "Más addonok ablakai Daylight UI stílusban. Telepített addononként egy kapcsoló."
L["Other cast bars' colors"] = "A többi varázslássáv színei"
L["Other faction name color"] = "A másik frakció névszíne"
L["Party and raid out of range opacity"] = "Csoport és raid hatótávon kívüli átlátszatlansága"
L["Party cast bar angled end"] = "Csoport varázslássávjának ferde vége"
L["Party cast bar background texture"] = "Csoport varázslássávjának háttértextúrája"
L["Party cast bar fills right to left"] = "Csoport varázslássávja jobbról balra töltődik"
L["Party cast bar font"] = "Csoport varázslássávjának betűtípusa"
L["Party cast bar height"] = "Csoport varázslássávjának magassága"
L["Party cast bar left / right"] = "Csoport varázslássávja balra / jobbra"
L["Party cast bar position"] = "Csoport varázslássávjának helye"
L["Party cast bar side"] = "Csoport varázslássávjának oldala"
L["Party cast bar spell icon"] = "Csoport varázslássávjának varázslatikonja"
L["Party cast bar texture"] = "Csoport varázslássávjának textúrája"
L["Party cast bar up / down"] = "Csoport varázslássávja fel / le"
L["Party cast bar width"] = "Csoport varázslássávjának szélessége"
