L["Pressing C opens Daylight UI's character window. Turn it off to use the game's own, in Daylight UI's look. Each window also has a button to switch to the other."] = "A C megnyomása a Daylight UI karakterablakát nyitja. Kapcsold ki, ha a játék sajátját használnád, Daylight UI kinézetben. Mindkét ablakon van egy gomb a másikra váltáshoz."
L["Pressing O shows Daylight UI's window: who's online, people you played with, friend requests and your raid's groups. Turn it off to use the game's own window, in Daylight UI's look. Each window also has a button to switch to the other."] = "Az O megnyomása a Daylight UI ablakát mutatja: ki van online, akikkel játszottál, barátkérések és a raided csoportjai. Kapcsold ki, ha a játék saját ablakát használnád, Daylight UI kinézetben. Mindkét ablakon van egy gomb a másikra váltáshoz."
L["Preview missing group buffs"] = "Hiányzó csoportbuffok előnézete"
L["Preview the buff bar"] = "A buff-sáv előnézete"
L["Profession window scale"] = "Szakmaablak mérete"
L["Quest item button side"] = "Küldetéstárgy-gomb oldala"
L["Quest levels in the tracker"] = "Küldetésszintek a követőben"
L["Quest log background opacity"] = "Küldetésnapló hátterének átlátszatlansága"
L["Quest pop-up scale"] = "Küldetés-felugró mérete"
L["Quest pop-up time"] = "Küldetés-felugró ideje"
L["Quest title text size"] = "Küldetéscím szövegmérete"
L["Quest titles in capitals, like the Daylight UI unit frame names. Objectives stay as they are."] = "Küldetéscímek nagybetűvel, mint a Daylight UI egységkeret-nevei. A feladatok maradnak, ahogy vannak."
L["Quest tracker background"] = "Küldetéskövető háttere"
L["Quest tracker grows upward"] = "A küldetéskövető felfelé nő"
L["Quest tracker height limit"] = "Küldetéskövető magassági korlátja"
L["Quest tracker width"] = "Küldetéskövető szélessége"
L["Raid 20 frames sit in a spot of their own, with their own handle when you unlock (/dui unlock), so a bigger raid can go where it fits. When off, they sit where Raid 10's do."] = "A Raid 20 keretek saját helyen ülnek, saját fogantyúval feloldáskor (/dui unlock), így egy nagyobb raid oda kerülhet, ahol elfér. Kikapcsolva ott ülnek, ahol a Raid 10-é."
L["Raid 20 own position"] = "Raid 20 saját helye"
L["Raid 40 frames sit in a spot of their own, with their own handle when you unlock (/dui unlock), so a bigger raid can go where it fits. When off, they sit where Raid 10's do."] = "A Raid 40 keretek saját helyen ülnek, saját fogantyúval feloldáskor (/dui unlock), így egy nagyobb raid oda kerülhet, ahol elfér. Kikapcsolva ott ülnek, ahol a Raid 10-é."
L["Raid 40 own position"] = "Raid 40 saját helye"
L["Ranged bar visibility"] = "Távolsági sáv láthatósága"
L["Ready check position"] = "Készenléti jel helye"
L["Recipe names take the rarity color of what they make. When off, they show how likely a skill-up is. The same switch sits beside the window's search."] = "A receptnevek annak a ritkasági színét kapják, amit készítenek. Kikapcsolva azt mutatják, mennyire valószínű a jártasságnövekedés. Ugyanez a kapcsoló az ablak keresője mellett is ott van."
L["Rename cooldown layout"] = "Cooldown-elrendezés átnevezése"
L["Restyled game windows"] = "Átszínezett játékablakok"
L["Revered reputation"] = "Revered hírnév"
L["Right stream max shown"] = "Jobb folyam legfeljebb"
L["Role icon position"] = "Szerepikon helye"
L["Same as Hostile"] = "Ugyanaz, mint a Hostile"
L["Same as unit frames: a class gradient when your unit frames' health bars use one. Class gradient uses the pairs from General > Gradients."] = "Ugyanaz, mint az egységkeretek: kaszt-színátmenet, ha az egységkereteid életerősávjai azt használják. A Kaszt-színátmenet az Általános > Színátmenetek párjait használja."
L["Section header text size"] = "Szakaszfejléc szövegmérete"
L["Separate damage meter window"] = "Külön sebzésmérő-ablak"
L["Sets the auras and name on this page's raid frames to the Battleground look. Click twice to confirm."] = "Ennek az oldalnak a raidkeretein az aurákat és a nevet Csatatér kinézetre állítja. Kattints kétszer a megerősítéshez."
L["Sets the auras and name on this page's raid frames to the DPS / Tank look. Click twice to confirm."] = "Ennek az oldalnak a raidkeretein az aurákat és a nevet DPS / Tank kinézetre állítja. Kattints kétszer a megerősítéshez."
L["Sets the auras and name on this page's raid frames to the Daylight UI look. Click twice to confirm."] = "Ennek az oldalnak a raidkeretein az aurákat és a nevet Daylight UI kinézetre állítja. Kattints kétszer a megerősítéshez."
L["Sets the auras and name on this page's raid frames to the Healer look. Click twice to confirm."] = "Ennek az oldalnak a raidkeretein az aurákat és a nevet Gyógyító kinézetre állítja. Kattints kétszer a megerősítéshez."
L["Sets the auras and name on this page's raid frames to the Minimal look. Click twice to confirm."] = "Ennek az oldalnak a raidkeretein az aurákat és a nevet Minimális kinézetre állítja. Kattints kétszer a megerősítéshez."
L["Sewing scene while tailoring"] = "Varrásjelenet szabáskor"
L["Shelf and List views"] = "Polc és Lista nézet"
L["Show cooldown numbers"] = "Cooldown-számok mutatása"
L["Show experience percent"] = "Tapasztalat százalékának mutatása"
L["Show hidden boss debuffs"] = "Rejtett boss-debuffok mutatása"
L["Show keybinds"] = "Billentyűk mutatása"
L["Show macro names"] = "Makrónevek mutatása"
L["Show personal health text at full"] = "Személyes életerő-szöveg teli életerőnél is"
L["Show personal power text at full"] = "Személyes erőforrás-szöveg teli erőforrásnál is"
L["Shows buff icons on each member."] = "Buff-ikonokat mutat minden tagon."
L["Shows debuff icons on each member."] = "Debuff-ikonokat mutat minden tagon."
L["Shows only the buffs on this list, with the filter above still applying. An empty list shows them all."] = "Csak az ezen a listán lévő buffokat mutatja, a fenti szűrő továbbra is érvényes. Az üres lista mindet mutatja."
L["Shows only the debuffs bosses put on players, the ones a fight is about."] = "Csak azokat a debuffokat mutatja, amiket bossok tesznek a játékosokra, amelyekről a harc szól."
L["Shows the health text large in the frame's inner corner (in Ribbon, at the inner end of the row above the bar), in the Health text color."] = "Az életerő-szöveget nagyban mutatja a keret belső sarkában (Szalagnál a sáv fölötti sor belső végén), az Életerő-szöveg színében."
L["Shows this indicator on each member while its spell is on them. Group buffs (Mark of the Wild, Fortitude, the Blessings) show from anyone, and count down their last minute."] = "Ezt a jelzőt mutatja minden tagon, amíg rajta van a varázslata. A csoportbuffok (Mark of the Wild, Fortitude, a Blessingek) bárkitől látszanak, és az utolsó percükben visszaszámolnak."
L["Size and look"] = "Méret és kinézet"
L["Size as a percent of the button's normal size: 100 is the game's own button size."] = "Méret a gomb normál méretének százalékában: a 100 a játék saját gombmérete."
L["Size, look and stacking of every plate."] = "Minden névtábla mérete, kinézete és tornyozása."
L["Small colored squares or spell icons on each member for your heals over time and shields, like Renew or Power Word: Shield. Each one shows while your spell is on them."] = "Kis színes négyzetek vagy varázslatikonok minden tagon az időbeli gyógyításaidhoz és pajzsaidhoz, mint a Renew vagy a Power Word: Shield. Mindegyik addig látszik, amíg a varázslatod rajtuk van."
L["Small icons over the focus from its left end."] = "Kis ikonok a fókusz fölött a bal végétől."
L["Small icons over your frame from its left end. Your buff bars show them too."] = "Kis ikonok a kereted fölött a bal végétől. A buff-sávjaid is mutatják őket."
L["Small icons under your pet's frame."] = "Kis ikonok a háziállatod kerete alatt."
L["Small tiles for a raid of up to 10: one column per group, left to right. Raid 20 and Raid 40 use these too while they're Same as Raid 10. Show, fade, textures and fonts here count for every raid size; your party has its own page."] = "Kis csempék legfeljebb 10 fős raidhez: csoportonként egy oszlop, balról jobbra. A Raid 20 és a Raid 40 is ezeket használja, amíg Ugyanaz, mint a Raid 10. Az itteni megjelenítés, elhalványítás, textúrák és betűtípusok minden raidméretre érvényesek; a csoportodnak saját oldala van."
L["Social window scale"] = "Közösségi ablak mérete"
L["Soft sound for quiet errors"] = "Halk hang a csendes hibákhoz"
L["Sort frames by"] = "Keretek rendezése"
L["Spellbook scale"] = "Varázskönyv mérete"
L["Stack size line"] = "Halomméret sora"
L["Summon position"] = "Idézés helye"
L["Swing timer angled left end"] = "Ütésidőzítő ferde bal vége"
L["Swing timer angled right end"] = "Ütésidőzítő ferde jobb vége"
