L["Swing timer fills right to left"] = "Ütésidőzítő jobbról balra töltődik"
L["Swing timer height"] = "Ütésidőzítő magassága"
L["Swing timer spacing"] = "Ütésidőzítő térköze"
L["Swing timer visibility"] = "Ütésidőzítő láthatósága"
L["Swing timer weapon icon"] = "Ütésidőzítő fegyverikonja"
L["Swing timer width"] = "Ütésidőzítő szélessége"
L["Swing timers grow upward"] = "Az ütésidőzítők felfelé nőnek"
L["Talent set 1 cooldown layout"] = "1. tehetségszett cooldown-elrendezése"
L["Talent set 2 cooldown layout"] = "2. tehetségszett cooldown-elrendezése"
L["Talk window look"] = "Beszélgetőablak kinézete"
L["Talking to NPCs: gossip, quests to accept and hand in, rewards to choose, vendors and trainers, all in one window, in Daylight UI style."] = "Beszélgetés NPC-kkel: beszélgetés, elfogadandó és leadandó küldetések, választandó jutalmak, árusok és oktatók, mind egy ablakban, Daylight UI stílusban."
L["Talking to an NPC opens Daylight UI's window for gossip, quests, rewards, vendors and trainers. Turn it off to use the game's own windows, in Daylight UI's look, for addons that build on them. Each window also has a button to switch to the other."] = "Ha egy NPC-vel beszélsz, a Daylight UI ablaka nyílik meg a beszélgetéshez, küldetésekhez, jutalmakhoz, árusokhoz és oktatókhoz. Kapcsold ki, ha a játék saját ablakait használnád, Daylight UI kinézetben, a rájuk épülő addonokhoz. Mindkét ablakon van egy gomb a másikra váltáshoz."
L["Target cast bar angled left end"] = "Célpont varázslássávjának ferde bal vége"
L["Target cast bar angled right end"] = "Célpont varázslássávjának ferde jobb vége"
L["Target cast bar background texture"] = "Célpont varázslássávjának háttértextúrája"
L["Target cast bar fills right to left"] = "Célpont varázslássávja jobbról balra töltődik"
L["Target cast bar font"] = "Célpont varázslássávjának betűtípusa"
L["Target cast bar height"] = "Célpont varázslássávjának magassága"
L["Target cast bar left / right"] = "Célpont varázslássávja balra / jobbra"
L["Target cast bar matches the frame's width"] = "Célpont varázslássávja a keret szélességéhez igazodik"
L["Target cast bar position"] = "Célpont varázslássávjának helye"
L["Target cast bar spell icon"] = "Célpont varázslássávjának varázslatikonja"
L["Target cast bar texture"] = "Célpont varázslássávjának textúrája"
L["Target cast bar up / down"] = "Célpont varázslássávja fel / le"
L["Target cast bar width"] = "Célpont varázslássávjának szélessége"
L["Target highlight in accent color"] = "Célpont kiemelése kiemelőszínben"
L["Text size of the time left on each icon. At 0 it follows the icon's size."] = "A hátralévő idő szövegmérete minden ikonon. 0-nál az ikon méretét követi."
L["The Daylight UI border, the item's quality color, your accent color (General > Appearance), or a color you pick."] = "A Daylight UI keret, a tárgy minőségi színe, a kiemelőszíned (Általános > Megjelenés), vagy egy általad választott szín."
L["The Legacy button shows Daylight UI's window: how far the next reward is, the challenges and the Legacy trees. Turn it off to use the game's own window, in Daylight UI's look. Each window also has a button to switch to the other."] = "A Legacy gomb a Daylight UI ablakát mutatja: mennyire van a következő jutalom, a kihívások és a Legacy-fák. Kapcsold ki, ha a játék saját ablakát használnád, Daylight UI kinézetben. Mindkét ablakon van egy gomb a másikra váltáshoz."
L["The NPC job's color when Friendly job color is One color."] = "Az NPC-foglalkozás színe, ha a Barátságos foglalkozásszín Egy szín."
L["The Quests and Achievements headings."] = "A Küldetések és az Achievementek fejléc."
L["The aggro color when Aggro color is One color."] = "Az aggrószín, ha az Aggro színe Egy szín."
L["The arrow's color while Arrow color is set to One color."] = "A nyíl színe, amíg a Nyíl színe Egy szín értéken áll."
L["The arrows' color when Arrow color is One color."] = "A nyilak színe, ha a Nyíl színe Egy szín."
L["The bag's picture, name and free slots above the search box. When off, the search box sits at the top with a small bank button next to the close button, and you drag the window by any empty spot."] = "A táska képe, neve és szabad helyei a keresőmező fölött. Kikapcsolva a keresőmező felül ül, a bezárás gomb mellett egy kis bankgombbal, és az ablakot bármelyik üres helyénél fogva húzhatod."
L["The bar's color for dead and offline players and tapped NPCs, and for NPCs by how they feel about you. The NPC colors show with Class and reaction or Dark; Class gradient uses the pairs on General > Gradients."] = "A sáv színe halott és offline játékosoknál, megcímkézett NPC-knél, és az NPC-knél aszerint, hogyan viszonyulnak hozzád. Az NPC-színek a Kaszt és viszony vagy a Sötét beállítással látszanak; a Kaszt-színátmenet az Általános > Színátmenetek párjait használja."
L["The bars fill from the right. Only when detached as a group."] = "A sávok jobbról töltődnek. Csak csoportként leválasztva."
L["The border color of every loot feed line when Loot feed border color is One color."] = "Minden zsákmánysor keretszíne, ha a Zsákmánysáv keretszíne Egy szín."
L["The border color when Border color is One color."] = "A keretszín, ha a Keretszín Egy szín."
L["The border color when Chat border color is set to One color."] = "A keretszín, ha a Chat keretszíne Egy szín értéken áll."
L["The border in a player's class color, other units in their reaction color."] = "A keret a játékos kasztszínében, más egységeknél a viszonyuk színében."
L["The border of a debuff you can dispel, and the raid tile's dispel icon."] = "Egy levehető debuff kerete, és a raidcsempe levételikonja."
L["The boss debuffs addons can't read, drawn by the game: up to two big icons in the middle, with a sweep for the time left. They only appear when a boss uses them."] = "Az addonok által nem olvasható boss-debuffok, amiket a játék rajzol ki: legfeljebb két nagy ikon középen, a hátralévő időt jelző söpréssel. Csak akkor jelennek meg, ha egy boss használja őket."
L["The cast bar's color when Cast bar fill style is One color."] = "A varázslássáv színe, ha a Varázslássáv kitöltési stílusa Egy szín."
L["The class-colored border in the unit's class (or reaction) gradient from General > Gradients, running left to right."] = "A kasztszínű keret az egység kaszt- (vagy viszony-) színátmenetében az Általános > Színátmenetek oldalról, balról jobbra futva."
L["The color of a ring, name tab or raid tile while something is attacking the unit: the Hostile color, or one you pick."] = "Egy gyűrű, névfül vagy raidcsempe színe, amíg valami támadja az egységet: az Ellenséges szín, vagy egy általad választott."
L["The color used while Header line color is set to One color."] = "A használt szín, amíg a Fejlécvonal színe Egy szín értéken áll."
L["The color used while Section header color is set to One color."] = "A használt szín, amíg a Szakaszfejléc színe Egy szín értéken áll."
L["The color used while Zone name color is set to One color."] = "A használt szín, amíg a Zónanév színe Egy szín értéken áll."
L["The cooldown edge's color when Cooldown edge is One color."] = "A cooldown-él színe, ha a Cooldown-él Egy szín."
L["The data texts, the data bar, and the clock, framerate, zone name and coordinates on the minimap. General uses the font on General > Appearance."] = "Az adatszövegek, az adatsáv, valamint az óra, a képkockasebesség, a zónanév és a koordináták a minitérképen. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The edge around each button."] = "A szegély minden gomb körül."
L["The empty part behind the bars in Daylight UI's windows. General uses the bar background above."] = "Az üres rész a sávok mögött a Daylight UI ablakaiban. Az Általános a fenti sávhátteret használja."
L["The empty part of every health and power bar: a dimmed copy of the bar's own color, or one you pick."] = "Minden életerő- és erőforrássáv üres része: a sáv saját színének halványított másolata, vagy egy általad választott."
L["The empty part's color when Bar background color is One color."] = "Az üres rész színe, ha a Sávháttér színe Egy szín."
L["The fill of the bars in Daylight UI's windows: reputation, skills, professions, pet experience, quest objectives. They keep their round shape. General uses the bar texture above."] = "A sávok kitöltése a Daylight UI ablakaiban: hírnév, jártasságok, szakmák, háziállat-tapasztalat, küldetésfeladatok. Megtartják a lekerekített alakjukat. Az Általános a fenti sávtextúrát használja."
L["The friendly health bar's color when Friendly health bar color is One color."] = "A barátságos életerősáv színe, ha a Barátságos életerősáv színe Egy szín."
L["The game's chat menu, channel, voice and social buttons next to chat, for Chat style: Classic. The Daylight chat box has its own menu and voice buttons. When off, they're gone; their slash commands still work."] = "A játék chatmenü-, csatorna-, hang- és közösségi gombjai a chat mellett, Klasszikus chatstílushoz. A Daylight chatdoboznak saját menü- és hanggombjai vannak. Kikapcsolva eltűnnek; a perjeles parancsaik továbbra is működnek."
L["The game's new-player tips (the game setting 'Tutorials'). When off, the game's tutorial tips are switched off."] = "A játék új játékosoknak szóló tippjei (a 'Tutorials' játékbeállítás). Kikapcsolva a játék tutorial-tippjei ki vannak kapcsolva."
L["The game's numbers that pop off what you hit and heal. Hits and heals on you: General > Combat text."] = "A játék számai, amik a megütött és gyógyított célpontról pattannak le. A rajtad lévő találatok és gyógyítások: Általános > Harci szöveg."
L["The game's own buff frames show beside Daylight UI's bars. When off, Daylight UI's bars replace them (the game's still show while Edit Mode is open)."] = "A játék saját buffkeretei a Daylight UI sávjai mellett látszanak. Kikapcsolva a Daylight UI sávjai váltják ki őket (a játékéi a Szerkesztő mód nyitva tartása alatt továbbra is látszanak)."
L["The game's own windows in Daylight UI style: Daylight UI borders, window background, font, controls and scroll bars."] = "A játék saját ablakai Daylight UI stílusban: Daylight UI keretek, ablakháttér, betűtípus, vezérlők és görgetősávok."
L["The game's tooltips in the Daylight UI look."] = "A játék súgóbuborékai Daylight UI kinézetben."
L["The gap between lines of tiles, like one raid group and the next."] = "Rés a csempesorok között, például egyik raidcsoport és a következő között."
L["The gap between one raid tile and the next in a line."] = "Rés két raidcsempe között egy sorban."
L["The gap between the swing timer bars. Only when detached as a group."] = "Rés az ütésidőzítő-sávok között. Csak csoportként leválasztva."
L["The glow behind your character in this color, when Glow color is One color."] = "A karaktered mögötti fény ebben a színben, ha a Fény színe Egy szín."
L["The guide that set this character up, to run again: a quick setup, every step page by page, or another profile."] = "Az útmutató, ami beállította ezt a karaktert, újrafuttatáshoz: gyors beállítás, minden lépés oldalanként, vagy egy másik profil."
L["The guild name's color when Friendly guild color is One color."] = "A céhnév színe, ha a Barátságos céhszín Egy szín."
L["The health numbers on the nameplates, and the level and threat % when they follow it. General uses the font on General > Appearance."] = "Az életerőszámok a névtáblákon, valamint a szint és a fenyegetés %, ha ezt követik. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The health text's color when Health text color is One color."] = "Az életerő-szöveg színe, ha az Életerő-szöveg színe Egy szín."
L["The highlight's color when Active spell color is One color."] = "A kiemelés színe, ha az Aktív varázslat színe Egy szín."
L["The icons wrap onto up to this many rows."] = "Az ikonok legfeljebb ennyi sorba tördelődnek."
L["The indicator's color when Heal indicator color is One color."] = "A jelző színe, ha a Gyógyításjelző színe Egy szín."
L["The item level at the bottom in your gear's quality color, durability green to yellow to red. When off, both are plain white."] = "A tárgyszint alul a felszerelésed minőségi színében, a tartósság zöldtől sárgán át pirosig. Kikapcsolva mindkettő sima fehér."
L["The line under the open tab in this color, when Tab underline is One color."] = "A nyitott fül alatti vonal ebben a színben, ha a Fül aláhúzása Egy szín."
L["The lines under the headers in this color, when Header lines is One color."] = "A fejlécek alatti vonalak ebben a színben, ha a Fejlécvonalak Egy szín."
L["The look shared by everything Daylight UI draws."] = "A kinézet, amin minden osztozik, amit a Daylight UI rajzol."
L["The main hand bar fills from the right. Only when detached on its own."] = "A főkéz-sáv jobbról töltődik. Csak önállóan leválasztva."
L["The mark shows what the quest wants from it, the way the map does: a sword to kill, a bag to loot, a cog to use, an eye to explore, in the quest's color. Needs the Quests module; without it, the mark is a !."] = "A jel azt mutatja, mit akar tőle a küldetés, ahogy a térkép: kard az öléshez, zsák a zsákmányoláshoz, fogaskerék a használathoz, szem a felfedezéshez, a küldetés színében. Kell hozzá a Küldetések modul; nélküle a jel egy !."
L["The marker over the spot of the quest you picked (click its icon in the tracker) in Daylight UI style, with the distance. It fades away once you're in the quest's area on the map. Turn it off to see the game's own marker."] = "A jelölő a kiválasztott küldetés helye fölött (kattints az ikonjára a követőben) Daylight UI stílusban, a távolsággal. Elhalványul, amint a küldetés területén vagy a térképen. Kapcsold ki, ha a játék saját jelölőjét látnád."
L["The mouseover border's color when Mouseover border color is One color."] = "Az egér alatti keret színe, ha az Egér alatti keretszín Egy szín."
L["The name's color when Name color is One color."] = "A név színe, ha a Névszín Egy szín."
L["The numbers over what your pet or totems hit."] = "A számok afölött, amit a háziállatod vagy a totemjeid megütnek."
L["The off hand bar fills from the right. Only when detached on its own."] = "A mellékkéz-sáv jobbról töltődik. Csak önállóan leválasztva."
L["The order of the quests within each zone. Most recent progress moves a quest and its zone to the top when a kill, item or objective counts. Nearest first looks again every few seconds as you move, never in a fight or a dungeon. Nothing moves in a fight."] = "A küldetések sorrendje zónánként. A Legutóbbi haladás egy küldetést és a zónáját a tetejére viszi, ha egy ölés, tárgy vagy feladat beszámít. A Legközelebbi elöl mozgás közben néhány másodpercenként újranéz, harcban vagy kazamatában soha. Harc közben semmi sem mozdul."
L["The outline's color when Target outline color is One color."] = "A körvonal színe, ha a Célpont körvonalának színe Egy szín."
L["The overshield's color when Overshield color is One color."] = "A túlpajzs színe, ha a Túlpajzs színe Egy szín."
L["The pressed border's color when Pressed border color is One color."] = "A lenyomott keret színe, ha a Lenyomott keretszín Egy szín."
L["The priority quest's color while Priority quest color is set to One color."] = "A kiemelt küldetés színe, amíg a Kiemelt küldetés színe Egy szín értéken áll."
L["The profile this character uses while the game's controller UI is on (Settings > Gameplay > Gamepad). Turning it on or off asks to switch. With None, it uses the same profile as without it."] = "A profil, amit ez a karakter használ, amíg a játék kontroller-felülete be van kapcsolva (Settings > Gameplay > Gamepad). Be- vagy kikapcsoláskor váltást kér. A Nincs esetén ugyanazt a profilt használja, mint nélküle."
L["The progress bars' color while Progress bar color is set to One color."] = "A haladássávok színe, amíg a Haladássáv színe Egy szín értéken áll."
L["The ranged bar fills from the right. Only when detached on its own."] = "A távolsági sáv jobbról töltődik. Csak önállóan leválasztva."
L["The ring's color when Cursor ring color is One color."] = "A gyűrű színe, ha a Kurzorgyűrű színe Egy szín."
L["The size of the messages in every chat window. Each chat tab's right-click menu sets it too."] = "Az üzenetek mérete minden chatablakban. Minden chatfül jobb klikkes menüje is beállítja."
L["The soft light moving round the main button of a Daylight UI window (Accept, Complete, Send...), in the style you pick, or Off for none. Needs Motion effects (General > Appearance)."] = "A Daylight UI ablakok fő gombja (Elfogadás, Teljesítés, Küldés...) körül futó lágy fény, a választott stílusban, vagy Ki, ha nem kell. Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["The sound when someone whispers you. The first five are gentle chimes made for Daylight UI; picking one plays it once."] = "A hang, amikor valaki suttog neked. Az első öt a Daylight UI-hoz készült lágy csengés; kiválasztáskor egyszer lejátssza."
L["The spell's icon at the end of your cast bar. Not while under the frame, where the portrait ring covers that spot."] = "A varázslat ikonja a varázslássávod végén. Nem, ha a keret alatt van, ahol a portrégyűrű takarja azt a helyet."
L["The spellbook and talent keys open Daylight UI's window. Turn it off to use the game's own window, in Daylight UI's look, for addons that build on it. Each window also has a button to switch to the other."] = "A varázskönyv és a tehetségek gombja a Daylight UI ablakát nyitja. Kapcsold ki, ha a játék saját ablakát használnád, Daylight UI kinézetben, a rá épülő addonokhoz. Mindkét ablakon van egy gomb a másikra váltáshoz."
L["The target, focus and party cast bars' color for a moment after their cast is interrupted."] = "A célpont, a fókusz és a csoport varázslássávjainak színe egy pillanatig azután, hogy megszakították a varázslásukat."
L["The target, focus and party cast bars' color while they cast."] = "A célpont, a fókusz és a csoport varázslássávjainak színe varázslás közben."
L["The target, focus and party cast bars' color while they channel."] = "A célpont, a fókusz és a csoport varázslássávjainak színe csatornázás közben."
L["The text in Daylight UI's windows (character, spellbook, professions, bags, quest journal) and the game's windows it restyles. General uses the font above."] = "A szöveg a Daylight UI ablakaiban (karakter, varázskönyv, szakmák, táskák, küldetésnapló) és a játék általa átszínezett ablakaiban. Az Általános a fenti betűtípust használja."
L["The text scrolling around your character: hits you take, heals, procs and more. Numbers over what you hit: General > Damage numbers."] = "A karaktered körül görgő szöveg: kapott ütések, gyógyítások, procok és még sok más. A megütött célpont fölötti számok: Általános > Sebzésszámok."
L["The two-color pairs behind the gradient accent, bars, cast bars, reputation and more, wherever a gradient is picked."] = "A kétszínű párok a színátmenetes kiemelés, a sávok, a varázslássávok, a hírnév és még sok más mögött, ahol színátmenet van kiválasztva."
L["The unit's name, in a small tab above the frame. Long names are cut short."] = "Az egység neve, egy kis fülben a keret fölött. A hosszú nevek rövidülnek."
L["The usual health bar color. Tapped mobs, Threat colors on the health bar and Special mobs paint over it."] = "A szokásos életerősáv-szín. A megcímkézett mobok, az életerősávon lévő Fenyegetésszínek és a Különleges mobok felülfestik."
L["The weapon's picture at the start of each bar. Only when detached as a group."] = "A fegyver képe minden sáv elején. Csak csoportként leválasztva."
L["The window background, when Window background color is One color. Dark colors keep text easy to read."] = "Az ablakháttér, ha az Ablakháttér színe Egy szín. A sötét színekkel a szöveg könnyen olvasható marad."
L["The window hides out of combat. With more than one of these on, it shows only when all of them hold."] = "Az ablak harcon kívül rejtve van. Ha ezek közül több is be van kapcsolva, csak akkor látszik, ha mindegyik teljesül."
L["The world map's quest list and quest pages in Daylight UI style, with Track, Share and Abandon on each quest. Turn it off to use the game's own."] = "A világtérkép küldetéslistája és küldetésoldalai Daylight UI stílusban, minden küldetésen Követés, Megosztás és Feladás gombbal. Kapcsold ki, ha a játék sajátját használnád."
L["The zone name's color when Minimap zone name color is One color."] = "A zónanév színe, ha a Minitérkép-zónanév színe Egy szín."
L["Their color when Active border and glow color is One color."] = "A színük, ha az Aktív keret- és fényszín Egy szín."
L["Their health as text by the bar."] = "Az életerejük szövegként a sáv mellett."
L["Their level by the bar."] = "A szintjük a sáv mellett."
L["This frame's health text. General uses the font on General > Appearance."] = "Ennek a keretnek az életerő-szövege. Az Általános az Általános > Megjelenés betűtípusát használja."
L["This frame's names. General uses the font on General > Appearance."] = "Ennek a keretnek a nevei. Az Általános az Általános > Megjelenés betűtípusát használja."
L["Time left on buffs"] = "Hátralévő idő a buffokon"
L["Time left on crowd control icons"] = "Hátralévő idő a tömegirányítás-ikonokon"
L["Time left on debuffs"] = "Hátralévő idő a debuffokon"
L["Time left on extra auras"] = "Hátralévő idő az extra aurákon"
L["Tooltip position"] = "Súgóbuborék helye"
L["Tooltip scale"] = "Súgóbuborék mérete"
L["Tooltip text size"] = "Súgóbuborék szövegmérete"
L["Top stream max shown"] = "Felső folyam legfeljebb"
L["Totem timers"] = "Totem-időzítők"
L["Unfriendly reputation"] = "Unfriendly hírnév"
L["Unlocks every frame, so each text stream shows a handle too. Drag one to move it."] = "Minden keretet felold, így minden szövegfolyam is fogantyút kap. Húzz egyet a mozgatásához."
L["Use Daylight UI's Cooldown Manager"] = "A Daylight UI Cooldown-kezelőjének használata"
L["Use Daylight UI's quest tracker"] = "A Daylight UI küldetéskövetőjének használata"
L["Use these textures everywhere"] = "Ezeknek a textúráknak a használata mindenhol"
L["Use this font everywhere"] = "Ennek a betűtípusnak a használata mindenhol"
L["Uses the Raid 10 frames, and the rest of this page is hidden. Turn it off to give this raid size its own, starting from a copy of Raid 10."] = "A Raid 10 kereteit használja, és az oldal többi része rejtve van. Kapcsold ki, ha ennek a raidméretnek sajátot adnál, a Raid 10 másolatából indulva."
L["Uses the game's own font in place of Daylight UI's fonts, which only have Latin letters. The options window changes after /reload."] = "A játék saját betűtípusát használja a Daylight UI betűtípusai helyett, amikben csak latin betűk vannak. A beállításablak /reload után változik."
L["View distance"] = "Látótávolság"
L["Weapon master locations"] = "Fegyvermesterek helye"
L["What Ctrl-click on a quest does. Your priority quest is the one the marker and arrow lead to."] = "Mit csinál a Ctrl+kattintás egy küldetésen. A kiemelt küldetésed az, amelyikhez a jelölő és a nyíl vezet."
L["What Shift-click on a quest does. With chat open it links the quest first."] = "Mit csinál a Shift+kattintás egy küldetésen. Nyitott chatnél előbb linkeli a küldetést."
L["What a target's, focus's or party member's cast bar does when its cast is interrupted. Your own interrupts light up in your accent color."] = "Mit csinál egy célpont, fókusz vagy csoporttag varázslássávja, amikor megszakítják a varázslását. A saját megszakításaid a kiemelőszínedben villannak fel."
L["What the tracker does when you enter a dungeon, raid or battleground. It comes back as you leave. This zone only keeps the quests for where you are; the All button over the list shows the rest until you leave."] = "Mit csinál a követő, amikor kazamatába, raidbe vagy csatatérre lépsz. Kilépéskor visszajön. A Csak ez a zóna csak az aktuális helyed küldetéseit tartja meg; a lista fölötti Mind gomb a többit is mutatja, amíg ki nem lépsz."
L["When off, the damage meters fade with the info panel. When on, every damage meter and summary window follows the settings here, the one in the panel too."] = "Kikapcsolva a sebzésmérők az infópanellel együtt halványulnak. Bekapcsolva minden sebzésmérő- és összegzőablak az itteni beállításokat követi, a panelben lévő is."
L["When off, the experience bar fades with the panel. When on, it follows the settings here, attached or separate."] = "Kikapcsolva a tapasztalatsáv a panellel együtt halványul. Bekapcsolva az itteni beállításokat követi, csatolva vagy külön."
L["When the cursor ring shows"] = "Mikor látszik a kurzorgyűrű"
L["When the threat meter slides out by itself in a fight: in a group or with a pet, only while you're the tank, or only when you click its tab. It never slides out by itself while you play solo, since all the threat is on you then. The threat meter beside the meter slides back once the fight ends, and a click on its tab overrides this until the next fight. A threat window of your own set to Only from its tab shows in every fight in a group."] = "Mikor csúszik ki magától a fenyegetésmérő harcban: csoportban vagy háziállattal, csak ha te vagy a tank, vagy csak ha a fülére kattintasz. Egyedül játszva sosem csúszik ki magától, mert akkor minden fenyegetés rajtad van. A mérő melletti fenyegetésmérő a harc végén visszacsúszik, és a fülére kattintás ezt felülírja a következő harcig. A Csak a füléről beállítású saját fenyegetésablak csoportban minden harcban látszik."
L["Where on the frame this indicator sits."] = "Hol ül ez a jelző a kereten."
L["Where the buff icons sit, on or around the frame. When debuffs and buffs share a spot over or under the frame, the buffs sit nearest it. Outside spots may need room around the frame."] = "Hol ülnek a buff-ikonok, a kereten vagy körülötte. Ha a debuffok és a buffok egy helyen osztoznak a keret fölött vagy alatt, a buffok ülnek hozzá legközelebb. A külső helyekhez a keret körül hely kellhet."
L["Where the buffs sit, on or around each frame. Outside spots may need more space between frames."] = "Hol ülnek a buffok, minden kereten vagy körülötte. A külső helyekhez több hely kellhet a keretek között."
L["Where the crowd control icons sit, on or around each frame. Outside spots may need more space between frames."] = "Hol ülnek a tömegirányítás-ikonok, minden kereten vagy körülötte. A külső helyekhez több hely kellhet a keretek között."
L["Where the debuff icons sit, on or around the frame. When debuffs and buffs share a spot over or under the frame, the buffs sit nearest it. Outside spots may need room around the frame."] = "Hol ülnek a debuff-ikonok, a kereten vagy körülötte. Ha a debuffok és a buffok egy helyen osztoznak a keret fölött vagy alatt, a buffok ülnek hozzá legközelebb. A külső helyekhez a keret körül hely kellhet."
L["Where the debuffs sit, on or around each frame. Outside spots may need more space between frames."] = "Hol ülnek a debuffok, minden kereten vagy körülötte. A külső helyekhez több hely kellhet a keretek között."
L["Where the extra auras sit, on or around each frame. Outside spots may need more space between frames."] = "Hol ülnek az extra aurák, minden kereten vagy körülötte. A külső helyekhez több hely kellhet a keretek között."
L["Where the happiness square or face sits, on or around the frame."] = "Hol ül a boldogság-négyzet vagy -arc, a kereten vagy körülötte."
L["Where the level badge sits: on the portrait, or any spot on or around the frame. You can also drag it in Design mode."] = "Hol ül a szintjelvény: a portrén, vagy bármely helyen a kereten vagy körülötte. Tervező módban húzással is mozgathatod."
L["Which cooldown layout this talent set uses. Your class's layouts show here, from every character of this class."] = "Melyik cooldown-elrendezést használja ez a tehetségszett. Itt a kasztod elrendezései látszanak, ennek a kasztnak minden karakteréről."
L["Which of the six indicators the rows below set."] = "A hat jelző közül melyiket állítják az alábbi sorok."
L["While the panel is away, how many seconds each message stays before it fades. A new message doesn't bring old ones back. Move the mouse over the chat to see them all again."] = "Amíg a panel távol van, minden üzenet ennyi másodpercig marad, mielőtt elhalványul. Egy új üzenet nem hozza vissza a régieket. Vidd az egeret a chat fölé, hogy újra mindet lásd."
L["While you have a target, your target's plate and all other plates use the sizes below (relative to Health bar width, Health bar height and Nameplate scale)."] = "Amíg van célpontod, a célpontod névtáblája és minden más névtábla az alábbi méreteket használja (az Életerősáv szélességéhez, az Életerősáv magasságához és a Névtábla méretéhez képest)."
L["Whisper preview time"] = "Suttogás-előnézet ideje"
L["Whisper side"] = "Suttogás oldala"
L["Whisper tile picture"] = "Suttogás-csempe képe"
L["Whisper tile size"] = "Suttogás-csempe mérete"
L["Whose gold the Gold text's tooltip lists and adds up: every character, or only those of the faction you're playing. A character counts for its faction once it has logged in with Daylight UI 1.8 or later."] = "Kinek az aranyát listázza és adja össze az Arany szöveg súgóbuboréka: minden karakterét, vagy csak a játszott frakcióét. Egy karakter akkor számít a frakciójába, ha már belépett Daylight UI 1.8-cal vagy újabbal."
L["Window background color"] = "Ablakháttér színe"
L["Window width"] = "Ablak szélessége"
L["With the experience bar above off, show the game's own bar at the bottom of the screen. When off, there's no experience bar at all."] = "Ha a fenti tapasztalatsáv ki van kapcsolva, a játék saját sávját mutatja a képernyő alján. Kikapcsolva egyáltalán nincs tapasztalatsáv."
L["With the portrait on its own, the crown, PvP flag and level badge stay on the frame instead of going with it."] = "Önálló portrénál a korona, a PvP-jelzés és a szintjelvény a kereten marad, nem megy vele."
L["With the portrait on its own, the crown, PvP flag, level badge and DoT skull stay on the frame instead of going with it."] = "Önálló portrénál a korona, a PvP-jelzés, a szintjelvény és a DoT-koponya a kereten marad, nem megy vele."
L["With the portrait on its own, the crown, resting Zzz, PvP flag and level badge stay on the frame instead of going with it."] = "Önálló portrénál a korona, a pihenés Zzz, a PvP-jelzés és a szintjelvény a kereten marad, nem megy vele."
L["Workshop scene while engineering"] = "Műhelyjelenet mérnökösködéskor"
L["Write the words out slowly"] = "A szavak lassú kiírása"
L["Your Legacy Points, their rewards, the challenges that earn them and the Legacy trees, in one window, in Daylight UI style."] = "Az Örökségpontjaid, a jutalmaik, az őket adó kihívások és a Legacy-fák egy ablakban, Daylight UI stílusban."
L["Your cast bar angled left end"] = "Varázslássávod ferde bal vége"
L["Your cast bar angled right end"] = "Varázslássávod ferde jobb vége"
L["Your cast bar background texture"] = "Varázslássávod háttértextúrája"
L["Your cast bar fills from the right. Not while under the frame."] = "A varázslássávod jobbról töltődik. Nem, ha a keret alatt van."
L["Your cast bar fills right to left"] = "Varázslássávod jobbról balra töltődik"
L["Your cast bar font"] = "Varázslássávod betűtípusa"
L["Your cast bar height"] = "Varázslássávod magassága"
L["Your cast bar layer"] = "Varázslássávod rétege"
L["Your cast bar left / right"] = "Varázslássávod balra / jobbra"
L["Your cast bar position"] = "Varázslássávod helye"
L["Your cast bar slides out from"] = "A varázslássávod innen csúszik ki:"
L["Your cast bar spell icon"] = "Varázslássávod varázslatikonja"
L["Your cast bar texture"] = "Varázslássávod textúrája"
L["Your cast bar up / down"] = "Varázslássávod fel / le"
L["Your cast bar width"] = "Varázslássávod szélessége"
L["Your friends, recent allies, friend requests and the raid, in one window, in Daylight UI style."] = "A barátaid, friss szövetségeseid, barátkéréseid és a raid, egy ablakban, Daylight UI stílusban."
L["Your letters, sending, and what you made through the mail and the auction house, in one window, in Daylight UI style."] = "A leveleid, a küldés, és amit a postán és az aukciósházon keresztül kerestél, egy ablakban, Daylight UI stílusban."
L["Your own accent, when Accent color is Custom color."] = "A saját kiemelésed, ha a Kiemelőszín Egyedi szín."
L["Your own buffs and heals over time on friendly plates, in a row."] = "A saját buffjaid és időbeli gyógyításaid a barátságos névtáblákon, egy sorban."
L["Your own debuffs on each enemy plate, in a row by the health bar."] = "A saját debuffjaid minden ellenséges névtáblán, egy sorban az életerősáv mellett."
L["Your own layout on this character. When off, this character's spells show where the game puts them, still in Daylight UI's look, for both talent sets, and your picks above wait until you turn it back on. Picking None for a talent set does the same for that set alone. Saved for this character."] = "A saját elrendezésed ezen a karakteren. Kikapcsolva ennek a karakternek a varázslatai ott látszanak, ahová a játék teszi őket, továbbra is Daylight UI kinézetben, mindkét tehetségszettnél, és a fenti választásaid várnak, amíg vissza nem kapcsolod. Egy tehetségszettnél a Nincs választása csak annál a szettnél teszi ugyanezt. Ennél a karakternél mentve."
L["Your party: bars like your own frame, or square tiles (Portrait None and Name on the bar). Set how they line up, what shows, and move them as one in unlock mode."] = "A csoportod: sávok, mint a saját kereted, vagy négyzetes csempék (Portré: Nincs, és Név a sávon). Állítsd be, hogyan sorakoznak, mi látszik, és feloldott módban egyben mozgasd őket."
L["Your profession's recipes in one window, in Daylight UI style."] = "A szakmád receptjei egy ablakban, Daylight UI stílusban."
L["Your spellbook and talents in one window, in Daylight UI style."] = "A varázskönyved és a tehetségeid egy ablakban, Daylight UI stílusban."
L["Your stances, forms, stealth and the page keys swap this bar's buttons, as in the game. When off, it always shows its own buttons. Vehicles still take it over."] = "A tartásaid, formáid, a lopakodás és a lapgombok cserélik ennek a sávnak a gombjait, ahogy a játékban. Kikapcsolva mindig a saját gombjait mutatja. A járművek továbbra is átveszik."
L["Zone names in the tracker"] = "Zónanevek a követőben"
L["[G] for General, [T] for Trade, [G] for guild (told apart from General by its guild green), [P] for party, [S] for say, [Y] for yell, [W] for whispers. Lines already in chat stay as they were. Right-click a chat tab and pick Channels to set your own tags."] = "[G] a Generalnak, [T] a Trade-nek, [G] a céhnek (a Generaltól a céhzöldje különbözteti meg), [P] a csoportnak, [S] a mondásnak, [Y] a kiabálásnak, [W] a suttogásoknak. A chatben már lévő sorok maradnak, ahogy voltak. Jobb klikk egy chatfülön, és a Csatornák menüpontban beállíthatod a saját címkéidet."
L["NEXT REWARD"] = "KÖVETKEZŐ JUTALOM"
L["At rank %d"] = "%d. rangnál"
L["English"] = "Angol"
L["Leave a field empty to use the default."] = "Hagyj üresen egy mezőt az alapértékhez."
L["Numbered channels keep their number in front of the short tag."] = "A számozott csatornák a rövid címke előtt megtartják a számukat."
L["A short tag before each message instead of the channel's or chat's name, like [G] or [P]. Lines already in chat stay as they were."] = "Rövid címke minden üzenet előtt a csatorna vagy a chat neve helyett, mint a [G] vagy a [P]. A chatben már lévő sorok maradnak, ahogy voltak."
L["Tag letters"] = "Címkebetűk"
L["The short tags start from your language's words (G for Grupo) or from English (P for Party). A tag you type in the list always wins."] = "A rövid címkék a nyelved szavaiból indulnak (G a Grupóból), vagy az angolból (P a Partyból). A listába beírt címke mindig nyer."
L["Your language"] = "A nyelved"
L["Your own short tags"] = "A saját rövid címkéid"
L["Quest tooltip detail"] = "Küldetés-súgóbuborék részletessége"
L["Full quest details"] = "Teljes küldetésrészletek"
L["What a quest's tooltip shows. Objectives keeps it short; Full quest details adds the quest's story and every reward, like Quest details from its menu."] = "Mit mutat egy küldetés súgóbuboréka. A Feladatok röviden tartja; a Teljes küldetésrészletek hozzáadja a küldetés történetét és minden jutalmát, mint a menüjéből elérhető Küldetés részletei."
L["0 leaves just the bar, with no outline round it."] = "A 0 csak a sávot hagyja meg, körvonal nélkül."
L["A colored part after your experience shows what the quests you can turn in will give. Hover the bar for the total."] = "A tapasztalatod utáni színes rész azt mutatja, mennyit adnak a leadható küldetéseid. Vidd a sáv fölé az egeret az összegért."
L["Attached to the info panel, the bar follows the panel's border. Turn on its own look to give it a border, corners and shadow of its own."] = "Az infópanelhez csatolva a sáv a panel keretét követi. Kapcsold be a saját kinézetét, ha saját keretet, sarkokat és árnyékot adnál neki."
L["Experience bar border and shadow"] = "Tapasztalatsáv kerete és árnyéka"
L["Experience bar size"] = "Tapasztalatsáv mérete"
L["Finished quests color"] = "Kész küldetések színe"
L["Gives the bar the border, corners and shadow below. When off, it takes the panel's style (attached) or General > Appearance's (separate)."] = "A sáv megkapja az alábbi keretet, sarkokat és árnyékot. Kikapcsolva a panel stílusát veszi fel (csatolva), vagy az Általános > Megjelenését (külön)."
L["How far the bar's shadow spreads. 0 leaves no shadow."] = "Milyen messzire terül a sáv árnyéka. A 0 árnyék nélkül hagyja."
L["How round the bar's corners are. 0 keeps them sharp."] = "Mennyire kerekek a sáv sarkai. A 0 élesen hagyja őket."
L["How tall the experience bar is, on the panel or on its own."] = "Milyen magas a tapasztalatsáv, a panelen vagy önállóan."
L["Reputation bar border and shadow"] = "Hírnévsáv kerete és árnyéka"
L["Rested XP color"] = "Pihent XP színe"
L["Daylight UI's chat box, with whispers as conversations, or the game's own windows (Classic)."] = "A Daylight UI chatdoboza, a suttogásokkal beszélgetésként, vagy a játék saját ablakai (Klasszikus)."
L["The color of the part that shows the XP from quests you can turn in."] = "Annak a résznek a színe, ami a leadható küldetésekből járó XP-t mutatja."
L["The color of the part that shows your rested XP, after your experience."] = "Annak a résznek a színe, ami a pihent XP-det mutatja, a tapasztalatod után."
L["The damage meter and minimap fade together (and the separate meter windows, if used). So does the experience bar, unless you give it its own fade on the Experience bar page. The damage meters can have their own on the Meters page."] = "A sebzésmérő és a minitérkép együtt halványul el (és a külön mérőablakok is, ha használod). A tapasztalatsáv is, hacsak a Tapasztalatsáv oldalon nem adsz neki saját elhalványítást. A sebzésmérőknek a Mérők oldalon lehet sajátjuk."
L["The empty part of the experience and reputation bars, behind the fill. General uses the bar background on General > Appearance."] = "A tapasztalat- és hírnévsávok üres része a kitöltés mögött. Az Általános az Általános > Megjelenés sávhátterét használja."
L["What the experience and reputation bars show, how they look and where they sit."] = "Mit mutatnak a tapasztalat- és hírnévsávok, hogyan néznek ki, és hol ülnek."
L["The experience bar's text and its +XP, and the separate reputation bar's. General uses the font on General > Appearance."] = "A tapasztalatsáv szövege és a +XP, valamint a külön hírnévsávé. Az Általános az Általános > Megjelenés betűtípusát használja."
L["The fill of the experience and reputation bars. General uses the bar texture on General > Appearance."] = "A tapasztalat- és hírnévsávok kitöltése. Az Általános az Általános > Megjelenés sávtextúráját használja."
L["The top-right panel: experience bar on top, damage meter and minimap below. Move it in unlock mode. The experience bar has its own page."] = "A jobb felső panel: felül a tapasztalatsáv, alatta a sebzésmérő és a minitérkép. Feloldott módban mozgathatod. A tapasztalatsávnak saját oldala van."
L["This bar's own outline, corners and shadow. When off, it follows General > Appearance."] = "Ennek a sávnak a saját körvonala, sarkai és árnyéka. Kikapcsolva az Általános > Megjelenés beállítást követi."
L["The tooltip's lines. Titles and small text have sizes of their own."] = "A súgóbuborék sorai. A címeknek és a kis szövegnek saját méretük van."
L["Tooltip title size"] = "Súgóbuborék címének mérete"
L["The name at the top of a tooltip (a player, a creature, an item, a spell) and the headings on Rich cards."] = "A név a súgóbuborék tetején (játékos, lény, tárgy, varázslat), és a fejlécek a Gazdag kártyákon."
L["Tooltip title font"] = "Súgóbuborék címének betűtípusa"
L["The name at the top of a tooltip and the headings on Rich cards. General uses the tooltip font."] = "A név a súgóbuborék tetején és a fejlécek a Gazdag kártyákon. Az Általános a súgóbuborék betűtípusát használja."
L["Tooltip small text size"] = "Súgóbuborék kis szövegének mérete"
L["The small lines: under a title, short facts, quotes and captions."] = "A kis sorok: cím alatt, rövid tények, idézetek és feliratok."
L["Tooltip small text font"] = "Súgóbuborék kis szövegének betűtípusa"
L["The small lines under a title, short facts, quotes and captions. General uses the tooltip font."] = "A kis sorok cím alatt, rövid tények, idézetek és feliratok. Az Általános a súgóbuborék betűtípusát használja."
