L["/dui welcome - what's new in Daylight UI 2.0, and the new portraits and tooltips to pick from"] = "/dui welcome - mi új a Daylight UI 2.0-ban, és a választható új portrék és súgóbuborékok"
L["1 min"] = "1 perc"
L["1 of them is yours and isn't counted."] = "Ebből 1 a tiéd, és nem számít bele."
L["2 hours"] = "2 óra"
L["2 weeks ago"] = "2 hete"
L["24 hours"] = "24 óra"
L["8 hours"] = "8 óra"
L["A buy priced well above what the item usually costs asks you once more before it goes through. When off, every buy goes through on the second click."] = "Egy, a tárgy szokásos áránál jóval drágább vásárlás még egyszer rákérdez, mielőtt végbemegy. Kikapcsolva minden vásárlás a második kattintásra végbemegy."
L["A finished roll stays up while your mouse is on it, and leaves once you move away."] = "Egy befejezett dobás fent marad, amíg rajta van az egér, és eltűnik, amint elviszed."
L["A friendly player's class icon by their name, the one picked for that class under Unit Frames > Look > Class icons, so you can spot the healer in a crowd. Above name needs the name over the bar (or no bar); on or under it, the icon goes before the name."] = "Egy barátságos játékos kasztikonja a neve mellett, az adott kaszthoz az Egységkeretek > Kinézet > Kasztikonok alatt választott, így tömegben is kiszúrod a gyógyítót. A Név fölött a sáv fölötti nevet igényli (vagy sáv nélkülit); rajta vagy alatta az ikon a név elé kerül."
L["A full scan is already running."] = "Már fut egy teljes keresés."
L["A light sweeps across the roll when someone wins it, twice when it's you. Needs Motion effects (General > Appearance)."] = "Fény söpör végig a dobáson, amikor valaki megnyeri, kétszer, ha te. Kell hozzá a Mozgáseffektek (Általános > Megjelenés)."
L["A line in the item's quality color along the top of each roll."] = "Egy vonal a tárgy minőségi színében minden dobás tetején."
L["A row of small ticks on a compact roll, one per player: tall for a high roll, faint for Greed, flat for Pass."] = "Kis jelek sora egy kompakt dobáson, játékosonként egy: magas a nagy dobásnak, halvány a Greednek, lapos a Passnak."
L["A score another addon adds (Raider.IO) as a row with the number in your accent color."] = "Egy másik addon által hozzáadott pontszám (Raider.IO) sorként, a szám a kiemelőszínedben."
L["A thin bar beside each roll, as long as the number, to compare rolls at a glance."] = "Vékony sáv minden dobás mellett, olyan hosszú, mint a szám, hogy egy pillantással összevethesd a dobásokat."
L["Above name"] = "A név fölött"
L["Adds what the item has usually cost over the last two weeks, under its auction price."] = "Hozzáadja, mennyibe került a tárgy általában az elmúlt két hétben, az aukciós ára alá."
L["Adds when the price was seen, like \"Seen 2 h ago\", so you know how fresh it is."] = "Hozzáadja, mikor látta az árat, például \"2 órája látva\", hogy tudd, mennyire friss."
L["After name"] = "A név után"
L["All %d"] = "Mind a(z) %d"
L["An auction"] = "Egy aukció"
L["An item you haven't seen at the Auction House for this many days is forgotten when you log in, so old prices don't hang around."] = "Az ennyi napja nem látott tárgyat az Aukciósházban belépéskor elfelejti, hogy ne maradjanak meg a régi árak."
L["Any rarity"] = "Bármilyen ritkaság"
L["As they picked"] = "Ahogy választottak"
