L["Best roll first puts Need above Greed above Pass, highest roll on top, so the winner leads. As they picked keeps the order people chose in."] = "A Legjobb dobás elöl a Needet a Greed elé, a Greedet a Pass elé teszi, a legmagasabb dobással felül, így a nyertes vezet. Az Ahogy választottak megtartja azt a sorrendet, ahogy az emberek választottak."
