L["Couldn't check its price."] = "Nem sikerült ellenőrizni az árát."
L["Couldn't check its price. Pick it again to try again."] = "Nem sikerült ellenőrizni az árát. Válaszd ki újra, hogy újra próbáld."
L["Couldn't check the price"] = "Nem sikerült ellenőrizni az árat"
L["Couldn't read its price just now. Check again to try once more."] = "Most nem sikerült beolvasni az árát. Az Újraellenőrzéssel próbáld még egyszer."
L["Cuts the left end of your focus's cast bar at an angle. When off, its end is straight. Not inside the frame or sliding out under it."] = "A fókuszod varázslássávjának bal végét ferdén levágja. Kikapcsolva a vége egyenes. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Cuts the right end of your focus's cast bar at an angle. When off, its end is straight. Not inside the frame or sliding out under it."] = "A fókuszod varázslássávjának jobb végét ferdén levágja. Kikapcsolva a vége egyenes. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Daylight UI loot rolls"] = "Daylight UI zsákmánydobások"
L["Daylight UI style Auction House window"] = "Daylight UI stílusú Aukciósház-ablak"
L["Daylight UI's die, coin and cross, each in its own color, or the game's own dice and coins."] = "A Daylight UI kockája, érméje és keresztje, mindegyik a saját színében, vagy a játék saját kockái és érméi."
L["Days to keep an unseen price"] = "Nem látott ár megtartása ennyi napig"
L["Deal price"] = "Jó ár"
L["Empties the Favorites list on the Buy tab. Right-click an item in the results to add it again."] = "Kiüríti a Vásárlás fül Kedvencek listáját. Jobb klikk egy tárgyon a találatokban, hogy újra hozzáadd."
L["Empties the Recent list on the Buy tab."] = "Kiüríti a Vásárlás fül Friss listáját."
L["Epic"] = "Epikus"
L["Equip: %s"] = "Felvétel: %s"
L["Every item tooltip shows what the cheapest one cost the last time you saw it at the Auction House. Items you've never seen there show nothing."] = "Minden tárgy súgóbuboréka mutatja, mennyibe került a legolcsóbb, amikor utoljára láttad az Aukciósházban. Az ott soha nem látott tárgyaknál semmi sem látszik."
L["Every one up is yours."] = "Minden fent lévő a tiéd."
L["Everyone passed."] = "Mindenki passzolt."
L["Focus cast bar angle"] = "Fókusz varázslássávjának dőlése"
L["Focus cast bar flip left end"] = "Fókusz varázslássávja bal végének tükrözése"
L["Focus cast bar flip right end"] = "Fókusz varázslássávja jobb végének tükrözése"
L["Focus cast bar own angle"] = "Fókusz varázslássávjának saját dőlése"
L["Forget"] = "Elfelejtés"
L["Forget every price"] = "Minden ár elfelejtése"
L["Forgets every remembered price on this realm. Searches and a full scan fill them in again."] = "Elfelejt minden megjegyzett árat ezen a realmon. A keresések és egy teljes keresés újra kitöltik őket."
L["Frames under this (%d)"] = "Keretek e alatt (%d)"
L["From your bags"] = "A táskáidból"
L["Full scan"] = "Teljes keresés"
L["Full scan again in %d min."] = "Újabb teljes keresés %d perc múlva."
L["Full scan done: %s item priced, %s skipped (the game hadn't loaded it; scan again later)."] = "Teljes keresés kész: %s tárgy beárazva, %s kihagyva (a játék nem töltötte be; keress újra később)."
L["Full scan done: %s item priced, %s skipped (the game hadn't loaded them; scan again later)."] = "Teljes keresés kész: %s tárgy beárazva, %s kihagyva (a játék nem töltötte be őket; keress újra később)."
L["Full scan done: %s item priced."] = "Teljes keresés kész: %s tárgy beárazva."
L["Full scan done: %s items priced, %s skipped (the game hadn't loaded it; scan again later)."] = "Teljes keresés kész: %s tárgy beárazva, %s kihagyva (a játék nem töltötte be; keress újra később)."
L["Full scan done: %s items priced, %s skipped (the game hadn't loaded them; scan again later)."] = "Teljes keresés kész: %s tárgy beárazva, %s kihagyva (a játék nem töltötte be őket; keress újra később)."
L["Full scan done: %s items priced."] = "Teljes keresés kész: %s tárgy beárazva."
L["Full scan stopped: something went wrong. Try again in a moment."] = "A teljes keresés leállt: valami hiba történt. Próbáld újra egy pillanat múlva."
L["Full scan stopped: the Auction House didn't answer. The game allows one full scan every %d minutes."] = "A teljes keresés leállt: az Aukciósház nem válaszolt. A játék %d percenként egy teljes keresést enged."
L["Full scan stopped: the Auction House sent back no auctions. The game allows one full scan every %d minutes."] = "A teljes keresés leállt: az Aukciósház nem küldött vissza aukciókat. A játék %d percenként egy teljes keresést enged."
L["Full scan stopped: the Auction House was closed. Nothing was kept."] = "A teljes keresés leállt: az Aukciósház bezárult. Semmi sem maradt meg."
L["Full scan stopped: the ruleset changed."] = "A teljes keresés leállt: megváltozott a szabályrendszer."
L["Gives the main hand bar's angled ends their own angle, set below. When off, they follow the Slant angle on Unit Frames > Look. Only when detached on its own."] = "A főkéz-sáv ferde végei saját dőlést kapnak, alább állítva. Kikapcsolva az Egységkeretek > Kinézet Dőlésszögét követik. Csak önállóan leválasztva."
L["Gives the off hand bar's angled ends their own angle, set below. When off, they follow the Slant angle on Unit Frames > Look. Only when detached on its own."] = "A mellékkéz-sáv ferde végei saját dőlést kapnak, alább állítva. Kikapcsolva az Egységkeretek > Kinézet Dőlésszögét követik. Csak önállóan leválasztva."
L["Gives the personal display's angled ends their own angle, set below. When off, they follow the Slant angle on Unit Frames > Look. Docked cast and swing bars lean with it."] = "A személyes kijelző ferde végei saját dőlést kapnak, alább állítva. Kikapcsolva az Egységkeretek > Kinézet Dőlésszögét követik. A dokkolt varázslás- és ütéssávok vele dőlnek."
L["Gives the power bar's angled ends their own angle, set below. When off, they follow the Slant angle on Unit Frames > Look. Only while the power bar is on its own. A cast bar sliding out from under it continues the line."] = "Az erőforrássáv ferde végei saját dőlést kapnak, alább állítva. Kikapcsolva az Egységkeretek > Kinézet Dőlésszögét követik. Csak amíg az erőforrássáv önállóan áll. Az alóla kicsúszó varázslássáv folytatja a vonalat."
L["Gives the ranged bar's angled ends their own angle, set below. When off, they follow the Slant angle on Unit Frames > Look. Only when detached on its own."] = "A távolsági sáv ferde végei saját dőlést kapnak, alább állítva. Kikapcsolva az Egységkeretek > Kinézet Dőlésszögét követik. Csak önállóan leválasztva."
L["Gives the swing timer's angled ends their own angle, set below. When off, they follow the Slant angle on Unit Frames > Look. Only when detached as a group."] = "Az ütésidőzítő ferde végei saját dőlést kapnak, alább állítva. Kikapcsolva az Egységkeretek > Kinézet Dőlésszögét követik. Csak csoportként leválasztva."
L["Gives your cast bar's angled ends their own angle, set below. When off, they follow the Slant angle on Unit Frames > Look. Not while under the frame, between the frames or under the personal display."] = "A varázslássávod ferde végei saját dőlést kapnak, alább állítva. Kikapcsolva az Egységkeretek > Kinézet Dőlésszögét követik. Nem, ha a keret alatt, a keretek között vagy a személyes kijelző alatt van."
L["Gives your focus's cast bar's angled ends their own angle, set below. When off, they follow the Slant angle on Unit Frames > Look. Not inside the frame or sliding out under it."] = "A fókuszod varázslássávjának ferde végei saját dőlést kapnak, alább állítva. Kikapcsolva az Egységkeretek > Kinézet Dőlésszögét követik. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Gives your target's cast bar's angled ends their own angle, set below. When off, they follow the Slant angle on Unit Frames > Look. Not inside the frame or sliding out under it."] = "A célpontod varázslássávjának ferde végei saját dőlést kapnak, alább állítva. Kikapcsolva az Egységkeretek > Kinézet Dőlésszögét követik. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Group list"] = "Csoportlista"
L["Grow direction"] = "Növekedési irány"
L["Has a bid: can't cancel"] = "Van rá licit: nem vonható vissza"
L["Holding Shift over a stack in your bags prices the whole stack instead of one."] = "Ha a Shiftet nyomva tartod egy halom fölött a táskáidban, az egész halmot árazza, nem egy darabot."
L["How Buy warns you about prices and how Sell prices your items."] = "Hogyan figyelmeztet a Vásárlás az árakra, és hogyan árazza be az Eladás a tárgyaidat."
L["How big the class icon is. Set to 0 to follow the name size."] = "Mekkora a kasztikon. A 0 a névmérethez igazítja."
L["How big the window is. Ctrl and the mouse wheel over the window changes it too."] = "Mekkora az ablak. A Ctrl és az egérgörgő az ablak fölött is módosítja."
L["How far over the usual price a buy has to be before it asks. At 150%, an item that usually costs 10 gold asks above 15 gold. Prices over it show in orange either way."] = "Mennyivel kell a szokásos ár fölött lennie egy vásárlásnak, hogy rákérdezzen. 150%-nál egy általában 10 aranyas tárgy 15 arany fölött kérdez. Az e fölötti árak így is, úgy is narancsban látszanak."
L["How far the main hand bar's angled ends lean: how far the cut reaches in, as a share of the bar's height. Near 0 is almost square, 100 is 45 degrees. Needs its own angle on. Only when detached on its own."] = "Mennyire dőlnek a főkéz-sáv ferde végei: milyen mélyre ér a vágás, a sáv magasságának arányában. 0 közelében majdnem szögletes, 100-nál 45 fok. Kell hozzá a saját dőlés. Csak önállóan leválasztva."
L["How far the off hand bar's angled ends lean: how far the cut reaches in, as a share of the bar's height. Near 0 is almost square, 100 is 45 degrees. Needs its own angle on. Only when detached on its own."] = "Mennyire dőlnek a mellékkéz-sáv ferde végei: milyen mélyre ér a vágás, a sáv magasságának arányában. 0 közelében majdnem szögletes, 100-nál 45 fok. Kell hozzá a saját dőlés. Csak önállóan leválasztva."
L["How far the personal display's angled ends lean: how far the cut reaches in, as a share of the bar's height. Near 0 is almost square, 100 is 45 degrees. Needs its own angle on. Docked cast and swing bars lean with it."] = "Mennyire dőlnek a személyes kijelző ferde végei: milyen mélyre ér a vágás, a sáv magasságának arányában. 0 közelében majdnem szögletes, 100-nál 45 fok. Kell hozzá a saját dőlés. A dokkolt varázslás- és ütéssávok vele dőlnek."
L["How far the power bar's angled ends lean: how far the cut reaches in, as a share of the bar's height. Near 0 is almost square, 100 is 45 degrees. Needs its own angle on. Only while the power bar is on its own. A cast bar sliding out from under it continues the line."] = "Mennyire dőlnek az erőforrássáv ferde végei: milyen mélyre ér a vágás, a sáv magasságának arányában. 0 közelében majdnem szögletes, 100-nál 45 fok. Kell hozzá a saját dőlés. Csak amíg az erőforrássáv önállóan áll. Az alóla kicsúszó varázslássáv folytatja a vonalat."
L["How far the ranged bar's angled ends lean: how far the cut reaches in, as a share of the bar's height. Near 0 is almost square, 100 is 45 degrees. Needs its own angle on. Only when detached on its own."] = "Mennyire dőlnek a távolsági sáv ferde végei: milyen mélyre ér a vágás, a sáv magasságának arányában. 0 közelében majdnem szögletes, 100-nál 45 fok. Kell hozzá a saját dőlés. Csak önállóan leválasztva."
L["How far the swing timer's angled ends lean: how far the cut reaches in, as a share of the bar's height. Near 0 is almost square, 100 is 45 degrees. Needs its own angle on. Only when detached as a group."] = "Mennyire dőlnek az ütésidőzítő ferde végei: milyen mélyre ér a vágás, a sáv magasságának arányában. 0 közelében majdnem szögletes, 100-nál 45 fok. Kell hozzá a saját dőlés. Csak csoportként leválasztva."
L["How far under the cheapest one up Sell puts your price, in copper. Gear and recipes go a whole silver under, as the game only takes them in silver."] = "Mennyivel a legolcsóbb fent lévő alá teszi az Eladás az áradat, rézben. A felszerelés és a receptek egy egész ezüsttel kerülnek alá, mert a játék ezeket csak ezüstben fogadja."
L["How far your cast bar's angled ends lean: how far the cut reaches in, as a share of the bar's height. Near 0 is almost square, 100 is 45 degrees. Needs its own angle on. Not while under the frame, between the frames or under the personal display."] = "Mennyire dőlnek a varázslássávod ferde végei: milyen mélyre ér a vágás, a sáv magasságának arányában. 0 közelében majdnem szögletes, 100-nál 45 fok. Kell hozzá a saját dőlés. Nem, ha a keret alatt, a keretek között vagy a személyes kijelző alatt van."
L["How far your focus's cast bar's angled ends lean: how far the cut reaches in, as a share of the bar's height. Near 0 is almost square, 100 is 45 degrees. Needs its own angle on. Not inside the frame or sliding out under it."] = "Mennyire dőlnek a fókuszod varázslássávjának ferde végei: milyen mélyre ér a vágás, a sáv magasságának arányában. 0 közelében majdnem szögletes, 100-nál 45 fok. Kell hozzá a saját dőlés. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["How far your target's cast bar's angled ends lean: how far the cut reaches in, as a share of the bar's height. Near 0 is almost square, 100 is 45 degrees. Needs its own angle on. Not inside the frame or sliding out under it."] = "Mennyire dőlnek a célpontod varázslássávjának ferde végei: milyen mélyre ér a vágás, a sáv magasságának arányában. 0 közelében majdnem szögletes, 100-nál 45 fok. Kell hozzá a saját dőlés. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["How long"] = "Időtartam"
L["How long a new auction stays up. Picking another length on the Sell tab changes this too. Longer auctions cost a bigger deposit."] = "Mennyi ideig marad fent egy új aukció. Ha az Eladás fülön másik időtartamot választasz, ez is változik. A hosszabb aukciók nagyobb letéttel járnak."
L["How many"] = "Mennyiség"
L["How many rolls show at once. Rolls past this wait their turn, with a line saying how many are waiting."] = "Hány dobás látszik egyszerre. Ezen felül a dobások sorukra várnak, egy sorral, ami jelzi, hány vár."
L["How many seconds a roll stays up after someone wins it. At 0 it leaves as soon as the winner is known."] = "Hány másodpercig marad fent egy dobás, miután valaki megnyerte. 0-nál eltűnik, amint ismert a nyertes."
L["How old the auction price is"] = "Mennyire régi az aukciós ár"
L["How the power text reads: a percent, the power itself, power out of max, or both."] = "Hogyan olvasható az erőforrás-szöveg: százalék, maga az erőforrás, erőforrás a maximumhoz képest, vagy mindkettő."
L["How wide each roll is."] = "Milyen széles minden dobás."
L["In a fight, rolls stay compact and their lists open only under your mouse, so they never cover more of the screen than they need."] = "Harcban a dobások kompaktak maradnak, és a listáik csak az egered alatt nyílnak ki, így sosem takarnak többet a képernyőből, mint amennyi kell."
L["It can't be dragged, nudged or reset by accident, and its handle goes under the others."] = "Nem lehet véletlenül elhúzni, eltolni vagy visszaállítani, és a fogantyúja a többi alá kerül."
L["It has a bid, so it can't be canceled."] = "Van rá licit, ezért nem vonható vissza."
L["It has a starting bid but no buyout, so there's no price to compare."] = "Van kezdőlicitje, de nincs azonnali ára, így nincs mivel összevetni."
L["It may be a different roll; check the tooltip before you buy."] = "Lehet, hogy más dobásról van szó; vásárlás előtt nézd meg a súgóbuborékot."
L["Item %d"] = "%d. tárgy"
L["Keep Classic"] = "Maradjon a Klasszikus"
L["Keep it open, about a minute"] = "Tartsd nyitva, nagyjából egy percig"
L["Keep results under the mouse"] = "Találatok megtartása az egér alatt"
L["Let's go"] = "Indulás"
L["Lines other addons add to a tooltip (prices, quest progress, scores, bag counts). Their own area: at the bottom of the card under a line. Mixed in: with the card's own rows. Hidden: left out; Daylight UI plugins' lines still show."] = "A más addonok által a súgóbuborékhoz adott sorok (árak, küldetéshaladás, pontszámok, táskadarabszámok). Saját terület: a kártya alján egy vonal alatt. Keverve: a kártya saját soraival együtt. Rejtett: kimaradnak; a Daylight UI bővítmények sorai továbbra is látszanak."
L["List order"] = "Lista sorrendje"
L["Loading new items from the game, %s to go"] = "Új tárgyak betöltése a játékból, még %s"
L["Lock in place"] = "Rögzítés a helyén"
L["Long names keep only their last word whole, the rest as initials (S. C. Commander), on enemy and friendly plates. A name on the bar that still doesn't fit is cut short so it never covers the health text."] = "A hosszú neveknek csak az utolsó szava marad egész, a többi kezdőbetű lesz (S. C. Commander), ellenséges és barátságos névtáblákon. A sávon lévő név, ami így sem fér el, rövidül, hogy sose takarja az életerő-szöveget."
L["Loot rolls"] = "Zsákmánydobások"
L["Loot rolls in a window of Daylight UI's own that shows who picked Need, Greed or Pass, every roll and who won. When off, the game's own roll popups show, in Daylight UI style."] = "Zsákmánydobások a Daylight UI saját ablakában, ami mutatja, ki választott Needet, Greedet vagy Passt, minden dobást és a nyertest. Kikapcsolva a játék saját dobásablakai látszanak, Daylight UI stílusban."
L["Lowest other"] = "Legalacsonyabb másik"
L["Main hand bar angle"] = "Főkéz-sáv dőlése"
L["Main hand bar flip left end"] = "Főkéz-sáv bal végének tükrözése"
L["Main hand bar flip right end"] = "Főkéz-sáv jobb végének tükrözése"
L["Main hand bar own angle"] = "Főkéz-sáv saját dőlése"
L["Mark duplicate drops"] = "Ismétlődő zsákmányok jelölése"
L["Max shown"] = "Legfeljebb ennyi"
L["Mixed in"] = "Keverve"
L["Move the rolls with the Loot Rolls handle in unlock mode (/dui unlock). The mouse wheel over the handle sets their size."] = "A dobásokat feloldott módban (/dui unlock) a Zsákmánydobások fogantyúval mozgathatod. A fogantyú fölött az egérgörgő a méretüket állítja."
L["My auctions"] = "Aukcióim"
L["Need, Greed and Pass in Daylight UI's own roll window: who picked what, every roll and the winner."] = "Need, Greed és Pass a Daylight UI saját dobásablakában: ki mit választott, minden dobás és a nyertes."
L["Need, Greed and Pass written beside their icons. When off, the buttons show only their icons. Hover one for its name."] = "A Need, a Greed és a Pass kiírva az ikonjuk mellé. Kikapcsolva a gombok csak az ikonjukat mutatják. Vidd fölé az egeret a nevéért."
L["New portrait mode"] = "Új portrémód"
L["Next up: %s."] = "Következik: %s."
L["No answer from the game. Check again before you cancel it again."] = "Nincs válasz a játéktól. Ellenőrizd, mielőtt újra visszavonod."
L["No answer from the game. Check your auctions before you post it again."] = "Nincs válasz a játéktól. Ellenőrizd az aukcióidat, mielőtt újra feladod."
L["No auctions match."] = "Nincs illeszkedő aukció."
L["No auctions up."] = "Nincs fent aukció."
L["No buyout to compare"] = "Nincs azonnali ár az összevetéshez"
L["No favorites yet. Right-click an item in the results to add it."] = "Még nincsenek kedvencek. Jobb klikk egy tárgyon a találatokban a hozzáadáshoz."
L["No items match."] = "Nincs illeszkedő tárgy."
L["No one else is selling it (checked %s). It stays up as it is."] = "Senki más nem árulja (ellenőrizve: %s). Fent marad, ahogy van."
L["No one else is selling it and it has no usual price yet. Type a price each."] = "Senki más nem árulja, és még nincs szokásos ára. Írj be darabárat."
L["No one else is selling it."] = "Senki más nem árulja."
L["No one else selling"] = "Senki más nem árulja"
L["No prices seen yet"] = "Még nincs látott ár"
L["No prices yet."] = "Még nincsenek árak."
L["No result seen."] = "Nincs látott találat."
L["No searches yet."] = "Még nincsenek keresések."
L["No usual price"] = "Nincs szokásos ár"
L["No usual price yet: search it again on another day, or run a full scan."] = "Még nincs szokásos ár: keress rá újra egy másik napon, vagy futtass teljes keresést."
L["No usual price: click again"] = "Nincs szokásos ár: kattints újra"
L["None of it is left in your bags to sell."] = "Már nincs belőle a táskáidban, amit eladhatnál."
L["Nothing in your bags can be sold."] = "A táskáidban semmi sem adható el."
L["Off hand bar angle"] = "Mellékkéz-sáv dőlése"
L["Off hand bar flip left end"] = "Mellékkéz-sáv bal végének tükrözése"
L["Off hand bar flip right end"] = "Mellékkéz-sáv jobb végének tükrözése"
L["Off hand bar own angle"] = "Mellékkéz-sáv saját dőlése"
L["On mouseover"] = "Egér alatt"
L["On the Auction House now"] = "Most az Aukciósházban"
L["One up, buyout %s."] = "Egy fent, azonnali ár %s."
L["Open the Auction House first."] = "Előbb nyisd meg az Aukciósházat."
L["Open the Auction House to browse."] = "Nyisd meg az Aukciósházat a böngészéshez."
L["Open the Auction House to cancel."] = "Nyisd meg az Aukciósházat a visszavonáshoz."
L["Open the Auction House to post."] = "Nyisd meg az Aukciósházat a feladáshoz."
L["Open the Auction House to search."] = "Nyisd meg az Aukciósházat a kereséshez."
