L["Other addons' lines"] = "Más addonok sorai"
L["Personal display own angle"] = "Személyes kijelző saját dőlése"
L["Pick Need, Greed or Pass"] = "Need, Greed vagy Pass választása"
L["Pick a category on the left, or type a name."] = "Válassz kategóriát bal oldalt, vagy írj be egy nevet."
L["Pick an auction to cancel it."] = "Válassz egy aukciót a visszavonásához."
L["Pick an item on the left."] = "Válassz egy tárgyat bal oldalt."
L["Pick an item to see its prices"] = "Válassz egy tárgyat, hogy lásd az árait"
L["Pick ticks"] = "Választásjelek"
L["Pick yours"] = "Válaszd a tiédet"
L["Players who passed stay in the list, dimmed. When off, they're left out."] = "A passzoló játékosok halványítva a listában maradnak. Kikapcsolva kimaradnak."
L["Players' full names in the roll list. When off, first names only."] = "A játékosok teljes neve a dobáslistában. Kikapcsolva csak keresztnevek."
L["Poor"] = "Gyenge"
L["Portrait look"] = "Portré kinézete"
L["Portraits can now be set into their frame: the border runs around both as one piece. Which do you want? Each frame's page has it under Portrait look."] = "A portrék mostantól a keretükbe illeszthetők: a szegély egy darabként fut körbe mindkettőn. Melyiket szeretnéd? Minden keret oldalán a Portré kinézete alatt van."
L["Post"] = "Feladás"
L["Post %d"] = "%d feladása"
L["Posted %d %s at %s each."] = "Feladva: %d %s, darabonként %s áron."
L["Posting..."] = "Feladás..."
L["Power bar angle"] = "Erőforrássáv dőlése"
L["Power bar flip left end"] = "Erőforrássáv bal végének tükrözése"
L["Power bar flip right end"] = "Erőforrássáv jobb végének tükrözése"
L["Power bar own angle"] = "Erőforrássáv saját dőlése"
L["Price each"] = "Darabár"
L["Price lines another addon adds (Auctionator, TSM) as a label and Daylight UI's coins."] = "Más addonok (Auctionator, TSM) által hozzáadott ársorok, címkével és Daylight UI érmékkel."
L["Price memory"] = "Ármemória"
L["Prices"] = "Árak"
L["Prices at or under this much of the usual price show in green as a deal."] = "A szokásos ár ennyi százaléka alatti árak zölden, jó árként látszanak."
L["Prices from other addons"] = "Árak más addonokból"
L["Qty"] = "Db"
L["Quality color line"] = "Minőségi színű vonal"
L["Quest progress from other addons"] = "Küldetéshaladás más addonokból"
L["Quest rows another addon adds (Questie) drawn like the game's own: the quest's name in its difficulty color and a thin bar per objective. A quest the game already lists isn't shown twice."] = "Más addon (Questie) által hozzáadott küldetéssorok a játék sajátjaihoz hasonlóan rajzolva: a küldetés neve a nehézségi színében, feladatonként egy vékony sávval. A játék által már listázott küldetés nem jelenik meg kétszer."
L["Range"] = "Tartomány"
L["Ranged bar angle"] = "Távolsági sáv dőlése"
L["Ranged bar flip left end"] = "Távolsági sáv bal végének tükrözése"
L["Ranged bar flip right end"] = "Távolsági sáv jobb végének tükrözése"
L["Ranged bar own angle"] = "Távolsági sáv saját dőlése"
L["Reading the Auction House..."] = "Az Aukciósház olvasása..."
L["Reading your auctions..."] = "Az aukcióid olvasása..."
L["Ready in"] = "Kész ennyi idő múlva"
L["Result time"] = "Találat ideje"
L["Roll bars"] = "Dobássávok"
