L["Sell price"] = "Eladási ár"
L["Selling"] = "Eladás"
L["2.0 runs the frame's border on around the portrait, so the two read as one piece. Classic lays the ring over the frame's end, as before. A portrait on its own wears the same border as a ring."] = "A 2.0 a keret szegélyét a portré köré is körbefuttatja, így a kettő egy darabnak látszik. A Klasszikus a gyűrűt a keret végére teszi, mint korábban. Az önálló portré ugyanazt a szegélyt viseli gyűrűként."
L["Shift for the whole stack"] = "Shift az egész halomhoz"
L["Shift: the whole stack"] = "Shift: az egész halom"
L["Shine on a win"] = "Csillogás nyeréskor"
L["Shorten long names"] = "Hosszú nevek rövidítése"
L["Show players who passed"] = "Passzoló játékosok mutatása"
L["Showing the cheapest %s: add words to narrow it."] = "A legolcsóbb %s látszik: adj hozzá szavakat a szűkítéshez."
L["Skip"] = "Kihagyás"
L["Sold"] = "Eladva"
L["Sold for %s. The gold is waiting in your mailbox, less the Auction House's cut."] = "Eladva %s áron. Az arany a postaládádban vár, az Aukciósház jutaléka nélkül."
L["Sold: in your mailbox"] = "Eladva: a postaládádban"
L["Sold: nothing to cancel."] = "Eladva: nincs mit visszavonni."
L["Someone bid %s on it. An auction with a bid can't be canceled: it goes to the highest bid when its time runs out, or sooner to anyone who pays your buyout."] = "Valaki %s licitet tett rá. Licites aukció nem vonható vissza: az ideje lejártakor a legmagasabb licité lesz, vagy hamarabb azé, aki kifizeti az azonnali árat."
L["Someone else bought it first."] = "Valaki más előbb megvette."
L["Someone put up %s at %s (checked %s), %s under yours. Cancel it and post again from Sell to be the cheapest."] = "Valaki feltett %s darabot %s áron (ellenőrizve: %s), %s különbséggel a tiéd alatt. Vond vissza, és add fel újra az Eladásból, hogy te legyél a legolcsóbb."
L["Something went wrong canceling it."] = "Valami hiba történt a visszavonáskor."
L["Something went wrong posting it."] = "Valami hiba történt a feladáskor."
L["Something went wrong with that purchase."] = "Valami hiba történt ezzel a vásárlással."
L["Something went wrong with that search."] = "Valami hiba történt ezzel a kereséssel."
L["Status"] = "Állapot"
L["Still checking a price. Click again in a moment."] = "Még ellenőrzök egy árat. Kattints újra egy pillanat múlva."
L["Still waiting for the game's answer to your last click. Try again in a moment."] = "Még várok a játék válaszára az előző kattintásodra. Próbáld újra egy pillanat múlva."
L["Swing timer angle"] = "Ütésidőzítő dőlése"
L["Swing timer flip left end"] = "Ütésidőzítő bal végének tükrözése"
L["Swing timer flip right end"] = "Ütésidőzítő jobb végének tükrözése"
L["Swing timer own angle"] = "Ütésidőzítő saját dőlése"
L["Talking to an auctioneer shows Daylight UI's window. Turn it off to use the game's own window, for addons that build on it. Each window also has a button to switch to the other."] = "Ha egy aukcióssal beszélsz, a Daylight UI ablaka nyílik meg. Kapcsold ki, ha a játék saját ablakát használnád, a rá épülő addonokhoz. Mindkét ablakon van egy gomb a másikra váltáshoz."
L["Target cast bar angle"] = "Célpont varázslássávjának dőlése"
L["Target cast bar flip left end"] = "Célpont varázslássávja bal végének tükrözése"
L["Target cast bar flip right end"] = "Célpont varázslássávja jobb végének tükrözése"
L["Target cast bar own angle"] = "Célpont varázslássávjának saját dőlése"
L["Text size of the power text. At 0 it follows the power bar's height."] = "Az erőforrás-szöveg szövegmérete. 0-nál az erőforrássáv magasságát követi."
L["That auction is yours."] = "Ez az aukció a tiéd."
L["That auction isn't in your list anymore. Check again."] = "Ez az aukció már nincs a listádban. Ellenőrizd újra."
L["That stack moved in your bags. Click Post to post it again."] = "Az a halom elmozdult a táskáidban. Kattints a Feladásra az újrafeladáshoz."
L["That was the last of %s."] = "Ez volt az utolsó ebből: %s."
L["That's %s of usual (%s, seen once so far)."] = "Ez a szokásos ár %s-a (%s, eddig egyszer látva)."
L["That's %s of usual (%s, the middle of %d days it was seen)."] = "Ez a szokásos ár %s-a (%s, a látott %d nap közepe)."
L["That's under half the usual price (%s)."] = "Ez a szokásos ár felénél kevesebb (%s)."
L["The Auction House closed while posting. Check your auctions before you post it again."] = "Az Aukciósház feladás közben bezárult. Ellenőrizd az aukcióidat, mielőtt újra feladod."
L["The Auction House closed."] = "Az Aukciósház bezárult."
L["The Auction House didn't answer. Try again in a moment."] = "Az Aukciósház nem válaszolt. Próbáld újra egy pillanat múlva."
L["The Auction House is busy: click again in a moment."] = "Az Aukciósház foglalt: kattints újra egy pillanat múlva."
L["The Auction House is having trouble right now. Try again later."] = "Az Aukciósháznak most gondjai vannak. Próbáld később."
L["The Auction House is still answering. Try again in a moment."] = "Az Aukciósház még válaszol. Próbáld újra egy pillanat múlva."
L["The Auction House takes whole silver only for this item. Type the price again."] = "Ennél a tárgynál az Aukciósház csak egész ezüstöt fogad el. Írd be újra az árat."
L["The Auction House takes whole silver only for this item: %s each. Click Post to post it."] = "Ennél a tárgynál az Aukciósház csak egész ezüstöt fogad el: darabonként %s. Kattints a Feladásra a feladásához."
L["The biggest update yet. Here's what's new."] = "Az eddigi legnagyobb frissítés. Íme, mi új."
L["The cheapest %s are %s each, %s of usual."] = "A legolcsóbb %s darabonként %s, a szokásos %s-a."
L["The cheapest %s are %s each."] = "A legolcsóbb %s darabonként %s."
L["The game asks you to look again at this price. Click Post again to post it."] = "A játék arra kér, hogy nézd meg újra ezt az árat. Kattints újra a Feladásra a feladásához."
L["The game asks: click again"] = "A játék kéri: kattints újra"
L["The game didn't answer. Check your mailbox and bags before you buy again."] = "A játék nem válaszolt. Ellenőrizd a postaládádat és a táskáidat, mielőtt újra vásárolsz."
L["The game didn't answer. Try again in a moment."] = "A játék nem válaszolt. Próbáld újra egy pillanat múlva."
L["The game hasn't loaded this item yet. Try again in a moment."] = "A játék még nem töltötte be ezt a tárgyat. Próbáld újra egy pillanat múlva."
L["The game hasn't said which Auction House this is yet. Try again in a moment."] = "A játék még nem mondta meg, melyik Aukciósházról van szó. Próbáld újra egy pillanat múlva."
L["The game is still loading this item. Try again in a moment."] = "A játék még tölti ezt a tárgyat. Próbáld újra egy pillanat múlva."
L["The game said no to that cancel."] = "A játék nemet mondott erre a visszavonásra."
L["The game said no to that cancel: %s."] = "A játék nemet mondott erre a visszavonásra: %s."
L["The game said no to that post."] = "A játék nemet mondott erre a feladásra."
L["The game said no to that post: %s."] = "A játék nemet mondott erre a feladásra: %s."
L["The game said no: %s."] = "A játék nemet mondott: %s."
L["The game sells the cheapest first, so %s would cost about %s."] = "A játék a legolcsóbbakat adja el elöl, így %s nagyjából %s lenne."
L["The game's"] = "A játéké"
L["The gap between rolls."] = "Rés a dobások között."
L["The height of the Need, Greed and Pass buttons, and the size of their icons."] = "A Need, Greed és Pass gombok magassága, és az ikonjaik mérete."
L["The items come back by mail; the deposit (%s) isn't refunded."] = "A tárgyak postán jönnek vissza; a letétet (%s) nem kapod vissza."
L["The items come back by mail; the deposit isn't refunded."] = "A tárgyak postán jönnek vissza; a letétet nem kapod vissza."
L["The layer your focus's cast bar draws in. Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue. Inside the frame or sliding out under it, it draws with the frame instead."] = "A réteg, amibe a fókuszod varázslássávja rajzolódik. Ahol két darab átfedi egymást, a magasabb réteg kerül felülre: Background, Low, Medium, High, aztán Dialogue. A kereten belül vagy alóla kicsúszva inkább a kerettel együtt rajzolódik."
L["The price changed and the game won't hold it: search again."] = "Az ár megváltozott, és a játék nem tartja: keress újra."
L["The price changed: check the new total and click again."] = "Az ár megváltozott: nézd meg az új végösszeget, és kattints újra."
L["The price quote is gone: click Buy again."] = "Az árajánlat elveszett: kattints újra a Vásárlásra."
L["The price quote ran out: click Buy again."] = "Az árajánlat lejárt: kattints újra a Vásárlásra."
L["The seconds left to pick, beside the timer bar."] = "A választásra hátralévő másodpercek, az időzítősáv mellett."
L["The spell's icon at the end of your focus's cast bar. Not inside the frame or sliding out under it."] = "A varázslat ikonja a fókuszod varázslássávjának végén. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["The tab you left open"] = "A legutóbb nyitva hagyott fül"
L["The thin dark line round the middle of the ring. When off, the ring is one smooth band. A portrait set into its frame has a thin ring with no line."] = "A vékony sötét vonal a gyűrű közepén körben. Kikapcsolva a gyűrű egy sima sáv. A keretébe illesztett portrénak vékony, vonal nélküli gyűrűje van."
L["The unit's mana, rage or energy written on the power bar. Raise Power bar height so it reads well."] = "Az egység manája, dühe vagy energiája az erőforrássávra írva. Növeld az Erőforrássáv magasságát, hogy jól olvasható legyen."
L["Their own area"] = "Saját terület"
L["Those are all yours."] = "Ezek mind a tieid."
L["Tied: the game rolls again."] = "Döntetlen: a játék újra dob."
L["Tips the main hand bar's left end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Only when detached on its own."] = "A főkéz-sáv bal végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Csak önállóan leválasztva."
L["Tips the main hand bar's right end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Only when detached on its own."] = "A főkéz-sáv jobb végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Csak önállóan leválasztva."
L["Tips the off hand bar's left end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Only when detached on its own."] = "A mellékkéz-sáv bal végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Csak önállóan leválasztva."
L["Tips the off hand bar's right end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Only when detached on its own."] = "A mellékkéz-sáv jobb végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Csak önállóan leválasztva."
L["Tips the power bar's left end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Only on an angled end, while the power bar is on its own, and not while your cast bar slides out from under it."] = "Az erőforrássáv bal végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Csak ferde végen, amíg az erőforrássáv önállóan áll, és nem, amíg a varázslássávod kicsúszik alóla."
L["Tips the power bar's right end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Only on an angled end, while the power bar is on its own, and not while your cast bar slides out from under it."] = "Az erőforrássáv jobb végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Csak ferde végen, amíg az erőforrássáv önállóan áll, és nem, amíg a varázslássávod kicsúszik alóla."
L["Tips the ranged bar's left end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Only when detached on its own."] = "A távolsági sáv bal végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Csak önállóan leválasztva."
L["Tips the ranged bar's right end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Only when detached on its own."] = "A távolsági sáv jobb végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Csak önállóan leválasztva."
L["Tips the swing timer's left end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Only when detached as a group."] = "Az ütésidőzítő bal végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Csak csoportként leválasztva."
L["Tips the swing timer's right end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Only when detached as a group."] = "Az ütésidőzítő jobb végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Csak csoportként leválasztva."
L["Tips your cast bar's left end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Not while under the frame, between the frames or under the personal display."] = "A varázslássávod bal végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Nem, ha a keret alatt, a keretek között vagy a személyes kijelző alatt van."
L["Tips your cast bar's right end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Not while under the frame, between the frames or under the personal display."] = "A varázslássávod jobb végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Nem, ha a keret alatt, a keretek között vagy a személyes kijelző alatt van."
L["Tips your focus's cast bar's left end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Not inside the frame or sliding out under it."] = "A fókuszod varázslássávjának bal végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Tips your focus's cast bar's right end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Not inside the frame or sliding out under it."] = "A fókuszod varázslássávjának jobb végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Tips your target's cast bar's left end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Not inside the frame or sliding out under it."] = "A célpontod varázslássávjának bal végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Tips your target's cast bar's right end the other way, so its bottom corner sticks out instead of its top. The other end keeps its own. Not inside the frame or sliding out under it."] = "A célpontod varázslássávjának jobb végét a másik irányba dönti, így a felső helyett az alsó sarka áll ki. A másik vége megtartja a sajátját. Nem a kereten belül, és nem, amíg alóla kicsúszik."
L["Tooltip look"] = "Súgóbuborék kinézete"
L["Two of the same item are tagged 1 of 2 and 2 of 2 and joined by a line. Once one is won, its winner is tagged \"has one\" on the other."] = "Két ugyanolyan tárgy 1/2 és 2/2 címkét kap, és egy vonal köti össze őket. Ha az egyiket megnyerik, a nyertese a másikon \"van egy\" címkét kap."
L["Type a price first."] = "Előbb írj be egy árat."
L["Type a price like %s."] = "Írj be egy árat, például így: %s."
L["Type a price of at least 1c."] = "Legalább 1c-s árat írj be."
L["Type how many to post."] = "Írd be, hányat adsz fel."
L["Uncommon"] = "Nem közönséges"
L["Undercut"] = "Alákínálás"
