L["Usual %s is the cheapest price seen so far (seen %s ago)."] = "A szokásos %s az eddig látott legolcsóbb ár (%s ezelőtt látva)."
L["Usual %s is the middle of the cheapest price each day for the last %d days (seen %s ago)."] = "A szokásos %s az elmúlt %d nap napi legolcsóbb árainak közepe (%s ezelőtt látva)."
L["Usual %s is the middle of the cheapest price on each of the %d days it was seen (seen %s ago)."] = "A szokásos %s a látott %d nap mindegyikének legolcsóbb árai közül a középső (%s ezelőtt látva)."
L["Usual %s is the middle of these"] = "A szokásos %s ezek közepe"
