L["Usual, stack of %d"] = "Szokásos, %d darabos halom"
L["Version"] = "Verzió"
L["Wait for the search to finish, then click again."] = "Várd meg, amíg a keresés befejeződik, aztán kattints újra."
L["Waiting on %d"] = "Várakozás erre: %d"
L["Welcome to Daylight UI %s"] = "Üdvözöl a Daylight UI %s"
L["When a roll shows who picked what and everyone's rolls. A roll stays small until you've picked, then its list opens. With one roll up the list shows on its own, and with several, on the one under your mouse or the one just won."] = "Mikor mutatja egy dobás, ki mit választott, és mindenki dobását. Egy dobás kicsi marad, amíg nem választottál, aztán kinyílik a listája. Egy fent lévő dobásnál a lista magától látszik, többnél azon, ami az egered alatt van, vagy amit épp megnyertek."
L["Which tab shows when you talk to an auctioneer. Pick Sell if you mostly come to post, or the tab you left open to carry on where you were."] = "Melyik fül látszik, amikor egy aukcióssal beszélsz. Válaszd az Eladást, ha többnyire feladni jössz, vagy a legutóbb nyitva hagyott fület, hogy ott folytasd, ahol abbahagytad."
L["Which way new rolls stack from the Loot Rolls handle."] = "Merre sorakoznak az új dobások a Zsákmánydobások fogantyútól."
L["With more than one roll up, each shows just the item, your buttons and a row of ticks for who has picked, so several rolls fit on screen at once. When off, every roll shows in full."] = "Ha egynél több dobás van fent, mindegyik csak a tárgyat, a gombjaidat és egy jelsort mutat arról, ki választott már, így egyszerre több dobás is elfér a képernyőn. Kikapcsolva minden dobás teljesen látszik."
L["With one roll"] = "Egy dobásnál"
L["You don't have enough gold for that."] = "Nincs ehhez elég aranyad."
L["You don't have that many in your bags."] = "Nincs ennyi a táskáidban."
L["You get when it sells"] = "Ennyit kapsz, ha elkel"
L["You picked %s"] = "Választásod: %s"
