L["Use Daylight UI global style"] = "A Daylight UI globális stílusának használata"
L["When on, this wears the borders, shadows and background set on General > Appearance, like every Daylight UI window. Turn it off to give it its own in the rows below."] = "Bekapcsolva az Általános > Megjelenés alatt beállított kereteket, árnyékokat és hátteret viseli, mint minden Daylight UI ablak. Kapcsold ki, ha az alábbi sorokban sajátot adnál neki."
L["Accent gradient border"] = "Színátmenetes kiemelőkeret"
L["When the accent color is a gradient (Daylight's, your class's or your own), the border runs along it. Needs Gradients on (General > Gradients)."] = "Ha a kiemelőszín színátmenet (a Daylighté, a kasztodé vagy a sajátod), a keret ezt követi. Kell hozzá a Színátmenetek bekapcsolása (Általános > Színátmenetek)."
L["How solid the border is: at 0 it's fully see-through."] = "Mennyire tömör a keret: 0-nál teljesen áttetsző."
L["How far the soft shadow around it reaches."] = "Milyen messzire ér körülötte a lágy árnyék."
L["How dark the shadow around it is."] = "Milyen sötét körülötte az árnyék."
L["Background opacity"] = "Háttér átlátszatlansága"
L["The color behind it: Daylight's own dark tone, a dark tint of your class color, or a color you pick."] = "A szín mögötte: a Daylight saját sötét tónusa, a kasztszíned sötét árnyalata, vagy egy általad választott szín."
L["Custom background color"] = "Egyedi háttérszín"
L["The background, when Background color is One color. Dark colors keep text easy to read."] = "A háttér, ha a Háttérszín Egy szín. A sötét színekkel a szöveg könnyen olvasható marad."
L["Borders and background"] = "Keretek és háttér"
L["Apply global style everywhere"] = "Globális stílus mindenhol"
L["Turns Use Daylight UI global style back on for every window and panel, so they all match the borders, shadows and background here."] = "Minden ablakon és panelen visszakapcsolja A Daylight UI globális stílusának használata beállítást, így mind az itteni keretekhez, árnyékokhoz és háttérhez igazodik."
L["How solid every window and panel is: bags, character, spellbook, NPC, group finder, the game's windows Daylight UI restyles, chat, the info panel, the quest box and the buff bars. At 0 they're fully see-through. One with Use Daylight UI global style off keeps its own."] = "Mennyire tömör minden ablak és panel: táskák, karakter, varázskönyv, NPC, csoportkereső, a játék Daylight UI által átszínezett ablakai, a chat, az infópanel, a küldetésdoboz és a buff-sávok. 0-nál teljesen áttetszők. Amelyiknél A Daylight UI globális stílusának használata ki van kapcsolva, megtartja a sajátját."
L["The experience bar's box. The minimap's box and each meter window have their own. At 0 opacity the box disappears; the bars still show."] = "A tapasztalatsáv doboza. A minitérkép dobozának és minden mérőablaknak sajátja van. 0 átlátszatlanságnál a doboz eltűnik; a sávok látszanak."
L["The box around the minimap, with the damage meter and data texts in it."] = "A doboz a minitérkép körül, benne a sebzésmérővel és az adatszövegekkel."
L["The data bar has no border on the global style: on a strip this thin the accent line is enough."] = "Az adatsávnak a globális stílusban nincs kerete: ilyen vékony csíkon elég a kiemelővonal."
L["The color of every chat panel's border. The border still lights up in your accent color while you drag a corner to size the chat."] = "Minden chatpanel keretének színe. A keret továbbra is a kiemelőszínedben villan fel, amíg egy sarkát húzva méretezed a chatet."
L["Every chat panel: the main one, the second one and a chat window pulled out on its own. On the global style the Classic chat keeps a thin line."] = "Minden chatpanel: a fő, a második, és egy külön kihúzott chatablak. A globális stílusban a Klasszikus chat megtart egy vékony vonalat."
L["Gives the second chat panel its own background opacity, set in the row below. When off, it's as see-through as the main chat panel. Shown while the chat's Use Daylight UI global style is off."] = "A második chatpanel saját háttér-átlátszatlanságot kap, az alábbi sorban állítva. Kikapcsolva ugyanolyan áttetsző, mint a fő chatpanel. Akkor látszik, ha a chat A Daylight UI globális stílusának használata beállítása ki van kapcsolva."
L[" and "] = " és "
