L["A chat line for each post"] = "Egy chatsor minden feladásnál"
L["A creature's face and a player's class icon at the top of their card. Off, the card starts with the name."] = "A kártya tetején a lény arca vagy a játékos kasztikonja. Kikapcsolva a kártya a névvel kezdődik."
L["A layout from Daylight UI's Export, the game's own Cooldown Manager, a guide or another UI. It becomes a new cooldown layout, used by the talent set you're in."] = "Egy elrendezés a Daylight UI exportjából, a játék saját Cooldown Manager funkciójából, egy útmutatóból vagy egy másik UI-ból. Új újratöltődés-elrendezés lesz belőle, amelyet a mostani tehetségszetted használ."
L["A new item shows both in Recent and in the group it belongs to, so you can find it either way."] = "Egy új tárgy a Friss között és a saját csoportjában is megjelenik, így bármelyik úton megtalálod."
L["A number on each nameplate showing how much health the enemy has left."] = "Minden névtáblán egy szám, amely mutatja, mennyi életereje maradt az ellenfélnek."
L["A number you can read at a glance."] = "Egy szám, amit egy pillantással leolvasol."
L["A player's casts in their class color, or their class's gradient with a two-color fill. Creatures' casts keep the fill style. Not with the Daylight gradient or a custom gradient."] = "A játékosok varázslásai a kasztszínükben, vagy kétszínű kitöltésnél a kasztjuk színátmenetével. A lények varázslásai megtartják a kitöltési stílust. Nem működik a Daylight színátmenettel vagy egyedi színátmenettel."
L["A row per item."] = "Tárgyanként egy sor."
L["A small icon before each text, in the numbers' color."] = "Egy kis ikon minden szöveg előtt, a számok színében."
L["A small icon over other players' heads, so you can spot the healer in a crowd."] = "Egy kis ikon a többi játékos feje fölött, hogy a tömegben is kiszúrd a gyógyítót."
L["A soft warm gray."] = "Lágy, meleg szürke."
L["A thin bar under each quest objective on the card. Off, the objective and its count still show."] = "Vékony sáv a kártyán minden küldetésfeladat alatt. Kikapcsolva a feladat és a számlálója továbbra is látszik."
L["A vendor pays more for it (%s each). Click Post again to post it anyway."] = "Egy kereskedő többet fizet érte (darabja %s). Kattints újra a Feladásra, ha mégis feladnád."
L["A weapon's damage per second, the big number over its damage and speed."] = "A fegyver másodpercenkénti sebzése, a nagy szám a sebzése és sebessége fölött."
L["A whole new Auction House: buy, sell and track your auctions, with prices on every item's tooltip."] = "Egy teljesen új Aukciósház: vásárolj, adj el és kövesd az aukcióidat, minden tárgy buborékján árakkal."
L["About %s made, at %s each on the Auction House."] = "Kb. %s készül, darabja %s az Aukciósházban."
L["Accent color follows the accent on General > Appearance, including the Daylight gradient. Custom gradient runs through colors you pick."] = "A Kiemelőszín az Általános > Megjelenés kiemelőszínét követi, a Daylight színátmenetet is beleértve. Az Egyedi színátmenet az általad választott színeken fut végig."
L["Accent color follows the accent on General > Appearance. Class gradient uses your class's two colors (set on the Gradients page). Custom gradient runs through two to five colors you pick. Reputation keeps its standing's colors."] = "A Kiemelőszín az Általános > Megjelenés kiemelőszínét követi. A Kaszt-színátmenet a kasztod két színét használja (a Színátmenetek oldalon állítható). Az Egyedi színátmenet kettő–öt általad választott színen fut végig. A hírnév megtartja a hírnévszintje színeit."
L["Accent color follows the accent on General > Appearance. Class gradient uses your class's two colors (set on the Gradients page). Custom gradient uses the two colors you pick. Reputation keeps its standing's colors."] = "A Kiemelőszín az Általános > Megjelenés kiemelőszínét követi. A Kaszt-színátmenet a kasztod két színét használja (a Színátmenetek oldalon állítható). Az Egyedi színátmenet a két általad választott színt használja. A hírnév megtartja a hírnévszintje színeit."
