L["Daylight UI leaves %s alone and skips their questions."] = "A Daylight UI nem nyúl ehhez: %s, és kihagyja a hozzájuk tartozó kérdéseket."
L["Daylight UI's own cards: name and tags up top, every number in tidy rows."] = "A Daylight UI saját kártyái: fent a név és a címkék, minden szám rendezett sorokban."
L["Daylight UI's own tooltip cards: the name and tags up top, every number in tidy rows."] = "A Daylight UI saját buborékkártyái: fent a név és a címkék, minden szám rendezett sorokban."
