L["Daylight's picks"] = "A Daylight választásai"
L["Drops the titles for a smaller card."] = "Elhagyja a címeket, így kisebb a kártya."
L["Each auction you post from Sell is written in chat with its price, so you can look back at what you put up."] = "Minden aukció, amit az Eladás lapról adsz fel, az árával együtt bekerül a chatbe, így visszanézheted, mit tettél fel."
L["Each bar in its player's class color, all in one color, or all in a gradient of colors you pick; a threat meter can color each bar by how close that player is to pulling."] = "Minden sáv a játékosa kasztszínében, mind egy színben, vagy mind egy általad választott színátmenetben; egy fenyegetésmérő aszerint is színezheti a sávokat, mennyire közel van az adott játékos az aggro elvételéhez."
