L["Enchants can't be sold: no profit."] = "Bűvölést nem lehet eladni: nincs haszon."
L["Every hand's bar in your class color, or your class's gradient with a two-color fill. A queued attack keeps its own color. Not with the Daylight gradient or a custom gradient."] = "Mindkét kéz sávja a kasztszínedben, vagy kétszínű kitöltésnél a kasztod színátmenetével. A sorba állított támadás megtartja a saját színét. Nem működik a Daylight színátmenettel vagy egyedi színátmenettel."
