L["How each hand's bar is filled: one color each, the Daylight gradient (the logo's blue to orange), a two-color gradient per hand (set on the Gradients page), or a gradient in colors you pick. A queued attack always keeps its own color."] = "Hogyan töltődik ki a kezek sávja: kezenként egy szín, a Daylight színátmenet (a logó kékjétől a narancsig), kezenként kétszínű színátmenet (a Színátmenetek oldalon állítható), vagy egy színátmenet az általad választott színekből. A sorba állított támadás mindig megtartja a saját színét."
L["How every cast bar (yours, target's, focus's and party's) is filled: one color each, the Daylight gradient (the logo's blue to orange), a two-color gradient per kind of cast (set on the Gradients page), or a gradient in colors you pick."] = "Hogyan töltődik ki minden varázslássáv (a tiéd, a célpontodé, a fókuszé és a csoporté): mindegyik egy színnel, a Daylight színátmenettel (a logó kékjétől a narancsig), varázslásfajtánként kétszínű színátmenettel (a Színátmenetek oldalon állítható), vagy egy színátmenettel az általad választott színekből."
