L["Rebuilt from the ground up: fewer missing spells, and glows that stay right in a fight."] = "Az alapoktól újraépítve: kevesebb hiányzó varázslat, és harcban is pontos fények."
L["Reload and play"] = "Újratöltés és játék"
L["Reset filters"] = "Szűrők visszaállítása"
L["Rich tooltips"] = "Részletes buborékok"
L["Rich tooltips are Daylight UI's own cards: the name up top with tags, then every number in tidy rows. Pick the look you like."] = "A részletes buborékok a Daylight UI saját kártyái: fent a név a címkékkel, alatta minden szám rendezett sorokban. Válaszd ki, melyik kinézet tetszik."
L["Same as unit frames: a class gradient or custom gradient when your unit frames' health bars use one. Class gradient uses the pairs from General > Gradients. Custom gradient runs through colors you pick."] = "Ugyanaz, mint az egységkereteken: kaszt- vagy egyedi színátmenet, ha az egységkereteid életerő-sávjai ilyet használnak. A Kaszt-színátmenet az Általános > Színátmenetek párjait használja. Az Egyedi színátmenet az általad választott színeken fut végig."
L["Search all favorites"] = "Keresés az összes kedvencben"
L["See who picked Need, Greed or Pass, everyone's roll and who won."] = "Lásd, ki választott Need, Greed vagy Pass lehetőséget, mindenki dobását, és hogy ki nyert."
L["Set up %s to match?"] = "Beállítsam hozzá illően ezt: %s?"
L["Share these parts. Whatever you switch off, they keep their own."] = "Ezeket a részeket osztod meg. Amit kikapcsolsz, abból a többiek a sajátjukat tartják meg."
L["Shares %s of %s parts. Whoever imports it keeps their own for the rest."] = "%s / %s részt oszt meg. Aki importálja, a többiből a sajátját tartja meg."
L["Shares all %s parts."] = "Mind a(z) %s részt megosztja."
L["Shelf"] = "Polc"
L["Show class icons"] = "Kasztikonok mutatása"
L["Show in the list again"] = "Újra mutasd a listában"
L["Show it"] = "Mutasd"
L["Show them"] = "Mutasd őket"
L["Showing the first %s in this order: add words to narrow it."] = "Az első %s látszik ebben a sorrendben: adj meg több szót a szűkítéshez."
L["Shows the health text large, in the Health text color, at the end Health text position picks (in Ribbon, on the row above the bar)."] = "Nagy méretben mutatja az életerő-szöveget, az Életerő-szöveg színében, annál a végénél, amelyet az Életerő-szöveg helye kiválaszt (Szalagban a sáv fölötti sorban)."
L["Shows the name on enemy plates. Turn it off for bars only."] = "Mutatja a nevet az ellenséges névtáblákon. Kapcsold ki, ha csak sávokat szeretnél."
L["Shows the name on friendly plates with a health bar. Plates that are just a name keep it."] = "Mutatja a nevet az életerő-sávos baráti névtáblákon. A csak névből álló táblák megtartják."
L["Slim leader tools"] = "Karcsú vezetői eszközök"
L["Solo, a mob attacking you turns red and the rest keep their normal color, like in a group."] = "Egyedül a téged támadó szörny pirosra vált, a többi megtartja a szokásos színét, ahogy csoportban."
L["Someone bid %s, more than you. Bid at least %s to win it back."] = "Valaki %s licitet adott, többet nálad. Licitálj legalább %s összeget, hogy visszaszerezd."
L["Someone else bid more, or it sold. Check again."] = "Valaki más többet licitált, vagy elkelt. Nézd meg újra."
L["Soulbound: no profit."] = "Lélekhez kötött: nincs haszon."
L["Stackable goods sell at their price only"] = "Halmozható áru csak a saját árán kel el"
L["Starting bid"] = "Kezdő licit"
L["Stay on the profile you have now, as it is."] = "Maradj a mostani profilodon, úgy, ahogy van."
L["Step %s of %d"] = "%s. lépés / %d"
L["Still checking its price. Click again in a moment."] = "Még ellenőrzöm az árát. Kattints újra egy pillanat múlva."
L["Suggested for you"] = "Neked ajánlott"
L["Swing timer gradient colors"] = "Ütésidőzítő színátmenet színei"
L["Swing timer gradient fifth color"] = "Ütésidőzítő színátmenet ötödik színe"
L["Swing timer gradient first color"] = "Ütésidőzítő színátmenet első színe"
L["Swing timer gradient fourth color"] = "Ütésidőzítő színátmenet negyedik színe"
L["Swing timer gradient second color"] = "Ütésidőzítő színátmenet második színe"
L["Swing timer gradient third color"] = "Ütésidőzítő színátmenet harmadik színe"
L["Switch on at least one part to import."] = "Kapcsolj be legalább egy részt az importáláshoz."
L["Switch on at least one part to share."] = "Kapcsolj be legalább egy részt a megosztáshoz."
L["Take these parts. Whatever you switch off stays as yours."] = "Ezeket a részeket veszed át. Amit kikapcsolsz, az a tiéd marad."
L["Takes %s of %s parts. The rest stay as yours."] = "%s / %s részt vesz át. A többi a tiéd marad."
L["Takes all %s parts."] = "Mind a(z) %s részt átveszi."
L["Target cast bar gradient colors"] = "Célpont-varázslássáv színátmenet színei"
L["Target cast bar gradient fifth color"] = "Célpont-varázslássáv színátmenet ötödik színe"
L["Target cast bar gradient first color"] = "Célpont-varázslássáv színátmenet első színe"
L["Target cast bar gradient fourth color"] = "Célpont-varázslássáv színátmenet negyedik színe"
L["Target cast bar gradient second color"] = "Célpont-varázslássáv színátmenet második színe"
L["Target cast bar gradient third color"] = "Célpont-varázslássáv színátmenet harmadik színe"
L["That's far under what most others ask (%s). Click Post again to post it anyway."] = "Ez jóval kevesebb, mint amennyit a legtöbben kérnek (%s). Kattints újra a Feladásra, ha mégis feladnád."
L["That's the buyout or more: buy it out instead."] = "Ez eléri az azonnali árat vagy több: inkább vedd meg azonnal."
L["The Auction House is still answering. Click again in a moment."] = "Az Aukciósház még válaszol. Kattints újra egy pillanat múlva."
L["The Auction House keeps %s of every sale."] = "Az Aukciósház minden eladásból %s jutalékot tart meg."
L["The Auction House takes whole silver only for this item: a starting bid of %s. Click Post to post it."] = "Ennél a tárgynál az Aukciósház csak egész ezüstöt fogad el: a kezdő licit %s. Kattints a Feladásra a feladáshoz."
L["The border runs around the portrait and the bar as one piece."] = "A szegély egy darabként fut körbe a portrén és a sávon."
L["The cast bar fills up while you cast a spell."] = "A varázslássáv feltöltődik, amíg varázsolsz."
L["The class icon above each name."] = "A kasztikon minden név fölött."
L["The color of the numbers. Accent color follows your accent along the strip. Pick White or One color if a dark accent is hard to read."] = "A számok színe. A Kiemelőszín a sáv mentén követi a kiemelőszínedet. Válaszd a Fehéret vagy az Egy színt, ha egy sötét kiemelőszín nehezen olvasható."
L["The cooldown layout you're using as text to share: every spell with its options, the groups and the Cooldown Manager's look."] = "A használt újratöltődés-elrendezésed szövegként, megosztásra: minden varázslat a beállításaival, a csoportok és a Cooldown Manager kinézete."
L["The game's %s row is set to Hidden in Edit Mode, so Daylight UI can't tell when this buff is up or missing. Set it to Always in Edit Mode for those options: Daylight UI still keeps the game's own icons out of sight."] = "A játék %s sora Hidden értékre van állítva a Szerkesztő módban, így a Daylight UI nem látja, mikor van fent vagy hiányzik ez a buff. Ezekhez a beállításokhoz állítsd Always értékre a Szerkesztő módban: a Daylight UI a játék saját ikonjait ettől még elrejtve tartja."
L["The game's Cooldown Manager makes no icon for this buff, so Daylight UI can't tell when it's up or missing, and the options for those are left out."] = "A játék Cooldown Managere nem készít ikont ehhez a buffhoz, így a Daylight UI nem látja, mikor van fent vagy hiányzik, és az ehhez tartozó beállítások kimaradnak."
L["The game's tooltip in the Daylight look."] = "A játék buboréka Daylight kinézetben."
L["The guide walks you through it, one easy choice at a time. About 2 minutes."] = "Az útmutató végigvezet rajta, egyszerre egy könnyű választással. Kb. 2 perc."
L["The layout: %s, with its look."] = "Az elrendezés: %s, a kinézetével együtt."
L["The lettering for every name, number and window. Run your mouse across them to try each one."] = "A betűtípus minden névhez, számhoz és ablakhoz. Húzd végig rajtuk az egeret, hogy mindegyiket kipróbáld."
L["The next color along the custom gradient of every health bar."] = "A következő szín minden életerő-sáv egyedi színátmenetében."
L["The next color along the custom gradient of every power bar."] = "A következő szín minden erőforrás-sáv egyedi színátmenetében."
L["The next color along the custom gradient of friendly health bars."] = "A következő szín a baráti életerő-sávok egyedi színátmenetében."
L["The next color along the custom gradient of the experience bar."] = "A következő szín a tapasztalatsáv egyedi színátmenetében."
L["The next color along the custom gradient of the health bar."] = "A következő szín az életerő-sáv egyedi színátmenetében."
L["The next color along the custom gradient of the meter's bars."] = "A következő szín a mérő sávjainak egyedi színátmenetében."
L["The next color along the custom gradient of the nameplates' cast bars."] = "A következő szín a névtáblák varázslássávjainak egyedi színátmenetében."
L["The next color along the custom gradient of the nameplates' health bars."] = "A következő szín a névtáblák életerő-sávjainak egyedi színátmenetében."
L["The next color along the custom gradient of the nameplates' power bars."] = "A következő szín a névtáblák erőforrás-sávjainak egyedi színátmenetében."
L["The next color along the custom gradient of the power bar."] = "A következő szín az erőforrás-sáv egyedi színátmenetében."
L["The next color along the custom gradient of the progress bars."] = "A következő szín a haladássávok egyedi színátmenetében."
L["The next color along the custom gradient of the row of combo points."] = "A következő szín a kombópontok sorának egyedi színátmenetében."
L["The next color along the custom gradient of the swing timer bars."] = "A következő szín az ütésidőzítő sávjainak egyedi színátmenetében."
L["The next color along the custom gradient of the target, focus and party cast bars."] = "A következő szín a célpont, a fókusz és a csoport varázslássávjainak egyedi színátmenetében."
L["The next color along the custom gradient of the tooltip's health bar."] = "A következő szín a buborék életerő-sávjának egyedi színátmenetében."
L["The next color along the custom gradient of your cast bar."] = "A következő szín a varázslássávod egyedi színátmenetében."
L["The next color along the custom gradient."] = "A következő szín az egyedi színátmenetben."
L["The numbers' color when Data bar text color is One color."] = "A számok színe, ha az Adatsáv szövegszíne Egy szín."
L["The numbers' color when Data text color is One color."] = "A számok színe, ha az Adatszöveg színe Egy szín."
L["The portrait is the picture of your character beside your health bar."] = "A portré a karaktered képe az életerő-sávod mellett."
L["The price went up since you looked: here are the prices now."] = "Az ár azóta emelkedett, hogy megnézted: itt vannak a mostani árak."
L["The quest helper points the way to your next quest."] = "A küldetéssegéd megmutatja az utat a következő küldetésedhez."
L["The recipe you pick shows what its materials cost, what it sells for and the profit, from the prices the Auction House has shown you. The Profit chip over the list shows every recipe's, best first."] = "A kiválasztott recept mutatja, mennyibe kerülnek az alapanyagai, mennyiért adható el és mennyi a haszon, az Aukciósház által eddig mutatott árak alapján. A lista fölötti Haszon címke minden receptét mutatja, a legjobbal kezdve."
L["The ring lies over the frame."] = "A gyűrű a keretre fekszik rá."
L["The same Alliance or Horde crest by the name of anyone you could attack who's flagged for PvP, players and NPCs alike, so you can tell before you attack that it would flag you."] = "Ugyanaz az Alliance- vagy Horde-címer jelenik meg mindenki neve mellett, akit megtámadhatsz és PvP-re jelölt, játékosoknál és NPC-knél egyaránt, így támadás előtt látod, hogy ettől te is PvP-jelölt lennél."
L["The signature blue to pink."] = "A jellegzetes kéktől rózsaszínig."
L["The starting bid has to be under the price."] = "A kezdő licitnek az ár alatt kell lennie."
L["The target's and target of target's health and power gradients run the other way, so they mirror yours. Only for a horizontal gradient."] = "A célpont és a célpont célpontjának életerő- és erőforrás-színátmenete fordított irányban fut, így a tiédnek tükörképei. Csak vízszintes színátmenetnél."
L["The tooltip is the box that pops up when you point at an item or a player."] = "A buborék az a doboz, ami felugrik, amikor egy tárgyra vagy játékosra mutatsz."
L["The top number is your best school."] = "A felső szám a legjobb mágiaiskolád."
L["The whole layout: every spell with its options, the groups and the Cooldown Manager's look. Ctrl+C to copy, then share it. Import takes it in on a character of the same class."] = "A teljes elrendezés: minden varázslat a beállításaival, a csoportok és a Cooldown Manager kinézete. Ctrl+C a másoláshoz, aztán oszd meg. Az Importálás egy azonos kasztú karakteren veszi át."
L["This color goes on your bars, borders and highlights. Run your mouse across them to try each one."] = "Ez a szín kerül a sávjaidra, szegélyeidre és kiemeléseidre. Húzd végig rajtuk az egeret, hogy mindegyiket kipróbáld."
L["This decides where everything sits on your screen. You can move any piece later."] = "Ez dönti el, hol legyen minden a képernyődön. Bármelyik darabot később is áthelyezheted."
L["This pack can set up %s to go with its profile."] = "Ez a csomag a profiljához illően be tudja állítani ezt: %s."
L["Threat colors when solo"] = "Fenyegetésszínek egyedül is"
L["Tool"] = "Eszköz"
L["Tools"] = "Eszközök"
L["Tooltip health gradient colors"] = "Buborék-életerő színátmenet színei"
L["Tooltip health gradient fifth color"] = "Buborék-életerő színátmenet ötödik színe"
L["Tooltip health gradient first color"] = "Buborék-életerő színátmenet első színe"
L["Tooltip health gradient fourth color"] = "Buborék-életerő színátmenet negyedik színe"
L["Tooltip health gradient second color"] = "Buborék-életerő színátmenet második színe"
L["Tooltip health gradient third color"] = "Buborék-életerő színátmenet harmadik színe"
L["Try again"] = "Újrapróbálás"
L["Type the starting bid like %s, or leave it empty."] = "Írd be a kezdő licitet így: %s, vagy hagyd üresen."
L["Uncollected only"] = "Csak a még meg nem szerzettek"
L["Under the portrait"] = "A portré alatt"
L["Undercut by percent"] = "Alákínálás százalékkal"
L["Upgrades only"] = "Csak fejlesztések"
L["Used by all Daylight UI text, except where a frame's own page picks another font. Game font is the client's own, including a font you've replaced it with. Fonts other addons share (SharedMedia) are listed with them, A to Z."] = "Minden Daylight UI szöveg ezt használja, kivéve ahol egy keret saját oldala másik betűtípust választ. A Játék betűtípusa a kliens sajátja, beleértve azt is, amire lecserélted. A más addonok által megosztott betűtípusok (SharedMedia) velük együtt szerepelnek, A-tól Z-ig."
L["Want the quest helper?"] = "Kéred a küldetéssegédet?"
L["What's Training"] = "Mit tanulhatsz"
L["When you're not fighting, Daylight UI can step out of the way. Hover one to watch it."] = "Amikor nem harcolsz, a Daylight UI félre tud állni az útból. Vidd az egeret valamelyikre, hogy megnézd."
L["Where a creature's health bar sits on its card: under the name, or at the end of the card."] = "Hol legyen a lény életerő-sávja a kártyáján: a név alatt vagy a kártya végén."
L["Where along each pet's bar the health text sits."] = "Hol legyen az életerő-szöveg az egyes háziállatok sávján."
L["Where along each tile the health text sits. The left / right nudge moves it from there."] = "Hol legyen az életerő-szöveg az egyes csempéken. A bal / jobb eltolás onnan mozdítja el."
L["Where along the health bar the health text sits. The left / right nudge moves it from there."] = "Hol legyen az életerő-szöveg az életerő-sávon. A bal / jobb eltolás onnan mozdítja el."
L["Where should your cast bar sit?"] = "Hol legyen a varázslássávod?"
L["Where the custom gradient of every health bar starts."] = "Ahol minden életerő-sáv egyedi színátmenete kezdődik."
