L["Where the custom gradient of the nameplates' health bars starts."] = "Ahol a névtáblák életerő-sávjainak egyedi színátmenete kezdődik."
L["Where the custom gradient of the nameplates' power bars starts."] = "Ahol a névtáblák erőforrás-sávjainak egyedi színátmenete kezdődik."
L["Where the custom gradient of the power bar starts."] = "Ahol az erőforrás-sáv egyedi színátmenete kezdődik."
L["Where the custom gradient of the progress bars starts."] = "Ahol a haladássávok egyedi színátmenete kezdődik."
L["Where the custom gradient of the row of combo points starts."] = "Ahol a kombópontok sorának egyedi színátmenete kezdődik."
L["Where the custom gradient of the swing timer bars starts."] = "Ahol az ütésidőzítő sávjainak egyedi színátmenete kezdődik."
L["Where the custom gradient of the target, focus and party cast bars starts."] = "Ahol a célpont, a fókusz és a csoport varázslássávjainak egyedi színátmenete kezdődik."
L["Where the custom gradient of the tooltip's health bar starts."] = "Ahol a buborék életerő-sávjának egyedi színátmenete kezdődik."
L["Where the custom gradient of your cast bar starts."] = "Ahol a varázslássávod egyedi színátmenete kezdődik."
L["Where the custom gradient starts."] = "Ahol az egyedi színátmenet kezdődik."
L["Where the level badge sits: on the portrait, under it at the ring's foot, or any spot on or around the frame. You can also drag it in Design mode."] = "Hol legyen a szintjelvény: a portrén, alatta a gyűrű tövénél, vagy bárhol a kereten vagy körülötte. A Tervező módban húzással is áthelyezheted."
L["Which layout do you start from?"] = "Melyik elrendezésből indulsz?"
L["Which quest tracker do you want?"] = "Melyik küldetéskövetőt szeretnéd?"
L["Which tooltips do you like?"] = "Milyen buborékok tetszenek?"
L["While you prowl, this bar shows a page of its own instead of your Cat Form buttons, like the game's Prowl bar. Fill it with the spells you open with."] = "Lopakodás közben ez a sáv saját oldalt mutat a Cat Form gombjaid helyett, mint a játék Prowl sávja. Töltsd fel azokkal a varázslatokkal, amelyekkel nyitsz."
L["Who draws your %s?"] = "Ki rajzolja ezt: %s?"
L["You will land at the next flight point."] = "A következő repülési pontnál fogsz leszállni."
L["You're the highest bidder"] = "Te vagy a legmagasabb licitáló"
L["Your DoTs and effects over each enemy."] = "A DoT-jaid és hatásaid minden ellenfél fölött."
L["Your UI is ready, %s"] = "Kész a felületed, %s"
L["Your bid of %s is the highest. It's yours when its time runs out, unless someone bids more or buys it out."] = "A(z) %s licited a legmagasabb. A tiéd lesz, amikor lejár az ideje, hacsak valaki nem licitál többet vagy veszi meg azonnal."
L["Your casts and channels in your class color, or your class's gradient with a two-color fill. Not with the Daylight gradient or a custom gradient."] = "A varázslásaid és csatornázásaid a kasztszínedben, vagy kétszínű kitöltésnél a kasztod színátmenetével. Nem működik a Daylight színátmenettel vagy egyedi színátmenettel."
L["Your class color as a sweep."] = "A kasztszíned végigfutó átmenetként."
L["Your debuffs on nameplates?"] = "A debuffjaid a névtáblákon?"
